const long long N = 200100;
long long n, a[N], b[N], ans;
priority_queue <pair<long long, long long>  > pq;

int main() {
	ios_base::sync_with_stdio(false);

	cin >> n;
	for(long long i = 0; i < n; i++)
		cin >> a[i];

	for(long long i = 0; i < n; i++) {
		cin >> b[i];
		if(b[i] != a[i])
			pq.push({b[i], i});
	}

	while(!pq.empty()) {
		auto p = pq.top();
		pq.pop();
		long long nxt = max({a[p.nd], b[(n + p.nd - 1) % n] , b[(p.nd + 1) % n]});
		// dbg(p);
		long long dif = p.st - nxt;
		dif /= (b[(n + p.nd - 1) % n] + b[(p.nd + 1) % n]);
		dif = max(dif, 1LL);
		ans += dif;
		p.st -= dif * (b[(n + p.nd - 1) % n] + b[(p.nd + 1) % n]);
		if(p.st != a[p.nd])
			pq.push(p);

		if(p.st < a[p.nd]) return cout << "-1\n", 0;
		b[p.nd] = p.st;
	}
	cout << ans << '\n';
}

