	}
	while (!qwq.empty()){
		pa now=qwq.top();
		qwq.pop();
		if (b[now.second]>now.first) {
			puts("-1");
			return 0;
		}
		if (b[now.second]==now.first) continue;
		int Ned=now.first-b[now.second];
		int tmp=a[now.second-1]+a[now.second+1];
