            A[b]=e;
        }else{
            ll f=a-(a-B[b])/(c+d)*(c+d);
            if(a==f){
                cnt=-1;
                break;
            }
            cnt+=(a-B[b])/(c+d);
            PQ.push(make_pair(f,b));
            A[b]=f;
        }

    }

