        cout << 0 << '\n';
        return 0;
    }
    while (!q.empty()) {
        int i = q.front(); q.pop();

        int s = b[(i-1+n)%n] + b[(i+1+n)%n];
        cnt += b[i]/s;
        b[i] %= s;

        if (localmax((i-1+n)%n)) q.push((i-1+n)%n);
        if (localmax((i+1+n)%n)) q.push((i+1+n)%n);

        if (b[i] < a[i]) break;
