using namespace std;

void failure () {
  cout << -1 << endl;
  exit(0);
}

const int MAX_N = 2e5 + 5;

int A [MAX_N];
int B [MAX_N];

int n;
set<pair<int, int>> diffs;

int step_back (int i, int nd) {
  diffs.erase(make_pair(B[i] - A[i], i));

  int li = (i + n - 1) % n;
  int ri = (i + 1) % n;

  int ld = B[li] - A[li];
  int cd = B[i] - A[i];
  int rd = B[ri] - A[ri];
  int rv = B[li] + B[ri];

  // remove as much as possible s.t. cd < nd
  int remc = (cd - nd) / rv;
  B[i] -= remc * rv;
  if (B[i] != A[i]) {
    remc++;
    B[i] -= rv;
  }

  if (B[i] < A[i]) failure();

  diffs.insert(make_pair(B[i] - A[i], i));
  return remc;
}

int main () {
  ios::sync_with_stdio(false);

  cin >> n;

  for (int i = 0; i < n; i++) {
    cin >> A[i];
  }

  for (int i = 0; i < n; i++) {
    cin >> B[i];
  }

  for (int i = 0; i < n; i++) {
    if (B[i] < A[i]) failure();
    diffs.insert(make_pair(B[i] - A[i], i));
  }

  int ans = 0;
  while (diffs.rbegin()->first > 0) {
    int idx = diffs.rbegin()->second;
    ans += step_back(idx, next(diffs.rbegin())->first);
  }

  cout << ans << endl;
}

