ll dov(VL& b, ll i, VL& a) {
	ll cnt = 0;
	ll j = (i + n - 1);
	ll val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		if (b[at(i)] < a[at(i)]) {
			ll t = (a[at(i)] - b[at(i)] + 1) / val;
			cnt -= t;
			b[at(i)] += t * val;
		}
		cnt += dov(b, j, a);
	}

	j = (i + 1);
	val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		if (b[at(i)] < a[at(i)]) {
			ll t = (a[at(i)] - b[at(i)] + 1) / val;
			cnt -= t;
			b[at(i)] += t * val;
		}
		cnt += dov(b, j, a);
	}
	return cnt;
}

