int n, a[MAX_N], b[MAX_N];

class compare {
  public:
    bool operator()(pair<int, int> a, pair<int, int> b) {
      return a.second < b.second;
    }
};

int main() {
  priority_queue<pair<int, int>, vector<pair<int, int>>, compare> que;
  cin >> n;
  for (int i = 0; i < n; ++i)
    cin >> a[i];
  for (int i = 0; i < n; ++i) {
    cin >> b[i];
    if (b[i] > a[i]) {
      que.push(make_pair(i, b[i]));
    }
  }

  int i = 0;
  while (!que.empty()) {
    pair<int, int> x = que.top();
    que.pop();
    if (x.second < (b[(x.first + 1) % n] + b[(x.first + n - 1) % n])) {
      puts("-1");
      return 0;
    }
    i += x.second / (b[(x.first + 1) % n] + b[(x.first + n - 1) % n]);
    x.second %= b[(x.first + 1) % n] + b[(x.first + n - 1) % n];
    b[x.first] = x.second;
    if (x.second > a[x.first]) {
      que.push(x);
    } else if (x.second < a[x.first]) {
      puts("-1");
      return 0;
    }
  }

  cout << i << endl;

  return 0;
}

