        if(B[i] == A[i]){
            ++count;
        }

    }

    if(B[N - 1] - B[N - 2] - B[0] >= A[N-1]){
        B[N - 1] -= B[N - 2];
        B[N - 1] -= B[0];
        ++ans;
        ret = N - 1;
    }

    else if(B[N - 1] == A[N-1]){
        ++count;
    }

    if(count == N){
        return INF32;
    }
    return ret;
}

