int N;
int A[200000];
int B[200000];
int sub() {
	int matches = 0;
	int cnt = 0;
	queue<int> que;
	REP(i, 0, N) {
		if (B[i] == A[i]) {
			++matches;
			continue;
		}

		if (B[i] > B[(i + N - 1) % N] && B[i] > B[(i + 1) % N]) {
			que.push(i);
		}
	}

	while (!que.empty()) {
		int i = que.front(); que.pop();
		int divisor = B[(i + N - 1) % N] + B[(i + 1) % N];
		int diff = B[i] - A[i];
		if (diff < divisor) return -1;
		int quot = diff / divisor;

		B[i] -= quot * divisor;
		cnt += quot;

		if (B[i] == A[i]) ++matches;

		for (int j : { (i + N - 1) % N, (i + 1) % N }) {
			if (B[j] == A[j]) continue;
			if (B[j] > B[(j + N - 1) % N] && B[j] > B[(j + 1) % N]) {
				que.push(j);
			}
		}
	}

	if (matches == N) {
		return cnt;
	} else {
		return -1;
	}
}

