int n;
vector<int> a, b;

int _left(int i) {
    return (n + i - 1) % n;
}

int _right(int i) {
    return (i + 1) % n;
}

typedef pair <int, int> pr;

bool ok(int i) {
    return b[i] > a[i] && (b[i] - a[i]) >= b[_left(i)] + b[_right(i)];
}

pr val_at(int x) {
    return make_pair(b[x], x);
}

int main() {

    cin >> n;
    a.resize(n);
    b.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    priority_queue <pr> pq;
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    for (int i = 0; i < n; i++) {
        if (ok(i)) {
            pq.push(val_at(i));
        }
    }

    int res = 0;

    while (pq.size() > 0) {
        int x = pq.top().second;
        pq.pop();

        int tmp = (b[x] - a[x]) / (b[_left(x)] + b[_right(x)]);
        b[x] -= tmp * (b[_left(x)] + b[_right(x)]);
        res += tmp;

        if (ok(_left(x))) {
            pq.push(val_at(_left(x)));
        }
        if (ok(_right(x))) {
            pq.push(val_at(_right(x)));
        }
        if (ok(x)) {
            pq.push(val_at(x));
        }
    }

    for (int i = 0; i < n; i++) {
        if (b[i] != a[i]) {
            cout << -1;
            return 0;
        }
    }

    cout << res;
    return 0;
}

