const int maxn = 200000 + 10;

int n, a[maxn], b[maxn];
struct qnode{
	int w, u;
	qnode() {}
	qnode(int _w, int _u):w(_w), u(_u) {}

	friend bool operator < (qnode a, qnode b) {
		if(a.w != b.w) return a.w < b.w;
		return a.u < b.u;
	}
};
priority_queue<qnode> q;

inline void fail() {
	puts("-1");
	exit(0);
}

signed main() {
//	freopen("data.in","r",stdin);
  scanf("%lld", &n);
	for(int i = 1;i <= n;i ++) scanf("%lld", &a[i]);
	for(int i = 1;i <= n;i ++) scanf("%lld", &b[i]);
  while(!q.empty()) q.pop();
	int cnt = 0;
	for(int i = 1;i <= n;i ++) if(a[i] != b[i]) q.push(qnode(b[i],i)), cnt ++;
	for(int i = 1;i <= n;i ++) if(a[i] > b[i]) fail();
	int step = 0;
	while(!q.empty()) {
    if(!cnt) break;
		qnode now = q.top(); q.pop();
		int x, y, z;
		y = now.u;
		x = (y == 1) ? (n) : (y - 1);
		z = (y == n) ? (1) : (y + 1);
		if(b[x] + b[z] > b[y]) fail();
    int tmp = b[x] + b[z];
		int del = b[y] - a[y];
		int ds = del / tmp;
		step += ds; b[y] -= ds * tmp;
		if(b[y] == a[y]) cnt --;
		else if(b[y] < a[y]) fail();
		else q.push(qnode(b[y],y));
	}
	printf("%lld\n", step);
	return 0;
}

