bool localmax(int i, int c[]) {
    return c[i] >= (c[(i-1+n)%n] + c[(i+1)%n]);
}

pair<ll,vector<int>> check(int c[]) {
    ll cnt = 0;
    priority_queue<pair<int,int>> pq;
    for (int i = 0; i < n; i++) {
        pq.push({c[i],i});
    }
    while (!pq.empty()) {
        auto p = pq.top(); pq.pop();
        int i = p.second;
        int s = c[(i-1+n)%n] + c[(i+1)%n];
        if (s == 0) continue;
        cnt += c[i]/s;
        if (c[i]/s == 0) break;
        c[i] %= s;
        pq.push({c[i],i});
    }
    vector<int> res;
    for (int i = 0; i < n; i++) {
        res.push_back(c[i]);
    }
    return {cnt,res};
}

