int main() {
	ll N;
	cin >> N;
	vector<ll> A(N), B(N);
	rep(i, N) cin >> A[i];
	rep(i, N) cin >> B[i];

	priority_queue<pair<ll, ll>> task; // <B[i], i>;
	rep(i, N) {
		if(A[i] < B[i]) {
			task.push(make_pair(B[i], i));
		}
	}

	ll ans = 0;
	while(task.size()>0) {
		ll id = task.top().second;
		task.pop();
		ll s = B[(id+N-1)%N] + B[(id+1)%N];
		if(B[id]-A[id]>=s){
			ll op = (B[id]-A[id])/s;
			ans += op;
			B[id] -= op*s;
			if(A[id]<B[id]) {
				task.push(make_pair(B[id], id));
			}
		} else {
			cout << -1 << endl;
			return 0;
		}
	}

	cout << ans << endl;
	return 0;
}

