  rep(i, N) pque.push({B[i], i});
  ll ans = 0;
  while(!pque.empty()){
    P p = pque.top();
    pque.pop();
    if(A[p.s] == B[p.s]) continue;
    if(B[p.s] < B[(p.s-1+N)%N] + B[(p.s+1)%N]) continue;
    int dec = min(B[p.s] / (B[(p.s-1+N)%N] + B[(p.s+1)%N]), (B[p.s] - A[p.s]) / (B[(p.s-1+N)%N] + B[(p.s+1)%N]));
    B[p.s] -= dec * (B[(p.s-1+N)%N] + B[(p.s+1)%N]);
    ans += dec;
    if(dec) pque.push({B[p.s], p.s});
  }
  rep(i, N) if(A[i] != B[i]){
    cout << -1 << endl;
    return;
  }
  cout << ans << endl;
}

