void solve(){
    cin >> n;
    a.resize(n,0);b.resize(n,0);
    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    while (true){
        flag=false;
        rep(i,n){
            ll k=b[(n+i-1)%n]+b[(n+i+1)%n];
            if (b[i]>=k){
                if (b[i]%k==a[i]%k) {
                    B+=(b[i]-a[i])/k;
                    b[i]=a[i];
                }
                else{
                    B+=b[i]/k;
                    b[i]=b[i]%k;
                    if (b[i]==0) {
                        b[i]+=k;
                        B-=1;
                    }
                }
                flag=true;
            }
        }
        if (!flag) break;
    }

    if (a==b) cout << B << endl;
    else cout << -1 << endl;

}

