const int N=2e5+5;

#define L(x) (x==1?n:x-1)
#define R(x) (x==n?1:x+1)

set< pair<int,int> > s;

int n,a[N],b[N];

void Wrong() {
	puts("-1");
	exit(0);
}

int main() {
	n=read();
	fo(i,1,n) a[i]=read();
	fo(i,1,n) b[i]=read();
	fo(i,1,n) s.insert(make_pair(-b[i],i));
	int ans=0;
	while (!s.empty()) {
		pair<int,int> tmp=*s.begin();s.erase(s.begin());
		int x=tmp.second,cnt=b[L(x)]+b[R(x)];
		if (b[x]<cnt) {
			if (a[x]!=b[x]) Wrong();
			continue;
		}
		if (b[x]<a[x]) Wrong();
		if (a[x]%cnt==b[x]%cnt) ans+=(b[x]-a[x])/cnt,b[x]=a[x];
		else {
			if (b[x]%cnt<a[x]) Wrong();
			ans+=b[x]/cnt;b[x]%=cnt;
			s.insert(make_pair(-b[x],x));
		}
	}
	printf("%d\n",ans);
	return 0;
}

