    int ans = 0;
    while(se.size())
    {
        auto it = se.end(); it--;
        int i = (*it).S, M = (*it).F;

        int left = i-1; if(left == 0) left = n;
        int right = i+1; if(right == n+1) right = 1;
        int x = B[left];
        int y = B[right];

        se.erase({B[i],i});
        if((A[i] % (x+y)) == (B[i] % (x+y)))
        {
            ans += (B[i] - A[i]) / (x+y);
            B[i] = A[i];
            continue;
        }

        if(B[i] <= (x+y)) kill();
        ans += B[i] / (x+y);
        B[i] %= (x+y);
        if(B[i] == 0) return cout<< -1, 0;
        se.insert({B[i],i});
    }
    cout<< ans;
}

