		que.emplace(b[i], i);
	}

	int ans = 0;
	while (not que.empty()) {
		auto [value, i] = que.top(); que.pop();
		int dis = value - (que.empty() ? a[i] : que.top().first);
		std::size_t ldx = (i == 0 ? n - 1 : i - 1);
		std::size_t rdx = (i == n - 1 ? 0 : i + 1);
		int vol = b[ldx] + b[rdx];
		int count = (dis + vol - 1) / vol;
		b[i] -= (count * vol);
		ans += count;
		if (b[i] < a[i]) { ans = -1; break; }
		if (b[i] > a[i]) que.emplace(b[i], i);
	}

	std::cout << ans << '\n';

	return 0;
}

