using namespace std;
typedef long long ll;
typedef pair<ll,int> P;

int n;
ll a[200005],b[200005];

P get(int pos){
	ll len=(b[(pos+1)%n]+b[(pos+n-1)%n]);
	ll rest=b[pos]-a[pos];
	ll l=1,r=(rest/len)+1;
	ll maxi=max(b[(pos+1)%n],b[(pos+n-1)%n]);
	while(l+1<r){
		ll mid=(l+r)/2LL;
		if(rest-len*mid>=maxi)l=mid;
		else{
			r=mid;
		}
	}
	return P(b[pos]-len*l,l);
}

int main(void){
	scanf("%d",&n);
	for(int i=0;i<n;i++){
		scanf("%lld",&a[i]);
	}
	priority_queue<P> que;
	for(int i=0;i<n;i++){
		scanf("%lld",&b[i]);
		if(b[i]!=a[i]){
			que.push(P(b[i],i));
		}
	}
	ll cnt=0;
	while(que.size()){
		P p=que.top();
		que.pop();
		ll nxt=b[p.second]-(b[(p.second+1)%n]+b[(p.second+n-1)%n]);
		if(nxt<a[p.second]){
			printf("-1\n");
			return 0;
		}
		P tmp=get(p.second);
		nxt=tmp.first;
		cnt+=tmp.second;
		b[p.second]=nxt;
		if(nxt>a[p.second]){
			que.push(P(nxt,p.second));
		}
	}
	printf("%lld\n",cnt);
	return 0;
}

