	int n;
	cin >> n;

	priority_queue<pair<int, int> > que;
	vector<int> a(n);
	vector<int> b(n);
	for(int i=0;i<n;i++){
		cin >> a[i];
	}
	for(int i=0;i<n;i++){
		cin >> b[i];
		if(b[i] > a[i])
			que.push(make_pair(b[i], i));
		else if(b[i] < a[i]){
			cout << -1 << endl;
			return 0;
		}
	}

	unsigned long long cnt = 0;
	while(!que.empty()){
		auto p = que.top(); que.pop();

		int i = p.second;
		int l = b[(i-1+n) % n], r = b[(i+1+n) % n];
		unsigned long long target = max(a[i], max(l, r));
		unsigned long long mod = l+r;
		int num = (p.first - target + mod - 1)/mod;
		int x = p.first - num*mod;
		cnt+=num;
		b[i] = x;

		if(x == a[i]){
			continue;
		}else if(x < a[i]){
			cout << -1 << endl;
			return 0;
		}
		que.push(make_pair(x, i));
