}

int main(){
    cin >> N;
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];

    priority_queue<P> q;
    rep(i, N){
        int a = i - 1;
        int b = i;
        int c = i + 1;
        if(a < 0) a = N - 1;
        if(N <= c) c = 0;

        if(A[b] < B[b] && B[a] + B[c] < B[b]) q.push( P(B[b], b) );
    }

    ll ans = 0;
    while(q.size()){

        P p = q.top();
        q.pop();

        int i = p.second;

        int a = i - 1;
        int b = i;
        int c = i + 1;
        if(a < 0) a = N - 1;
        if(N <= c) c = 0;

        ans += B[b] / (B[a] + B[c]);
        B[b] %= B[a] + B[c];

        int nc = c + 1;
        if(N <= nc) nc = 0;
        if(A[c] < B[c] && B[b] + B[nc] < B[c]) q.push( P(B[c], c) );

