int main(){
    int n;
    cin>>n;
    vector<ll> a(n);
    vector<ll> b(n);
    for(int i=0;i<n;i++) cin>>a[i];
    for(int i=0;i<n;i++) cin>>b[i];
    ll tar=accumulate(a.begin(),a.end(),0LL);
    ll sum=accumulate(b.begin(),b.end(),0LL);
    ll cnt=0;
    priority_queue<pair<ll,int>> que;
    for(int i=0;i<n;i++) que.push({b[i],i});
    while(tar<sum && !que.empty()){
        auto tmp=que.top(); que.pop();
        int i=tmp.second;
        if(b[i]==a[i]) continue;
        ll x=b[(i+n-1)%n]+b[(i+1)%n];
        if(b[i]-x<=0) break;
        ll sndv=max({b[(i+n-1)%n],b[(i+1)%n],a[i]});
        ll tm=(b[i]-sndv)/x;
        if(tm<=0) tm=1;
        b[i]-=x*tm;
        sum-=x*tm;
        cnt+=tm;
        if(b[i]<=0) break;
        que.push({b[i],i});
    }
    if(a==b){
        cout<<cnt<<endl;
    }
    else{
        cout<<-1<<endl;
    }

    return 0;
}

