  int N; 
  cin >> N;

  vector<int> A(N);
  REP(i, N) cin >> A[i];

  vector<int> B(N);
  REP(i, N) cin >> B[i];

  priority_queue<pair<int, int>> q;
  REP(i, N) q.push({B[i], i});

  int cnt = 0;
  while(!q.empty()){
    auto p = q.top(); q.pop();
    if(B[p.second]-B[(p.second+N-1)%N]-B[(p.second+1)%N] >= A[p.second]){
      int mi = B[(p.second+N-1)%N]+B[(p.second+1)%N];
      int now = (B[p.second]-A[p.second])/mi;
      B[p.second] -= now*mi;
      cnt += now;
      if(B[p.second] != A[p.second]) q.push({B[p.second], p.second});
    }
  }

  REP(i, N){
    if(A[i] != B[i]){
      cout << -1 << "\n";
      return 0;
    }
  }
  cout << cnt << "\n";

  return 0;
}

