	for (int i = 0; i < n; ++i) cin >> a[i];
	for (int i = 0; i < n; ++i) cin >> b[i];
	for (int i = 0; i < n; ++i) pq.push(make_pair(b[i], i));
	long long ans = 0;
	while (!pq.empty()) {
		int now = pq.top().second; pq.pop();
		int dif = b[now] - a[now];
		int tmp = b[(now - 1 + n) % n] + b[(now + 1) % n];
