uint mod = MOD;
struct Modint{
    uint num = 0;
    Modint(){}
    Modint(const Modint &x) : num(x.num){}
    inline operator ll() const { return num; }
    inline Modint& operator+=(Modint x){ num += x.num; if(num >= mod) num -= mod; return *this; }
    inline Modint& operator++(){ if(num == mod - 1) num = 0; else num++; return *this; }
    inline Modint operator++(int){ Modint ans(*this); operator++(); return ans; }
    inline Modint operator- () const { return Modint(0) -= *this; }
    inline Modint operator- (Modint x) const { return Modint(*this) -= x; }
    inline Modint& operator-=(Modint x){ if(num < x.num) num += mod; num -= x.num; return *this; }
    inline Modint& operator--(){ if(num == 0) num = mod - 1; else num--; return *this; }
    inline Modint operator--(int){ Modint ans(*this); operator--(); return ans; }
    inline Modint& operator*=(Modint x){ num = ull(num) * x.num % mod; return *this; }
    inline Modint& operator/=(Modint x){ return operator*=(x.inv()); }
    template<class T> Modint(T x){ x %= mod; if(x < 0) x += mod; num = uint(x); }
    template<class T> inline Modint operator+(T x) const { return Modint(*this) += x; }
    template<class T> inline Modint& operator+=(T x){ x %= mod; if(x < 0) x += mod; num += x; if(num >= mod) num -= mod; return *this; }
    template<class T> inline Modint operator- (T x) const { return Modint(*this) -= x; }
    template<class T> inline Modint& operator-=(T x){ return operator-=(Modint(x)); }
    template<class T> inline Modint operator* (T x) const { return Modint(*this) *= x; }
    template<class T> inline Modint& operator*=(T x){ return operator*=(Modint(x)); }
    template<class T> inline Modint operator/ (T x) const { return Modint(*this) /= x; }
    template<class T> inline Modint& operator/=(T x){ return operator/=(Modint(x)); }
    inline Modint inv() const { ll x = 0, y = 0; extgcd(num, mod, x, y); return x; }
    inline ll extgcd(ll a, ll b, ll &x, ll &y) const { ll g = a; x = 1; y = 0; if(b){ g = extgcd(b, a % b, y, x); y -= a / b * x; } return g; }
    inline Modint pow(ull x) const { Modint ans = 1, cnt = *this; while(x){ if(x & 1) ans *= cnt; cnt *= cnt; x /= 2; } return ans; }
};
