        int M = (i + N) % N;
        int R = (i + N + 1) % N;
        if (B[L] + B[R] < B[M] && B[M] > A[M]) {
            int times = (B[M] - A[M])/ (B[L] + B[R]);
            B[M] -= (B[L] + B[R]) * times;
            cnt += times;
            // rep(i, N) cout << B[i] << " ";
            // cout << endl;   
            REP(j, -1, 1) {
                int i2 = num.second + j + N*2;
                int L1 = (i2 + N - 1) % N;
                int M1 = (i2 + N) % N;
                int R1 = (i2 + N + 1) % N;
                pq.push({B[M1] - B[L1] - B[R1], M1});
            }
        }
    }
    rep(i, N) {
        if (B[i] != A[i]) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << cnt << endl;

    return 0;
}

