using namespace std;

int solve(lli n, vector<lli> const &before, vector<lli> const &after) {
  vector<lli> val = after;
  lli cnt = 0;
  while (true) {
    priority_queue<tuple<lli,lli>> que;
    lli s = 0;
    for (lli i = 0; i < n; ++i) {
      if (val[i]>before[i] && val[i] > val[(i-1+n)%n] + val[(i+1)%n]) {
        que.emplace(val[i], i);
      }
      if (before[i] == val[i]) { ++s; }
    }
    if (s == n) { break; }
    if (que.empty()) { return -1; }
    lli top, i; tie(top, i) = que.top();
    auto const dv = val[(i-1+n)%n] + val[(i+1)%n];
    if (dv <= 0) { return -1; }
    auto const m = min({
        (val[i]-before[i])/dv,
        (val[i]-val[(i-1+n)%n]+dv)/dv,
        (val[i]-val[(i+1)%n]+dv)/dv });
    val[i] -= m * dv;
    cnt += m;
  }
  return cnt;
}

