    cin >> N;
    REP(i, N) {
        cin >> A[i];
    }
    REP(i, N) {
        cin >> B[i];
    }
    priority_queue<pll, vector<pll>> q;
    REP(i, N) {
        q.push(pll(B[i], i));
    }

    ll ans = 0;
    while (!q.empty()) {
        pll t = q.top();
        q.pop();
        if (B[t.second] <= A[t.second])
