        if (B[t.second] <= 0 && B[t.second] + s == A[t.second]) {
            B[t.second] += s;
            ans--;
        }
        if (B[t.second] <= 0)
            break;
        q.push(pll(B[t.second], t.second));
    }

    REP(i, N) {
        if (A[i] != B[i]) {
            cout << -1 << endl;
            return 0;
        }
