vector<int> sim(vector<int> a) {
    int n = a.size();
    for (int i = 0; i < TIMES; i++) {
        int k = rnd() % n;
        for (int j : {-1, 1}) {
            int idx = (k + j + n) % n;
            a[k] += a[idx];
        }
    }
    return a;
}

int solve(vector<int> as, vector<int> bs) {
    int n = as.size();
    priority_queue<pair<int, int>> que;
    for (int i = 0; i < n; i++) que.emplace(bs[i], i);
    int cnt = 0;
    vector<bool> ok(n);
    while (!que.empty()) {
        auto top = que.top();
        que.pop();
        int v = top.first, i = top.second;
        if (v < as[i]) {
            exit(1);
            return -1;
        } else if (v == as[i]) {
            ok[i] = true;
            continue;
        }
        int yoko = 0;
        int nax = 0;
        for (int j : {-1, 1}) {
            int k = i + j;
            if (k < 0) k += n;
            if (k >= n) k -= n;
            yoko += bs[k];
            nax = max(nax, bs[k]);
        }
        if (v - yoko < as[i]) {
            exit(1);
            return -1;
        }
        if (as[i] >= nax) {
            int dif = v - as[i];
            if (dif % yoko) {
                exit(1);
                return -1;
            }
            cnt += dif / yoko;
            v -= dif;
            bs[i] = v;
            ok[i] = true;
            continue;
        }
        int dif = v - nax;
        int t = (dif + yoko - 1) / yoko;
        cnt += t;
        v -= yoko * t;
        if (v < as[i]) {
            exit(1);
            return -1;
        }
        bs[i] = v;
        que.emplace(v, i);
    }
    return cnt;
}

