inline char fgc()
{
    static char buf[1 << 20], *p1 = buf, *p2 = buf;
    return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1 << 20, stdin), p1 == p2) ? EOF : *p1++;
}

inline bool cmp(const Node &x, const Node &y)
{
    return x.b - x.a < y.b - y.a;
}

inline int read()
{
    char s;
    int res = 0, neg = 1;
    while (!isdigit(s = fgc()))
        if (s == '-')
            neg = -1;
    while (isdigit(s))
    {
        res = (res << 3) + (res << 1) + (s - '0');
        s = fgc();
    }
    return res * neg;
}

int main()
{
