void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<int> a(n), b(n);

	for (auto &it : a)
		cin >> it;

	priority_queue<pair<int, int>> pq;

	for (size_t i = 0; i < b.size(); i++)
	{
		cin >> b[i];

		if (b[i] < a[i])
		{
			cout << -1 << endl;

			return;
		}

		pq.emplace(b[i], i);
	}

	ll cnt = 0;

	while (!pq.empty())
	{
		int wh = pq.top().second;

		pq.pop();

		assert(b[wh] >= a[wh]);

		if (b[wh] > a[wh])
		{
			auto sub = b[wh == 0 ? n - 1 : wh - 1] + b[wh + 1 == n ? 0 : wh + 1];

			if (sub > b[wh])
			{
				cout << -1 << endl;

				return;
			}

			if ((b[wh] - a[wh]) % sub == 0)
			{
				cnt += (b[wh] - a[wh]) / sub;
				b[wh] = a[wh];
			}
			else
			{
				cnt += b[wh] / sub;
				b[wh] %= sub;
			}

			if (b[wh] < a[wh])
			{
				cout << -1 << endl;

				return;
			}

			pq.emplace(b[wh], wh);
		}
	}

	cout << cnt << endl;
}


