    for (int i = 0; i < n; ++i)
        pq.push({b[i], i});
    int ans = 0;
    while (!pq.empty()) {
        pair<int, int> here = pq.top();
        pq.pop();
        int p = b[mod(here.second - 1, n)];
        int q = b[mod(here.second, n)];
        int r = b[mod(here.second + 1, n)];
        if (q <= (p + r))
            continue;
        ans += q / (p + r);
        q %= (p + r);
        b[here.second] = q;
