using namespace std;

const int Nmax = 2e5 + 5;

queue<int> q;
int a[Nmax], b[Nmax];
int n, nr_op = 0;
bool inQ[Nmax];


static int nxt(int x)
{
    return (x < n ? x + 1 : 1);
}

static int prv(int x)
{
    return (x > 1 ? x - 1 : n);
}

void check(int i)
{
    if(!inQ[i] && b[i] - (b[prv(i)] + b[nxt(i)]) >= a[i])
        q.push(i), inQ[i] = 1;
}

void solve()
{
    int i;
    for(i=1; i<=n; ++i)
        check(i);

    while(q.size())
    {
        int x = q.front();
        q.pop();
        inQ[x] = 0;

        int curr = (b[x] - a[x]) / (b[prv(x)] + b[nxt(x)]);
        assert(curr);
        nr_op += curr;
        b[x] -= curr * (b[prv(x)] + b[nxt(x)]);

        check(x);
        check(nxt(x));
        check(prv(x));
    }

    for(i=1; i<=n; ++i) 
        if(a[i] != b[i]) 
        {
            cout << -1 << '\n';
            return;
        }

    cout << nr_op << '\n';
}

