struct Order{
  lint idx;
  lint B;
  bool operator < (const Order &other) const { return B < other.B; }
};
int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  lint N;
  cin >> N;
  vector<lint> A(N);
  vector<lint> B(N);
  REP(i, N) cin >> A[i];
  REP(i, N) cin >> B[i];
  multiset<Order> ms;
  REP(i, N) {
    if(A[i] < B[i]) {
      Order o;
      o.idx = i;
      o.B = B[i];
      ms.insert(o);
    }
  }
  int ans = 0;
  while(!ms.empty()) {
    Order o = *prev(ms.end(), 1);
    ms.erase(prev(ms.end(), 1));
    lint num = (B[o.idx] - B[(o.idx-1+N)%N] - B[(o.idx+1)%N] - 1) / (B[(o.idx-1+N)%N] + B[(o.idx+1)%N]) + 1;
    if(num <= 0) {
      cout << -1 << endl;
      return 0;
    }
    B[o.idx] -= num * (B[(o.idx-1+N)%N] + B[(o.idx+1)%N]);
    ans += num;
    if(B[o.idx] < A[o.idx]) {
      cout << -1 << endl;
      return 0;
    } else if(B[o.idx] > A[o.idx]) {
      o.B = B[o.idx];
      ms.insert(o);
    }
  }
