    for (int i = 0; i < n; i++) {
        cin >> b[i];
        v.emplace_back(b[i], i);
    }

    SegmentTree<P> st(v, P(0, -1));
    ll ans = 0;
    while (true) {
        P tar = st.query_fast(0, n);
        //cerr << tar.second << " " << tar.first << endl;
        if (a[tar.second] > tar.first) {
            ans = -1;
            break;
        }

        if (a[tar.second] == tar.first) {
            st.update(tar.second, P(-a[tar.second], tar.second));
            continue;
        }

        int il = (tar.second + n - 1) % n;
        int ir = (tar.second + 1) % n;
        ll lv = abs(st.getLeaf(il).first);
        ll rv = abs(st.getLeaf(ir).first);

        ll hoge = max(a[tar.second], lv + rv);
        //cerr << tar2.first << endl;
        st.update(tar.second, tar);

        ll cnt = (tar.first - hoge + (lv + rv) * (a[tar.second] < hoge)) / (lv + rv);
        ans += cnt;
        ll val = tar.first - cnt * (lv + rv);
        if (val == a[tar.second]) {
            st.update(tar.second, P(-a[tar.second], tar.second));
        } else {
            st.update(tar.second, P(val, tar.second));
        }

        P tar3 = st.query_fast(0, n);
        //cerr << tar3.first << ": " << tar3.second << endl;
        if (tar3.second == tar.second) {
