      cout << -1 << endl;
      return 0;
    }
    if (b[i] > a[i]) {
      pq.push(ii(b[i], i));
    } else {
      done[i] = 1;
    }
  }
  while (!pq.empty()) {
    ii fst = pq.top(); pq.pop();
    int sec_val = 0;
    if (!pq.empty()) {
      ii scnd = pq.top();
      sec_val = scnd.first;
    }
    int i = fst.second;
    int i_min = (i + n - 1) % n;
    int i_add = (i + 1) % n;
    while (b[i] > a[i] && (b[i] > sec_val || (done[i_min] && done[i_add]) || (b[i] > b[i_min] && b[i] > b[i_add]))) {
      int sub_fac = max(min((b[i] - a[i]) / (b[i_min] + b[i_add]), min((b[i] - b[i_min]) / (b[i_min] + b[i_add]), (b[i] - b[i_add]) / (b[i_min] + b[i_add]))), 1);
      if (done[i_min]) {
        sub_fac = max(sub_fac, min((b[i] - a[i]) / (b[i_min] + b[i_add]), (b[i] - b[i_add]) / (b[i_min] + b[i_add])));
      }
      if (done[i_add]) {
        sub_fac = max(sub_fac, min((b[i] - a[i]) / (b[i_min] + b[i_add]), (b[i] - b[i_min]) / (b[i_min] + b[i_add])));
      }
      if (done[i_min] && done[i_add]) {
        sub_fac = max(sub_fac, (b[i] - a[i]) / (b[i_min] + b[i_add]));
      }
      if (b[i] - sub_fac * (b[i_min] + b[i_add]) < a[i]) {
        cout << -1 << endl;
        return 0;
      } else {
        b[i] -= sub_fac * (b[i_min] + b[i_add]);
