int main(){
	int a;scanf("%d",&a);
	for(int i=0;i<a;i++)scanf("%d",p+i);
	for(int i=0;i<a;i++)scanf("%d",q+i);
	long long ret=0;
	while(1){
		bool chg=false;
		bool dame=false;
		for(int i=0;i<a;i++){
			if(p[i]>q[i]){
				dame=true;break;
			}
			if(q[i]>q[(i-1+a)%a]+q[(i+1)%a]){
				int am=q[i]%(q[(i-1+a)%a]+q[(i+1)%a]);
				if(am>=p[i]){
					ret+=q[i]/(q[(i-1+a)%a]+q[(i+1)%a]);
					q[i]=am;
					chg=true;
				}else if((q[i]-p[i])%(q[(i-1+a)%a]+q[(i+1)%a])==0){
					ret+=(q[i]-p[i])/(q[(i-1+a)%a]+q[(i+1)%a]);
					q[i]=p[i];
					chg=true;
				}else{
					dame=true;break;
				}
			}
		}
		if(dame){
			ret=-1;break;
		}
