ll solver2(vector<ll>A,vector<ll>B){
    int N = (int)A.size();
    ll res = 0;

    for(int i = 0; i < N;i++){
        B[i] -= A[i];
        A[i] = 0;
        if(B[i] < 0) return -1;
    }

    priority_queue<pll> pq;
    for(int i = 0; i < N;i++){
        if(A[i] == B[i]) continue;
        pq.push(pll(B[i],i));
    }
    while(pq.size()){
        ll max1,id1; tie(max1,id1) = pq.top(); pq.pop();
        ll max2 = -LINF,id2 = -1;
        if(pq.size()){
            tie(max2,id2) = pq.top();pq.pop();
        }

        ll S = B[(id1-1+N)%N] + B[(id1+1+N)%N];
        if(max1 == max2){
            res++;
            B[id1] -= S;
        }else{
            ll C = ((max1-max(A[id1],max2))+S-1)/S;
            res+=C;
            B[id1] -= S*C;
        }
        if(max2 != -LINF){
            pq.push(pll(B[id2],id2));
        }
        if(B[id1] < A[id1]) return -1;
        if(B[id1] == A[id1]) continue;
        pq.push(pll(B[id1],id1));
    }
    return res;
}

template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> A(N),B(N);

    for(auto& in:A) cin >> in;
    for(auto& in:B) cin >> in;
    return solver2(A,B);
}

