        if (pi == -1) pi = n - 1;
        if (ni == n) ni = 0;
        long long x = b[pi] + b[ni];
        long long y = max(b[pi], b[ni]);
        long long cnt = min((b[i] - a[i]) / x, (b[i] - y) / x + 1);
        if (!cnt)
        {
            cout << -1 << endl;
            return 0;
        }
        ans += cnt;
        b[i] -= cnt * x;
        if (b[i] > a[i])
            q.push(make_pair(b[i], i));
    }
    cout << ans << endl;
    return 0;
}

