class CNumbersOnACircle {
public:
    void solve(std::istream& in, std::ostream& out) {
        int N;
        in >> N;
        vector<ll> A(N), B(N);
        REP(i,0,N) in >> A[i];
        REP(i,0,N) in >> B[i];

        priority_queue<pair<int,int>, vector<pair<int,int>>> que;
        REP(i,0,N) {
            if (B[i] == A[i]) continue;
            else if (B[i] < A[i]) {
                out << -1 << "\n";
                return;
            }
            que.push({B[i], i});
        }

        int answer = 0;
        while (!que.empty()) {
            auto p = que.top();
            que.pop();
            const int index = p.second;
            auto& current = B[index];

            const auto& previous = B[(index - 1 + N) % N];
            const auto& next = B[(index + 1) % N];

            if (previous + next >= current) {
                assert(false);
            }

            ll lowerValue = max(A[index], previous + next);

            const int cnt = max(1LL, (current - lowerValue) / (next + previous));
            current -= cnt * (next + previous);
            answer += cnt;

            if (current < A[index]) {
                out << -1 << "\n";
                return;
            } else if (A[index] < current) {
                que.push({current, index});
            }
        }
        if (A == B) {
            out << answer << "\n";
        } else {
            out << -1 << "\n";
        }
    }
};


