        }
    }

    int128_t ret = 0;
    while (pq.size()) {
        auto p = pq.top();
        pq.pop();

        int128_t prev = (p.second - 1 + N) % N;
        int128_t next = (p.second + 1) % N;

        int128_t num = (B[p.second] - std::max({B[prev], B[next], A[p.second]})) / (B[prev] + B[next]);
        assert(0 <= num);
        //int num = (B[p.second] - std::max({pq.top().first, A[p.second]})) / (B[prev] + B[next]);

        B[p.second] -= (B[prev] + B[next]) * num;
