class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long N, std::vector<long long> A, std::vector<long long> B)
{
    priority_queue<pair<int, int>> q;

    for (int i = 0; i < N; i++)
    {
        q.push(make_pair(B[i], i));
    }
    ll ans = 0;
    while (!q.empty())
    {
        int now = q.top().second;
        q.pop();
        int dif = B[now] - A[now];
        int tmp = B[(now - 1 + N) % N] + B[(now + 1) % N];

        if (dif != 0 && dif < tmp)
        {
            ans = -1;
            break;
        }
        ans += dif / tmp;
        B[now] -= dif / tmp * tmp;
        if (B[now] != A[now])
            q.push(make_pair(B[now], now));
    }

    cout << ans << endl;
    return;
}

