const int maxn=3e5+10;
int a[maxn],b[maxn],n;
priority_queue<pair<int,int>> s;
long long ans;

int main(){
    scanf("%d",&n);
    for(int i=0;i<n;i++){
        scanf("%d",&a[i]);
    }
    for(int i=0;i<n;i++){
        scanf("%d",&b[i]);
        s.push({b[i],i});
    }
    int l,r;
    while(!s.empty()){
        auto it=s.top();
        if(it.first==a[it.second]){
            s.pop();
            continue;
        }
        int l=((it.second)-1);
        if(l<0)l=n-1;
        int r=(l+2);
        if(r>=n)r-=n;
        int sum=(b[l]+b[r]);
        if(b[it.second]<sum||b[it.second]-sum<a[it.second]){
            return !printf("-1");
        }
        if(a[it.second]>sum){
            if((b[it.second]-a[it.second])%sum)
                return !printf("-1");
            ans+=(b[it.second]-a[it.second])/sum;
            b[it.second]=a[it.second];
            s.pop();continue;
        }
        ///find the first number that is in form of
        ///b-sum*k<=sum sum*(k+1)>=b
        int cur=b[it.second]/sum-(b[it.second]%sum==0?1:0);
        b[it.second]-=sum*cur;
        ans+=cur;
        s.pop();
        s.push({b[it.second],it.second});
    }
    printf("%lld\n",ans);
}
