		else if (b[i] == b[i + 1] || b[i] == b[i - 1] || b[i] < a[i]) {
			pos = false;
			break;
		}
		else if (b[i] > b[i + 1] && b[i] > b[i - 1]) {
			picos.push(i);
		}
