struct HEAPDATA {
	int pos, val;
	bool operator<(const HEAPDATA &rhs) const {
		return val < rhs.val;
	}
};
int g(int pos) {
	return b[(pos+n)%n];
}
int max3(int v1, int v2, int v3) {
	return max(v1, max(v2, v3));
}
int main() {
	cin>>n;
	for (int i=0; i<n; i++)
		cin>>a[i];
	for (int i=0; i<n; i++)
		cin>>b[i];
	priority_queue<HEAPDATA> heap;
	for (int i=0; i<n; i++) {
		if (b[i] < a[i]) {
			cout<<-1<<endl;
			return 0;
		}
		if (b[i] > a[i])
			heap.push(HEAPDATA{i, b[i]});
	}

	long long ans = 0;
	for (int i=heap.top().pos; heap.size()>0; i=heap.top().pos){
		heap.pop();
		int decrment = g(i-1) + g(i+1);
		int allowdelta = b[i] - max3(g(i-1), a[i], g(i+1));
		int allowmulti = allowdelta / decrment + (allowdelta%decrment?1:0);
		b[i] -= decrment*allowmulti;
		// cout<<"b["<<i<<"] == "<<b[i]<<" \tby decr="<<decrment<<"*"<<allowmulti<<"  (heapsize="<<heap.size()<<endl;
		if (b[i] < a[i]) {
			cout<<-1<<endl;
			return 0;
		}
		ans += (long long)allowmulti;
		if (b[i] > a[i])
			heap.push(HEAPDATA{i, b[i]});
	}
	cout<<ans<<endl;
	return 0;
}

