const int INF = 1.01e9;

int solve(int n, vector<int> a, vector<int> b) {
    set<pair<int, int>> st;
    for (int i = 0; i < n; i++) st.insert({b[i], i});

    int ans = 0;
    while (!st.empty()) {
        auto it = st.rbegin();
        int i = it->second;
        st.erase(*it);
        if (b[i] == a[i]) continue;
        else if (b[i] < a[i]) return -1;
        else if (b[i] > a[i]) {
            b[i] -= b[(i - 1 + n) % n];
            b[i] -= b[(i + 1) % n];
            st.insert({b[i], i});
            ans++;
        } else assert(0);
    }
    return ans;
}

