				ans+=(b[x]-a[x])/(b[(x+n-2)%n+1]+b[x%n+1]);
				b[x]=a[x];
			}
		}
		else{
			ans+=b[x]/(b[(x+n-2)%n+1]+b[x%n+1]);	
			b[x]%=(b[(x+n-2)%n+1]+b[x%n+1]);
			if(b[x]<a[x]){write("-1\n");return 0;}
			else if(b[x]>a[x])p.push(make_pair(b[x],x));
		}
	}
	write(ans,'\n');

	return 0;
}

