int index_max(int a[],int num){
	int max=a[0];
	int index=0;
	for(int i=1;i<num;i++){
		if(max<a[i]){
			max=a[i];
			index=i;
		}
	}
	return index;
}

int side(int a[],int p,int num){
	if(p==0){
		return a[num-1]+a[1];
	}else if(p==num-1){
		return a[num-2]+a[0];
	}else{
		return a[p-1]+a[p+1];
	}
}

void show(int a[],int num){
	for(int i=0;i<num;i++){
		cout<<a[i]<<" ";
	}
	cout<<endl;
}

int cheack(int a[],int b[],int num){
	for(int i=0;i<num;i++){
		if(a[i]!=b[i])return 0;
	}
	return 1;
}

