#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

int64_t min_val = INT64_MAX;

int64_t solve(const vector<int64_t>& as, vector<int64_t>& bs, int n, int64_t c)
{
	if (c >= min_val) return INT64_MAX;

	bool has_diff = false;
	FOR_LT(i, 0, n) {
		if (as[i] != bs[i]) {
			has_diff = true;
			break;
		}
	}
	if (!has_diff) {
		min_val = c;
		return c;
	}

	int64_t ans = INT64_MAX;

	if (bs[n - 1] + bs[1] < bs[0]) {
		int64_t d = bs[n - 1] + bs[1];
		bs[0] -= d;
		ans = min(ans, solve(as, bs, n, c + 1));
		bs[0] += d;
	}
	FOR_LE(i, 1, n - 2) {
		if (bs[i - 1] + bs[i + 1] < bs[i]) {
			int64_t d = bs[i - 1] + bs[i + 1];
			bs[i] -= d;
			ans = min(ans, solve(as, bs, n, c + 1));
			bs[i] += d;
		}
	}
	if (bs[n - 2] + bs[0] < bs[n - 1]) {
		int64_t d = bs[n - 2] + bs[0];
		bs[n - 1] -= d;
		ans = min(ans, solve(as, bs, n, c + 1));
		bs[n - 1] += d;
	}

	return ans;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;

	vector<int64_t> as(n);
	for (auto& a : as) {
		cin >> a;
	}
	vector<int64_t> bs(n);
	for (auto& b : bs) {
		cin >> b;
	}

	int64_t ans = solve(as, bs, n, 0);
	if (ans != INT64_MAX) {
		cout << ans << endl;
	}
	else {
		cout << -1 << endl;
	}

	return 0;
}

