template <typename T, typename... Tail>
auto make_v(T init, size_t s, Tail... tail) {
#define rec make_v(init, tail...)
    return V<decltype(rec)>(s, rec);
#undef rec
}

ll solve() {
    ll N;
    cin >> N;
    V<ll> A(N), B(N);
    for(auto &&e : A) cin >> e;
    for(auto &&e : B) cin >> e;
    priority_queue<PLL> pq;
    for(ll i = 0; i < N; i++) pq.emplace(B[i], i);
    ll ret = 0;
    while(pq.size()) {
        ll val, idx;
        tie(val, idx) = pq.top();
        pq.pop();
        ll l = B[(idx + N - 1) % N], r = B[(idx + 1) % N];
        if(val < l + r) break;
        if(val < A[idx]) break;
        ll div = min(val / (l + r), (val - A[idx]) / (l + r));
        ret += div;
        val -= div * (l + r);
        B[idx] = val;
        if(A[idx] < val) pq.emplace(val, idx);
    }
    return A == B ? ret : -1;
}

int main() {
    cout << solve() << endl;
    return 0;
}

