		tmp=c[le(u)]+c[re(u)];
		if(q.empty()){
			if((c[u]-a[u])%tmp!=0) return puts("-1"),0;
			ans+=(c[u]-a[u])/tmp; c[u]=a[u]; break;
		}
		int t=(c[u]-max(max(c[le(u)],c[re(u)]),a[u]))/tmp;t=max(t,1ll);
		c[u]-=t*tmp; ans+=t;
		if(c[u]<a[u]) return puts("-1"),0;
		if(c[u]>a[u]) q.push(make_pair(c[u],u));
	}
	cout<<ans;
	return 0;
}

