int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N;
  cin >> N;
  vector<i64> A(N), B(N);
  for (auto& x : A) cin >> x;
  for (auto& x : B) cin >> x;

  auto solve = [&]() {
    REP(i, N - 1) {
      if (B[i] == B[i + 1]) return -1;
    }
    REP(i, N) {
      if (B[i] < A[i]) return -1;
    }
    priority_queue<pair<i64, int>> pq;
    int ok_cnt = 0;
    REP(i, N) {
      if (B[i] > A[i]) {
        pq.emplace(B[i], i);
      } else {
        ok_cnt++;
      }
    }
    int step = 0;
    while (pq.size()) {
      i64 btop = pq.top().first;
      int bix = pq.top().second;
      pq.pop();
      ++step;
      assert(B[bix] == btop);
      int l = (bix - 1 + N) % N;
      int r = (bix + 1) % N;
      B[bix] -= B[l] + B[r];
      if (B[bix] < A[bix]) return -1;
      if (B[bix] == A[bix]) {
        ok_cnt++;
      } else {
        pq.emplace(B[bix], bix);
      }
    }
    assert(ok_cnt == N);
    return step;
  };
  cout << solve() << endl;
}

