#define OUT(v) cout<<v<<endl

int main() {
  IN(N);

  vi A(N), B(N);
  REP(i, N) {
    cin >> A[i];
  }
  priority_queue<pii> q;
  bool cannot = false;
  REP(i, N) {
    cin >> B[i];
    if (B[i] < A[i]) {
      cannot = true;
    }
    q.push(make_pair(B[i], i));
  }
  if (cannot) {
    OUT(-1);
    return 0;
  }
  ll ans = 0;
  while(!q.empty()) {
    ++ans;
    pii p = q.top(); q.pop();
    int index = p.second;
    B[index] -= B[(index-1+N) % N] + B[(index+1+N) % N];
    if (B[index] < A[index]) {
      OUT(-1);
      return 0;
    }
    if (B[index] > A[index])
      q.push(make_pair(B[index], index));
  }
  OUT(ans);

  return 0;
}

