int N;

int mod(int a){
    if(a < 0) return a + N;
    if(a == N) return 0;
    return a;
}

int main(){
    cin >> N;
    vector<ll> A(N), B(N);
    priority_queue<pair<ll,ll>> PQ;
    for(int i = 0; i < N; i++) cin >> A[i];
    for(int i = 0; i < N; i++) cin >> B[i];
    for(int i = 0; i < N; i++ ) PQ.push({B[i],i});
    ll ans = 0;
    bool flag = 1;

    while(!PQ.empty()){
        auto e = PQ.top(); PQ.pop();
        if(B[e.second] == A[e.second]) continue;
        ll sum = B[mod(e.second-1)] + B[mod(e.second + 1)];
        ll cnt =  (B[e.second]-A[e.second])  / sum;
        if(cnt == 0) continue;

        B[e.second] -= cnt * sum;
        ans += cnt;

        if(B[e.second] < A[e.second]){flag = 0; break; }
        else if(B[e.second] == A[e.second]) continue;
        else PQ.push({B[e.second], e.second});
    }
    for (int i = 0; i < N; ++i) {
        if (A[i] != B[i]) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;
    //else cout << -1 << endl;
}

