#include <bits/stdc++.h>
using namespace std;
#define ll long long

ll next(ll i, ll n) {
	if (i == n - 1) return 0;
	else return i + 1;
}

ll prev(ll i, ll n) {
	if (i == 0) return n - 1;
	else return i - 1;
}

int main() {
	ll n;
	cin >> n;
	vector<ll> a(n), b(n), c(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
	}
	for (ll i = 0; i < n; i++) {
		cin >> b[i];
	}

	ll ans = 0, fin = 0, miss = 0;
	vector<bool> finished(n);
	for (ll i = 0; i < n; i++) finished[i] = false;

	for (ll i = 0;; i = next(i, n)) {
		if (fin == n || miss == n) break;
		if (!finished[i]) {
			ll ne = next(i, n), pr = prev(i, n);
			if (b[i] - b[ne] - b[pr] > 0) {
				miss = 0;
				ans += b[i] / (b[ne] + b[pr]);
				b[i] = b[i] % (b[ne] + b[pr]);
				if (b[i] == a[i]) { finished[i] = true; fin++; }
				else if (b[i] < a[i]) miss = n;
			}
			else miss++;
		}
	}

	if (miss == n) cout << -1 << endl;
	else cout << ans << endl;

	return 0;
}

