#define MAX_N 200000
using namespace std;

int main(void) {
  int N;
  cin >> N;
  //N = MAX_N;
  int64_t A[MAX_N];
  rep(i, N) { cin >> A[i]; }
  //rep(i, N) { A[i] = 1; }

  int64_t B[MAX_N];
  rep(i, N) { cin >> B[i]; }
  //rep(i, N) { B[i] = (i % 2) ? MAX_N : 1; }
  int64_t C[MAX_N];
  queue<int> queC;
  rep(i, N) { queC.push(i); }

  int64_t Ans = 0;
  while (1) {
    if (queC.empty())
      break;
    while (!queC.empty()) {
      auto item = queC.front();
      queC.pop();
      if (item == 0) {
        C[N - 1] = B[N - 1] - B[N - 2] - B[0];
        C[0] = B[0] - B[1] - B[N - 1];
        C[item + 1] = B[item + 1] - B[item + 0] - B[item + 2];
      } else if (item == 1) {
        C[0] = B[0] - B[1] - B[N - 1];
        C[item + 0] = B[item + 0] - B[item + 1] - B[item - 1];
        C[item + 1] = B[item + 1] - B[item + 0] - B[item + 2];
      } else if (item == (N - 1)) {
        C[item - 1] = B[item - 1] - B[item + 0] - B[item - 2];
        C[N - 1] = B[N - 1] - B[N - 2] - B[0];
        C[0] = B[0] - B[N - 1] - B[1];
      } else if (item == (N - 2)) {
        C[item - 1] = B[item - 1] - B[item + 0] - B[item - 2];
        C[item + 0] = B[item + 0] - B[item + 1] - B[item - 1];
        C[N - 1] = B[N - 1] - B[N - 2] - B[0];
      } else {
        C[item - 1] = B[item - 1] - B[item + 0] - B[item - 2];
        C[item + 0] = B[item + 0] - B[item + 1] - B[item - 1];
        C[item + 1] = B[item + 1] - B[item + 0] - B[item + 2];
      }
    }

    rep(i, N) {
      if (C[i] >= A[i]) {
        int64_t diff = B[i] - C[i];
        int d = (B[i] - A[i]) / (diff);
        Ans += d;
        B[i] = B[i] - diff * d;
        // B[i] = C[i];
        C[i] = 0;
        queC.push(i);
      }
    }
  }
  bool possible = true;
  rep(i, N) {
    if (A[i] != B[i]) {
      // cout << "i=" << i << " A=" <<A[i] << " B=" << B[i] << endl;
      possible = false;
      break;
    }
  }
  if (possible == false) {
    cout << "-1" << endl;
  } else {
    cout << Ans << endl;
  }
  return 0;
}

