			if(b[i]<a[i])
			{
				cout<<"-1";
				exit(0);
			}
			if(b[i]>(b[prev]+b[nxt]))
			{
				fl=1;						
				res+=((b[i]-a[i])/(b[prev]+b[nxt]));
				b[i]=((b[i])%(b[prev]+b[nxt]));	
				if(b[i]==0)
					b[i]=a[i];			
			}
		}
		if(a==b)
			break;
		if(!fl)
			break;		
	}
	if(a!=b)
		cout<<"-1";
	else
		cout<<res;
}

