int mod_pow(int x, int n, int mod) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % mod;
		x = 1LL*x * x % mod;
		n >>= 1;
	}
	return res;
}

typedef vector<vector<Edge>> Graph;
template< unsigned mod >
struct RollingHash {
	vector< unsigned > hashed, power;
	unsigned base = 10007;

	inline unsigned mul(unsigned a, unsigned b) const {
		return (1LL * a * b) % mod;
	}

	RollingHash(const string& s) {
		int sz = (int)s.size();
		hashed.assign(sz + 1, 0);
		power.assign(sz + 1, 0);
		power[0] = 1;
		for (int i = 0; i < sz; i++) {
			power[i + 1] = mul(power[i], base);
			hashed[i + 1] = mul(hashed[i], base) + s[i];
			if (hashed[i + 1] >= mod) hashed[i + 1] -= mod;
		}
	}

	unsigned get(int l, int r) const {
		unsigned ret = hashed[r] + mod - mul(hashed[l], power[r - l]);
		if (ret >= mod) ret -= mod;
		return ret;
	}


	unsigned connect(unsigned h1, unsigned h2, ll h2len) const {
		unsigned ret = mul(h1, mod_pow(base, h2len, mod)) + h2;
		if (ret >= mod) ret -= mod;
		return ret;
	}

	unsigned powstr(unsigned h2, int h2len, ll ts) const {
		if (ts == 0) return 0;

		unsigned han = powstr(h2, h2len, ts / 2);

		unsigned ret = connect(han, han, h2len * (ts/2));
		if (ts % 2)
			ret = connect(ret, h2, h2len);

		return ret;
	}

	/*unsigned powstr(unsigned h2, int h2len, ll ts) const {
		unsigned ret = 0;

		REP(i, ts)
			ret = connect(ret, h2, h2len);

		return ret;
	}*/

	int LCP(const RollingHash< mod >& b, int l1, int r1, int l2, int r2) {
		int len = min(r1 - l1, r2 - l2);
		int low = -1, high = len + 1;
		while (high - low > 1) {
			int mid = (low + high) / 2;
			if (get(l1, l1 + mid) == b.get(l2, l2 + mid)) low = mid;
			else high = mid;
		}
		return (low);
	}
};

