    for (auto &&b : B) { is >> b; } // end b

    segtree segB(N);
    for (int i = 0; i < N; ++i) {
        segB.update(i, B[i]);
    } // end i

    ll K = 0;
    while(true){
        auto big = segB.max();
        int it = big.second;
        if(B[it] <= A[it]) break;
        int next, prev;
        next = it+1; next %= N;
        prev = it-1; prev += prev < 0 ? N : 0;

        B[it] -= B[prev] + B[next];
        if(B[it] < A[it]) break;
        segB.update(it, B[it]);
        K++;
    }

    for (int i = 0; i < N; ++i) {
        if(A[i] != B[i]){
            cout << -1 << endl;
            return;
        }
    } // end i
