ll N;
vector<ll> A;
vector<ll> B;

void solve() {
	scanf("%lld", &N);
	A.assign(N, 0);
	rep(i, N) scanf("%lld", &A[i]);
	B.assign(N, 0);
	rep(i, N) scanf("%lld", &B[i]);

	priority_queue<pair<ll,ll>> q;
	rep(i,N)if(A[i]!=B[i])q.push({B[i],i});

	ll ans = 0;
	vector<pair<ll,ll>> v(N,{-1,-1});

	while(!q.empty()){
		pair<ll,ll> p=q.top();q.pop();
		ll r=p.second+1;
		if(r>=N)r-=N;
		ll l=p.second-1;
		if(l<0)l+=N;
		if(B[p.second]-A[p.second] >= B[l]+B[r]){
			ll t=(B[p.second]-A[p.second])/(B[l]+B[r]);
			B[p.second]-=t*(B[l]+B[r]);
			ans+=t;
			if(B[p.second]>A[p.second])q.push({B[p.second],p.second});

			if(v[r].second!=-1){
				q.push(v[r]);
				v[r]={-1,-1};
			}
			if(v[l].second!=-1){
				q.push(v[l]);
				v[l]={-1,-1};
			}
		}else{
			v[p.second]=p;
		}

	}

	rep(i,N){
		if(v[i].second!=-1){
			printf("-1\n");return;
		}
	}
	printf("%lld\n", ans);

}

