void solve() {
  int n;
  cin >> n;
  vi32 a(n);
  vi32 b(n);
  cin >> a >> b;
  using T = tuple<int, int>;
  pqdesc<T> q;
  rep(i, n) {
    q.emplace(b[i], i);
  }
  i64 ans = 0;
  while (sz(q)) {
    int _, i;
    tie(_, i) = q.top();
    q.pop();
    int prev = (i - 1 + n) % n;
    int next = (i + 1) % n;
    int div = b[prev] + b[next];
    int c = (b[i] - max(div, a[i]) + div - 1) / div;
    if (c <= 0) continue;
    b[i] -= div * c;
    ans += c;
    if (a[i] >= b[i]) continue;
    q.emplace(b[i], i);
  }
  if (a == b) {
    cout << ans << endl;
  } else {
    cout << -1 << endl;
  }
}

