    vector<ll> A(N + 1), B(N + 1);
    repn(i, N) cin >> A[i];
    repn(i, N) cin >> B[i];

    priority_queue<pair<ll,ll>> p;
    repn(i, N) p.push({B[i],i});

    ll ans = 0;
    while (!p.empty()) {
        auto x = p.top();
        p.pop();
        ll i = x.second;

        ll T= B[i % N + 1] + B[(i + N - 2) % N + 1];

        if (B[i] >= A[i] && (B[i] - A[i]) % T == 0) {
            ans += (B[i] - A[i]) / T;
            B[i] = A[i];
        }

        else {
            if (T > B[i]) { ans = -1; break; }
            ans += B[i] / T;
            B[i] %= T;
            p.push({ B[i],i });
            if (B[i] < A[i]) { ans = -1;  break; }
        }

