template<typename tp> inline void read(tp &x) {
    x = 0; char c = getchar(); int f = 0;
    for (; c < '0' || c > '9'; f |= c == '-', c = getchar());
    for (; c >= '0' && c <= '9'; x = (x << 3) + (x << 1) + c - '0', c = getchar());
    if (f) x = -x;
}
#define int long long
const int N = 3e5 + 233;
int a[N], b[N], n;
inline int F(int x) { return b[x] - a[x]; } 
inline int get(int x) {
	if (!x) x = n; if (x == n + 1) x = 1;
	return b[x];
}
inline int G(int x) { return get(x - 1) + get(x + 1); } 
struct node_t {
	int id;
	friend bool operator < (node_t x, node_t y) {
		return make_pair(F(x.id) - G(x.id), x.id) > make_pair(F(y.id) - G(x.id), y.id);
	}
};
set <node_t> s;

signed main(void) {
	read(n);
	rep (i, n) read(a[i]);
	rep (i, n) read(b[i]);
	rep (i, n) if (F(i)) s.insert((node_t) {i});
	int ans = 0;
	while (!s.empty()) {
		node_t u = *s.begin(); s.erase(s.begin());
		int la = F(u.id), per = G(u.id);
		if (la < per) return cout << -1 << "\n", 0;
		int cnt = floor((long double) la / per);
		b[u.id] -= cnt * per;
		ans += cnt;
		function <void(int)> re = [&](int u) {
			node_t t = (node_t) {u};
			if (s.count(t)) s.erase(t);
			if (F(u)) s.insert(t);
		};
		re(get(u.id - 1)); re(get(u.id + 1)); re(u.id);
	}
	cout << ans << "\n";
}

