void solve(void)
{
  using std::string;
  using std::vector;
  using std::map;
  using std::pair;
  using std::cin;
  using std::cout;
  ui N{}; std::cin >> N;
  vector<ll> A(N), B(N);
  rep(0, N) cin >> A[i];
  rep(0, N) cin >> B[i];

  typedef pair<ui, ll> Pair;
  auto cmp = [](Pair p1, Pair p2){ return p1.second < p2.second; };
  std::priority_queue<Pair, vector<Pair>, decltype(cmp)> queue(cmp);
  rep(0, N)
  {
    if(B[i] > A[i])
    {
      queue.push({i, B[i]});
    }
  }

  ll ans = queue.empty() ? -1 : 0;
  while(!queue.empty())
  {
    Pair p = queue.top();
    queue.pop();
    auto curr = p.first;
    auto back = (p.first + N - 1) % N;
    auto next = (p.first + 1) % N;
    while (B[curr] != A[curr] && B[curr] > B[next] + B[back])
    {
      B[curr] -= B[back] + B[next];
      ++ans;
    }
    if(B[curr] < A[curr] || B[curr] == p.second)
    {
      ans = -1;
      break;
    }
    if(B[curr] > A[curr])
    {
      queue.push({curr, B[curr]});
    }
  }

  cout << ans << '\n';
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

