using Pll = pair<ll, ll>;

int main() {
  cin.tie(0);
  int N;
  cin >> N;
  vector<ll> A(N), B(N);
  FOR(i, N) cin >> A[i];
  FOR(i, N) cin >> B[i];
  priority_queue<Pll> can;
  FOR(i, N) {
    if (B[i] >= A[i]) can.push(Pll(B[i], i));
  }
  ll ans = 0;
  while (!can.empty()) {
    Pll p = can.top();
    int i = p.second;
    can.pop();
    ll bunbo = (B[i == 0 ? N - 1 : i - 1] + B[i == N - 1 ? 0 : i + 1]);
    ll num = p.first - A[i];
    ans += num / bunbo;
    num %= bunbo;
    if (B[i] == A[i] + num) {
      print(-1);
      return 0;
    }
    B[i] = A[i] + num;
    if (B[i] > A[i]) can.push(Pll(B[i], i));
  }
  FOR(i, N) {
    if (A[i] != B[i]) {
      print(-1);
      return 0;
    }
  }
  print(ans);
  return 0;
}

