void solve() {
    int n; cin >> n;
    vi a(n), b(n);
    FOR(i, 0, n) cin >> a[i];
    FOR(i, 0, n) cin >> b[i];
    set<pi> st;
    FOR(i, 0, n) st.insert(mp(b[i], i));
    long long res = 0;
    while (sz(st)) {
        int u = st.rbegin()->se;
        st.erase(*st.rbegin());
        int pu = (u + n - 1) % n;
        int nu = (u + 1) % n;
        if (b[u] < a[u]) {
            cout << -1 << "\n";
            return;
        }
        if (a[u] < b[u]) {
            int s = b[pu] + b[nu];
            int x = (b[u] - a[u]) / s;
            chkmin(x, (b[u] - b[nu]) / s + 1);
            chkmin(x, (b[u] - b[pu]) / s + 1);
            if (!x) {
                cout << -1 << "\n";
                return;
            }
            res += x;
            b[u] -= s * x;
            if (b[u] < a[u]) {
                cout << -1 << "\n";
                return;
            }
            if (a[u] < b[u]) {
                st.insert(mp(b[u], u));
            }
        }
    }
    cout << res << "\n";
}

