			ans += bs[i] / d;
			bs[i] = c;
		}

		if (bs[i] == as[i]) {
			ce++;
		}

		update(as, bs, n, i + 1, move_idx);
		update(as, bs, n, i - 1, move_idx);
	}

	cout << ans << endl;

	return 0;
}

