ll solver4(vector<ll> A,vector<ll> B){
    int N = (int)A.size();
    ll res = 0;

    priority_queue<pll> pq;

    vector<int> flag(N);
    function<bool(bool)> rec = [&](bool f){
        if(f){
            for(int i = 0; i < N;i++){
                if(A[i] == B[i]){
                    if(pq.size()){
                        if(!rec(false)) return false;
                    }
                    continue;
                }
                pq.push(pll(B[i],i));
            }
            if(!rec(false)) return false;
            return true;
        }

        int cnt = 0;
        while(pq.size()){
            if(cnt++ > 50) break;
            ll max1,id1; tie(max1,id1) = pq.top(); pq.pop();
            ll max2 = -LINF,id2 = -1;
            if(pq.size()){
                tie(max2,id2) = pq.top();pq.pop();
            }

            ll S = B[(id1-1+N)%N] + B[(id1+1+N)%N];
            if(max1 == max2){
                res++;
                B[id1] -= S;
            }else{
                ll C = ((max1-max(A[id1],max2))+S-1)/S;
                res+=C;
                B[id1] -= S*C;
            }
            if(max2 != -LINF){
                pq.push(pll(B[id2],id2));
            }
            if(B[id1] < A[id1]) return false;
            if(B[id1] == A[id1]) continue;
            pq.push(pll(B[id1],id1));
        }

        if(pq.size()){
            for(int i = 0; i < N;i++){
                if(A[i] == B[i]){
                    if(pq.size()){
                        if(!rec(false)) return false;
                    }
                    continue;
                }
                pq.push(pll(B[i],i));
            }
        }
        return true;
    };
    if(!rec(true)) return -1;
    return res;
}

