        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long N, std::vector<long long> A, std::vector<long long> B)
{
    ll sumAll = accumulate(B.begin(), B.end(), 0);
    ll sumA = accumulate(A.begin(), A.end(), 0);

    ll ans = 0;
    while (1)
    {
        bool allFalse = true;
        for (int i = 0; i < N; i++)
        {
            ll sum = 0;
            if (i == 0)
            {
                sum += B[i + 1] + B[N - 1];
            }
            else if (i == N - 1)
            {
                sum += B[i - 1] + B[0];
            }
            else
            {
                sum += B[i - 1] + B[i + 1];
            }

            if (sum < B[i])
            {
                B[i] -= sum;
                sumAll -= sum;
                ans++;
                allFalse = false;
                break;
            }
        }
        if (allFalse)
        {
            break;
        }
    }

    if (sumA == sumAll)
    {
        cout << ans << endl;
        return;
    }
    else
    {
        cout << -1 << endl;
        return;
    }
}

