  cin.tie(0);
  ios::sync_with_stdio(0);
  int N;
  cin >> N;
  int A[N], B[N];
  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < N; i++) cin >> B[i];
  auto next = [&](int i) { return (i + 1) % N; };
  auto prev = [&](int i) { return (i - 1 + N) % N; };
  SegmentTree<Mono> seg(N);
  for (int i = 0; i < N; i++) {
    int n = next(i), p = prev(i);
    seg.unsafe_set(i, {B[i] - B[p] - B[n], i});
  }
  seg.rebuild();
  int ans = 0;
  while (true) {
    auto res = seg.query(0, N);
    if (res.first <= 0) break;
    int i = res.second;
    int n = next(i), p = prev(i);
    while (B[i] > B[n] + B[p]) {
      ans++;
      B[i] -= B[n] + B[p];
    }
    seg.set_val(i, {B[i] - B[p] - B[n], i});
    seg.set_val(n, {B[n] - B[i] - B[next(n)], n});
    seg.set_val(p, {B[p] - B[i] - B[prev(p)], p});
  }
  cout << ans << '\n';
  return 0;
}

