	A.resize(N);
	B.resize(N);
	for (int i = 0; i < N; ++i)
		cin >> A[i];
	for (int i = 0; i < N; ++i) {
		s.insert(lpair(B[i], i));
		cin >> B[i];
	}

	bool is_change = true;
	llong ans = 0;
	while (is_change) {
		is_change = false;
		auto s_end = s.end();
		for (auto it = s.begin(); it != s_end; ++it) {
			int id = it->second;
