        same[i] = (a[i] == b[i]);
    }
    auto push = [&](int i) {
        int sum = b[(i - 1 + n) % n] + b[(i + 1) % n];
        if (sum < b[i] and !same[i]) q.push(i);
    };
    rep(i, n) push(i);
    ll ans = 0;
    while (q.size()) {
        int i = q.front();
        q.pop();
        int sum = b[(i - 1 + n) % n] + b[(i + 1) % n];
        if (sum >= a[i]) {
