	ll a[200010], b[200010];
	rep(i, n)
		cin >> a[i];
	priority_queue<pll> q;
	rep(i, n) {
		cin >> b[i];
		q.push({ b[i],i });
	}
	ll rs = 0;
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		auto i = p.second;
		auto bf = (i + n - 1) % n;
		auto nx = (i + 1) % n;
		auto v = b[bf] + b[nx];
		auto ma = max({ a[i],b[bf],b[nx] });
		auto inter = (b[i] - ma);
		auto d = inter / v;
		if (inter % v > 0) {
			d++;
		}

		rs += d;
		b[i] -= d * v;
		if (b[i] < a[i]) {
			cout << -1 << endl;
			return;
		}

		if (b[i] > a[i]) {
			q.push({ b[i],i });
		}
	}
	cout << rs << endl;
}



