  i64 sumA = accumulate(begin(A), end(A), 0LL);
  i64 sumB = accumulate(begin(B), end(B), 0LL);

  set<pair<i64, int>> S;
  for (auto i = 0u; i < B.size(); ++i) {
    S.emplace(B[i], i);
