                  (B[i] - A[i]) / (l + r));
      if (k <= 0) return -1;

      ret += k;

      sumB -= k * (l + r);
      B[i] -= k * (l + r);

      if (B[i] <= 0) return -1;
      S.emplace(B[i], i);
    }

