void rec(ll depth, vector<int> &state) {
  dump(state, depth);
  if(state == A) {
    cout << depth << endl;
    exit(0);
  }
  if(state.size() == 0) {
    cout << -1 << endl;
    exit(0);
  }
  auto tmp = vector<int>(N);
  copy(ALL(state), tmp.begin());
  REP(i, N) {
    int prev = i - 1;
    int next = i + 1;
    if(i == 0) {
      prev = N - 1;
    }
    if(i == N - 1) {
      next = 0;
    }
    if(state[prev] + state[next] < state[i]) {
      tmp[i] = tmp[i] - state[prev] - state[next];
      rec(depth + 1, tmp);
    }
  }
  cout << -1 << endl;
  exit(0);
}

