using namespace std;

int main(){
	long long n, imax, vmax, ileft, iright, t;
	long long cnt = 0;
	cin >> n;
	vector<long long> a(n);
	vector<long long> b(n);
	priority_queue<pair<long long, long long>> pq;
	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	for(int i=0; i<n; i++){
		cin >> b[i];
		if(b[i] != a[i]){
			pq.push({b[i], i});
		}
	}

	while(!pq.empty()){
		vmax = pq.top().first;
		imax = pq.top().second;
		pq.pop();

		if(imax != n-1){
			iright = imax+1;
		}else{
			iright = 0;
		}
		if(imax != 0){
			ileft = imax-1;
		}else{
			ileft = n-1;
		}

		if(vmax%(b[ileft]+b[iright])==a[imax]){
			cnt += (vmax-a[imax])/(b[ileft]+b[iright]);
			b[imax] = a[imax];
			continue;
		}

		if(vmax-a[imax] <= (b[ileft]+b[iright])){
			cout << -1 << endl;
			return 0;
		}

		t = (vmax-a[imax])/(b[ileft]+b[iright]);
		cnt += t;
		b[imax] -= t*(b[ileft]+b[iright]);
		pq.push({b[imax], imax});
	}
	cout << cnt << endl;
	return 0;
}

