#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll,int> pr; // val, id
int N;
ll A[200001],B[200001];

int getPrev(int x){
    return (x-1+N)%N;
}
int getNext(int x){
    return (x+1)%N;
}
set<pr> tmp;
ll cnt=0;
int main(void){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N;
    for(int i=0;i<N;i++){
        cin >> A[i];
    }

    for(int i=0;i<N;i++){
        cin >> B[i];
    }
    for(int i=0;i<N;i++){
        if (B[i] < A[i]){
            cout << -1 << endl;
             return 0;
        }
        if (B[i]!=A[i]) tmp.insert({B[i], i});
    }
    while(tmp.size()>0){
        auto it = tmp.end();
        it--;
        int id = it->second;
        ll val = it->first;
        int prev = getPrev(id);
        int nxt = getNext(id);
        tmp.erase(it);
        ll nxtval = A[id];
        if(tmp.size()>0){ // get the next smallest value
            it = tmp.end();
            it--;
            nxtval = it->first;
            if(nxtval <= A[id]){ // need to resolve directly
                if ((val-A[id])%(B[prev]+B[nxt])!=0){
                    cout << -1 << endl;
                    return 0;
                }
                cnt += (val-A[id])/(B[prev]+B[nxt]);
                B[id] = A[id]; // no need to add it back
                continue;
            }else{ // make it smaller than nxtval
                cnt += (val-nxtval)/(B[prev] + B[nxt]);
                B[id] = (val-nxtval)%(B[prev] + B[nxt]) + nxtval;
                if(B[id]>=nxtval){
                    B[id] = B[id] - B[prev] - B[nxt];
                    cnt++;
                }
                if (B[id] < A[id]){
                    // cout << "id: " << id << endl;
                    cout << -1 << endl;
                    return 0;
                }
                if (B[id] > A[id]){
                    tmp.insert({B[id], id});
                }                
            }
        }else{ // last 1 has to resolve
            if ((val-A[id])%(B[prev]+B[nxt])!=0){
                cout << -1 << endl;
                return 0;
            }
            cnt += (val-A[id])/(B[prev]+B[nxt]);
            break;
        }
    }
    cout << cnt << endl;
    return 0;
}

