int main()
{
	int n;
	cin >> n;

	priority_queue<pair<int, int> > que;

	vector<int> a(n);
	vector<int> b(n);
	for(int i=0;i<n;i++){
		cin >> a[i];
	}
	for(int i=0;i<n;i++){
		cin >> b[i];
		que.push(make_pair(b[i], i));
	}

	int cnt = 0;
	while(!que.empty()){
		auto p = que.top(); que.pop();
		if(p.first == a[p.second]){
			continue;
		}else if(p.first < a[p.second]){
			break;
		}

		int i = p.second;
		int target = max(a[i], max(b[(i-1+n) % n], b[(i+1) % n]));
		int mod = b[(i-1+n) % n]+b[(i+1) % n];
		int x = p.first - ((p.first - target + mod - 1)/mod)*mod;
		b[i] = x;
		que.push(make_pair(x, i));
		cnt+=((p.first - target + mod - 1)/mod);
	}

	bool ans = true;
	for(int i=0;i<n;i++){
		if(a[i] != b[i]){
			ans = false;
			break;
		}
	}
	if(ans){
		cout << cnt << endl;
	}else{
		cout << -1 << endl;
	}
	return 0;
}

