	long long best = 0;
	while (match != n) {
		for (int i = 0; i < n; i++) {
			int j = (i - 1 + n) % n;
			int k = (i + 1) % n;
			int sum = b[j] + b[k];
			if (b[i] - sum < a[i]) {
				continue;
			}
			if (sum > best) {
				best = sum;
				bestIndex = i;
			}
		}
		if (best == 0) {
			return -1;
		}
		b[bestIndex] -= best;
		if (b[bestIndex] == a[bestIndex]) {
			match++;
		}
		count++;
		best = 0;
	}
	return count;
}

