int a[200000];
int b[200000];

int main() {
    int n, i;
    long long ans = 0;
    priority_queue <pair<int, int>> q;

    scanf("%d", &n);

    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    for (i = 0; i < n; i++) scanf("%d", &b[i]);

    for (i = 0; i < n; i++) q.push(make_pair(b[i], i));

    while (!q.empty()) {
        int x = q.top().second, l, r, c;

        q.pop();

        if (b[x] < a[x]) {
            puts("-1");
            return 0;
        } else if (b[x] == a[x]) {
            continue;
        }

        l = (x - 1 + n) % n;
        r = (x + 1) % n;

        if (b[x] <= b[l] + b[r]) {
            puts("-1");
            return 0;
        }

        c = (b[x] - a[x]) / (b[l] + b[r]);

        if (c == 0) {
            puts("-1");
            return 0;
        }

        ans += c;
        b[x] -= (b[l] + b[r]) * c;

        q.push(make_pair(b[x], x));
    }

    printf("%lld\n", ans);

    return 0;
}

