int N;
int A[200010], B[200010];

int calc(int *a, int n) {
    int cnt = 0;
    priority_queue<pii> q;
    REP(i, n) q.emplace(a[i], i);
    while (!q.empty()) {
        int v, p;
        tie(v, p) = q.top();
        q.pop();
        int sum = a[(p + n - 1) % n] + a[(p + 1) % n];
        if (sum > 0 && a[p] > sum) {
            cnt += a[p] / sum;
            a[p] %= sum;
            q.emplace(a[p], p);
        }
    }
    return cnt;
}

