const int max_n = 200222, inf = 1000111222;

int n, a[max_n], b[max_n];

int triv() {
    int res = 0;
    while (true) {
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            if (a[i] != b[i]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return res;
        }
        int pos = 0;
        for (int i = 0; i < n; ++i) {
            if (b[i] > b[pos]) {
                pos = i;
            }
        }
        int sum = b[(pos + n - 1) % n] + b[(pos + 1) % n];
        if (b[pos] <= sum) {
            return -1;
        }
        b[pos] -= sum;
        ++res;
    }
}

long long solve() {
    long long res = 0;
    set<pair<int, int>> q;
    for (int i = 0; i < n; ++i) {
        q.insert({b[i], i});
    }
    while (!q.empty()) {
        pair<int, int> p = *q.rbegin();
        q.erase(p);
        int pos = p.second;
        if (p.first < a[pos]) {
            return -1;
        }
        if (p.first == a[pos]) {
            continue;
        }
        int x = b[(pos + n - 1) % n];
        int y = b[(pos + 1) % n];
        //cout << "$" << pos << " " << x << " " << y << endl;
        if (b[pos] <= x + y) {
            return -1;
        }
        int c = b[pos] % (x + y);
        res += b[pos] / (x + y);
        if (c < a[pos]) {
            if ((a[pos] - c) % (x + y)) {
                return -1;
            }
            res -= (a[pos] - c) / (x + y);
            c = a[pos];
        }
        b[pos] = c;
        //cout << "$ " << pos << " " << b[pos] << endl;
        q.insert({b[pos], pos});
    }
    return res;
}

