  bool Flag = 0;
  vector<int32_t>::iterator PrevMaxI, FollMaxI, MaxI;

  while (A != B) {
    MaxI = max_element(B.begin(), B.end());
    if (MaxI == B.begin()) {
      PrevMaxI = B.end() - 1;
      FollMaxI = MaxI + 1;
    } else if (MaxI == (B.end() - 1)) {
      PrevMaxI = MaxI - 1;
      FollMaxI = B.begin();
    } else {
      PrevMaxI = MaxI - 1;
      FollMaxI = MaxI + 1;
    }
    *MaxI -= (*PrevMaxI + *FollMaxI);
    if (*MaxI < 0) {
      Flag = true;
      break;
    }
    ++res;
  }
  if (Flag) {
    cout << "-1" << endl;
  } else {
    cout << res << endl;
  }
}

