int n;
vector<int> a, b;
lint result;

void apply(int i) {
  int prev = i > 0 ? i - 1 : n - 1;
  int next = i + 1 < n ? i + 1 : 0;
  while (b[prev] > b[i] || b[next] > b[i]) {
    if (b[prev] > b[i])
      apply(prev);
    if (b[next] > b[i])
      apply(next);
  }
  int delta = b[prev] + b[next];
  int step_count = (b[i] - a[i]) / delta;
  if (step_count <= 0) {
    printf("-1\n");
    exit(0);
  }
  result += step_count;
  b[i] -= step_count * delta;
}

