int Bdec_all(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if ((Btmp[i] - A[i]) % Bnei == 0)
	{
		anstmp += (Btmp[i] - A[i]) / Bnei;
		if((Btmp[i] - A[i]) / Bnei > 0)
			anychange = 1;
		Btmp[i] = A[i];
	}
	else
	{
		anstmp += Btmp[i] / Bnei;
		if (Btmp[i] / Bnei > 0)
			anychange = 1;
		Btmp[i] %= Bnei;
	}
	if (Btmp[i] < A[i])
		return -1;
	return Btmp[i];
}

int Bdec(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if (Btmp[i] > A[i])
	{
		Btmp[i] -= Bnei;
		anstmp++;
	}
	return Btmp[i];
}

bool Btop(int i, vector<int> Btmp)
{
	if (Btmp[i] > (Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N]))
		return true;
	return false;
}

void DP()
{
	priority_queue<pair<ll, int>, vector<pair<ll, int> >, less<pair<ll, int> > > Bque;
	for (int i = 0; i < N; i++)
		Bque.push(make_pair(B[i], i));
	while (1)
	{
		anychange = 0;
		while(1)
		{
			pair<ll, int> Btmp = Bque.top();
			int i = Btmp.second;
			if (Btop(i, B))
			{
				Bque.pop();
				B[i] = Bdec_all(i, B);
				if (B[i] == -1)
				{
					ansmin = -1;
					return;
				}
				Bque.push(make_pair(B[i], i));
			}
			else
				break;
		}
		if (B == A)
		{
			ansmin = anstmp;
			return;
		}
		if (!anychange)
		{
			ansmin = -1;
			return;
		}
	}
	return;
}

