void solve() {
	int n; cin >> n;
	vector<ll> a(n), b(n);
	priority_queue<tuple<ll, ll, int>> pque;
	rep(i, n) {
		cin >> a[i];
	}
	rep(i, n) {
		cin >> b[i];
		if(b[i] != a[i]) pque.push(make_tuple(b[i], a[i], i));
	}
	int cnt = 0;
	while(pque.size()) {
		cnt ++;
		tuple<ll, ll, int> t = pque.top(); pque.pop();
		tuple<ll, ll, int> tnext = pque.top();
		int pos = get<2>(t); ll bnext = 0;
		bnext = get<0>(tnext);
