    rep(i, N) cin >> B[i];
    ll ans = 0;
    queue<int> que;
    rep(j, N){
        int i = (j+N-1)%N, k = (j+1)%N;
        if(B[j] > B[i]+B[k]) que.push(j);
    }
    while(!que.empty()){
        int j = que.front();
        que.pop();
        int i = (j+N-1)%N, k = (j+1)%N;
