                ans += B[j]/S-1;
                B[j] = S;
            }
            else{
                ans += B[j]/S;
                B[j] %= S;
            }
        }
        que.push(i), que.push(k);
    }
    bool res = true;
    rep(i, N) if(A[i] != B[i]) res = false;
