  bool is_crct=true;
  int count = 0;

  for(int i=0;i<n;i++){
    scanf("%ld", &a[i]);
    flags[i] = true;
  }
  for(int i=0;i<n;i++){
    scanf("%ld", &b[i]);
  }

  while(num_flgs>0){
    long tmp=-100;
    size_t max_idx = -1;
    for(int i=0;i<n;i++){
      if(!(tmp>b[i]*flags[i])){
