      continue;
    }
    tmp = b[max_idx] - (b[GET_IDX(max_idx+1,n)] + b[GET_IDX(max_idx-1,n)]);
    if(tmp<=0){
      is_crct = false;
      break;
    }
    b[max_idx] = tmp;
    count++;
  }

  if(is_crct){
