typedef long long ll;
const int N = 2e5+100;
struct node{ int x,v; };
bool operator < (node a,node b){ return a.v<b.v; }

int a[N],b[N],n; ll ans;
bool check(){
    priority_queue<node> Q;
    for(int i=0;i<n;++i) Q.push((node){i,b[i]});
    while(!Q.empty()){
        node cur=Q.top(); Q.pop();
        if(a[cur.x]<b[cur.x]){
            int l=cur.x-1; if(l<0) l+=n;
            int r=cur.x+1; if(r>=n) r-=n;
            int up=b[l]+b[r];
            if(up>=b[cur.x]) return false;
            ans+=(b[cur.x]-a[cur.x])/up;
            b[cur.x]-=(b[cur.x]-a[cur.x])/up*up;
        }
        if(a[cur.x]<b[cur.x]) Q.push((node){cur.x,b[cur.x]});
    }
    for(int i=0;i<n;++i) if(b[i]!=a[i]) return false;
    return true;
}
