#include <bits/stdc++.h>

using namespace std;
#define int64 long long

const int N_MAX = 200010;

int A[N_MAX], B[N_MAX];
int nNum;

inline int nextIndex(int i) {
	return i < nNum ? i + 1 : 1;
}

inline int prevIndex(int i) {
	return i > 1 ? i - 1 : nNum;
}

bool reducible(int i) {
	return B[i] - A[i] >= B[nextIndex(i)] + B[prevIndex(i)];
}

void outerInit() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	auto fi = new ifstream("test.inp");
	if (*fi) {
		cin.rdbuf(fi->rdbuf());
	}
}

void readData() {
	cin >> nNum;
	for (int i = 1; i <= nNum; ++i) cin >> A[i];
	for (int i = 1; i <= nNum; ++i) cin >> B[i];
}

void solveData() {
	queue<int> reducibleIndices;
	for (int i = 1; i <= nNum; ++i) {
		if (reducible(i)) {
			reducibleIndices.push(i);
		}
	}

	int64 result = 0;
	while (!reducibleIndices.empty()) {
		int i = reducibleIndices.front();
		reducibleIndices.pop();
		if (!reducible(i)) continue;

		int in = nextIndex(i);
		int ip = prevIndex(i);
		int ac = B[in] + B[ip];
		int nStep = (B[i] - A[i]) / ac;
		result += nStep;
		B[i] -= nStep * ac;

		if (reducible(in)) {
			reducibleIndices.push(in);
		}
		if (reducible(ip)) {
			reducibleIndices.push(ip);
		}
	}

	for (int i = 1; i <= nNum; ++i) {
		if (A[i] != B[i]) {
			cout << "-1\n";
			return;
		}
	}

	cout << result << "\n";
}

int main() {
	outerInit();

	readData();
	solveData();
}

