        cin >> b[i];
        pq.push({b[i], i});
    }
    int ans = 0;
    while (!pq.empty()) {
        pair<int, int> here = pq.top();
        pq.pop();
        int p = b[(here.second + n - 1) % n];
        int q = b[here.second];
        int r = b[(here.second + 1) % n];
        if (q <= (p + r))
            continue;
        ans += q / (p + r);
        q %= (p + r);
        b[here.second] = q;
        pq.push({q, here.second});
    }
