struct QST{
	int i,b;
};
bool operator < (const QST &a,const QST &b) {return a.b<b.b;}

int n,a[maxn],b[maxn];
ULL hs[maxn];
priority_queue<QST> Q;

int main()
{
	scanf("%d",&n);
	fo(i,1,n) scanf("%d",&a[i]);
	fo(i,1,n) scanf("%d",&b[i]);

	hs[0]=1;
	fo(i,1,n) hs[i]=hs[i-1]*P;
	ULL hsa=0, hsb=0;
	fo(i,1,n) hsa+=hs[i]*a[i], hsb+=hs[i]*b[i];

	fo(i,1,n) Q.push((QST){i,b[i]});
	int ans=0;
	while (!Q.empty() && hsa!=hsb)
	{
		QST tp=Q.top(); Q.pop();
		int i=tp.i;
		if (b[i]>a[i] && b[i]>=b[i%n+1]+b[(i==1)?n:i-1])
		{
			int sum=b[i%n+1]+b[(i==1)?n:i-1];
			if (a[i]>sum && (b[i]-a[i])%sum!=0) {ans=-1; break;}
			int d=min(b[i]-a[i],b[i]-b[i]%sum);
			hsb=hsb-b[i]*hs[i]+(b[i]-d)*hs[i];
			b[i]-=d;
			ans+=d/sum;
			if (hsa==hsb) break;
			Q.push((QST){i,b[i]});
		}
