int main(){
    ll N; cin >> N;
    vector<ll> A(N); rep(i, N) cin >> A[i];
    vector<ll> B(N); rep(i, N) cin >> B[i];

    cauto check = [&](ll i){
        ll mi = (i - 1 + N) % N; // i - 1
        ll pi = (i + 1) % N;     // i + 1

        if(A[i] > B[i]){
            cout << -1 << endl;
            exit(EXIT_SUCCESS);
        }

        return B[i] - B[mi] - B[pi] > 0 and B[i] > A[i];
    };

    // pair<ll, ll> = (B[i], i)
    priority_queue<pair<ll, ll>> pq;

    rep(i, N){
        ll mi = (i - 1 + N) % N; // i - 1
        ll pi = (i + 1) % N;     // i + 1

        if(check(i)){
            pq.emplace(B[i], i);
        }
    }

    ll ans = 0;
    while(not pq.empty()){
        cauto i = pq.top().second; pq.pop();
        ll mi = (i - 1 + N) % N; // i - 1
        ll pi = (i + 1) % N;     // i + 1

        ll op = B[mi] + B[pi];
        ans += (B[i] - A[i]) / op;
        B[i] = B[i] % op;

        if(check(i)) pq.emplace(B[i], i);
        if(check(mi)) pq.emplace(B[mi], mi);
        if(check(pi)) pq.emplace(B[pi], pi);
    }

    cout << ans << endl;

    return 0;
}

