// セグ木
template<typename T,typename F,T UNIT>
struct ST{
  int size;
  vector<T> seg;
  F func;

  ST(int N,F func): func(func){
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
    build();
  }

  ST(const vector<T> &v,F func) : func(func){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.resize(2 * size);
    // set
    for(int i=0;i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k,T& x){
    seg[k + size] = x;
  }

  void build(){
    for(int k=size-1; k>0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1]);
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1]);
    }
  }

  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

int main(){
  ini(N); 
  vl A(N) , B(N);
  in(A); in(B);
  auto f = [](ll a,ll b){
    return max(a , b);
  };
  ST<ll , decltype(f) , -1LL> st(B , f);
  ll cnt = 0;
  while(st.query(0 , N) != -1){
    // nibutan
    int l = 0 , r = N;
    while(l + 1 < r){
      int med = (l + r) / 2;
      if(st.query(l,med) < st.query(med,r)) l = med;
      else r = med;
    }
    int idx = l;

    if(B[idx] == A[idx]){
      st.update(idx , -1);
    }
    else if(B[idx] <= B[(idx+1)%N] + B[(idx+N-1)%N]){
      die("-1");
    }
    else{
      while(A[idx] != B[idx] && B[idx] > B[(idx+1)%N] && B[idx] > B[(idx+N-1)%N]){
        if(B[idx] <= B[(idx+1)%N] + B[(idx+N-1)%N]) die("-1");
        B[idx] -= B[(idx+1)%N] + B[(idx+N-1)%N];
        cnt++;
      }
      st.update(idx , B[idx]);
    }
  }
  out(cnt);
}

