typedef pair<int, int> ii;

int a[200001], b[200001], n;
bitset<200001> done;

int main() {
  int num_op = 0;
  ios_base::sync_with_stdio(false);
  cin >> n;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> b[i];
  }
  priority_queue<ii> pq;
  for (int i = 0; i < n; i++) {
    if (b[i] < a[i]) {
      cout << -1 << endl;
      return 0;
    }
    if (b[i] > a[i]) {
      pq.push(ii(b[i], i));
    } else {
      done[i] = 1;
    }
  }
  while (!pq.empty()) {
    ii fst = pq.top(); pq.pop();
    int sec_val = 0;
    if (!pq.empty()) {
      ii scnd = pq.top();
      sec_val = scnd.first;
    }
    int i = fst.second;
    int i_min = (i + n - 1) % n;
    int i_add = (i + 1) % n;
    while (b[i] > a[i] && (b[i] > sec_val || (done[i_min] && done[i_add]) || (b[i] > b[i_min] && b[i] > b[i_add]))) {
      if (b[i] - (b[i_min] + b[i_add]) < a[i]) {
        cout << -1 << endl;
        return 0;
      } else {
        b[i] -= (b[i_min] + b[i_add]);
        num_op++;
      }
    }
    if (b[i] > a[i]) {
      pq.push(ii(b[i], i));
    } else {
      done[i] = 1;
    }
  }
  cout << num_op << endl;
  return 0;
}

