void solve() {
	int n; cin >> n;
	vector<ll> a(n), b(n);
	priority_queue<tuple<ll, ll, int>> pque;
	rep(i, n) {
		cin >> a[i];
	}
	rep(i, n) {
		cin >> b[i];
		if(b[i] != a[i]) pque.push(make_tuple(b[i], a[i], i));
	}
	ll cnt = 0;
	while(pque.size()) {
		tuple<ll, ll, int> t = pque.top(); pque.pop();
		int pos = get<2>(t);
		ll minus = b[(pos - 1 + n) % n] + b[(pos + 1) % n];
		ll c = (b[pos] - max(b[(pos - 1 + n) % n], b[(pos + 1) % n])) / minus;
		b[pos] -= minus * (c >= 1 ? c : 1LL);
		cnt += (c >= 1 ? c : 1LL);
		if(b[pos] > a[pos]) pque.push(make_tuple(b[pos], a[pos], pos));
		if(b[pos] < a[pos]) {
			cout << -1 << endl;
			return;
		}
	}
	cout << cnt << endl;
}

