int main(int argc, char const* argv[])
{
  int n;
  cin >> n;
  vector<ll> a(n), b(n);
  cin >> a >> b;
  queue<int> q;
  rep(i, n){
    int l = (i + n - 1) % n;
    int r = (i + 1) % n;
    if(b[i] > b[l] + b[r]){
      q.push(i);
    }
  }
  ll res = 0;
  while(!q.empty()){
    auto p = q.front(); q.pop();

    int l = (p + n - 1) % n;
    int r = (p + 1) % n;
    ll tmp = b[p] / (b[l] + b[r]);
    res += tmp;
    b[p] -= tmp * (b[l] + b[r]);
    if(b[p] < a[p]){
      cout << -1 << endl;
      return 0;
    }

    int l_l = (l + n - 1) % n;
    if(b[p] + b[l_l] < b[l])q.push(l);
    int r_r = (r + 1) % n;
    if(b[p] + b[r_r] < b[r])q.push(r);
  }
  rep(i, n){
    if(a[i] != b[i]){
      cout << -1 << endl;
      return 0;
    }
  }
  cout << res << endl;
  return 0;
}

