    vector<int> a(n), b(n);
    for(int i=0;i<n;i++) cin >> a[i];
    for(int i=0;i<n;i++) cin >> b[i];
    for(int i=0;i<n;i++) ms.insert({b[i], i});
    while(!ms.empty()){
    	auto itr = ms.end();
    	itr--;
    	if(itr->first == a[itr->second]){
    		ms.erase(itr);
