#include <bits/stdc++.h>

using namespace std;

const int N = 500 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
long long A[N], B[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> A[i];

    for (int i = 0; i < n; ++i)
        cin >> B[i];

    return true;
}

void solve() {
    set< pair<long long, int> > Q;
    auto check = [] (int i, set< pair<long long, int> >& Q) {
        (i += n) %= n;
        auto a = B[(n + i - 1) % n];
        auto b = B[i];
        auto c = B[(i + 1) % n];

        if (b > a + c)
            Q.insert(make_pair(b, i));
    };

    for (int i = 0; i < n; ++i)
        check(i, Q);

    auto ans = 0ll;

    while (!Q.empty()) {
        auto i = Q.rbegin()->second;
        Q.erase(--Q.end());
        auto d = B[(n + i - 1) % n] + B[(i + 1) % n];
        auto k = (B[i] - A[i]) / d;
        B[i] -= k * d;
        ans += k;
        check(i - 1, Q);
        check(i + 1, Q);
    }

    for (int i = 0; i < n; ++i)
        if (A[i] != B[i]) {
            cout << -1 << endl;
            return ;
        }

    cout << ans << endl;
}

