void func(long long N, std::vector<long long> A, std::vector<long long> B){

    priority_queue<pair<lli,lli>> q;

    REP(i,0,N)q.push({B[i],i});

    lli cnt = 0;
    while(q.size()){
        pair<lli,lli> top = q.top();
        q.pop();
        lli diff = B[(top.second+1)%N] + B[(top.second+N-1)%N];
        lli able = (B[top.second]-A[top.second])/(diff);
        if(able == 0){
            cout<<-1<<endl;
            return;
        }
        B[top.second] -= able * diff;
        cnt += able;
        if(B[top.second] != A[top.second])q.push({B[top.second],top.second});
    }

    cout<<cnt<<endl;

}

