ll good_mod(ll value, ll base) {
    return (value % base + base) % base;
}

int main() {
    ll N;
    cin >> N;
    vector<ll> init;
    vector<ll> target;
    for (ll i = 0; i < N; i++) {
        ll Ai;
        cin >> Ai;
        init.push_back(Ai);
    }
    for (ll i = 0; i < N; i++) {
        ll Bi;
        cin >> Bi;
        target.push_back(Bi);
    }
    struct NumInfo {
        ll idx;
        ll number;
    };
    auto comp = [](NumInfo lhs, NumInfo rhs){ return lhs.number < rhs.number; };
    priority_queue<NumInfo, vector<NumInfo>, decltype(comp)> queue(comp);
    for (ll i = 0; i < N; i++) {
        if (init[i] > target[i]) {
            cout << -1 << endl;
            return 0;
        } else if (init[i] < target[i]) {
            queue.push(NumInfo{i, target[i]});
        }
    }
    ll cnt = 0;
    while (!queue.empty()) {
        NumInfo info = queue.top();
        queue.pop();
        ll neighbour = target[good_mod(info.idx - 1, N)] + target[good_mod(info.idx + 1, N)];
        if (target[info.idx] - init[info.idx] < neighbour) {
            cout << -1 << endl;
            return 0;
        }
        ll cnt_local = (target[info.idx] - init[info.idx]) / neighbour;
        cnt += cnt_local;
        target[info.idx] -= cnt_local * neighbour;
        if (target[info.idx] > init[info.idx]) {
            queue.push(NumInfo{info.idx, target[info.idx]});
        }
    }
    cout << cnt << endl;
}

