struct Search {
	int i;
	int64_t v;
};


auto comp = [](const Search & lhs, const Search & rhs) {
	return lhs.v < rhs.v;
};

void update(const vector<int64_t>& as, const vector<int64_t> & bs, int n, int i, priority_queue<Search, vector<Search>, decltype(comp)>& move_idx)
{
	if (i < 0) i += n;
	if (n <= i) i -= n;

	if (as[i] == bs[i]) return;

	if (i == 0) {
		if (bs[n - 1] + bs[1] < bs[0]) move_idx.push({ 0, bs[0] - bs[1] - bs[n - 1] });
	}
	else if (i == n - 1) {
		if (bs[n - 2] + bs[0] < bs[n - 1]) move_idx.push({ n - 1, bs[n - 1] - bs[0] - bs[n - 2]} );
	}
	else {
		if (bs[i - 1] + bs[i + 1] < bs[i]) move_idx.push({ i, bs[i] - bs[i + 1] - bs[i - 1] });
	}
}


bool fullfilled(const vector<int64_t>& as, const vector<int64_t>& bs, int n)
{
	return (memcmp(&as[0], &bs[0], n * sizeof(int64_t))== 0);
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;

	vector<int64_t> as(n);
	for (auto& a : as) {
		cin >> a;
	}

	vector<int64_t> bs(n);
	for (auto& b : bs) {
		cin >> b;
	}

	int ce = 0;
	FOR_LT(i, 0, n) {
		if (as[i] == bs[i]) ce++;
		if (bs[i] < as[i]) {
			cout << -1 << endl;
			return 0;
		}
	}

	priority_queue<Search, vector<Search>, decltype(comp)> move_idx(comp);

	FOR_LT(i, 0, n) {
		update(as, bs, n, i + 1, move_idx);
	}

	int64_t ans = 0;

	while (ce != n) {
		if (move_idx.empty()) {
			cout << -1 << endl;                            
			return 0;
		}
		Search s = move_idx.top();
		int i = s.i;
		move_idx.pop();

		int64_t d = 0;
		if (i == 0) {
			d = bs[n - 1] + bs[1];
		}
		else if (i == n - 1) {
			d = bs[n - 2] + bs[0];
		}
		else {
			d = bs[i - 1] + bs[i + 1];
		}

		if (d <= as[i]) {
			if ((bs[i] - as[i]) % d != 0) {
				cout << -1 << endl;
				return 0;
			}
			ans += (bs[i] - as[i]) / d;
			bs[i] = as[i];
		}
		else {
			int64_t c = bs[i] % d;
			if (c < as[i]) {
				cout << -1 << endl;
				return 0;
			}
			ans += bs[i] / d;
			bs[i] = c;
		}

		if (bs[i] == as[i]) {
			ce++;
		}

		update(as, bs, n, i + 1, move_idx);
		update(as, bs, n, i - 1, move_idx);
	}

	cout << ans << endl;

