        if(p_idx == -1) p_idx = n - 1;
        if(n_idx == n) n_idx = 0;

        times = 1;
        minus = b[p_idx] + b[n_idx];
        if(b[idx] - minus <= 0){
            out << "-1" << endl;
            return 0;
        }
        times = min((b[idx] - a[idx]) / minus, ll(ceil((b[idx] - minus) / double(minus))));

        b[idx] -= minus * times;
        if(b[idx] < a[idx]){
            b[idx] += minus;
            times -= 1;
        }
        // out << idx << " " << b[idx] << endl;
        cnt += times;

        if(b[idx] == a[idx]){
            continue;
        }else{
            q.push(lp(b[idx], idx));
        }
    }
    out << cnt << endl;
}

