int64_t judge(int n, int *a, int *b) {
	for (int i = 0; i < n; i++) if (a[i] > b[i]) return -1;
	int64_t res = 0;
	while (1) {
		bool updated = false;
		for (int i = 0; i < n; i++) {
			int prev = (i - 1 + n) % n;
			int next = (i + 1) % n;
			int sum = b[prev] + b[next];
			if (b[i] >= sum) {
				int yo = b[i] - a[i];
				res += yo / sum;
				b[i] -= yo / sum * sum;
				updated = true;
			}
		}
		if (!updated) break;
	}
	for (int i = 0; i < n; i++) if (a[i] != b[i]) return -1;
	return res;
}


