int a[200005],b[200005];
int n;
bool check(int i) {
	if(b[i]>b[(i+n-2)%n+1]&&b[i]>b[i%n+1]&&b[i]!=a[i])
		return 1;
	return 0;
}
void solve() {
	cin>>n;
	fr(i,1,n)
		cin>>a[i];
	fr(i,1,n)
		cin>>b[i];
	set<int> lar;
	for(int i=1; i<=n; i++) {
		if(check(i))
			lar.insert(i);
	}
	int ans=0;
	while(lar.size()) {
		int te=*lar.begin();
		lar.erase(lar.begin());
		int lol=min((b[te]-a[te])/(b[te%n+1]+b[(te+n-2)%n+1]),b[te]/(b[te%n+1]+b[(te+n-2)%n+1]));
		ans+=lol;
		b[te]-=lol*(b[te%n+1]+b[(te+n-2)%n+1]);
		if(check(te%n+1)) {
			lar.insert(te%n+1);
		}
		if(check((te+n-2)%n+1)) {
			lar.insert(((te+n-2)%n+1));
		}
	}
	fr(i,1,n) {
		if(a[i]!=b[i]) {
			cout<<-1<<endl;
			return;
		}
	}
	cout<<ans<<endl;
}

