using lli = long long int;
using pli = std::pair<lli, int>;

std::vector<lli> A, B;

int main(void){
    std::priority_queue<pli> Q;
    int n; scanf("%d", &n);
    A.resize(n); B.resize(n);
    REP(i, n) scanf("%lld", &A[i]);
    REP(i, n) {scanf("%lld", &B[i]); if(A[i] < B[i]) Q.push(pli(B[i], i));}

    lli res = 0;
    while(not Q.empty()){
        int idx; lli v = 0;
        std::tie(std::ignore, idx) = Q.top(); Q.pop();
        if(not Q.empty()) std::tie(v, std::ignore) = Q.top();
        int idx_p = (idx-1 + n) % n;
        int idx_l = (idx+1) % n;
        lli V = B[idx_p] + B[idx_l];
        lli K1 = (B[idx] - A[idx]) / V; if(K1 == 0) K1 = 1;
        B[idx] -= K1 * V; res += K1;
        if(B[idx] < A[idx]) break;
        else if(B[idx] > A[idx]){
            Q.push(pli(B[idx], idx));
        }
    }
    bool same = true;
    REP(i, n) if(A[i] != B[i]){
        same = false;
        break;
    }
    if(same) printf("%lld\n", res);
    else puts("-1");
    return 0;
}

