priority_queue<pair<int,int>>q;

int main(){
	cin>>n;
	for(int i=1;i<=n;++i)cin>>a[i];
	for(int i=1;i<=n;++i)cin>>b[i];
	for(int i=1;i<=n;++i)q.push(make_pair(b[i],i));
	while(!q.empty()){
		int x=q.top().second;q.pop();
		int y=q.top().first;
		int L=x==1?n:x-1,R=x==n?1:x+1;
		int w=b[x]-a[x];
		if(!w)continue;
		int l=1,r=w/(b[L]+b[R]);
		if(!r){
			puts("-1");
			return 0;
		}
		while(l!=r){
			int mid=l+r+1>>1;
			if(b[x]-(mid-1)*(b[L]+b[R])>=y)l=mid;
			else r=mid-1;
		}
		ans+=l;
		b[x]-=l*(b[L]+b[R]);
		q.push(make_pair(b[x],x));
	}
	printf("%d\n",ans);
}

