        rep (i,N){
            int a=B[(i-1+N)%N]+B[(i+1)%N];
            if (B[i]-A[i]>=a){
                int b=(B[i]-A[i])/a;
                B[i]-=a*b;
                ans+=b;
                c=true;
            }
        }
        if (A==B){
            cout << ans << endl;
            break;
        }
    }
    if (!c){
        cout << -1 << endl;
    }
}

