ll n;
ll at(ll i) {
	return (i + n) % n;
}

ll dov(VL& b, ll i) {
	ll cnt = 0;
	ll j = (i + n - 1);
	while (true) {
		ll val = b[at(j - 1)] + b[at(j + 1)];
		if (val < b[at(j)]) {
			cnt += b[at(j)] / val;
			b[at(j)] %= val;
			--j;
			if (j < 0) { j += n; }
			cnt += dov(b, j);
			continue;
		}
		break;
	}
	return cnt;
}

