int main() {
  ll N;
  cin >> N;

  vector<ll> A(N);
  vector<ll> B(N);
  priority_queue<pair<ll, int>> q;
  for (int i = 0; i < N; i++) {
    cin >> A[i];
  }
  for (int i = 0; i < N; i++) {
    cin >> B[i];
    if (B[i] - A[i] > 0) {
      q.push(make_pair(B[i] - A[i], i));
    }
  }

  ll ans = 0;
  while(true) {
    if (q.size()==0) {
      break;
    }
    pair<ll, int> p = q.top();
    q.pop();

    ll p2first = 0;
    if (q.size()>1) {
      p2first = q.top().first;
    }

    int il, im, ir;
    im = p.second;
    il = im - 1;
    ir = im + 1;
    if (il < 0) il = N-1;
    if (ir == N) ir = 0;

    ll d = B[il] + B[ir];
    ll c = (p.first - p2first + d - 1) / d;
    if (c==0) c = 1;

    B[im] -= d * c;
    if (B[im] < A[im]) {
      ans = -1;
      break;
    }

    ans += c;
    if (B[im] - A[im] > 0) {
      q.push(make_pair(B[im] - A[im], im));
    }
  }

  if (ans==-1) {
    cout << "-1\n";
    return 0;
  }

  cout << ans << "\n";

  return 0;
}

