    auto cmp = [&] (const int &i, const int &j) {
        if(get_dif(i) == get_dif(j))
            return i < j;
        return b[i] > b[j];
    };

    multiset<int, decltype(cmp)>S(cmp);
    for(int i = 0; i < n; ++i) {
        if(a[i] != b[i])
            S.insert(i);
    }

    long long ops = 0;
    while(!S.empty()) {
        int poz = *S.begin();
        S.erase(S.begin());
        vector<int>neighb = {(poz - 1 + n) % n, (poz + 1 + n) % n};
        bool both_fixed = true;
        int sumNeighb = 0;
        for(int x : neighb) {
            if(S.find(x) != end(S))
