ll solve(int n, vector<int> a, vector<int> b) {

    rep(i, n) if (a[i] > b[i]) return -1;

    priority_queue<pii> q;
    rep(i, n) {
        q.push(pii{b[i], i});
    }


    ll cnt = 0;
    while(1){
        // out(i);

        if (SZ(q) == 0) break;

        int j = q.top().S;
        // out(j);

        q.pop();

        if (a[j] == b[j]) continue;

        int neig = b[(j - 1 + n) % n] + b[(j + 1) % n];

        if (b[j] <= neig) continue;

        // b > a + cでbがAiと一致するまで
        ll tmp = (b[j] - a[j]) / neig;
        cnt += tmp;
        b[j] -= neig * tmp;


        q.push(pii{b[j], j});

    }

    rep(i, n) if (a[i] != b[i]) return -1;
    return cnt;
}


