int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<int> a(n), b(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);
  for (int i = 0; i < n; i++) cin >> b.at(i);

  priority_queue<pair<int, int>> pq;
  for (int i = 0; i < n; i++) pq.push(make_pair(b.at(i) - a.at(i), i));

  int ans = 0;
  while (true) {
    pair<int, int> p = pq.top();
    pq.pop();

    if (p.first == 0) break;

    b.at(p.second) -= b.at((p.second + 1) % n) + b.at((p.second - 1 + n) % n);
    pq.push(make_pair(b.at(p.second) - a.at(p.second), p.second));
    ans++;

    if (b.at(p.second) < 0) {
      ans = -1;
      break;
    }
  }

  cout << ans << '\n';
}

