	cin.tie(0);
	ios::sync_with_stdio(false);		//DON'T USE scanf/printf/puts !!
	cout << fixed << setprecision(20);

	int N; cin >> N;
	V<int> A(N),B(N);
	rep(i,N) cin >> A[i];
	rep(i,N) cin >> B[i];
	rep(i,N) if(A[i] > B[i]){
		cout << -1 << endl;
		return 0;
	}
	using P = pair<int,int>;
	priority_queue<P> q;
	rep(i,N) q.push(P(B[i],i));
	ll ans = 0;
	while(!q.empty()){
		int i = q.top().sc; q.pop();
		int d = B[(i+1)%N]+B[(i+N-1)%N];
		int t = (B[i]-A[i])/d;
		if(t == 0) continue;
		B[i] -= t*d;
		ans += t;
		if(B[i] != A[i]) q.push(P(B[i],i));
	}
	rep(i,N) if(A[i] != B[i]){
		cout << -1 << endl;
		return 0;
	}
	cout << ans << endl;
