struct Segment_tree {
	struct Node{
		long long sum;
		pii maxj;
	}T[800010];
	void pushup(int now) {
		T[now].sum = T[now << 1].sum + T[now << 1 | 1].sum;
		T[now].maxj = max(T[now << 1].maxj, T[now << 1 | 1].maxj);
	}
	void Build(int now, int l, int r) {
		if (l == r) {
			T[now].maxj = mp(b[l], l);
			T[now].sum = b[l] - a[l];
			return ;
		}
		int mid = l + r >> 1;
		Build(now << 1, l, mid), Build(now << 1 | 1, mid + 1, r);
		pushup(now);
	}
	void Update(int now, int l, int r, int pos) {
		if (l == r) {
			T[now].maxj = mp(b[l], l);
			T[now].sum = b[l] - a[l];
			return ;
		}
		int mid = l + r >> 1;
		if (pos <= mid) Update(now << 1, l, mid, pos);
		else Update(now << 1 | 1, mid + 1, r, pos);
		pushup(now);
	}
}seg;

int main(){
	int n; scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}
	for (int i = 0; i < n; i++) {
		scanf("%d", &b[i]);
	}
	seg.Build(1, 0, n - 1);
	long long ans = 0;
	int last = -1;
	while (seg.T[1].sum) {
		int pos = seg.T[1].maxj.se;
		if (pos == last) {
			printf("-1\n");
			return 0;
		}
		int modd = b[(pos - 1 + n) % n] + b[(pos + 1) % n];
		int cnt = (b[pos] - a[pos]) / modd;
		ans += cnt;
		b[pos] -= cnt * modd;
		last = pos;
		seg.Update(1, 0, n - 1, pos);
	}
	printf("%lld\n", ans);
	return 0;
}

