{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, n);

    priority_queue<t2> q_b_idx;
    rep (i, n) q_b_idx.push(t2(blist[i], i));

    ll ans = 0LL;
    while (!q_b_idx.empty()) {
        t2 b_idx = q_b_idx.top(); q_b_idx.pop();
        ll b = get<0>(b_idx);
        ll idx = get<1>(b_idx);

        if (blist[idx] < alist[idx]) {
            cout << -1;
            return 0;
        }
        if (alist[idx] == blist[idx]) continue;

        ll idx_prev = idx - 1LL;
        if (idx_prev < 0LL) idx_prev = n - 1LL;
        ll idx_next = idx + 1LL;
        if (idx_next >= n) idx_next = 0LL;

        ll subcount = blist[idx] - max({blist[idx_prev], blist[idx_next], alist[idx]});
        subcount /= (blist[idx_prev] + blist[idx_next]);
        blist[idx] = blist[idx] - (blist[idx_prev] + blist[idx_next]) * subcount;
        ans += subcount;

        if (blist[idx] < alist[idx]) {
            cout << -1;
            return 0;
        }
        if (alist[idx] == blist[idx]) continue;

        assert(blist[idx] >= blist[idx_prev]);
        assert(blist[idx] >= blist[idx_next]);

        blist[idx] = blist[idx] - (blist[idx_prev] + blist[idx_next]);
        ans++;

        if (blist[idx] < alist[idx]) {
            cout << -1;
            return 0;
        }
        if (alist[idx] == blist[idx]) continue;

        q_b_idx.push(t2(blist[idx], idx));
    }

    cout << ans;

