void solve() {
  long N;
  cin >> N;
  vector<long> A(N);
  rep (i, N) cin >> A[i];
  vector<long> B(N);
  rep (i, N) cin >> B[i];
  priority_queue<pair<long, long>> pq;
  rep (i, N) pq.push(make_pair(B[i], i));
  long result = 0;
  while (pq.size()) {
    auto tmp = pq.top();
    pq.pop();
    long num = tmp.first;
    long index = tmp.second;
    if (B[index] < A[index]) {
      cout << -1 << endl;
      return;
    }
    if (B[index] == A[index]) continue;
    long prev = (index - 1 + N) % N;
    long next = (index + 1) % N;
    long tmp_sum = B[prev] + B[next];
    long next_large = A[index];
    if (pq.size()) next_large = pq.top().first;
    long diff = B[index] - next_large;
    B[index] -= max((diff / tmp_sum), 1l) * tmp_sum;
    result += max((diff / tmp_sum), 1l);
    pq.push(make_pair(B[index], index));
  }
  cout << result << endl;
}

