inline int prv(int x){
	return (x - 1 + n) % n;
}

inline int nxt(int x){
	return (x + 1) % n;
}

int main(){
	scanf("%d", &n);
	for(int i = 0;i < n;i++)
		scanf("%d", A + i);
	for(int i = 0;i < n;i++)
