			q[sz++] = prv(i);
		if(B[nxt(i)] > A[nxt(i)] && B[nxt(i)] > B[nxt(nxt(i))] + B[i])
			q[sz++] = prv(i);
		if(B[i] > A[i] && B[i] > B[prv(i)] + B[nxt(i)])
			q[sz++] = nxt(i);
	}
