int main(){
    int N;
    priority_queue<P> que;
    ll a[210000], b[210000];
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> a[i];
    }
    for(int i = 0; i < N; i++){
        cin >> b[i];
        que.push(P(b[i], i));
    }

    ll res = 0;
    while(!que.empty()){
        P x = que.top(); que.pop();
        int index = x.sc;
        if(a[index] == b[index]){
            continue;
        }
        ll nextB, trial;
        if(a[index] >= max(b[(index + N + 1) % N], b[(index + N - 1) % N])){
            trial = (b[index] - a[index]) / (b[(index + N + 1) % N] + b[(index + N - 1) % N]);
            nextB = b[index] - (b[(index + N + 1) % N] + b[(index + N - 1) % N]) * trial;
            if(nextB != a[index]){
                cout << -1 << endl;
                return 0;
            }
        }
        else{
            ll nextBMax = max(b[(index + N + 1) % N], b[(index + N - 1) % N]);
            trial = (b[index] - nextBMax) / (b[(index + N + 1) % N] + b[(index + N - 1) % N]) + 1;
            nextB = b[index] - (b[(index + N + 1) % N] + b[(index + N - 1) % N]) * trial;
        }

        if(nextB < a[index]){
            cout << -1 << endl;
            return 0;
        }
        else if(nextB > a[index]){
            que.push(P(nextB, index));
        }
        b[index] = nextB;
        res += trial;
    }

    cout << res << endl;


    return 0;
}

#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

class SegmentTree {
public:
    SegmentTree(ll n, ll value) {
        n_ = (ll)pow(2, ceil(log2(n)));
        nodes_.resize(2 * n_ - 1, value);
    }

    void update(ll x, ll v) {
        nodes_[x + n_ - 1] = v;
        for (ll i = (x + n_ - 2) / 2; i > 0; i = (i - 1) / 2) {
            nodes_[i] = max(nodes_[2 * i + 1], nodes_[2 * i + 2]);
        }
        nodes_[0] = max(nodes_[1], nodes_[2]);
    }

    ll getMaxIndex(ll k = 0) {
        //最も大きいもののindexを返す
        if (k >= n_ - 1) {
            //最下段まで来ていたらindexを返す
            return k - (n_ - 1);
        }
        return (nodes_[2 * k + 1] >= nodes_[2 * k + 2] ? getMaxIndex(2 * k + 1) : getMaxIndex(2 * k + 2));
    }

    ll getMax(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {
        if (r < 0) {
            r = n_;
        }
        if (r <= a || b <= l) {
            return INT_MAX;
        }
        if (a <= l && r <= b) {
            return nodes_[k];
        }
        ll lv = getMax(a, b, 2 * k + 1, l, (l + r) / 2);
        ll rv = getMax(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(lv, rv);
    }

private:
    //2のべき乗
    ll n_;
    vector<ll> nodes_;
};

int main() {
    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (ll i = 0; i < N; i++) {
        cin >> B[i];
    }

    SegmentTree st(N, 0);
    for (ll i = 0; i < N; i++) {
        st.update(i, B[i]);
    }

    ll same_num = 0;
    for (ll i = 0; i < N; i++) {
        if (A[i] == B[i]) {
            same_num++;
            st.update(i, 0);
        }
    }

    ll ans = 0;
    while (same_num < N) {
        ll index = st.getMaxIndex();
        ll left = (index + N - 1) % N;
        ll right = (index + 1) % N;
        ll sub = B[left] + B[right];
        ll lr_max = max(B[left], B[right]);

        if (A[index] >= lr_max) {
            //B[index]がA[index]ぴったりになって終了
            if ((B[index] - A[index]) % sub != 0) {
                cout << -1 << endl;
                return 0;
            } else {
                ans += (B[index] - A[index]) / sub;
                B[index] = A[index];

                //もう見ないので0にしておく
                st.update(index, 0);
                same_num++;
            }
        } else {
            //left, rightの大きい方を下回るような操作回数kを求める
            ll k = (B[index] - lr_max + sub - 1) / sub;

            //その操作によってA[index]を下回ってしまってはダメ
            if (B[index] - k * sub < A[index]) {
                cout << -1 << endl;
                return 0;
            } else {
                ans += k;
                B[index] -= k * sub;

                if (B[index] == A[index]) {
                    st.update(index, 0);
                    same_num++;
                } else {
                    st.update(index, B[index]);
                }
            }
        }
    }

    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    for (int i = 0; i < n; ++i)
        cin >> b[i];
    set<pair<int, int>> t;
    for (int i = 0; i < n; ++i)
        t.insert({b[i], i});
    long long ans = 0;
    while (!t.empty()) {
        auto now = --t.end();
        int pos = now->second;
        t.erase(now);
        int f = (pos - 1 + n) % n, s = (pos + 1) % n;
        if (b[pos] - b[f] - b[s] < a[pos]) {
            cout << -1 << endl;
            return 0;
        }
        int del1 = b[pos] - a[pos];
        int del2 = b[pos] - max(b[f], b[s]);
        int minus = b[f] + b[s];
        int nw = min(del1 / minus, (del2 + minus - 1) / minus);
        ans += nw;
        b[pos] -= nw * minus;
        if (b[pos] != a[pos])
            t.insert({b[pos], pos});
    }
    cout << ans << endl;
    return 0;
}

