int main() {
    int n; cin >> n;
    vector<long long> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    priority_queue<pair<long long, int>> pq;
    for (int i = 0; i < n; i++) {
        pq.push({b[i], i});
    }
    long long cnt = 0;
    while (!pq.empty()) {
        auto curr = pq.top(); pq.pop();
        int i = curr.second;
        long long y = curr.first;
        long long x = b[(n+i-1)%n];
        long long z = b[(n+i+1)%n];
        long long t = y - ((y-a[i]) / (x+z)) * (x+z);
        long long s = y - ((y - max(x,z) + (x+z-1)) / (x+z)) * (x+z);
        long long u = max(t, s);
        cnt += (y-u) / (x+z);
        b[i] = u;
        if (b[i] != a[i]) pq.push({b[i], i});
        if (b[i] != a[i] && y == u) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << cnt << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=3e5+10;
int a[maxn],b[maxn],n;
set<pair<int,int>,greater<pair<int,int>>> s;
long long ans=0;

int main(){
    scanf("%d",&n);
    for(int i=0;i<n;i++){
        scanf("%d",&a[i]);
    }
    for(int i=0;i<n;i++){
        scanf("%d",&b[i]);
        s.insert(make_pair(b[i],i));
    }
    int l,r;
    while(!s.empty()){
        auto it=*s.begin();
        if(it.first==a[it.second]){
            s.erase(s.begin());
            continue;
        }
        int l=((it.second)-1);
        if(l<0)l=n-1;
        int r=(l+2)%n;
        int sum=(b[l]+b[r]);
        if(b[it.second]<sum||b[it.second]-sum<a[it.second]){
            return !printf("-1");
        }
        if(a[it.second]>sum){
            if((b[it.second]-a[it.second])%sum)
                return !printf("-1");
            ans+=(b[it.second]-a[it.second])/sum;
            b[it.second]=a[it.second];
            s.erase(s.begin());continue;
        }
        ///find the first number that is in form of
        ///b-sum*k<=sum sum*(k+1)>=b
        int cur=b[it.second]/sum-(b[it.second]%sum==0?1:0);
        b[it.second]-=sum*cur;
        ans+=cur;
        s.erase(s.begin());
        s.insert(make_pair(b[it.second],it.second));
    }
    printf("%lld\n",ans);
}
