inline void coborare(int p) {
    int q;
    bool f = 1;
    while (f && (q = 2 * p) <= k) {
        if (q < k && v[heap[q + 1]] > v[heap[q]]) q++;
        if (v[heap[q]] > v[heap[p]]) {
            std::swap(heap[p], heap[q]);
            p = q;
        } else f = 0;
    }
}

inline int vezi(int p) {
    int A = v[n - 1], b = v[0];
    if (p > 0)
        A = v[p - 1];
    if (p < n - 1)
        b = v[p + 1];
    int cat = (v[p] - a[p]) / (A + b);
    if (cat == 0)
        prost();
    v[p] -= cat * (A + b);
    return cat;
}

int main() {
