    for (int i = 0; i < n; i++)
        fscanf(fin, "%d", &a[i]);

    for (int i = 0; i < n; i++) {
        fscanf(fin, "%d", &v[i]);
        if (v[i] < a[i])
            prost();
        else if (v[i] != a[i])
            heap[++k] = i;
    }

    for (int i = k / 2; i > 0; i--)
        coborare(i);

    long long ans = 0;
    while (k) {
        int x = heap[1];
        ans += vezi(x);
        if (v[x] == a[x]) {
            std::swap(heap[1], heap[k]);
            k--;
        }
        coborare(1);
    }

    fprintf(fout, "%lld\n", ans);

    fclose(fin);
    fclose(fout);
    return 0;
}

