int N;
ll A[MAX_N], B[MAX_N];

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	priority_queue<pl> que;
	rep(i, 0, N) {
		cin >> B[i];
		if(A[i] < B[i]) que.push(pl(B[i], i));
	}
	ll cnt = 0;
	while(!que.empty()) {
		pl p = que.top(); que.pop();
		int at = p.sec;
		// debug(vl(B, B + N), p, cnt);
		ll r = B[(N + at - 1) % N] + B[(at + 1) % N];
		if(B[at] <= r) {
			cout << -1 << "\n";
			return;
		}
		if(B[at] % r > A[at]) {
			cnt += B[at] / r;
			B[at] %= r;
			que.push(pl(B[at], at));
		}
		else {
			if((B[at] - A[at]) % r) {
				cout << "-1\n"; 
				return;
			}
			else {
				cnt += (B[at] - A[at]) / r;
				B[at] = A[at];
			}
		}
	}
	cout << cnt << "\n";
}

