int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    REP(i, N) cin >> A[i];
    REP(i, N) cin >> B[i];

    bool flag = false;
    REP(i, N) if(B[i] < A[i]) flag = true;
    if(flag){
        cout << -1 << endl;
        return 0;
    }

    vector<ll> C(N);
    REP(i, N) C[i] = B[i];

    priority_queue<pll> pq;
    REP(i, N){
    	if(B[i] != A[i]) pq.push({B[i], i});
    }

	ll res = 0;
	while(!pq.empty()){
		auto tmp = pq.top();pq.pop();
		ll idx = tmp.second;
		ll sum = C[(idx+1)%N] + C[(idx-1+N)%N];
		ll r = (C[idx] - A[idx])/sum;
		if(r == 0){
			cout << -1 << endl;
            return 0;
		}
		C[idx] -= r*sum;
		if(C[idx] != A[idx]) pq.push({C[idx], idx});
        res += r;
        //cout << C << endl;
	}
    cout << res << endl;
    return 0;
}

