typedef long long lint;

int main() {
  int n;
  scanf("%d", &n);
  vector<int> a(n), b(n);
  for (int i = 0; i < n; ++i)
    scanf("%d", &a[i]);
  for (int i = 0; i < n; ++i)
    scanf("%d", &b[i]);

  set<pair<int, int>> bvi;
  for (int i = 0; i < n; ++i)
    bvi.emplace(b[i], i);
  int result = 0;
  while (!bvi.empty()) {
    auto it = prev(bvi.end());
    int value, id;
    tie(value, id) = *it;
    bvi.erase(it);

    if (value == a[id]) {
      continue;
    } else if (value < a[id]) {
      printf("-1\n");
      return 0;
    } else {
      int next_value = prev(bvi.end())->first;
      int delta = b[(id + 1) % n] + b[(id - 1 + n) % n];
      int jump_count = max((value - max(next_value, a[id])) / delta, 1);
      result += jump_count;
      value -= delta * jump_count;
      b[id] = value;
      if (b[id] < a[id]) {
        printf("-1\n");
        return 0;
      }
      bvi.emplace(b[id], id);
    }
  }

  printf("%d\n", result);

  return 0;
}

