signed main(){
  int N;cin>>N;
  std::vector<int> a(N),b(N);
  for(int i=0;i<N;i++)cin>>a[i];
  for(int i=0;i<N;i++)cin>>b[i];
  for(int i=0;i<N;i++)if(b[i]<a[i])fin(-1);
  int ok=0,ans=0;
  std::vector<int> ook(N,0);
  for(int i=0;i<N;i++){
    if(b[i]==a[i]){
      ok++;
      ook[i]++;
    }
  }
  if(ok==N)fin(0);
  queue<int> que;
  for(int i=0;i<N;i++)if(ook[(i+1)%N]==0)if(b[i]<b[(i+1)%N]&&b[(i+1)%N]>b[(i+2)%N])que.push((i+1)%N);
  while(que.size()){
    int p=que.front();que.pop();
    int l=b[(p-1+N)%N],r=b[(p+1)%N];int t=l+r;
    int s=(b[p]-max({l,r,a[p]}))/t;
    if((b[p]-max({l,r,a[p]}))%t)s++;
    b[p]-=s*t;
    ans+=s;
    if(b[p]<a[p])fin(-1);
    if(b[p]==a[p]){
      ok++;
      ook[p]++;
    }
    if(ok==N)fin(ans);
    if(ook[(p+1)%N]==0)if(b[p]<b[(p+1)%N]&&b[(p+1)%N]>b[(p+2)%N])que.push((p+1)%N);
