        batch = (B[bix] - A[bix]) / (B[l] + B[r]);
      } else {
        batch = (btop - bnext + (B[l] + B[r] - 1)) / (B[l] + B[r]);
      }
      if (batch == 0) return -1;
      step += batch;
      B[bix] -= batch * (B[l] + B[r]);
      if (B[bix] < A[bix]) return -1;
      if (B[bix] == A[bix]) {
        ok_cnt++;
      } else {
        pq.emplace(B[bix], bix);
      }
    }
    assert(ok_cnt == N);
    return step;
  };
  cout << solve() << endl;
}

