            pq.push(pair({B[i], i}));
        }
    }

    int64_t ret = 0;
    while (pq.size()) {
        auto p = pq.top();
        pq.pop();

        int prev = (p.second - 1 + N) % N;
        int next = (p.second + 1) % N;

        int64_t num = (B[p.second] - std::max({B[prev], B[next], A[p.second]})) / (B[prev] + B[next]);
        assert(0 <= num);
        //int num = (B[p.second] - std::max({pq.top().first, A[p.second]})) / (B[prev] + B[next]);

        B[p.second] -= (B[prev] + B[next]) * num;
        ret += num;

        //std::cout << p.second << " " << B[p.second] << std::endl;

        if (B[p.second] != A[p.second]) {
            B[p.second] -= (B[prev] + B[next]);
            ret++;
            if (B[p.second] < A[p.second]) {
                return -1;
            } else if (B[p.second] != A[p.second]) {
                pq.push(pair({B[p.second], p.second}));
            }
        }
    }
    return ret;
}

