void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    priority_queue<pair<int, int>> pq;
    rep(i, n) {
        if (b[i] != a[i]) pq.push(pair<int, int>(b[i], i));
    }
    int cnt = 0;
