            if (b[1] != a[1]) chmax(mx, b[1]);
            if (b[n - 1] != a[n - 1]) chmax(mx, b[n - 1]);
        } else if (idx == n - 1) {
            if (b[0] != a[0]) chmax(mx, b[0]);
            if (b[n - 2] != a[n - 2]) chmax(mx, b[n - 2]);
        } else {
            if (b[idx - 1] != a[idx - 1]) chmax(mx, b[idx - 1]);
            if (b[idx + 1] != a[idx + 1]) chmax(mx, b[idx + 1]);
