    VEC(ll,a,n);
    VEC(ll,b,n);
    priority_queue<pll>q;
    rep(n)if(a[i]!=b[i])q.emplace(b[i],i);
    ll ans=0;
    while(q.size()){
        Modint at=q.top().second;
        q.pop();
        ll cnt=b[at]-max({b[at-1],b[at+1],a[at]});
        if(cnt<=0)return out(-1);
        cnt+=b[at-1]+b[at+1]-1;
        cnt/=b[at-1]+b[at+1];
        b[at]-=(b[at-1]+b[at+1])*cnt;
        ans+=cnt;
        if(b[at]<a[at])return out(-1);
        if(b[at]>a[at])q.emplace(b[at],at);
    }
    out(ans);
}

