int n, nr_op = 0;


static int nxt(int x)
{
    return (x < n ? x + 1 : 1);
}

static int prv(int x)
{
    return (x > 1 ? x - 1 : n);
}

void check(int i)
{
    if(b[i] - (b[prv(i)] + b[nxt(i)]) >= a[i])
    {
        ++nr_op;
        q.push(i);
    }
}

void solve()
{
    int i;
    for(i=1; i<=n; ++i)
        check(i);

    while(q.size())
    {
        int x = q.front();
        q.pop();

        b[x] -= b[prv(x)] + b[nxt(x)];

        check(x);
        check(nxt(x));
        check(prv(x));
    }

    for(i=1; i<=n; ++i) 
        if(a[i] != b[i]) 
        {
            cout << -1 << '\n';
            return;
        }

    cout << nr_op << '\n';
}

