        in >> a[i];
    }
    REP(i, n){
        in >> b[i];
    }
    priority_queue<pair<ll, ll> > q;
    ll cnt = 0;
    REP(i, n){
        q.push(lp(b[i], i));
    }

    ll idx, p_idx, n_idx;
    ll minus, times;
    ll pre_idx = -1;
    ll prepre_idx = -1;
    while(!q.empty()){
        idx = q.top().second;
        q.pop();
        if(pre_idx == idx && prepre_idx == pre_idx){
            out << "-1" << endl;
            return 0;
        }
        if(b[idx] == a[idx]) continue;
        p_idx = idx - 1;
