int main() {
  int N;
  int count = 0;
  std::cin >> N;
  std::vector<int> A(N), B(N);

  // 入力
  for (auto& a_i : A) {
    std::cin >> a_i;
  }
  for (auto& b_i : B) {
    std::cin >> b_i;
  }

  while (1) {
    bool       end          = true;
    const auto before_count = count;

    for (int i = 0; i < N; i++) {
      auto &a = A[i], &b = B[i];
      if (a < b) {
        end = false;

        int d; // 変化量
        if (i == 0) {
          d = B.at(N - 1) + B.at(1);
        } else if (i == N - 1) {
          d = B.at(N - 2) + B.at(0);
        } else {
          d = B.at(i - 1) + B.at(i + 1);
        }

        int howMany = (b - a) / d;
        b -= howMany * d;
        count += howMany;
      }
    }
    if (end) {
      std::cout << count;
      return 0;
    }

    // 一回も操作しなかった場合
    if (count == before_count) {
      std::cout << "-1";
      return 0;
    }
  }
  return 0;
}

