const int N=2e5;
int n, a[N], b[N], val[1<<18], cho[1<<19], off;
int choose(int x, int y) {return val[x]>val[y]?x:y;}
void update(int x, int v) {
	val[x]=v;
	for(x|=off; x>>=1; ) cho[x]=choose(cho[x<<1], cho[x<<1|1]);
}
int main() {
	assert(scanf("%d", &n)==1);
	for(int i=0; i<n; ++i) assert(scanf("%d", a+i)==1);
	for(int i=0; i<n; ++i) assert(scanf("%d", b+i)==1);
	for(off=1; off<n; off<<=1);
	for(int i=0; i<off; ++i) {
		val[i]=i<n?b[i]:-1;
		cho[i+off]=i;
	}
	for(int i=off; --i; ) cho[i]=choose(cho[i<<1], cho[i<<1|1]);
	int ans=0;
	while(true) {
		int x=cho[1];
		if(val[x]==-1) break;
		if(b[x]<a[x]) GG;
		int l=b[(x+n-1)%n], r=b[(x+1)%n], s=l+r;
		if(a[x]>=s) {
			if(a[x]%s!=b[x]%s) GG;
			ans+=(b[x]-a[x])/s;
			b[x]=a[x];
			update(x, -1);
		} else {
			ans+=b[x]/s;
			b[x]%=s;
			if(b[x]==a[x]) {
				update(x, -1);
				continue;
			}
