LL getnum(int p){
	int pm = p==0?N-1:p-1;
	int pp = p+1==N?0:p+1;
	return B[pm] + B[pp];
}

LL getmax(int p){
	int pm = p==0?N-1:p-1;
	int pp = p+1==N?0:p+1;
	return max(B[pm], B[pp]);
}

