#include <algorithm>
#include <iostream>
#include <set>
#include <string>
#include <vector>

int main() {
  int N;
  int count = 0;
  std::cin >> N;
  std::vector<int> A(N), B(N);

  // 入力
  for (auto& a_i : A) {
    std::cin >> a_i;
  }
  for (auto& b_i : B) {
    std::cin >> b_i;
  }

  std::set<std::pair<int, int>, std::greater<std::pair<int, int>>>
      uncomp_B_index;
  for (int i = 0; i < N; i++) {
    if (A.at(i) != B.at(i)) {
      uncomp_B_index.emplace(B.at(i), i);
    }
  }

  while (!uncomp_B_index.empty()) {
    auto       it = uncomp_B_index.begin();
    const auto i  = it->second;
    int &      a = A.at(i), &b = B.at(i);

    uncomp_B_index.erase(it);

    const int d = B.at((N + i - 1) % N) + B.at((i + 1) % N); // 変化量

    const int howMany = (b - a) / d;
    b -= d * howMany;
    count += howMany;

    if (howMany <= 0) {
      std::cout << "-1";
      return 0;
    }

    if (a != b) {
      uncomp_B_index.emplace(b, i);
    }
  }

  std::cout << count;

  return 0;
}

