using namespace std;

static const int MAX = 1000000;

struct Node{int key, i;};

int n;
int cnt = 0;
int A[MAX], B[MAX];
Node node[MAX];

bool cmp(const Node &a, const Node &b)
{
    return a.key > b.key;
}

void solve(int now_i){
    int fi = node[now_i].i;
    if(B[fi] == A[fi])return;
    int l = fi-1;
    if(fi-1==-1)l = n-1;
    int r = fi+1;
    if(r==n)r = 0;
    B[fi]-=B[l]+B[r];
    cnt++;
    if(B[fi]>A[fi]){
        node[now_i].key = B[fi];
        sort(node, node+n, cmp);
        solve(now_i);
    }
    else if(B[fi] == A[fi]){
        node[now_i].key = B[fi];
        sort(node, node+n, cmp);
        solve(now_i);
    }
    else {
        cnt = -1;
        return;
    }

}

int main(int argc, const char * argv[]) {
    // input from txt


    /////////
