    for (int i = 0; i < n; i++) {
        if (a.at(i) < b.at(i)) que.push(make_pair(b.at(i), i));
    }

    auto prev = [&](int i){return (i + n - 1) % n;};
    auto next = [&](int i){return (i + 1) % n;};

    long long cnt = 0;
    while (true) {
        auto p = que.top(); que.pop();
        int i = p.second;
        long long &x = b.at(i);

        if (b.at(prev(i)) + b.at(next(i)) > x) break;

        cnt += (x - a.at(i)) / ((b.at(prev(i)) + b.at(next(i))));
        x -=  ((x - a.at(i)) / ((b.at(prev(i)) + b.at(next(i))))) * (b.at(prev(i)) + b.at(next(i)));

        if (a.at(i) < x) que.push(make_pair(x, i));
    }

    for (int i = 0; i < n; i++) {
        if (a.at(i) != b.at(i)) {
            cout << -1 << endl;
            return 0;
        }
    }
