            if (v < b[idx]) {
                res = -1;
                break;
            } else {
                continue;
            }
	    }
	    int64 mul = max(b[(idx-1+N)%N], b[(idx+1)%N]);
	    int64 minus = b[(idx-1+N)%N] + b[(idx+1)%N];
	    mul = (v - mul + minus - 1) / minus;
        v -= minus * mul;
	    if (v <= 0) {
	        if (mul == 1) {
                res = -1;
                break;
            } else {
	            v += minus;
	            mul -= 1;
	        }
	    }
	    b[idx] = v;
	    pq.emplace(v, idx);
	    res += mul;
//	    REP(j, N) {
