void solve(long long N, std::vector<long long> A, std::vector<long long> B){
  long long ret = 0;
  multiset<pair<long long, int> > q;
  for (int i = 0; i < N; i++) {
    q.insert(make_pair(B[i], i));
  }
  while (!q.empty()) {
    auto a = (--(q.end()));
    if (a->first == A[a->second]) {
      q.erase(a);
    } else {
      long long l, r;
      l = B[((a->second - 1) + N)%N];
      r = B[((a->second + 1) + N)%N];
      if ((B[a->second] - A[a->second]) / (l+r) < 1) {
        std::cout << -1 << std::endl;
        return;
      }
      ret += (B[a->second] - A[a->second]) / (l+r);
      B[a->second] -= ((B[a->second] - A[a->second]) / (l+r)) * (l+r);
      pair<long long, int> t = make_pair(B[a->second], a->second);
      if (B[a->second] < A[a->second]) {
        std::cout << -1 << std::endl;
        return;
      } else if (B[a->second] == A[a->second]) {
        q.erase(a);
      } else {
        q.erase(a);
        q.insert(t);
      }
    }
  }
  std::cout << ret << std::endl;
}

