	vector<ll> As(N);
	vector<ll> Bs(N);

	for (ll i = 0; i < N; ++i)
	{
		cin >> As[i];
	}

	for (ll i = 0; i < N; ++i)
	{
		cin >> Bs[i];
	}

	set<ll> check;
	for (ll i = 0; i < N; ++i)
	{
		if (Bs[i] > Bs[(i + 1) % N] + Bs[(i != 0) ? (i - 1) : (N - 1)])
		{
			check.insert(i);
		}
	}

	cout << -3 / 4;

	ll res = 0;
	ll pos;
	ll equalCount = 0;
	while (true)
	{
		if (check.empty())
		{
			res = -1;
			break;
		}

		ll pos = *(check.begin());

		ll decr = Bs[(pos + 1) % N] + Bs[(pos != 0) ? (pos - 1) : (N - 1)];
		ll quot = (Bs[pos] - As[pos]) / decr ;
		res += quot;
		Bs[pos] -= decr * quot;

		if (Bs[pos] == As[pos])
		{
			++equalCount;
		}
		if (Bs[pos] < As[pos])
		{
			res = -1;
			break;
		}
		if (equalCount == N)
		{
			break;
		}

		check.erase(pos);
		ll mpos = (pos != 0) ? (pos - 1) : (N - 1);
		if (Bs[mpos] > Bs[(mpos + 1) % N] + Bs[(mpos != 0) ? (mpos - 1) : (N - 1)])
