	}
	bool is_same(std::vector<ll> &A, std::vector<ll> &B) {
		for(int i = 0; i < N; ++i) {
			if(A[i] != B[i])
				return false;
		}
		return true;
	}

	ll run(int _N, std::vector<ll> A, std::vector<ll> B) {
		N = _N;
		ll cnt = 0, back;
		std::vector<ll> reduced = B;
		bool flag = false;
		auto c = [&](int l, int r) { return reduced[l] <= reduced[r]; };
		std::priority_queue<int, std::vector<int>, decltype(c)> que(c);
		for(int i = 0; i < N; ++i) {
			que.push(i);
		}
		while(true) {
			if(is_same(A, reduced)) {
				return cnt;
			}
			// for(int i = 0; i < N; ++i) {
			// 	std::cerr << reduced[i] << " ";
			// }
			// std::cerr << std::endl;
			//for(int i = 0; i < N; ++i) {
			while(! que.empty()) {
				int i = que.top();
				que.pop();
				// std::cerr << "pop: " << i << std::endl;

				for(int i = 0; i < N; ++i) {
					std::cerr << reduced[i] << " ";
				}
				// std::cerr << std::endl;
				while(true) {
					if(A[i] < reduced[i]) {
						// std::cerr << "found: " << i << std::endl;
						// not same
						if(lmax(reduced, i)) {
							// reduce local max
							back = backward(reduced, i);
							// std::cerr << "to: " << back << std::endl;
							if(A[i] > back) {
								return -1;
							}else{
								reduced[i] = back;
								flag = true;
								++cnt;
							}
						}else{
							break;
						}
					}else{
						break;
					}
				}
				if(flag) {
					que.push(i);
					que.push((i-1)%N);
					que.push((i+1)%N);
					flag = false;
				}
			}
			if(is_same(A, reduced)) {
				return cnt;
			}
			if(flag == false) {
				return -1;
			}
			flag = false;
		}
		return -1;
	}
};

