inline ll read()
{
	ll x=0; char c=getchar(),f=1;
	for(;c<'0'||'9'<c;c=getchar())if(c=='-')f=-1;
	for(;'0'<=c&&c<='9';c=getchar())x=x*10+c-'0';
	return x*f;
}
inline void write(ll x)
{
	static char buf[20];
	int len=0;
	if(x<0)putchar('-'),x=-x;
	for(;x;x/=10)buf[len++]=x%10+'0';
	if(!len)putchar('0');
	else while(len)putchar(buf[--len]);
}
inline void writesp(ll x){write(x); putchar(' ');}
inline void writeln(ll x){write(x); putchar('\n');}
struct Data{
	int x,id;
	friend bool operator < (Data a,Data b){return a.x<b.x;}
};
std::priority_queue<Data>q;
int a[maxn],b[maxn];
int n;
int main()
{
	n=read();
	for(int i=1;i<=n;i++)
		a[i]=read();
	for(int i=1;i<=n;i++)
		b[i]=read();
	for(int i=1;i<=n;i++)
		if(a[i]<b[i])q.push((Data){b[i],i});
	ll ans=0;
	while(!q.empty()){
		Data now=q.top(); q.pop();
		if(now.x!=b[now.id])continue;
		int l=(now.id+n-2)%n+1,r=now.id%n+1;
		if(b[now.id]<=b[l]+b[r]){
			puts("-1"); return 0;
		}
		ans+=b[now.id]/(b[l]+b[r]);
		b[now.id]=b[now.id]%(b[l]+b[r]);
		if(b[now.id]>a[now.id])q.push((Data){b[now.id],now.id});
	}
	for(int i=1;i<=n;i++)
		if(a[i]!=b[i]){
			puts("-1"); return 0;
		}
	writeln(ans);
	return 1;
}

