struct qnode{
	int w, u;
	qnode() {}
	qnode(int _w, int _u):w(_w), u(_u) {}

	friend bool operator < (qnode a, qnode b) {
		if(a.w != b.w) return a.w < b.w;
		return a.u < b.u;
	}
};
priority_queue<qnode> q;

inline void fail() {
	puts("-1");
	exit(0);
}

int main() {
//	freopen("data.in","r",stdin);
  scanf("%d", &n);
	for(int i = 1;i <= n;i ++) scanf("%d", &a[i]);
	for(int i = 1;i <= n;i ++) scanf("%d", &b[i]);
  while(!q.empty()) q.pop();
	for(int i = 1;i <= n;i ++) q.push(qnode(b[i],i));
	int cnt = n, step = 0;
	while(1) {
    if(!cnt) break;
		qnode now = q.top(); q.pop();
		int x, y, z;
		y = now.u;
		x = (y == 1) ? (n) : (y - 1);
