void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    auto left = [n](int idx) -> int {
        if (idx == 0) return n - 1;
        else return idx - 1;
    };
    auto right = [n](int idx) -> int {
        if (idx == n - 1) return 0;
        else return idx + 1;
    };

    priority_queue<pair<int, int>> pq;
    rep(i, n) {
        if (a[i] > b[i]) {
            cout << -1 << "\n";
            return;
        }
        if (a[i] < b[i]) {
            pq.push(pair<int, int>(b[i], i));
        }
    }
    int cnt = 0;
    while (!pq.empty()) {
        int idx = pq.top().second;
        pq.pop();
        int mx = 0;
        if (b[left(idx)] != a[left(idx)]) chmax(mx, b[left(idx)]);
        if (b[right(idx)] != a[right(idx)]) chmax(mx, b[right(idx)]);
        if (mx == 0) mx = a[idx];
        int d = b[left(idx)] + b[right(idx)];
        cnt += (mx + d - 1) / d;
        b[idx] -= (mx + d - 1) / d * d;
        if (b[idx] < a[idx]) {
            cout << -1 << "\n";
            return;
        }
        if (b[idx] > a[idx]) {
            pq.push(pair<int, int>(b[idx], idx));
        }
    }

    cout << cnt << "\n";
    return;
}

