const int MAX = 2e5+10;
const int NG = -1;

int N;
ll A[MAX], B[MAX];

ll solve() {
    priority_queue<ii> q;
    ll ans = 0;
    REP (i, N) {
        if (B[i] == A[i]) continue;
        if (B[i] < A[i]) return NG;
        q.push(ii(B[i], i));
    }

    while (!q.empty()) {
        ll i = q.top().second;
        q.pop();
        ll r = B[(i+1)%N] + B[(N+i-1)%N];
        ll k = (B[i] - A[i]) / r;
        if (k <= 0) return NG;
        ans += k;
        B[i] -= r * k;
        if (A[i] == B[i]) continue;
        q.push(ii(B[i], i));
    }

    return ans;
}

