		}
		LL An = (A[i] - B[i]) % (A[L(i)] + A[R(i)]) + B[i];
		if (An == A[i])return;
		que.insert({ An - B[i],i });
		val[i] = An - B[i];
	};
	for (LL i = 0; i < N; ++i) {
		seal(i);
	}
	LL ans = 0;
