int main()
{
    int n;
    cin >> n;
    vector<ll> a(n+1);
    vector<ll> b(n+2);
    for(int i = 1; i <= n; i++)
    {
        cin >> a[i];
    }
    priority_queue<P> que;
    for(int i = 1; i <= n; i++)
    {
        cin >> b[i];
        que.push(P(b[i], i));
    }
    b[0] = b[n];
    b[n+1] = b[1];
    ll ans = 0;
    while(que.size())
    {
        P p1 = que.top();
        que.pop();
        ll pos = p1.second;
        ll cand, up1;
        ll dec = b[pos-1] + b[pos+1];
        if(que.size() == 0)
        {
            cand = a[pos];
