            }
        }
        else
        { 
            P p2 = que.top();
            cand = p2.first;
            ll x = p1.first - cand;
            up1 = p1.first - dec * (x/dec + 1);
            ans += (x/dec + 1);
        }
        if(up1 < a[pos])
        {
            cout << -1 << endl;
            return 0;
        }
        else
        {
