ll solver(vector<ll>A,vector<ll>B){
    int N = (int)A.size();
    ll res = 0;
    while(true){
        ll max1 = -LINF,max2 = -LINF;
        ll id1 = -1,id2 = -1;
        for(int i = 0; i < N;i++){
            if(A[i] == B[i]) continue;
            if(B[i] > max1){
                id2 = id1;
                id1 = i;

                max2 = max1;
                max1 = B[i];
            }else if(B[i] > max2){
                id2 = i;
                max2 = B[i];
            }
        }
        if(max1 == -LINF) break;
        ll S = B[(id1-1+N)%N] + B[(id1+1+N)%N];
        if(max1 == max2){
            res++;
            B[id1] -= S;
        }else{
            ll C = ((max1-max(A[id1],max2))+S-1)/S;
            res+=C;
            B[id1] -= S*C;
        }
        if(B[id1] < A[id1]) return -1;
    }
    return res;
}

