        int nxt = getNext(id);
        tmp.erase(it);
        ll nxtval = A[id];
        if(tmp.size()>0){ // get the next smallest value
            it = tmp.end();
            it--;
            nxtval = it->first;
            if(nxtval <= A[id]){ // need to resolve directly
                if ((val-A[id])%(B[prev]+B[nxt])!=0){
                    cout << -1 << endl;
                    return 0;
                }
                cnt += (val-A[id])/(B[prev]+B[nxt]);
                B[id] = A[id]; // no need to add it back
                continue;
            }else{ // make it smaller than nxtval
                cnt += (val-nxtval)/(B[prev] + B[nxt]);
                B[id] = (val-nxtval)%(B[prev] + B[nxt]) + nxtval;
                while(B[id]>=nxtval){
                    B[id] = B[id] - B[prev] - B[nxt];
                    cnt++;
                }
                if (B[id] < A[id]){
                    // cout << "id: " << id << endl;
                    cout << -1 << endl;
                    return 0;
                }
                if (B[id] > A[id]){
                    tmp.insert({B[id], id});
                }                
            }
        }else{ // last 1 has to resolve
            if ((val-A[id])%(B[prev]+B[nxt])!=0){
                cout << -1 << endl;
                return 0;
            }
            cnt += (val-A[id])/(B[prev]+B[nxt]);
            break;
        }
    }
    cout << cnt << endl;
    return 0;
}

