main() {
    int64_t n;
    cin >> n;

    vector<int64_t> a(n), b(n);
    for (auto&& aa : a) {
        cin >> aa;
    }
    for (auto&& bb : b) {
        cin >> bb;
    }

    priority_queue<pair<int64_t, int64_t>> q;
    for (auto i : irange(0L, n)) {
        if (b[i] < a[i]) {
            cout << -1 << endl;
            return 0;
        }

        q.emplace(b[i], i);
    }

    int64_t ans = 0;
    while (!q.empty()) {
        auto idx = q.top().second;
        q.pop();

        auto prev = (idx - 1 + n) % n;
        auto next = (idx + 1) % n;

        auto tmp = (b[idx] - a[idx]) / (b[prev] + b[next]);
