        b[idx] -= (b[prev] + b[next]) * tmp;

        if (tmp == 0 && b[idx] != a[idx]) {
            cout << -1 << endl;
            return 0;
        }

        if (a[idx] != b[idx]) {
            q.emplace(b[idx], idx);
        }
    }

    if (a == b) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
