void solve() {
    int n;
    cin >> n;
    vector<ll> a(n), b(n);
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    auto left = [n](int idx) -> int {
        if (idx == 0) return n - 1;
        else return idx - 1;
    };
    auto right = [n](int idx) -> int {
        if (idx == n - 1) return 0;
        else return idx + 1;
    };

    priority_queue<pair<ll, int>> pq;
    rep(i, n) {
        if (a[i] > b[i]) {
            cout << -1 << "\n";
            return;
        }
        if (a[i] < b[i]) {
            pq.push(pair<int, int>(b[i], i));
        }
    }
    ll cnt = 0;
    while (!pq.empty()) {
        int idx = pq.top().second;
        pq.pop();
        ll x = (b[idx] - a[idx]) / (b[left(idx)] + b[right(idx)]);
        if (x == 0) {
            cout << -1 << "\n";
            return;
        }
        cnt += x;
        b[idx] -= (b[left(idx)] + b[right(idx)]) * x;
        if (b[idx] < a[idx]) {
            cout << -1 << "\n";
            return;
        }
        if (b[idx] > a[idx]) {
            pq.push(pair<ll, int>(b[idx], idx));
        }
    }

    cout << cnt << "\n";
    return;
}

