	int* b = new int[N];

	priority_queue<pair<int, int>> que; // 降順に出力

	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	for (int i = 0; i < N; i++) {
		cin >> b[i];
		if (b[i] < a[i]) {
			cout << -1 << endl;
			return 0;
		}
		pair<int, int> p = pair<int, int>(b[i], i);
		que.push(p);
	}

	int count = 0;

	while (que.size() > 0) {
		pair<int, int>p = que.top();
		que.pop();
		int i = p.second;
		int k = p.first;
		int left = b[(i + 1) % N];
		int right = b[(i + N - 1) % N];

		if (a[i] < k) {
			if (left + right > k - a[i]) {
				cout << -1 << endl;
				return 0;
			}

			int s = max(a[i], max(left, right));
			int r = (k - s) / (left + right);
			if (r > 0) {
				count += r;
				k -= (left + right) * r;
			}

			if (k > a[i]) {
				if (k == left || k == right) {
					cout << -1 << endl;
					return 0;
				}
				k -= (left + right);
				count++;
			}

			b[i] = k;
			if (k < a[i]) {
