int solve(int N, const vector<int>& A, const vector<int>& B0) {
    auto B = B0;
    set<pair<int, int>> bag;
    REP(i, N) {
        if (B[i] < A[i]) return -1;
        if (B[i] == A[i]) continue;
        bag.insert({-B[i], i});
    }
    int ans = 0;
    //debug(A);
    //debug(B, bag);
    while (!bag.empty()) {
        ++ans;
        //debug(B, bag);
        int i = bag.begin()->second;
        int i0 = i == 0 ? N-1 : i-1;
        int i1 = i == N-1 ? 0 : i+1;
        //debug(i0, i, i1, "B:", B[i0], B[i], B[i1]);
        B[i] -= B[i0] + B[i1];
        if (B[i] < A[i]) return -1;
        bag.erase(bag.begin());
        if (B[i] == A[i]) continue;
        bag.insert({-B[i], i});
    }
    return ans;
}

