vector<ll> A;
vector<ll> B;

int check(int idx){
    int l, r;
    if(idx == 0){
        l = N-1; r = 1;
    }
    else if(idx == N - 1){
        l = N-2; r = 0;
    }
    else{
        l = idx-1; r = idx + 1;
    }

    if(B[idx] - B[l] - B[r] >= A[idx]){
        return true;
    }
    return false;
}

void proc(int idx){
    int l, r;
    if(idx == 0){
        l = N-1; r = 1;
    }
    else if(idx == N - 1){
        l = N-2; r = 0;
    }
    else{
        l = idx-1; r = idx + 1;
    }

    ll tmp = B[idx] / (B[l] + B[r]);
    B[idx] -= tmp * (B[l] + B[r]);
    ans += tmp;
    return;
}

void bfs(){
    queue<int> que;
    for(int i = 0; i < N; ++i){
        if(check(i)){
            que.push(i);
        }
    }

    while (!que.empty()) {
        int idx = que.front(); que.pop();
        proc(idx);

        int l, r;
        if(idx == 0){
            l = N-1; r = 1;
        }
        else if(idx == N - 1){
            l = N-2; r = 0;
        }
        else{
            l = idx-1; r = idx + 1;
        }

        if (check(l)) {
            que.push(l);
        }
        if (check(r)) {
            que.push(r);
        }
    }
    return;
}

