inline int &B(int x) {
	if(x < 1) return b[x + n];
	if(x > n) return b[x - n];
	return b[x];
}

int main() {
	n = input();
	for(int i = 1; i <= n; i ++)
		a[i] = input();
	std::queue<int> q;
	for(int i = 1; i <= n; i ++) {
