		if(b[i] > B(i - 1) and b[i] > B(i + 1))
			q.push(i);
	}
	lolong ans = 0;
	while(not q.empty()) {
		int p = q.front();
		q.pop();
		int sum = B(p - 1) + B(p + 1);
		int max = std::max(a[p], std::max(B(p - 1), B(p + 1)));
		int times = (b[p] - max + sum - 1) / sum;
