            const int cnt = max(1LL, (current - lowerValue) / (next + previous));
            current -= cnt * (next + previous);
            answer += cnt;

            if (current < A[index]) {
                out << -1 << "\n";
                return;
            } else if (A[index] < current) {
                que.push({current, index});
            }
        }
        out << answer << "\n";
    }
};


