		if(a[id] == val){
			continue;
		}
		int res = 0;
		if(id - 1 > 0) res += b[id - 1];
		else res += b[n];
		if(id + 1 <= n) res += b[id + 1];
		else res += b[1];
		int nxt = a[id] + res;
		if(!q.empty()){
		    nxt = max(q.top().f, nxt);
		}
		int k = (b[id] - nxt + res) / res;
		ans += k;
		b[id] -= k * res;
		if(b[id] < a[id]) break;
		if(b[id] > a[id]) q.push(mp(b[id], id));
	}

	for(int i = 1; i <= n; i++){
		if(a[i] != b[i]){
			cout << -1;
			return 0;
		}
	}
	cout << ans;


return 0;
}

