using namespace std;

template<typename T>
struct Segtree {
    int n;
    T e;
    vector<T> dat;
    typedef function<T(T a, T b)> Func;
    Func f;

    Segtree(){}
    Segtree(int n_input, Func f_input, T e_input){
        initialize(n_input, f_input, e_input);
    }
    void initialize(int n_input, Func f_input, T e_input){
        f = f_input;
        e = e_input;
        n = 1;
        while(n < n_input) n <<= 1;
        dat.resize(2*n-1, e);
    }

    void update(int k, T a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1)/2;
            dat[k] = f(dat[2*k+1], dat[2*k+2]);
        }
    }

    T get(int k){
        return dat[k+n-1];
    }

    T between(int a, int b){
        return query(a, b+1, 0, 0, n);
    }

    T query(int a, int b, int k, int l, int r){
        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return dat[k];
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};

void fail(){
    cout << -1 << endl;
    exit(0);
}

int main(){
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for(int i=0; i<N; i++) cin >> A[i];
    for(int i=0; i<N; i++) cin >> B[i];
    for(int i=0; i<N; i++) if(A[i] > B[i]) fail();
    typedef pair<int, int> P;
    P MIN = {-1e9, -1};
    Segtree<P> st(N, [](P a, P b){ return max(a, b); }, MIN);
    for(int i=0; i<N; i++) st.update(i, {B[i], i});

    int64_t ans = 0;
    while(true){
        int i = st.between(0, N-1).second;
        if(i == -1) break;
        int n1 = B[(i+1)%N], n2 = B[(i+N-1)%N];
        int d = n1 + n2;
        int num = (B[i]-A[i])/d;
        ans += num;
        B[i] -= num*d;
        if(B[i] == A[i]){
            st.update(i, MIN);
        }else{
            if(B[i] >= max(n1, n2)) fail();
            st.update(i, {B[i], i});
        }
    }
    cout << ans << endl;
    return 0;
}

