#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}


ll solve(int N, vi& a, vi& b) {
    priority_queue<ii> pq;
    rep(i,N){
        if (b[i] < a[i]) return -1;
        if (b[i] == b[(i+1)%N]) return -1;
    }
    rep(i,N){
        if (b[i] == a[i]) continue;
        pq.emplace(b[i], i);
    }

    ll ans = 0;
    while (!pq.empty()){
        int val=pq.top().first, i=pq.top().second; pq.pop();
        assert(b[i] == val);

        int left=b[(i-1+N)%N], right=b[(i+1)%N], w = left + right;
        if (left > val) return -1;
        if (left == val) {
            if (a[(i-1+N)%N] != left) return -1;
        }
        if (right > val) return -1;
        if (right == val) {
            if (a[(i+1)%N] != right) return -1;
        }

        int mi = min(left, right), mx = max(left, right);
        int target = mx-1; if (target == mi) --target;

        if (a[i] > target) {
            target = a[i];
        }
        int over = val - target;
        int step = (over + w-1) / w;
        int ws = w * step;

        if (val - ws < a[i]) return -1;
        b[i] = val - ws;
        ans += step;
        if (b[i] > a[i]) pq.emplace(b[i], i);
    }

    rep(i,N) if (b[i] != a[i]) return -1;

    return ans;
}

int main() {
    int N; scanf("%d%*c", &N);
    vi a(N), b(N);
    loadvec(a, N);
    loadvec(b, N);
    cout << solve(N,a,b) << endl;
    return 0;
}

