bool satisfy(int i) {
  int a = B[(i - 1 + N) % N];
  int b = B[i];
  int c = B[(i + 1) % N];

  return (B[i] > A[i]) && (b > (a + c));
}

void perform_ops(int i) {
  int a = B[(i - 1 + N) % N];
  int b = B[i];
  int c = B[(i + 1) % N];

  if((b % (a + c)) == 0) {
    ans += (b / (a + c));
    ans -= 1;
    B[i] = a + c;
  } else {
    ans += (b / (a + c));
    B[i] = b % (a + c);
  }
}

