			ans = -1;
			break;
		}
		int i = it->second;
		c.erase(it);
		int d = b[i] - a[i];
		int e = b[(i + 1) % n] + b[(i - 1 + n) % n];
		int r = d / e;
		ans += r;
		b[i] -= r * e;
		if (a[i] != b[i]) c.insert(make_pair(b[i], i));
	}

	cout << ans << endl;

	return 0;
