void solv() {

	cin >> n;
	ll a[200010];
	priority_queue<pll> q;

	for (size_t i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	ll b[200010];
	bool ok = true;
	for (size_t i = 0; i < n; i++)
	{
		cin >> b[i];
		if (a[i] > b[i]) {
			ok = false;
		}
		if(a[i] < b[i])
			q.push(make_pair(b[i], i));
	}
	if (!ok) {
		cout << -1 << endl;
		return;
	}
	ll cnt = 0;
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		ll v1 = b[(p.second + 1) % n];
		ll v2 = b[(p.second + n - 1) % n];
		ll v = (v1 + v2);
		if (q.empty()) {
			if ((p.first - a[p.second]) % v != 0) {
				cout << -1 << endl;
				return;
			}
			cnt += (p.first - a[p.second]) / v;
			break;
		}
		else {
			ll ma = max(a[p.second], max(v1,v2));
			ll rem = p.first - ma;
			ll t = rem / v;
			if (t > 0) {
				cnt += t;
				b[p.second] -= t * v;
			}
			else {
				cnt++;
				b[p.second] -= v;
			}
		}

		if (b[p.second] < a[p.second]) {
			cout << -1 << endl;
			return;
		}
		if (b[p.second] > a[p.second]) {
			q.push(make_pair(b[p.second], p.second));
		}
	}

	cout << cnt << endl;
}
