void solve(void)
{
  using std::string;
  using std::vector;
  using std::map;
  using std::pair;
  using std::cin;
  using std::cout;
  ui N{}; std::cin >> N;
  vector<ll> A(N), B(N);
  rep(0, N) cin >> A[i];
  rep(0, N) cin >> B[i];

  typedef pair<ui, ll> Pair;
  auto cmp = [](Pair p1, Pair p2){ return p1.second < p2.second; };
  std::priority_queue<Pair, vector<Pair>, decltype(cmp)> queue(cmp);
  rep(0, N)
  {
    if(B[i] > A[i])
    {
      queue.push({i, B[i]});
    }
    else if(B[i] < A[i])
    {
      cout << "-1" << '\n';
      return;
    }
  }

  // ll ans = queue.empty() ? -1 : 0;
  ll ans{};
  while(!queue.empty())
  {
    Pair p = queue.top();
    queue.pop();
    auto curr = p.first;
    auto sum = B[(curr + N - 1) % N] + B[(curr + 1) % N];

    if((A[curr] - B[curr]) % sum == 0)
    {
      ans += (B[curr] - A[curr]) / sum;
      B[curr] = A[curr];
      continue;
    }
    if(B[curr] <= sum)
    {
      ans = -1;
      break;
    }

    ans += B[curr] / sum;
    B[curr] %= sum;
    if(B[curr] < A[curr])
    {
      ans = -1;
      break;
    }

    queue.push({curr, B[curr]});

  }

  cout << ans << '\n';
  return;
}

