        auto prev = (idx - 1 + n) % n;
        auto next = (idx + 1) % n;

        auto tmp = (b[idx] - a[idx]) / (b[prev] + b[next]);
        ans += tmp;
        b[idx] -= (b[prev] + b[next]) * tmp;

        if (b[idx] != a[idx] && b[idx] >= b[prev] + b[next]) {
            cout << -1 << endl;
            return 0;
        }

        auto prev2 = (prev - 1 + n) % n;
        if (b[prev] - (b[prev2] + b[idx]) >= a[prev]) {
            q.emplace(b[prev], prev);
        }

        auto next2 = (next + 1) % n;
        if (b[next] - (b[idx] + b[next2] >= a[next])) {
            q.emplace(b[next], next);
        }
    }

    if (a == b) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
}

