priority_queue<pii> pq;

int pv(int x) {
	if (x==0) return n-1;
	return --x;
}
int nx(int x) {
	if (x==n-1) return 0;
	return ++x;
}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);

	cin >> n;
	for (int i=0; i<n; i++) cin >> arr[i];
	for (int i=0; i<n; i++) cin >> brr[i];

	for (int i=0; i<n; i++) pq.push(pii(brr[i], i));

	while (!pq.empty()) {
		pii tmp = pq.top();
		pq.pop();

		//cout << tmp.va << ' ' << tmp.vb << '\n';
		int v = tmp.va, i = tmp.vb;
		if (v < arr[i]+brr[pv(i)]+brr[nx(i)]) {
			if (brr[i] == arr[i] && brr[pv(i)] == arr[pv(i)] && brr[nx(i)] == arr[nx(i)]) continue;
			break;
		}

		ans += (ll) (brr[i]-arr[i])/(brr[pv(i)]+brr[nx(i)]);
		brr[i] = (brr[i]-arr[i])%(brr[pv(i)]+brr[nx(i)])+arr[i];
		pq.push(pii(brr[i], i));
	}

	for (int i=0; i<n; i++) {
		if (arr[i] == brr[i]) continue;

		cout << -1;
		return 0;
	}

	cout << ans;
}

