vector<int> as;
vector<int> bs;

int solve() {
  int ops = 0;
  while (true) {
    bool ok = true;
    bool changed = false;
    for (int i = 0; i < bs.size(); ++i) {
      auto a = as[i];
      auto b = bs[i];
      if (a > b) return -1;
      if (a == b) continue;
      ok = false;
      auto pre = i == 0 ? bs.back() : bs[i - 1];
      auto post = i == bs.size() - 1 ? bs.front() : bs[i + 1];
      if (b > pre && b > post && (b - pre - post) >= a) {
        changed = true;
        bs[i] -= pre + post;
        ++ops;
      }
    }
    if (ok) break;
    if (!changed) return -1;
  }
  return ops;
}

