int n;
bool good(int i) {
    return (b[i] > b[(i + 1) % n] + b[(i + n - 1) % n] && b[i] > a[i]);
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> a[i];
    for (int i = 0; i < n; i++)
        cin >> b[i];

    vector<int> V;
    for (int i = 0; i < n; i++)
        if (good(i))
            V.push_back(i);
    long long int ans = 0;
    for (int p = 0; p < V.size(); p++) {
        int i = V[p];
        int t = b[(i + 1) % n] + b[(i + n - 1) % n];
        int k = (b[i] - a[i]) / t;
        ans += k;
        b[i] -= t * k;
        if (good((i + 1) % n))
            V.push_back((i + 1) % n);
        if (good((i + n - 1) % n))
            V.push_back((i + n - 1) % n);
    }
    for (int i = 0; i < n; i++)
        if (a[i] != b[i]) {
            ans = -1;
            break;
        }
    cout << ans << "\n";
}

