int main() {
	long long n;
	cin>>n;
	vector<long long> sol(n);
	for(long long i=0; i<n; i++)
		cin>>sol[i];
	priority_queue<pair<long long,long long> > pq;
	unordered_map<long long,long long> mp;
	for(long long i=0; i<n; i++) {
		long long temp;
		cin>>temp;
		pq.push(make_pair(temp, i));
		mp[i] = temp;
	}
	long long prev, next;
	long long flag = true;
	long long count = 0;
	while(!pq.empty()) {
		pair<long long,long long> k = pq.top();
		pq.pop();
		long long index = k.second;
		long long num = k.first;
		if(sol[index] == k.first)
			continue;
		if(index == 0) {
			prev = n-1;
			next = 1;
		}
		else if(index == n-1) {
			next = 0;
			prev = n-2;
		}
		else {
			next = index+1;
			prev = index-1;
		}

		long long next_num = mp[next];
		long long prev_num = mp[prev];
		long long new_num = num - next_num- prev_num;
		//cout<<new_num<<endl;
		pq.push(make_pair(new_num, index));
		mp[index] = new_num;
		if(mp[index] < sol[index]) {
			cout<<-1;
			exit(0);
		}
		count++;
		bool done = true;
		for(long long i=0; i<n; i++) {
			if(mp[i] > sol[i]) {
				done = false;
				break;
			}
		}
		if(done == true) {
			cout<<count;
			exit(0);
		}
	}


}

