int main() {
	int N;



	cin >> N;

    vector<long long> A(N), B(N);
    priority_queue<pair<long long, int>> seq;
    for (auto& i : A)
      cin >> i;
    for (auto& i : B)
      cin >> i;

    REP(i, N) {
      auto tmp = B[i] - A[i];
      if (tmp < 0LL) {
        cout << -1 << endl;
        return 0;
      }
      else if (tmp > 0LL)
        seq.emplace(tmp, i);
    }

    int r = 0;
    while (!seq.empty()) {
      auto i = seq.top().second; seq.pop();

      if (B[i] < (B[(i-1+N) % N] + B[(i+1) % N])) {
        cout << -1 << endl;
        return 0;
      }
      auto yabai = max(B[(i-1+N) % N] - A[(i-1+N) % N], B[(i+1) % N] - A[(i+1) % N]);
      auto heri = (B[i] - yabai) / (B[(i-1+N) % N] + B[(i+1) % N]);
      if (yabai) heri++;
      r += heri;
      B[i] = B[i] - (B[(i-1+N) % N] + B[(i+1) % N]) * heri;
      auto tmp = B[i] - A[i];
      if (tmp < 0LL) {
        cout << -1 << endl;
        return 0;
      }
      else if (tmp > 0LL)
        seq.emplace(tmp, i);

    }

	cout << r << endl;

	return 0;
}

