int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll n;
    in >> n;
    ll a[n];
    ll b[n];
    REP(i, n){
        in >> a[i];
    }
    REP(i, n){
        in >> b[i];
    }
    priority_queue<pair<ll, ll> > q;
    ll cnt = 0;
    REP(i, n){
        q.push(lp(b[i], i));
    }

    ll idx, p_idx, n_idx;
    ll minus, times;
    ll pre_idx = -1;
    while(!q.empty()){
        idx = q.top().second;
        q.pop();

        if(b[idx] == a[idx]) continue;
        p_idx = idx - 1;
        n_idx = idx + 1;
        if(p_idx == -1) p_idx = n - 1;
        if(n_idx == n) n_idx = 0;

        times = 1;
        minus = b[p_idx] + b[n_idx];
