        }
        times = min((b[idx] - a[idx]) / minus, ll(ceil((b[idx] - minus) / double(minus))));

        b[idx] -= minus * times;
        // out << idx << " " << b[idx] << endl;
        cnt += times;
        pre_idx = idx;
        if(b[idx] == a[idx]){
            continue;
        }else{
            q.push(lp(b[idx], idx));
        }
    }
    out << cnt << endl;
}

