int fin() {
    cout << -1 << endl;
    return 0;
}

int main() {
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++)cin >> a[i];
    vector<int> b(n);
    for (int i = 0; i < n; i++)cin >> b[i];

    priority_queue<vector<int>> que;
    for (int i = 0; i < n; i++) {
        if (b[i] > a[i]) que.push({b[i], i});
        else if (b[i] < a[i])return fin();
    }

    int ret = 0;
    while (!que.empty()) {
        auto v = que.top();
        que.pop();

        int sum_next = b[convert(v[1] - 1)] + b[convert(v[1] + 1)];
        int count = max(1, (b[v[1]] - (que.empty() ? 0 : max(0, que.top()[1] - sum_next + 1))) / sum_next);
        b[v[1]] -= sum_next * count;
        ret += count;
        if (b[v[1]] < a[v[1]])return fin();
        if (b[v[1]] == a[v[1]])continue;
        que.push({b[v[1]], v[1]});
    }

    for (int i = 0; i < n; i++) {
        if (a[i] != b[i])return fin();
    }

    cout << ret << endl;
    return 0;
}

