ll sum(vector<ll> &A) {
	ll s = 0;
	for(int i = 0; i < A.size(); i++) s += A[i];
	return s;
}

bool zerominus(vector<ll> &B) {
	for (int i = 0; i < B.size(); i++) {
	    if (B[i] <= 0) return true;
	}
	return false;
}

int solveNaive(vector<ll> &A, vector<ll> &B) {
	int N = A.size();

	int ans = 0;
	while(sum(A) < sum(B) && !zerominus(B)) {
		ll ma = 0, ma_i = -1;
		for(int i = 0; i < B.size(); i++) {
			if (ma < B[i] && B[(i + N - 1) % N] + B[(i + 1) % N] < B[i]) {
				ma_i = i;
				ma = B[i];
			}
		}
		if (ma_i == -1) break;
		ans++;
		B[ma_i] -= B[(ma_i + N - 1) % N] + B[(ma_i + 1) % N];
	}

	if (A == B) {
		return ans;
	} else {
		return -1;
	}
}

ll calcScore(vector<ll> &B, vector<ll> &around_sum, int i) {
	return ((B[i] - around_sum[i]) <= 0 ? -1 : 1) * B[i];
}

int solve(vector<ll> &A, vector<ll> &B) {
	int N = A.size();
	vector<ll> around_sum(N);
	for(int i = 0; i < N; i++) {
		around_sum[i] = B[(i + N - 1) % N] + B[(i + 1) % N];
	}

	vector<ll> score(N);
	for(int i = 0; i < N; i++) {
		score[i] = calcScore(B, around_sum, i);
	}
	set<pll, greater<pll>> S;
	for(int i = 0; i < N; i++) {
		S.insert({score[i], i});
	}

	ll sumA = 0;
	ll sumB = 0;
	for(int i = 0; i < N; i++) {
		sumA += A[i];
	}

	for (int i = 0; i < N; i++) {
	    sumB += B[i];
	}

	int ans = 0;
	while(sumA < sumB && !zerominus(B)) {
		pll ma = *S.begin();
		if (ma.first < 1) break;

		ll minus = around_sum[ma.second];

		int i = ma.second;
		int j = (i + 1) % N;
		int k = (i + N - 1) % N;

		S.erase({calcScore(B, around_sum, i), i});
		S.erase({calcScore(B, around_sum, j), j});
		S.erase({calcScore(B, around_sum, k), k});

		around_sum[j] -= minus;
		around_sum[k] -= minus;
		B[i] -= minus;
		sumB -= minus;

		S.insert({calcScore(B, around_sum, i), i});
		S.insert({calcScore(B, around_sum, j), j});
		S.insert({calcScore(B, around_sum, k), k});

		ans++;
	}

	if (A == B) {
		return ans;
	} else {
		return -1;
	}	
}

vector<ll> genValid(int N, int K) {
	vector<ll> ret(N, 1);
	for(int i = 0; i < K; i++) {
		int r = rand() % N;
		ret[r] = ret[(r + N - 1) % N] + ret[(r + 1) % N] + ret[r];
	}
	return ret;
}

void testValidCase(int N) {
	const int K = 5;
	for(int t = 0; t < 100; t++) {
		vector<ll> A(N, 1);
		vector<ll> B_ = genValid(N, K);
		vector<ll> B = B_;
		int ret = solve(A, B);
		if (ret != K) {
			cout << "Test Failed (1)" << endl;
			cout << "input(A): " << A << ", input(B): " << B << endl;
			cout << "expect: " << K << ", output: " << ret << endl; 
