			cout << "Test Failed (2)" << endl;
			cout << "input(A): " << A << ", input(B): " << B << endl;
			cout << "expect: " << K << ", output[solve]: " << ret << ", output[solveNaive]: " << ret2 << endl; 
		}
	}
}


