int N;
int arr[MAX];
int brr[MAX];
queue<int> q;

int test(int idx)
{
	if (idx == 0) return brr[0] > brr[1] + brr[N - 1];
	if (idx == N - 1) return brr[N - 1] > brr[0] + brr[N - 2];
	return brr[idx] > brr[idx - 1] + brr[idx + 1];
}

int main(void)
{
	cin >> N;
	for (int i = 0; i < N; i++) cin >> arr[i];
	for (int i = 0; i < N; i++) cin >> brr[i];
	for (int i = 0; i < N; i++)
	{
		if (test(i)) q.push(i);
	}
	int ans = 0;
	while (!q.empty())
	{
		int cur = q.front();
		q.pop();
		int prv;
		int nxt;
		if (cur) prv = cur - 1;
		else prv = N - 1;
		if (cur < N - 1) nxt = cur + 1;
		else nxt = 0;
		brr[cur] -= brr[prv] + brr[nxt];
		ans++;
		if (brr[cur] < arr[cur])
		{
			cout << -1 << endl;
			return 0;
		}
		if (test(prv)) q.push(prv);
		if (test(cur)) q.push(cur);
		if (test(nxt)) q.push(nxt);
	}
	for (int i = 0; i < N; i++)
	{
		if (arr[i] != brr[i])
		{
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

