    int im=i-1, ip=i+1;
    if(im==-1)im=n-1;
    if(ip==n)ip=0;
    int x=(B[im]+B[ip]);
    int y=max(B[im], B[ip]);
    if(B[i]<x+A[i]){
      puts("-1");
      return 0;
    }
    int cntp=min((B[i]-A[i])/x, (B[i]-y)/x+1);
    cnt+=cntp;
    B[i]-=cntp*x;
    if(B[i]>A[i]){
      S.push(make_pair(B[i], i));
    }

  }

  printf("%d\n", cnt);
  return 0;
}

