    scanf("%lld", &a[i]);
  }
  for(int i = 0; i < n; i++) {
    scanf("%lld", &b[i]);
    if(b[i] > a[i]) pq.push({b[i], i});
  }
  ll moves = 0;
  while(not pq.empty()) {
    auto cur = pq.top(); pq.pop();
    ll have = cur.first;
    int idx = cur.second;
    if(b[idx] != have) continue;
    ll d = b[(idx + n - 1) % n] + b[(idx + 1) % n];
    if((b[idx] - a[idx]) % d == 0) {
      moves += (b[idx] - a[idx]) / d;
      b[idx] = a[idx];
    } else {
      moves += b[idx] / d;
      b[idx] %= d;
    }
    if(b[idx] > a[idx]) pq.push({b[idx], idx});
  }
  for(int i = 0; i < n; i++) {
    if(a[i] != b[i]) moves = -1;
  }
  cout << moves << '\n';
}

