        if (B[i] < A[i]) {
            cout << -1 << "\n";
            return 0;
        }
        if (B[i] > A[i]) q.push({B[i], i});
    }
    LL ans = 0;
    while (!q.empty()) {
        auto pp = q.top();
        q.pop();
        int it = pp.second;
        int x = B[(it+N-1)%N], y = B[(it+1)%N];
        int goal = max(A[it], max(x, y));
        if (goal >= B[it]) {
            cout << -1 << "\n";
            return 0;
        }
        int k = (B[it]-goal-1)/(x+y);
        k++;
        ans += k;
        B[it] -= ((LL)k) * (x+y);
        if (B[it] < A[it]) {
