#include <cstdio>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;
using pii = pair<int,int>;

int main(){
    int n, ans=0;
    scanf("%d", &n);
    vector<int> ini(n), ar(n);
    auto comp = [](pii x, pii y){
        return x.second < y.second;
    };
    priority_queue<pii,vector<pii>,decltype(comp)> qu(comp);
    for(int i=0;i<n;i++){
        scanf("%d", &ini[i]);
    }
    for(int i=0;i<n;i++){
        scanf("%d", &ar[i]);
        qu.push( make_pair(i,ar[i]) );
    }
    while(!qu.empty()){
        auto itr = qu.top();
        qu.pop();

        int diff = ar[(itr.first+n-1)%n]+ar[(itr.first+n+1)%n];
        int tmp = ar[itr.first]/diff;
        if(tmp==0) break;
        ans += tmp;
        ar[itr.first] -= tmp*diff;
        if(ar[itr.first]>ini[itr.first])
            qu.push( make_pair(itr.first, ar[itr.first]) );
    }
    if(ini==ar)
        printf("%d\n", ans);
    else
        printf("-1\n");
    return 0;
}

#include <stdio.h>
#include <vector>
#include <set>
