int main() {
  int N;
  int count = 0;
  std::cin >> N;
  std::vector<int> A(N), B(N);

  // 入力
  for (auto& a_i : A) {
    std::cin >> a_i;
  }
  for (auto& b_i : B) {
    std::cin >> b_i;
  }

  std::unordered_set<int> notcomp_indexes;
  for (int i = 0; i < N; i++) {
    if (A.at(i) != B.at(i)) {
      notcomp_indexes.insert(i);
    }
  }

  while (1) {
    bool       end          = true;
    const auto before_count = count;

    int maxB = 0, maxB_i, secondmaxB;
    for (const auto i : notcomp_indexes) {
      if (B.at(i) > maxB) {
        secondmaxB = maxB;
        maxB       = B.at(i);
        maxB_i     = i;
      }
    }
    // 終了条件
    if (maxB == 0) {
      std::cout << count;
      return 0;
    }

    int d; // 変化量
    if (maxB_i == 0) {
      d = B.at(N - 1) + B.at(1);
    } else if (maxB_i == N - 1) {
      d = B.at(N - 2) + B.at(0);
    } else {
      d = B.at(maxB_i - 1) + B.at(maxB_i + 1);
    }
    const int howMany = std::min((B.at(maxB_i) - secondmaxB) / d + 1,
                                 (B.at(maxB_i) - A.at(maxB_i)) / d);
    B[maxB_i] -= d * howMany;
    count += howMany;

    if (howMany <= 0) {
      std::cout << "-1";
      return 0;
    }
    if (B.at(maxB_i) == A.at(maxB_i)) {
      notcomp_indexes.erase(maxB_i);
    }
  }
  return 0;
}

