using P = pair<int,int>;
int main(){
  int N;
  cin >> N;

  bool flag = true;
  int cnt = 0;
  int t_cnt = 0;
  priority_queue<P> PQ;

  vector<int> A(N);
  for(int i=0; i<N; i++){
    cin >> A[i];
  }
  vector<int> B(N);
  for(int i=0; i<N; i++){
    cin >> B[i];
    if(A[i] == B[i]){
      t_cnt++;
    }
    else{
      P add = {B[i],i};
      PQ.push(add);
    }
  }

  while(PQ.size()){
    P p = PQ.top();
    PQ.pop();
    cnt++;
    int a, b;
    if(p.second == 0){
      a = p.first - B[N-1] - B[1];
      b = p.second;
    }
    else if(p.second == N-1){
      a = p.first - B[N-2] - B[0];
      b = p.second;
    }
    else{
      a = p.first - B[p.second + 1] - B[p.second - 1];
      b = p.second;
    }
    B[p.second] = a;
    if(B[p.second] == A[p.second]){
      t_cnt++;
    }
    else if(B[p.second] < A[p.second]){
      flag = false;
      break;
    }
    else{
      P add = {a,b};
      PQ.push(add);
    }
  }

  if(flag && t_cnt == N){
    cout << cnt << endl;
  }
  else{
    cout << -1 << endl;
  }
}

