	for (int i = 0; i < n; i++) cin >> b[i];
	set<pair<int, int>, greater<pair<int, int> > > c;
	for (int i = 0; i < n; i++) c.insert(make_pair(b[i], i));

	int ans = 0;

	while (!c.empty()) {
		int i = c.begin()->second;
		c.erase(c.begin());
		int d = b[i] - a[i];
		int e = b[(i + 1) % n] + b[(i - 1 + n) % n];
		int r = d / e;
		if (r == 0) {
			ans = -1;
			break;
		}
		ans += r;
		b[i] -= r * e;
		if (d % e != 0)
			c.insert(make_pair(b[i], i));
	}

	cout << ans << endl;

	return 0;
}

