const int MAX = 2e5+10;

int N;
ll A[MAX], B[MAX];

ll solve() {
    priority_queue<ii> b;
    int ans = 0;
    REP (i, N) {
        if (A[i] == B[i]) continue;
        if (B[i] < A[i]) return -1;
        b.push(ii(B[i], i));
    }

    while (!b.empty()) {
        ll x = b.top().first, i = b.top().second; b.pop();
        ll c1 = B[(i+1)%N], c2 = B[(N+i-1)%N];
        ll r = c1 + c2;
        int k = (B[i] - max({A[i], c1-r, c2-r})) / r;
        if (k == 0) return -1;
        ans += k;
        B[i] -= r * k;
        if (A[i] == B[i]) continue;
        b.push(ii(B[i], i));
    }

    return ans;
}

