			int d = B[ring(N, i - 1)] + B[ring(N, i + 1)];
			if (B[i] <= d || B[i] == A[i]) {
				index[i] = 0;
				continue;
			}

			int side = max(B[ring(N, i - 1)], B[ring(N, i + 1)]);
			if (A[i] > side && (B[i] - A[i]) % d != 0) {
				cout << "-1" << endl;
				return 0;
			}

			if (B[i] > A[i] && A[i] > side) {
				index[i] = (B[i] - A[i]) / d;
				allinv = 1;
			}
			else {
				index[i] = 1;
				allinv = 1;
			}
		}
		if (allinv == 0) {
			cout << "-1" << endl;
			return 0;
		}
		rep(i, N) {
			B[i] -= index[i] * (B[ring(N, i - 1)] + B[ring(N, i + 1)]);
			count += index[i];

			if (B[i] < A[i]) {
				cout << "-1" << endl;
				return 0;
			}
			else if (B[i] != A[i]) {
				flag = 0;
			}
		}
		if (flag == 1) {
			cout << count << endl;
		}
	}

	return 0;
}

