using namespace std;

typedef long long ll;
typedef pair <ll, ll> pll;

struct segtree{
	pll T[606060];
	ll sz = 1 << 18;

	void init(ll n, ll *B)
	{
		ll i;

		for(i=0; i<n; i++){
			T[sz + i] = pll(B[i], i);
		}

		for(i=sz-1; i; i--){
			T[i] = max(T[i << 1], T[i << 1 | 1]);
		}
	}

	void update(ll p, ll v)
	{
		p += sz; T[p] = pll(v, p - sz);

		for(p>>=1; p; p>>=1){
			T[p] = max(T[p << 1], T[p << 1 | 1]);
		}
	}

	pll getval() { return T[1]; }
};

segtree T;
ll A[202020], B[202020];
ll n, cnt, ans;

void die() { printf("-1\n"); exit(0); }

int main()
{
	ll i, v, l, r;

	scanf("%lld", &n);

	for(i=0; i<n; i++){
		scanf("%lld", A + i);
	}

	for(i=0; i<n; i++){
		scanf("%lld", B + i);
		cnt += (A[i] == B[i]);
	}

	T.init(n, B);

	for(; cnt<n; ){
		tie(v, i) = T.getval();
		if(v == -1) die();
		l = B[(i + n - 1) % n]; r = B[(i + 1) % n];

		if(B[i] == A[i]){
			cnt ++; T.update(i, -1);
			continue;
		}

		if(B[i] < A[i] || B[i] <= l + r) die();

		if((B[i] - A[i]) % (l + r) == 0){
			cnt ++;
			ans += (B[i] - A[i]) / (l + r);
			B[i] = A[i]; T.update(i, -1);
			continue;
		}
		else{
			ans += B[i] / (l + r);
			B[i] %= (l + r);
			T.update(i, B[i]);
		}
	}

	printf("%lld\n", ans);

	return 0;
}

