int anstmp;

vector<int> Bdec_all(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	while (1)
	{
		if (Btmp[i] > Bnei && Btmp[i] > A[i])
		{
			Btmp[i] -= Bnei;
			anstmp++;
		}
		else
			break;
	}
	return Btmp;
}

vector<int> Bdec(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if (Btmp[i] > A[i])
	{
		Btmp[i] -= Bnei;
		anstmp++;
	}
	return Btmp;
}

bool Btop(int i, vector<int> Btmp)
{
	if (Btmp[i] > (Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N]))
		return true;
	return false;
}

void DP(vector<int> Bprev, int anstmptmp)
{
	anstmp = anstmptmp;
	for (int i = 0; i < N; i++)
	{
		if (Btop(i, Bprev))
			Bprev = Bdec_all(i, Bprev);
	}
	anstmptmp = anstmp;
	for (int i = 0; i < N; i++)
	{
		vector<int> Bnext;
		if (Btop(i, Bprev))
		{
			anstmp = anstmptmp;
			Bnext = Bdec(i, Bprev);
			DP(Bnext, anstmp);
		}
	}
	if (Bprev == A)
		ansmin = min(ansmin, anstmp);
	return;
}

