	for(int i = 0; i < n; i++) scanf("%lld", &b[i]);

	auto f = [n](int ind) {
		return (ind + n) % n;
	};

	auto solve = [n, f](std::vector<i64>& a) {
		using P = std::pair<i64, int>;

		std::priority_queue<P> qu;
		for(int i = 0; i < n; i++) qu.push({a[i], i});

		i64 count = 0;
		while(!qu.empty()) {
			auto p = qu.top(); qu.pop();
			i64 & val = a[p.second];
			i64 tmp = a[f(p.second + 1)] + a[f(p.second - 1)];

			if(val < tmp or !tmp) continue;

			i64 T = val / tmp;
			count += T;
			val %= tmp;

			qu.push({val, p.second});
		}

		return count;
	};
	auto A = solve(a);
	auto B = solve(b);

	if(a != b) printf("-1\n");
	else printf("%lld\n", std::abs(A - B));
	return 0;
