signed main() {
	int i;

	typedef pair<int, int> P;
	priority_queue<P> que;

	cin >> n;
	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];

	int eqCnt = 0;
	rep(i, n) {
		if (a[i] > b[i]) { cout << -1 << endl; return 0; }
		if (a[i] == b[i]) { eqCnt++; }
	}

	rep(i, n) que.push(P(b[i], i));

	int ans = 0;
	while (!que.empty()) {
		P now = que.top(); que.pop();
		int iter = now.second;
		int hoge = b[(iter - 1 + n) % n] + b[(iter + 1) % n];

		int cnt = min((b[iter] + hoge - 1) / hoge, (b[iter] - a[iter]) / hoge);
		if (cnt <= 0) continue;
		b[iter] -= cnt * hoge;
		ans += cnt;

		if (b[iter] < a[iter]) { cout << -1 << endl; return 0; }
		if (b[iter] == a[iter]) { eqCnt++; }
		else { que.push(P(b[iter], iter)); }
	}
	if (eqCnt < n) cout << -1 << endl;
	else cout << ans << endl;
	return 0;
