int n, a[N], b[N]; 

priority_queue <pii> Q; 

int main() {
  scanf("%d", &n); ll ans = 0; 
  for(int i = 1; i <= n; i++) {
    scanf("%d", &a[i]); 
  }
  for(int i = 1; i <= n; i++) {
    scanf("%d", &b[i]); 
    Q.push({b[i], i}); 
    if(b[i] < a[i]) {
      puts("-1"); 
      return 0; 
    }
  }
  while(!Q.empty()) {
    pii tmp = Q.top(); Q.pop(); 
    if(tmp.fi == a[tmp.se]) continue ; 
    if(tmp.fi < a[tmp.se]) {
      puts("-1"); 
      return 0; 
    }
    int id = tmp.se; 
    int id1 = id + 1; 
    int id2 = id - 1; 
    if(id1 > n) id1 -= n; 
    if(id2 < 1) id2 += n; 
    if(tmp.fi < b[id1] + b[id2] + a[id]) {
      puts("-1");
      return 0; 
    }
    int t = b[id1] + b[id2]; 
    int x = b[id] - a[id]; 
    ans += x / t; b[id] -= x / t * t; 
    if(a[id] != b[id])
      Q.push({b[id], id}); 
  }
  for(int i = 1; i <= n; i++) {
    if(a[i] != b[i]) {
      puts("-1"); 
      return 0; 
    }
  }
  printf("%lld\n", ans);
