	ll a[200010], b[200010];
	rep(i, n) cin >> a[i];
	rep(i, n) cin >> b[i];
	priority_queue<pll> q;
	rep(i, n) {
		q.push(make_pair(b[i], i));
	}
	ll res = 0;
	while (!q.empty()) {
		auto p = q.top();
		q.pop();

		ll i = p.second;
		ll nex = (i + 1) % n;
		ll bef = (i + n - 1) % n;
		ll v = b[nex] + b[bef];
		ll ma = max({b[nex],b[bef],a[i]});
