		ll d = inter / v;
		if (inter % v != 0) {
			d++;
		}
		b[i] -= d * v;
		res += d;
		if (b[i] < a[i]) {
			cout << -1 << endl;
			return;
		}

		if (b[i] > a[i]) {
			q.push(make_pair(b[i],i));
		}
	}
	cout << res << endl;
}
