const int N = 200200;
int a[N];
int b[N];
ll ans = 0;
int n;

void solve(int id) {
	int p = id - 1, q = id + 1;
	if (p < 0) p += n;
	if (q >= n) q -= n;
	int k = (b[id] - a[id]) / (b[p] + b[q]);
	if (k <= 0) return;
	ans += k;
	b[id] -= (b[p] + b[q]) * k;
	solve(p);
	solve(q);
}

