int Solve() {
  int n;
  cin >> n;
  vector<int> as(n);
  vector<int> bs(n);
  for (int i = 0; i < n; i++) cin >> as[i];
  for (int i = 0; i < n; i++) cin >> bs[i];

  int cost = 0;
  int match_count = 0;
  for (int i = 0; i < n; i++) {
    if (as[i] == bs[i]) {
      match_count++;
    }
  }

  deque<int> queue;
  for (int i = 0; i < n; i++) {
    queue.push_back(i);
  }


  while (!queue.empty()) {
    int i = queue.front();
    queue.pop_front();
    if (bs[i] - (bs[(i + n - 1) % n] + bs[(i + 1) % n]) >= as[i]) {
      bs[i] -= bs[(i + n - 1) % n] + bs[(i + 1) % n];
      cost++;
      if (bs[i] == as[i]) {
        match_count++;
        if (match_count == n) {
          return cost;
        }
      }
      queue.push_back((i + n - 1) % n);
      queue.push_back(i);
      queue.push_back((i + 1) % n);
    }
  }
  return -1;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve() << endl;
}

