int arr[200000];
int newArr[200000];

struct compare
{
	bool operator()(int const& a, int const& b)
	{
		return newArr[a] < newArr[b];
	}
};

priority_queue<int, vector<int>, compare> pq;

int main()
{
	int n;
	cin >> n;
	for (int i = 0; i < n; i++)
	{
		cin >> arr[i];
	}
	for (int i = 0; i < n; i++)
	{
		cin >> newArr[i];
	}
	for (int i = 0; i < n; i++)
	{
		pq.push(i);
	}
	int elementsLeft = n;
	int result = 0;
	while (elementsLeft > 0)
	{
		int u = pq.top();
		pq.pop();
		if (newArr[u] == arr[u])
		{
			elementsLeft--;
			continue;
		}
		if (newArr[u] < arr[u])
		{
			cout << -1 << endl;
			return 0;
		}
		int sum = newArr[(u + 1) % n] + newArr[(u + n - 1) % n];
		int quotient = newArr[u] / sum;
		if (quotient <= 0) {cout << -1 << endl; return 0;}
		newArr[u] %= sum;
		if (newArr[u] == 0) {newArr[u] = sum; quotient--;}
		pq.push(u);
		result += quotient;
	}
	cout << result << endl;
	return 0;
}

