void solve() {
  int n;
  cin >> n;
  vi32 a(n);
  vi32 b(n);
  cin >> a >> b;
  using T = tuple<int, int>;
  pqdesc<T> q;
  rep(i, n) {
    q.emplace(b[i], i);
  }
  i64 ans = 0;
  while (1) {
    int _, i;
    tie(_, i) = q.top();
    q.pop();
    int prev = (i - 1 + n) % n;
    int next = (i + 1) % n;
    int div = b[prev] + b[next];
    // b[i] - div * c >= a[i] を満たす最大の c
    // - div * c >= a[i] - b[i]
    // div * c <= b[i] - a[i]
    // c <= (b[i] - a[i]) / div
    // c = (b[i] - a[i]) / div
    int c = (b[i] - a[i]) / div;
    if (c <= 0) break;
    b[i] -= div * c;
    ans += c;
    q.emplace(b[i], i);
  }
  if (a == b) {
    cout << ans << endl;
  } else {
    cout << -1 << endl;
  }
}

