			return 0;
		}
	}

	int ans = 0;
	while (!pq.empty()) {
		pair<int, int> p = pq.top();
		pq.pop();
		int i = p.second, d = B[mod(i - 1 + N, N)] + B[mod(i + 1, N)];
		if (B[i] - A[i] < d) {
