        ll x = B[i] - A[i] - B[(i+1)%N] - B[(i+N-1)%N];
        if ( x >= 0 ) {
            q.push(make_pair(x, i));
        }
    };
    for ( int i = 0; i < N; i++ ) {
        check(i);
    }
    ll ans = 0;
    while ( !q.empty() ) {
        auto p = q.top();
        q.pop();
        int i = p.second;
        if ( p.first != B[i] - A[i] - B[(i+1)%N] - B[(i+N-1)%N]) {
            check(i);
            continue;
        } 
        ll c = B[(i+1)%N] + B[(i+N-1)%N];
        ll n = (B[i] - A[i]) / c;
        B[i] -= n * c;
        ans += n;
        check((i+1)%N);
        check((i+N-1)%N);
    }

    for ( int i = 0; i < N; i++ ) {
        if ( A[i] != B[i] ) return -1;
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

