void solv() {
	cin >> n;
	ll a[200010], b[200010];
	priority_queue<pll> q;
	rep(i, n) {
		cin >> a[i];
	}
	rep(i,n){
		cin >> b[i];
		q.push(make_pair(b[i], i));
	}

	ll res = 0;
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		int i = p.second;
		int nex = (p.second + 1) % n;
		int bef = (p.second + n - 1) % n;
		ll v = b[nex] + b[bef];
		ll ma = max({b[nex],b[bef],a[i]});
		ll du = b[i] - ma;
		ll d = du / v;
		if ((du % v) != 0)
			d++;
		res += d;
		b[i] -= d * v;
		if (b[i] < a[i]) {
			cout << -1 << endl;
			return;
		}
		if (b[i] > a[i]) {
			q.push(make_pair(b[i], i));
		}
	}
	cout << res << endl;
}
