template <class T>
class SegTree {
    int n;                       // 葉の数
    vector<T> data;              // データを格納するvector
    T def;                       // 初期値かつ単位元
    function<T(T, T)> operation; // 区間クエリで使う処理
    function<T(T, T)> update;    // 点更新で使う処理

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return def; // 交差しない
        if (a <= l && r <= b)
            return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return operation(c1, c2);
        }
    }

  public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTree(size_t _n, T _def, function<T(T, T)> _operation,
            function<T(T, T)> _update)
        : def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n < _n) {
            n *= 2;
        }
        data = vector<T>(2 * n - 1, def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n - 1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    // [a, b)の区間クエリを実行
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // 添字でアクセス
    T operator[](int i) {
        return data[i + n - 1];
    }
};

int main() {
    int N;
    cin >> N;
    vi A(N), B(N);
    cin >> A >> B;
    SegTree<Pi> st(N, mp(-1, -1), [](Pi a, Pi b) { return max(a, b); },
                   [](Pi a, Pi b) { return b; });
    vb complete(N, false);
    int count = 0;
    rep(i, N) {
        if (B[i] < A[i]) {
            cout << -1 << endl;
            return 0;
        }
        if (B[i] == A[i]) {
            complete[i] = true;
            count++;
            st.change(i, mp(-1, i));
        } else {
            st.change(i, mp(B[i], i));
        }
    }
    ll ans = 0;
    while (count < N) {
        DEB {
            rep(i, N) {
                cout << " " << st[i].first;
            }
            cout << endl;
        }
        Pi p = st.query(0, N);
        int idx = p.second;
        ll left = (complete[(idx + N - 1) % N] ? A[(idx + N - 1) % N]
                                               : st[(idx + N - 1) % N].first);
        ll right = (complete[(idx + 1) % N] ? A[(idx + 1) % N]
                                            : st[(idx + 1) % N].first);
        ll op_num = (p.first - A[idx]) / (left + right);
        ll new_num = p.first - (left + right) * op_num;
        if (op_num == 0) {
            cout << -1 << endl;
            return 0;
        }
        ans += op_num;

        if (new_num == A[idx]) {
            st.change(idx, mp(-1, idx));
            complete[idx] = true;
            count++;
        } else {
            st.change(idx, mp(new_num, idx));
        }
    }
    cout << ans << endl;

    return 0;
}

