            pq.push({A[i], i});
        }
        int res = 0;
        while (!pq.empty()) {
            int val, idx;
            tie(val, idx) = pq.top();
            pq.pop();

            int l = idx > 0 ? idx - 1 : sz - 1;
            int r = idx < sz - 1 ? idx + 1 : 0;

