typedef long long li;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n;
    cin >> n;
    vector<li> xs(n), ys(n);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i];
    }
    priority_queue<pair<li, li>> q;
    for (int i = 0; i < n; ++i) {
        cin >> ys[i];
        q.emplace(ys[i], i);
    }

    li ans = 0;
    while (not q.empty()) {
        auto t = q.top(); q.pop();
        li i = t.second;
        li v = t.first;
        if (v < xs[i]) {
            ans = -1;
            break;
        } else if (v == xs[i]) {
            continue;
        }
        li d = v - xs[i];
        li u = ys[(i + 1) % n] + ys[(i + n - 1) % n];
        if (d % u == 0) {
            ans += d / u;
            ys[i] = xs[i];
            continue;
        } else {
            li nv = v % u;
            if (nv == v) {
                ans = -1;
                break;
            }
            ans += v / u;
            ys[i] = nv;
            q.emplace(nv, i);
        }
    }

    cout << ans << endl;
    return 0;
}

