	return v;
}
int ri(int v) {
	v++;
	if(v>=N) v-=N;
	return v;
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	FOR(i,N) cin>>A[i];
	FOR(i,N) cin>>B[i];

	ll num=0;
	queue<int> Q;
	FOR(i,N) if(B[i]>B[le(i)]+B[ri(i)] && B[i]>A[i]) Q.push(i);
	while(Q.size()) {
		i=Q.front();
		Q.pop();

		//cout<<num<<" "<<i<<" "<<B[0]<<" "<<B[1]<<" "<<B[2]<<endl;

		ll L=B[le(i)];
		ll R=B[ri(i)];
		ll S=L+R;

		if(B[i]<=S) continue;
		if(B[i]<A[i]) return _P("-1\n");
		if(B[i]<=A[i]) continue;

		if(A[i]>S) {
			if((B[i]-A[i])%S) return _P("-1\n");
			num+=(B[i]-A[i])/S;
			B[i]=A[i];
		}
		else {
			ll v=B[i]/S;
			if(B[i]%S) {
				num+=v;
				B[i]%=S;
			}
			else {
				num+=v-1;
				B[i]=S;
			}
		}
		x=le(i);
		if(B[x]>B[le(x)]+B[ri(x)] && B[x]>A[x]) Q.push(x);
		x=ri(i);
		if(B[x]>B[le(x)]+B[ri(x)] && B[x]>A[x]) Q.push(x);
	}

	FOR(i,N) if(A[i]!=B[i]) return _P("-1\n");
	cout<<num<<endl;



}


