const int MAX_N = 200005;
int N;
int A[MAX_N];
int B[MAX_N];

signed main()
{
  cin >> N;
  REP(n,N) {
    cin >> A[n];
  }
  priority_queue<II> pq;
  int ansCnt = 0;
  REP(n,N) {
    cin >> B[n];
    pq.push(II(B[n], n));
    if(B[n] == A[n]) ansCnt++;
    else if(B[n] < A[n]) {
      cout << -1 << endl;
      return 0;
    }
  }

  int ans = 0;
  while(ansCnt < N) {
    II p = pq.top(); pq.pop();
    int num = p.first, index = p.second;
    int l = (index == 0 ? B[N-1] : B[index-1]);
    int r = (index == N-1 ? B[0] : B[index+1]);

    int lr = l+r;

    if(num <= lr) {
      cout << -1 << endl;
      return 0;
    }

    int t = num/lr - 1 + (num%lr == 0 ? 0 : 1);

    ans += t;
    num = num - t*lr;

    if(A[index] == num) {
      ansCnt++;
    }
    if(A[index] > num) {
      cout << -1 << endl;
      return 0;
    }
    B[index] = num;
    pq.push(II(num, index));
  }

  cout << ans << endl;

  return 0;
}

