signed main() {

    SS(int, N);
    SV(int, A, N);
    SV(int, B, N);

    auto get_l = [&](int idx) -> int {
        if (idx) return idx - 1;
        return N - 1;
    };
    auto get_r = [&](int idx) -> int {
        if (idx < N - 1) return idx + 1;
        return 0;
    };

    // [val, idx]
    prique<pair<int, int>> pq;
    REP(i, N) pq.emplace(B[i], i);

    ll res = 0;
    int lst = -1;
    while (not pq.empty()) {
        auto tp = pq.top(); pq.pop();
        int val, idx;
        tie(val, idx) = tp;
        if (lst == idx) return print(-1);
        int goal = A[idx];
        if (val < goal) return print(-1);
        if (val == goal) continue;
        int neighbor = B[get_l(idx)] + B[get_r(idx)];
        if (neighbor > val) return print(-1);
        int k = (val - goal) / neighbor;
        if (k < 0) return print(-1);
        res += k;
        val -= k * neighbor;
        B[idx] = val;
        if (val > goal) pq.emplace(val, idx);
        if (val < goal) return print(-1);
        lst = idx;
    }

    print(res);

}

