int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);

  int n;
  std::cin >> n;
  std::vector<int> A(n), B(n);
  for (int i = 0; i < n; i++) {
    std::cin >> A[i];
  }
  for (int i = 0; i < n; i++) {
    std::cin >> B[i];
  }
  std::set<std::pair<int, int>, std::greater<std::pair<int, int>>> s;

  for (int i = 0; i < n; i++) {
    s.emplace(B[i], i);
  }

  long long ans = 0;
  while (!s.empty()) {
    int i = s.begin()->second;
    s.erase(s.begin());
    int d = B[i] - A[i], t = B[(i + 1) % n] + B[(i - 1 + n) % n];
    if (d != 0 && d < t) {
      ans = -1;
      break;
    }
    ans += d / t;
    B[i] -= d / t * t;
    if (B[i] != A[i])
      s.insert(std::make_pair(B[i], i));
  }

  std::cout << ans << std::endl;

  return 0;
}

