      q.push(i);
    }
  }
  int ans = 0;
  while (!q.empty()) {
    int i = q.front();
    q.pop();
    int mod = sum(i);
    int pi = (i + n - 1) % n, ni = (i + n + 1) % n;
    int old = b[i];
    b[i] -= (b[i] - a[i]) / mod * mod;
    ans += (old - b[i]) / mod;
    if (canAdd(pi)) {
      q.push(pi);
    }
    if (canAdd(ni)) {
      q.push(ni);
    }
  }
  for (int i = 0; i < n; ++i) {
    if (b[i] != a[i]) {
      cout << -1 << endl;
      return 0;
    }
  }
  cout << ans << endl;
  return 0;
}

