#include <bits/stdc++.h>

using namespace std;
using ll = long long;

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  struct Num {
    int n, i;
    Num(int n, int i) : n(n),i(i) {}
    bool operator<(const Num& x) const {return n<x.n;}
  };
  int N; cin>>N;
  vector<int> A(N); for(auto& a : A) cin>>a;
  vector<int> B(N); for(auto& b : B) cin>>b;
  auto solve = [&]() -> ll {
    priority_queue<Num, vector<Num>> pq;
    for (int i = 0; i < N; i++) {
      if (B[i] < A[i]) {
        return -1;
      }
      if (B[i] > A[i])
        pq.emplace(B[i], i);
    }
    ll ans = 0;
    while (not pq.empty()) {
      auto t = pq.top(); pq.pop();
      auto a = (t.i+N-1)%N;
      auto c = (t.i+1)%N;
      auto apc = B[a]+B[c];
      if (t.n < apc)
        return -1;
      auto m = t.n%apc;
      if (m < A[t.i]) {
        auto d = t.n-A[t.i];
        if (d%apc>0)
          return -1;
        ans += d/apc;
        B[t.i] = A[t.i];
      } else {
        B[t.i] = m;
        ans += t.n/apc;
        if (m > A[t.i])
          pq.emplace(m, t.i);
      }
    }
    return ans;
  };
  cout << solve() << endl;

  return 0;
}

