int get_next_idx(int i) {
    if (i == N - 1) return 0;
    else return i + 1;
}
int get_prev_idx(int i) {
    if (i == 0) return N - 1;
    else return i - 1;
}

ll get_next(int i, vector<ll>& arr) {
    return arr[get_next_idx(i)];
}
ll get_prev(int i, vector<ll>& arr) {
    return arr[get_prev_idx(i)];
}

bool is_peak(int i, vector<ll>& arr) {
    ll p = get_prev(i, arr);
    ll n = get_next(i, arr);
    return (arr[i] >= p + n);
}

int main(void)
