	long long ans = 0;
	int last = -1;
	while (seg.T[1].sum) {
		int pos = seg.T[1].maxj.se;
		if (pos == last) {
			printf("-1\n");
			return 0;
		}
		int modd = b[(pos - 1 + n) % n] + b[(pos + 1) % n];
		int cnt = (b[pos] - a[pos]) / modd;
		ans += cnt;
		b[pos] -= cnt * modd;
		last = pos;
		seg.Update(1, 0, n - 1, pos);
		seg.Update(1, 0, n - 1, (pos - 1 + n) % n), seg.Update(1, 0, n - 1, (pos + 1) % n);
	}
