llint get(llint p)
{
	if(b[p] <= a[p] && b[p] <= b[(p-1+n)%n]+b[(p+1)%n]) return 0;
	llint s = b[(p-1+n)%n]+b[(p+1)%n], m = max(b[(p-1+n)%n], b[(p+1)%n]);
	return min((b[p]-a[p])/s, (b[p]-m+s-1)/s);
}

