int main() {
    int n, result = 0;
    cin >> n;
    int a[n], b[n];
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    auto cmp = [&](int left, int right) {
        return b[left] < b[right];
    };
    priority_queue<int, vector<int>, decltype(cmp)> queue(cmp);
    for (int i = 0; i < n; i++) {
        if (b[i] != a[i]) {
            queue.emplace(i);
        }
    }
    while (!queue.empty()) {
        auto top = queue.top();
        queue.pop();
        if (b[top] > b[(top - 1 + n) % n] + b[(top + 1) % n]) {
            result += b[top] / (b[(top - 1 + n) % n] + b[(top + 1) % n]);
            b[top] %= b[(top - 1 + n) % n] + b[(top + 1) % n];
            if (b[top] > a[top]) {
                queue.emplace(top);
            } else if (b[top] < a[top]) {
                result = -1;
                break;
            }
        } else {
            result = -1;
            break;
        }
    }
    cout << result;
    return 0;
}

