int solve(int n, vector<lli> const &before, vector<lli> const &after) {
  auto const MaxF = maximum<tuple<lli,lli>>;
  auto st = make_segment_tree(MaxF, make_tuple(-1, -1), n);
  REP(i, n) {
    st.update(i, make_tuple(after[i]>before[i]? after[i]:-1, i));
  }
  lli cnt = 0;
  while (true) {
    lli fst, idx; tie(fst, idx) = st.query(0, n);
    if (fst < 0) { break; }
    lli snd, id2; tie(snd, id2) = MaxF(st.query(0, idx), st.query(idx+1, n));
    lli const prev = get<0>(st.at((idx-1+n)%n));
    lli const next = get<0>(st.at((idx+1)%n));
    lli const dv = (prev==-1? before[(idx-1+n)%n]:prev) + (next==-1? before[(idx+1)%n]:next);
    //cerr << cnt << ":(" << fst << "/" << idx << "/" << dv << ")" ;
    // REP(i, n) {
    //   cerr << get<0>(st.at(i)) << "/" << get<1>(st.at(i)) << ", ";
    // }
    //cerr << "\n";
    lli const m = min((fst-before[idx])/dv, (fst-snd+dv)/dv);
    if (m < 1) { return -1; }
    lli const newv = fst - m * dv;
    if (newv < before[idx]) { return -1; }
    cnt += m;
    st.update(idx, make_tuple(newv>before[idx]? newv:-1, idx));
  }
  return cnt;
}

int main() {
  // cout << fixed << setprecision(10);
  int N;
  cin >> N;
  vector<lli> bef, aft;
  REP(i, N) {
    lli A; cin >> A;
    bef.push_back(A);
  }
  REP(i, N) {
    lli B; cin >> B;
    aft.push_back(B);
  }
  cout << solve(N, bef, aft) << endl;
  return 0;
}

