  }
  ST<ll , decltype(f) , -1LL> st(B , f);
  ll cnt = 0;
  ll m = 0;
  auto func = [&](int idx, int flg){
    ll nxt = B[idx]
    -(B[(idx+1)%N] + B[(idx + N - 1)%N]+A[(idx+1)%N] + A[(idx + N - 1)%N]);
    if(nxt < 0 && flg) die(-1);
    while(nxt >= 0){
      B[idx] -= B[(idx+1)%N] + B[(idx + N - 1)%N];
      B[idx] -= A[(idx+1)%N] + A[(idx + N - 1)%N];
      st.update(idx , B[idx]);
