    while(1){
      func(idx , fff); fff = 0;
      if(B[idx] < B[(idx + 1) % N]) idx = (idx + 1) % N;
      else if(B[idx] == B[(idx + 1) % N] && B[idx] != 0) die(-1);
      else if(B[idx] < B[(idx + N - 1) % N]) idx = (idx + N - 1) % N;
