void func(long long N, std::vector<long long> A, std::vector<long long> B){

    lli cnt = 0;

    while(1){
        lli maxdiff=-1;
        lli maxPos = -1;
        if(B[N-1]+B[1] < B[0]){
            maxdiff = B[N-1]+B[1];
            maxPos = 0;
        }
        REP(i,1,N){
            if(B[i-1]+B[(i+1)%N] < B[i]){
                lli diff = B[i-1]+B[(i+1)%N];
                if(diff>maxdiff){
                    maxdiff = diff;
                    maxPos = i;
                }
            }
        }
        if(maxdiff==-1){
            cout<<-1<<endl;
            return;
        }

        cnt += (B[maxPos]/maxdiff);

        B[maxPos] %= maxdiff;

        bool ok = true;
        REP(i,0,N){
            if(A[i] != B[i]){
                ok = false;
                break;
            }
        }
        if(ok)break;
    }

    cout<<cnt<<endl;

}

