	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	ll n; cin >> n;
	vll a(n), b(n);
	read(a); read(b);

	segment_tree<M::max_indexed_t<>> seg(n);
	rep(i, 0, n) {
		seg.update(i, { b[i],i });
	}
	ll cnt = 0;
	while (true) {
		auto mx = seg.query(0, n);
		if (mx.first == a[mx.second]) {
			//finish
			seg.update(mx.second, pll{-INF, mx.second});
			continue;
		}
		if (mx.first == -INF) {
			break;
		}
		auto l = seg.a[(n + mx.second - 1) % n + seg.n - 1];//seg.query((n+ mx.second - 1) % n, mx.second );
		auto r = seg.a[(mx.second + 1) % n + seg.n - 1];//seg.query((mx.second + 1) % n, (mx.second + 2) % n);
		ll minus = l.first + r.first;
		if (mx.first -minus < a[mx.second]  ) {
			cout << -1 << endl; return 0;
		}
		ll cnt_ = (mx.first - a[mx.second]) / minus;
		ll val = mx.first - cnt_ * minus;
		cnt += cnt_;
		seg.update(mx.second, { val ,mx.second });
	}
	cout << cnt << endl;
	return 0;

}

