  ll c = 0;
  priority_queue<pii> pq;
  rep(i,0,n) pq.push({b[i], i});

  bool good=true;
  while (!pq.empty()) {
    int wtf = pq.top().fst;
    int m = pq.top().snd;
    pq.pop();
    if (b[m] != wtf) continue;
    if (b[m] == a[m]) continue;
    int m1 = pq.top().snd;

    int k = ((b[m] - a[m] + b[(m-1+n)%n] + b[(m+1)%n]- 1) / (b[(m-1+n)%n] + b[(m+1)%n]));
    int other = ((b[m] - b[m1] + b[(m-1+n)%n] + b[(m+1)%n]- 1) / (b[(m-1+n)%n] + b[(m+1)%n]));
    if ( other<k) k = other;
    b[m] -= k * (b[(m-1+n)%n] + b[(m+1)%n]);
    c += k;
    pq.push({b[m],m});

    if (b[m] < a[m]) goto fail;
  }

