#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

class SegmentTree {
public:
    SegmentTree(ll n, ll value) {
        n_ = (ll)pow(2, ceil(log2(n)));
        nodes_.resize(2 * n_ - 1, value);
    }

    void update(ll x, ll v) {
        nodes_[x + n_ - 1] = v;
        for (ll i = (x + n_ - 2) / 2; i > 0; i = (i - 1) / 2) {
            nodes_[i] = max(nodes_[2 * i + 1], nodes_[2 * i + 2]);
        }
        nodes_[0] = max(nodes_[1], nodes_[2]);
    }

    ll getMaxIndex(ll k = 0) {
        //最も大きいもののindexを返す
        if (k >= n_ - 1) {
            //最下段まで来ていたらindexを返す
            return k - (n_ - 1);
        }
        return (nodes_[2 * k + 1] >= nodes_[2 * k + 2] ? getMaxIndex(2 * k + 1) : getMaxIndex(2 * k + 2));
    }

    ll getMax(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {
        if (r < 0) {
            r = n_;
        }
        if (r <= a || b <= l) {
            return INT_MAX;
        }
        if (a <= l && r <= b) {
            return nodes_[k];
        }
        ll lv = getMax(a, b, 2 * k + 1, l, (l + r) / 2);
        ll rv = getMax(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(lv, rv);
    }

private:
    //2のべき乗
    ll n_;
    vector<ll> nodes_;
};

int main() {
    ll N;
    cin >> N;
    vector<ll> A(N), B(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (ll i = 0; i < N; i++) {
        cin >> B[i];
    }

    SegmentTree st(N, 0);
    for (ll i = 0; i < N; i++) {
        st.update(i, B[i]);
    }

    ll same_num = 0;
    for (ll i = 0; i < N; i++) {
        if (A[i] == B[i]) {
            same_num++;
        }
    }

    ll ans = 0;
    while (same_num < N) {
        ll index = st.getMaxIndex();
        ll left = (index + N - 1) % N;
        ll right = (index + 1) % N;
        ll sub = B[left] + B[right];
        ll lr_max = max(B[left], B[right]);
        if (A[index] > lr_max) {
            if (B[left] != A[left] || B[right] != A[right] || (B[index] - A[index]) % sub != 0) {
                cout << -1 << endl;
                return 0;
            } else {
                ans += (B[index] - A[index]) / sub;
                B[index] = A[index];
                st.update(index, 0);
                same_num++;
            }
        } else {
            ll k = (B[index] - lr_max + sub - 1) / sub;
            if (B[index] - k * sub < A[index]) {
                cout << -1 << endl;
                return 0;
            } else {
                ans += k;
                B[index] -= k * sub;
                st.update(index, B[index]);
                if (B[index] == A[index]) {
                    same_num++;
                }
            }
        }
    }

    cout << ans << endl;
}

