			continue;

		int idxLeft = idx - 1;
		if (idxLeft < 0)
			idxLeft = N - 1;
		int idxRight = idx + 1;
		if (idxRight == N)
			idxRight = 0;

		LL sum = B[idxLeft] + B[idxRight];
		if (sum <= 0) {
			ret = -1;
			break;
		}
		LL times = B[idx] / sum;
		if (times == 0LL)
			times = 1LL;
		ret += times;

		B[idx] -= times * sum;
		if (B[idx] < A[idx]) {
			ret = -1;
			break;
		}

		heap.push(make_pair(B[idx], idx));
	}

