    for (int i = 0; i < n; ++i)
        cin >> b[i];
    set<pair<int, int>> t;
    for (int i = 0; i < n; ++i)
        t.insert({b[i], i});
    long long ans = 0;
    while (!t.empty()) {
        auto now = --t.end();
        int pos = now->second;
        t.erase(now);
        int f = (pos - 1 + n) % n, s = (pos + 1) % n;
        if (b[pos] == a[pos])
            continue;
        if (b[pos] - b[f] - b[s] < a[pos]) {
            cout << -1 << endl;
