        int del1 = b[pos] - a[pos];
        int del2 = b[pos] - max(b[f], b[s]);
        int minus = b[f] + b[s];
        int nw = min(del1 / minus, (del2 + minus - 1) / minus);
        ans += nw;
        b[pos] -= nw * minus;
        if (b[pos] != a[pos])
            t.insert({b[pos], pos});
        assert(b[pos] >= a[pos]);
    }
    cout << ans << endl;
    return 0;
}

