ll n;
ll at(ll i) {
	return (i + n) % n;
}

ll dov(VL& b, ll i, VL& a) {
	ll cnt = 0;
	ll j = (i + n - 1);
	ll val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		cnt += dov(b, j, a);
	}

	j = (i + 1);
	val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		cnt += dov(b, j, a);
	}
	return cnt;
}

