		int64_t d = bs[n - 2] + bs[0];
		ans = min(ans, decrease(as, bs, n, c, n - 1, d));
	}

	return ans;
}
#endif

void update(const vector<int64_t> & bs, int n, int i, queue<int>& move_idx)
{
	if (i < 0) i += n;
	if (n <= i) i -= n;

	if (i == 0) {
		if (bs[n - 1] + bs[1] < bs[0]) move_idx.push(0);
	}
	else if (i == n - 1) {
		if (bs[n - 2] + bs[0] < bs[n - 1]) move_idx.push(n - 1);
	}
	else {
		if (bs[i - 1] + bs[i + 1] < bs[i]) move_idx.push(i);
	}
}


int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;

	vector<int64_t> as(n);
	for (auto& a : as) {
		cin >> a;
	}

	vector<int64_t> bs(n);
	for (auto& b : bs) {
		cin >> b;
	}

	int ce = 0;
	FOR_LT(i, 0, n) {
		if (as[i] == bs[i]) ce++;
	}

	queue<int> move_idx;

	if (bs[n - 1] + bs[1] < bs[0]) {
		move_idx.push(0);
	}
	FOR_LT(i, 1, n - 1) {
		if (bs[i - 1] + bs[i + 1] < bs[i]) {
			move_idx.push(i);
		}
	}
	if (bs[n - 2] + bs[0] < bs[n - 1]) {
		move_idx.push(n - 1);
	}

	int64_t ans = 0;

	while (ce != n) {
		if (move_idx.empty()) {
			cout << -1 << endl;
			return 0;
		}
		int i = move_idx.front();
		move_idx.pop();

		int64_t d = 0;
		if (i == 0) {
			d = bs[n - 1] + bs[1];
		}
		else if (i == n - 1) {
			d = bs[n - 2] + bs[0];
		}
		else {
			d = bs[i - 1] + bs[i + 1];
		}

		int64_t c = bs[i] / d;
		ans += c;
		bs[i] -= c * d;
		if (bs[i] < as[i]) {
			cout << -1 << endl;
			return 0;
		}
		if (bs[i] == as[i]) {
			ce++;
		}

		update(bs, n, i + 1, move_idx);
		update(bs, n, i - 1, move_idx);
	}

	if (ans != INT64_MAX) {
		cout << ans << endl;
	}
	else {
		cout << -1 << endl;
	}

	return 0;
}

