    pair<int, int> p = pq.top();
    pq.pop();

    if (p.first == 0) break;

    int keep = b.at((p.second + 1) % n) + b.at((p.second - 1 + n) % n);

    if (b.at(p.second) / keep == 0) {
      ans = -1;
      break;
    }

    ans += b.at(p.second) / keep;
    b.at(p.second) %= keep;
    pq.push(make_pair(b.at(p.second) - a.at(p.second), p.second));
  }

  cout << ans << '\n';
}

