{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long N, std::vector<long long> A, std::vector<long long> B)
{
    ll ans = 0;
    priority_queue<pair<ll, ll>> q;
    bool allFalse = true;
    for (int i = 0; i < N; i++)
    {

        if (A[i] < B[i])
        {
            q.push(make_pair(B[i], i));
        }
    }
    ll cant = 0;
    while (!q.empty() && cant < q.size())
    {
        auto p = q.top();
        q.pop();

        ll sum = 0;
        int index = p.second;
        if (index == 0)
        {
            sum += B[index + 1] + B[N - 1];
        }
        else if (index == N - 1)
        {
            sum += B[index - 1] + B[0];
        }
        else
        {
            sum += B[index - 1] + B[index + 1];
        }
        if (sum < B[index])
        {
            while (sum < B[index])
            {
                ans++;
                B[index] -= sum;
            }
            if (A[index] < B[index])
            {
                q.push(make_pair(B[index], index));
            }
        }else{
            cant++;
        }
    }

    for (int i = 0; i < N; i++)
    {
        if (A[i] != B[i])
        {
            cout << -1 << endl;
            return;
        }
    }

    cout << ans << endl;
    return;
}

