int main(){

    int N;
    cin >> N;
    vector<int> A(N);
    vector<int> B(N);

    for(int i = 0; i < N; i++){
        cin >> A[i];
    }

    for(int i = 0; i < N; i++){
        cin >> B[i];
    }

    vector<bool> on(N, false);

    for(int i = 0; i < N; i++){
        if(A[i] > B[i]){
            cout << -1 << endl;
            return 0;
        }
    }

    queue<int> q;

    if(B[0] > B[1] + B[N - 1]){
        q.push(0);
        on[0] = true;
    }
    for(int i = 1; i < N - 1; i++){
        if(B[i] > B[i - 1] + B[i + 1]){
            q.push(i);
            on[i] = true;
        }
    }
    if(B[N - 1] > B[N - 2] + B[0]){
        q.push(N - 1);
        on[N - 1] = true;
    }

    long long ans = 0;
    while(!q.empty()){
        int temp = q.front();
        q.pop();

        if(A[temp] == B[temp]){
            continue;
        }

        if(!on[temp]){
            continue;
        }
        on[temp] = false;

        int leftIndex;
        if(temp == 0){
            leftIndex = N - 1;
        }
        else{
            leftIndex = temp - 1;
        }
        int left = B[leftIndex];

        int rightIndex;
        if(temp == N - 1){
            rightIndex = 0;
        }
        else{
            rightIndex = temp + 1; 
        }
        int right = B[rightIndex];

        int center = B[temp];
        int target = A[temp];

        int lrSum = left + right;
        if(center > lrSum){
            if(lrSum > target){
                int rest = center % lrSum;
                if(rest < target){
                    cout << -1 << endl;
                    return 0;
                }
                else{
                    if(!on[rightIndex]){
                        q.push(rightIndex);
                        on[rightIndex] = true;
                    }
                    if(!on[leftIndex]){
                        q.push(leftIndex);
                        on[leftIndex] = true;
                    }

                    ans += (center / lrSum);
                    B[temp] = rest;
                }
            }
            else{
                int diff = center - target;
                if(diff % lrSum == 0){
                    ans += (diff / lrSum);
                    B[temp] = target;
                    if(!on[rightIndex]){
                        q.push(rightIndex);
                        on[rightIndex] = true;
                    }
                    if(!on[leftIndex]){
                        q.push(leftIndex);
                        on[leftIndex] = true;
                    }
                }
                else{
                    cout << -1 << endl;
                    return 0;
                }
            }
        }
    }

    for(int i = 0; i < N; i++){
        if(A[i] != B[i]){
            cout << -1 << endl;
            return 0;
        }
    }

    cout << ans << endl;

    return 0;
}

