    for(int i=0; i<N; i++) {
        int v1 = B[(i + N - 1) % N];
        int v2 = B[i];
        int v3 = B[(i + 1) % N];
        if(v1 < v2 and v2 > v3 and v2 > A[i]) que.emplace(i);
