int main(){
	int N; cin >> N;
	for (int i = 0; i < N; i++){
		cin >> A[i];
	}
	for (int i = 0; i < N; i++){
		cin >> B[i];
	}

	priority_queue<pii> pq;
	LL res = 0;
	for (int i = 0; i < N; i++){
		if (A[i] != B[i]){
			pq.push(make_pair(B[i], i));
		}
