		if (dec == 0){
			cout << -1 << endl;
			return 0;
		}
		p.first -= dec * (B[rgt] + B[lft]);
		res += dec;
		B[p.second] = p.first;
		if (p.first == A[idx]) continue;
		if (p.first < A[idx]){
			cout << -1 << endl;
			return 0;
		}
		pq.push(p);
	}
