typedef long long i64; typedef vector<int> ivec; typedef vector<string> svec;

int N;
i64 A[202020], B[202020];

i64 &at(int i)
{
	if (i == -1) return B[N - 1];
	else if (i == N) return B[0];
	return B[i];
}

bool ext(int i)
{
	return at(i - 1) < at(i) && at(i) > at(i + 1);
}

void fail()
{
	puts("-1");
	exit(0);
}

bool qd[202020];
queue<int> Q;

void app_test(int i)
{
	if (i < 0) i += N;
	if (i >= N) i -= N;

	if (ext(i) && B[i] > A[i]) {
		if (!qd[i]) {
			qd[i] = true;
			Q.push(i);
		}
	} else if (B[i] < A[i]) {
		fail();
	}
}

int main()
{
	scanf("%d", &N);
	for (int i = 0; i < N; ++i) scanf("%lld", A + i);
	for (int i = 0; i < N; ++i) scanf("%lld", B + i);

	i64 ret = 0;
	for (int i = 0; i < N; ++i) app_test(i);

	while (!Q.empty()) {
		int p = Q.front(); Q.pop();
		qd[p] = false;

		i64 cnt = (B[p] - A[p]) / (at(p - 1) + at(p + 1));
		if (cnt == 0) {
			if (B[p] != A[p]) {
				fail();
			} else break;
		}
		ret += cnt;
		//printf("%d %lld\n", p, (at(p - 1) + at(p + 1)) * cnt);
		B[p] -= (at(p - 1) + at(p + 1)) * cnt;
		app_test(p - 1);
		app_test(p);
		app_test(p + 1);

		//for (int i = 0; i < N; ++i) printf("%lld ", B[i]); puts("");
	}

	for (int i = 0; i < N; ++i) if (A[i] != B[i]) fail();
	printf("%lld\n", ret);

	return 0;
}

