    if(b[i] < a[i]) {
      puts("-1"); 
      return 0; 
    }
  }
  while(!Q.empty()) {
    tmp = Q.top(); Q.pop(); 
    if(tmp.d == a[tmp.id]) continue ; 
    if(tmp.d < a[tmp.id]) {
