bool f(ll i) {
  bool res;
  if(i == 0) {
    ll m = b[n - 1] + b[1];
    res = b[0] > m && b[0] > a[0];
  } else if(i == n - 1) {
    ll m = b[n - 2] + b[0];
    res = b[n - 1] > m && b[n - 1] > a[n - 1];
  } else {
    ll m = b[i - 1] + b[i + 1];
    res = b[i] > m && b[i] > a[i];
  }
  return res;
}

int main() {
  cin >> n;
  a.resize(n);
  b.resize(n);
  rep(i, n) cin >> a[i];
  rep(i, n) cin >> b[i];
  set<ll> st;
  rep2(i, 1, n - 1) {
    ll m = b[i - 1] + b[i + 1];
    if(b[i] > m && b[i] > a[i]) st.insert(i);
  }
  ll m0 = b[n - 1] + b[1];
  if(b[0] > m0 && b[0] > a[0]) st.insert(0);
  ll mn = b[n - 2] + b[0];
  if(b[n - 1] > mn && b[n - 1] > a[n - 1]) st.insert(n - 1);
  ll ans = 0;
  while(true) {
    if(st.empty()) break;
    ll i = *st.begin();
    st.erase(st.begin());
    if(i == 0) {
      ll m = b[n - 1] + b[1];
      ans += b[0] / m;
      b[0] %= m;
      if(f(n - 1)) st.insert(n - 1);
      if(f(1)) st.insert(1);
    } else if(i == n - 1) {
      ll m = b[n - 2] + b[0];
      ans += b[n - 1] / m;
      b[n - 1] %= m;
      if(f(n - 2)) st.insert(n - 2);
      if(f(0)) st.insert(0);
    } else {
      ll m = b[i - 1] + b[i + 1];
      ans += b[i] / m;
      b[i] %= m;
      if(f(i - 1)) st.insert(i - 1);
      if(f(i + 1)) st.insert(i + 1);
    }
  }
  bool ok = true;
  rep(i, n) if(a[i] != b[i]) ok = false;
  if(ok)
    cout << ans << endl;
  else
    cout << -1 << endl;
}

