typedef long long ll;
int N;
const int MAX_N = 200000;
ll A[MAX_N], B[MAX_N];
priority_queue<pair<ll, int>> U;

void check_insert(int i)
{
  int i_prev = (i + N - 1) % N, i_next = (i + 1) % N;
  if (B[i] - A[i] >= B[i_prev] + B[i_next])
  {
    U.push(make_pair(B[i], i));
  }
}

ll solve()
{
  ll res = 0;
  for (int i = 0; i < N; ++i)
  {
    check_insert(i);
  }
  while (!U.empty())
  {
    int i = U.top().second;
    U.pop();
    int i_prev = (i + N - 1) % N, i_next = (i + 1) % N;
    ll k = (B[i] - A[i]) / (B[i_prev] + B[i_next]);
    B[i] -= k * (B[i_prev] + B[i_next]);
    res += k;
    check_insert(i_prev);
    check_insert(i);
    check_insert(i_next);
  }
  for (int i = 0; i < N; ++i)
  {
    if (A[i] != B[i])
    {
      return -1;
    }
  }
  return res;
}

