		if (st < x) {
			ll u = x - st;
			if (h - u > v[i]) return false;
		}
		else if (x < s) {
			ll u = s - x;
			if (h - u > v[i]) return false;
		}
		else {
			if (h > v[i])return false;
		}
		s = st;
	}
	return true;
}
