const int N_MAX = 200010;

int A[N_MAX], B[N_MAX];
int nNum;

inline int nextIndex(int i) {
	return i < nNum ? i + 1 : 1;
}

inline int prevIndex(int i) {
	return i > 1 ? i - 1 : nNum;
}

bool reducible(int i) {
	return B[i] - A[i] >= B[nextIndex(i)] + B[prevIndex(i)];
}

void outerInit() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	auto fi = new ifstream("test.inp");
	if (*fi) {
		cin.rdbuf(fi->rdbuf());
