void readData() {
	cin >> nNum;
	for (int i = 1; i <= nNum; ++i) cin >> A[i];
	for (int i = 1; i <= nNum; ++i) cin >> B[i];
}

void solveData() {
	set<int> reducibleIndices;
	for (int i = 1; i <= nNum; ++i) {
		if (reducible(i)) {
			reducibleIndices.insert(i);
		}
	}

	int64 result = 0;
	while (!reducibleIndices.empty()) {
		int i = *reducibleIndices.begin();
		reducibleIndices.erase(reducibleIndices.begin());

		int in = nextIndex(i);
		int ip = prevIndex(i);
		int ac = B[in] + B[ip];
		int nStep = (B[i] - A[i]) / ac;
		result += nStep;
		B[i] -= nStep * ac;

		if (reducible(in)) {
			reducibleIndices.insert(in);
		}
		if (reducible(ip)) {
			reducibleIndices.insert(ip);
		}
	}

	for (int i = 1; i <= nNum; ++i) {
		if (A[i] != B[i]) {
			cout << "-1\n";
			return;
		}
	}

	cout << result << "\n";
}

