int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  struct Num {
    int n, i;
    Num(int n, int i) : n(n),i(i) {}
    bool operator<(const Num& x) const {return n<x.n;}
    bool operator>(const Num& x) const {return n>x.n;}
  };
  priority_queue<Num, vector<Num>, less<>> pq;
  int N; cin>>N;
  vector<int> A(N); for(auto& a : A) cin>>a;
  vector<int> B(N); for(auto& b : B) cin>>b;
  auto solve = [&]() -> int {
    for (int i = 0; i < N; i++) {
      if (B[i] < A[i]) {
        return -1;
      }
      if (B[i] > A[i])
        pq.emplace(B[i], i);
    }
    ll ans = 0;
    while (not pq.empty()) {
      auto t = pq.top(); pq.pop();
      auto a = (t.i+N-1)%N;
      auto c = (t.i+1)%N;
      auto ac = B[a]+B[c];
      if (t.n < ac)
        return -1;
      auto m = t.n%ac;
      if (m < A[t.i]) {
        auto d = t.n-A[t.i];
        if (d%ac>0)
          return -1;
        ans += d/ac;
        B[t.i] = A[t.i];
      } else {
        B[t.i] = m;
        ans += t.n/ac;
        if (m > A[t.i])
          pq.emplace(m, t.i);
      }
    }
    return ans;
  };
  cout << solve() << endl;

  return 0;
}

