// AtCoder Grand Contest 037
int main(){

    int n; cin >> n;
    vector<int> a(n), b(n);
    rep(i, n)cin >> a[i];
    rep(i, n)cin >> b[i];

    typedef pair<int, int> pa;
    priority_queue<pa> que;

    auto judge = [&](int i){
        return b[i] > b[(i + 1) % n] and b[i] > b[(i + n - 1) % n] and b[i] > a[i];
    };

    auto doit = [&](int i){
        que.push(pa(b[(i + 1) % n] + b[(i + n - 1) % n], i));
    };

    rep(i, n){
        if(judge(i))doit(i);
    }

    int ans = 0;
    while(que.size()){
        pa p = que.top(); que.pop();
        int i = p.second;
        int sum = b[(i + 1) % n] + b[(i + n - 1) % n];
        if(b[i] - sum < a[i]){
            cout << -1 << endl;
            return 0;
        }
        if(b[i] - sum <= max(b[(i + 1) % n], b[(i + n - 1) % n])){
            ans++;
            b[i] -= sum;
        } else {
            int mx = max<int>({b[(i + 1) % n], b[(i + n - 1) % n], a[i]});
            int step = (b[i] - mx) / sum;
            b[i] -= step * sum;
            ans += step;
        }
        if(judge(i))doit(i);
        if(judge((i + 1) % n))doit((i + 1) % n);
        if(judge((i + n - 1) % n))doit((i + n - 1) % n);
    }

    rep(i, n)if(b[i] > a[i]){
        cout << -1 << endl;
        return 0;
    }

    cout << ans << endl;
    return 0;

}

