        if(r==n+1) r=1;
        if((b[u]-a[u])%(b[l]+b[r])==0)
        {
            ans+=(b[u]-a[u])/(b[l]+b[r]);
            b[u]=a[u];continue;
        }
        int now=a[u];
        if(!q.empty()) now=max(now,q.top().x);
        if((b[u]-now)/(b[l]+b[r])>0)
