void add (int &x, int y)
{
    x += y;
    if (x >= mod)
        x -= mod;
}
void sub (int &x, int y)
{
    x -= y;
    if (x < 0)
        x += mod;
}
int mult (int x, int y)
{
    return x * 1LL * y % mod;
}
int mult (int a, int b, int c)
{
    return mult(mult(a, b), c);
}
int mult (int a, int b, int c, int d)
{
    return mult(mult(a, b), mult(c, d));
}

int first_bigger (int bound, int mod, int rem)
{
    rem %= mod;

    if (rem >= bound)
        return rem;

    const int x = (bound - rem + mod - 1) / mod;
    return rem + mod * x;
}

