            const int guard1 = first_bigger(a[pos], step, b[pos]);
            const int guard2 = first_bigger(max(b[prev], b[next]), step, b[pos]);
            const int guard  = min(b[pos], max(guard1, guard2));

            assert((b[pos] - guard) % step == 0);
            ans += (b[pos] - guard) / step;
            b[pos] = guard;

            while (b[pos] >= max(b[prev], b[next]) && b[pos] > a[pos])
                b[pos] -= step, ans++;

            if (b[pos] < a[pos])
            {
                cout << -1 << endl;
                return true;
            }

            try_add(prev);
            try_add(next);
        }

        cout << ans << endl;
        return true;
    };

    while (solve_test());
}


