set <pair<long long int, int> > S;

long long int CALC(void) {


	if (S.size() == 0) { return 0; }
	else {
		auto it = S.begin();
		int id = (*it).second;

		long long int w = - (*it).first;
		S.erase((*it));

		long long int ret = w;

		B[id] -= (B[(id - 1 + N) % N] + B[(id + 1) % N])*w;


		id = (id - 1 + N) % N;
		w = (B[id] - A[id]) / (B[(id - 1 + N) % N] + B[(id + 1) % N]);

		if (w > 0) {
			S.insert(make_pair(-w, id));
		}

		id =(id+2)%N;
		w = (B[id] - A[id]) / (B[(id - 1 + N) % N] + B[(id + 1) % N]);

		if (w > 0) {
			S.insert(make_pair(-w, id));
		}

		return ret;

	}

	return 0;

}

