    for(int i = 0; i < N; i++){
        if(A[i] > B[i]){
            cout << -1 << endl;
            return 0;
        }
    }

    queue<int> q;

    if(B[0] > B[1] + B[N - 1]){
        q.push(0);
        on[0] = true;
    }
    for(int i = 1; i < N - 1; i++){
        if(B[i] > B[i - 1] + B[i + 1]){
            q.push(i);
            on[i] = true;
        }
    }
    if(B[N - 1] > B[N - 2] + B[0]){
        q.push(N - 1);
        on[N - 1] = true;
    }

    int ans = 0;
    while(!q.empty()){
        int temp = q.front();
        q.pop();

        if(A[temp] == B[temp]){
            continue;
        }

        if(!on[temp]){
            continue;
        }
        on[temp] = false;

        int leftIndex;
        if(temp == 0){
            leftIndex = N - 1;
        }
        else{
            leftIndex = temp - 1;
        }
        int left = B[leftIndex];

        int rightIndex;
        if(temp == N - 1){
            rightIndex = 0;
        }
        else{
            rightIndex = temp + 1; 
        }
        int right = B[rightIndex];

        int center = B[temp];
        int target = A[temp];

        int lrSum = left + right;
        if(center > lrSum){
            if(lrSum > target){
                int rest = center % lrSum;
