                    cout << -1 << endl;
                    return 0;
                }
                else{
                    if(!on[rightIndex]){
                        q.push(rightIndex);
                        on[rightIndex] = true;
                    }
                    if(!on[leftIndex]){
                        q.push(leftIndex);
                        on[leftIndex] = true;
                    }

                    ans += (center / lrSum);
                    B[temp] = rest;
                }
            }
            else{
                int diff = center - target;
                if(diff % lrSum == 0){
                    ans += (diff / lrSum);
                    B[temp] = target;
                    if(!on[rightIndex]){
                        q.push(rightIndex);
                        on[rightIndex] = true;
                    }
                    if(!on[leftIndex]){
                        q.push(leftIndex);
                        on[leftIndex] = true;
                    }
                }
                else{
                    cout << -1 << endl;
                    return 0;
                }
            }
        }
    }

    for(int i = 0; i < N; i++){
        if(A[i] != B[i]){
            cout << -1 << endl;
            return 0;
        }
    }

    cout << ans << endl;

    return 0;
}

