void ROP(ll i){
  ans+=(b[i]-a[i])/(b[(i-1+n)%n]+b[(i+1+n)%n]);
  b[i]-=(b[i]-a[i])/(b[(i-1+n)%n]+b[(i+1+n)%n])*(b[(i-1+n)%n]+b[(i+1+n)%n]);
  if((b[(i-1+n)%n]-a[(i-1+n)%n])/(b[(i-2+n)%n]+b[(i+n)%n])>0){
      ROP(i-1);
    }
  if((b[(i+1+n)%n]-a[(i+1+n)%n])/(b[(i+n)%n]+b[(i+2+n)%n])>0){
      ROP(i+1);
    }
  return;
}

