ll ans1 = 0, ans2 = 0;
priority_queue<pll> q1;
priority_queue<pll> q2;

void f1(ll a[], ll n){
    pll x = q1.top();
    ll idx = x.se;
    ll y = a[(idx-1+n)%n] + a[(idx+1+n)%n];
    if(a[idx] <= y){
        return;
    }    
    else {
        ans1++;
        q1.pop();
        a[idx]-=y;
        q1.push(mp(a[idx], idx));
        f1(a, n);
    }
}

void f2(ll b[], ll n){
    pll x = q2.top();
    ll idx = x.se;
    ll y = b[(idx-1+n)%n] + b[(idx+1+n)%n];
    if(b[idx] <= y){
        return;
    }
    else {
        ans2++;
        q2.pop();
        b[idx]-=y;
        q2.push(mp(b[idx], idx));
        f2(b, n);
    }
}

