int const nmax = 200000;
int target[1 + nmax], v[1 + nmax];

int main()
{
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);

  int n;
  cin >> n;
  for(int i = 0; i < n; i++)
    cin >> target[i];
  for(int i = 0;i < n; i++)
    cin >> v[i];
  queue<int> q;
  for(int i = 0;i < n; i++)
    q.push(i);
  ll result = 0;
  while(0 < q.size()){
    int pos = q.front();
    q.pop();
    if(v[pos] < v[(pos + n - 1) % n] || v[pos] < v[(pos + 1) % n])
      continue;
    if(v[pos] <= target[pos])
      continue;

    int stop = max(target[pos], max(v[(pos + 1) % n], v[(pos + (n - 1)) % n]));
    int jumps = (v[pos] - stop) / (v[(pos + 1) % n] + v[(pos + (n - 1)) % n]);
    jumps = max(jumps, 1);
    if(0 < jumps){
      v[pos] -= jumps * (v[(pos + 1) % n] + v[(pos + (n - 1)) % n]);
      q.push((pos + 1) % n);
      q.push((pos + n - 1) % n);
      q.push(pos);
      result += jumps;
    }
  }
  for(int i = 0;i < n; i++)
    if(v[i] != target[i]) {
      cout << -1;
      return 0;
    }
  cout << result;
  return 0;
}

#include <cstdio>
#include <queue>

using namespace std;

int n,a[200001], b[200001];
priority_queue< pair<int, int> > q;

int main(){
  scanf("%d",&n);

  for(int i = 0;i < n;++i)
    scanf("%d", &a[i]);

  for(int i = 0;i < n;++i)
    scanf("%d", &b[i]);

  for(int i = 0;i < n;++i){
    q.push(make_pair(b[i], i));
  }

  int ans = 0;

  while(!q.empty() && ans != -1){
    pair<int, int> cur = q.top();
    q.pop();

    if(cur.first != a[cur.second]){
      int pos1 = cur.second - 1;
      int pos2 = cur.second + 1;
      if(pos1 < 0) pos1 += n;
      if(pos2 >= n) pos2 -= n;
      int s = b[pos1] + b[pos2];

      int diff = b[cur.second],k;

      if((b[cur.second] - a[cur.second]) % s == 0){
        k = (b[cur.second] - a[cur.second]) / s;
        b[cur.second] -= k * s;
      }else{
          if(!q.empty()) diff -= max(q.top().first - 1, a[cur.second]);
          else diff -= a[cur.second];

          k = max(1, diff / s);
          b[cur.second] -= k * s;
      }

      if(b[cur.second] < a[cur.second]) ans = -1;
      else{
        q.push(make_pair(b[cur.second], cur.second));
        ans += k;
      }
    }
  }

  printf("%d\n", ans);

  return 0;
}

