        t.first = B[t.second] = t.first - k * s;
        ans += k;
        if (t.first < A[t.second])
            break;
        q.push(t);
    }

    bool exist = true;
    REP(i, N)
    {
        if (A[i] != B[i])
            exist = false;
    }

