struct Query{
  lint idx;
  lint B;
  bool operator < (const Query &other) const { return B < other.B; }
};
int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  lint N;
  cin >> N;
  vector<lint> A(N);
  vector<lint> B(N);
  REP(i, N) cin >> A[i];
  REP(i, N) cin >> B[i];
