    Query o = *prev(ms.end(), 1);
    ms.erase(prev(ms.end(), 1));
    lint num1 = (B[o.idx] - (B[(o.idx-1+N)%N] + B[(o.idx+1)%N]) - 1) / (B[(o.idx-1+N)%N] + B[(o.idx+1)%N]) + 1;
