ll solver3(vector<ll>A,vector<ll>B){
    int N = (int)A.size();
    ll res = 0;

    priority_queue<pll> pq;
    for(int i = 0; i < N;i++){
        if(A[i] == B[i]) continue;
        pq.push(pll(B[i],i));
    }
    vector<int> flag(N);
    while(pq.size()){
        vector<ll> vs,ids;

        ll ms = -LINF;
        bool ok = true;
        while(pq.size()){
            ll v,i; tie(v,i) = pq.top(); pq.pop();
            ms = v;
            if(flag[(i-1+N)%N] || flag[(i+1)%N]){
                pq.push(pll(v,i));
                ok = false;
                break;
            }
            flag[i] = true;
            vs.push_back(v);
            ids.push_back(i);
        }
        if(ok) ms = -LINF;

//        cout <<  " === " << endl;
//        cout << vs << endl;
//        cout << ids << endl;
//        cout << B << endl;

        int M = (int)vs.size();
        for(int i = 0; i < M;i++){
            ll v = vs[i];
            ll id = ids[i];

            ll S = B[(id-1+N)%N] + B[(id+1)%N];
            ll C = ((v-max(A[id],ms))+S-1)/S;

            res += C;
            B[id] -= S*C;

            if(B[id] < A[id]) return -1;
            if(B[id] != A[id]){
                pq.push(pll(B[id],id));
            }
            flag[id] = false;
        }
    }
    return res;
}

template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> A(N),B(N);

    for(auto& in:A) cin >> in;
    for(auto& in:B) cin >> in;
    return solver3(A,B);
}

