void solve() {
  int n; cin >> n;
  vi a(n), b(n); cin >> a >> b;

  priority_queue<pii> pq;
  rep(i,n) {
    if (a[i] < b[i]) {
      pq.emplace(b[i], i);
    } else if (a[i] > b[i]) {
      cout << -1 << endl;
      return;
    }
  }

  ll ans = 0;

  while (!pq.empty()) {
    int k = pq.top().second; pq.pop();
    int sum = b[(k-1+n) % n] + b[(k+1) % n];
    if (b[k] <= sum) {
      cout << -1 << endl;
      return;
    }
    if (a[k] > sum) {
      if ((b[k] - a[k]) % sum) {
        cout << -1 << endl;
        return;
      }
      ans += (b[k] - a[k]) / sum;
      b[k] = a[k];
    } else {
      ans += b[k] / sum;
      b[k] %= sum;
      if (a[k] > b[k]) {
        cout << -1 << endl;
        return;
      } else if (a[k] < b[k]) {
        pq.emplace(b[k], k);
      }
    }
  }

  cout << ans << endl;
}


