int64_t solve()
{
	int N;
	scanf("%d", &N);
	std::vector<int64_t> A(N), B(N);
	for (auto& e: A) scanf("%lld", &e);
	for (auto& e: B) scanf("%lld", &e);
	std::queue<int> que;
	for (int i{}; i < N; i++)
		if (A[i] > B[i])
			return -1;
	for (int i{}; i < N; i++)
		if (B[i] > B[(i + N - 1) % N] + B[(i + 1) % N] && B[i] > A[i])
			que.push(i);
	int64_t ans{};
	while (!que.empty())
	{
		int now{que.front()};
		que.pop();
		int next{(now + 1) % N}, prev{(now + N - 1) % N};
		int64_t quo{(B[prev] + B[next])}, rest{B[now] % quo};
		if (A[now] > rest)
		{
			if (A[now] % quo != rest) return -1;
			ans += (B[now] - A[now]) / quo;
			B[now] = A[now];
		}
		else
		{
			ans += B[now] / quo;
			B[now] = rest;
		}

		if (B[next] > B[now] + B[(next + 1) % N] && B[next] > A[next])
			que.push(next);
		if (B[prev] > B[now] + B[(prev + N - 1) % N] && B[prev] > A[prev])
			que.push(prev);
	}
	for (int i{}; i < N; i++)
		if (A[i] != B[i])
			return -1;
	return ans;
}

