		if (bs[i - 1] + bs[i + 1] < bs[i]) {
			int64_t d = bs[i - 1] + bs[i + 1];
			ans = min(ans, decrease(as, bs, n, c, i, d));
		}
	}
	if (bs[n - 2] + bs[0] < bs[n - 1]) {
