const int MAXN = 2.1e5;
int N;
int A[MAXN];
int B[MAXN];

[[noreturn]] void NOSAD() {
	cout << -1 << '\n'; exit(0);
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	for (int i = 0; i < N; i++) {
		cin >> B[i];
	}

	priority_queue<pair<int, int>> pq;
	for (int i = 0; i < N; i++) {
		if (B[i] < A[i]) {
			NOSAD();
		}
		if (B[i] > A[i]) {
			pq.emplace(B[i], i);
		}
	}
	ll ans = 0;
	while (!pq.empty()) {
		int i = pq.top().second; pq.pop();
		assert(B[i] > A[i]);
		int x = (i+N-1) % N;
		int y = (i+1) % N;
		assert(B[i] >= B[x]);
		assert(B[i] >= B[y]);
		if (B[i] <= B[x] + B[y]) {
			// then we're screwed, as no one can move
			NOSAD();
		}
		if (A[i] >= B[x] + B[y]) {
			// we'll go to A[i]
			if ((B[i] - A[i]) % (B[x] + B[y]) != 0) {
				NOSAD();
              /*
              If no more operation are to be done at indices X and Y, then if B[X] and
              B[Y] will not change, so we're screwed
              If changes are to be made to X and Y, they can't be made as A[i] >= B[x] + B[y]
              => A[i] > B[x] and A[i] > B[y] => Min B[i] can be A[i] and even then we can't do 
              any operation on X and Y, so B[i] has to be reduced to A[i]
              */
			}
			ans += (B[i] - A[i]) / (B[x] + B[y]);
			B[i] = A[i];
			continue;
		} else {
			ans += B[i] / (B[x] + B[y]);
			B[i] %= B[x] + B[y];
          // Similarly if we can't leave B[i] to be greater than B[x] and B[y]
          // as then no futher operation are possible for x and y, so make it less
          // than B[x] + B[y], so if A[i] > B[i], then we can't proceed further, 
          // otherwise push new (B[i], i) to the PQ
			if (B[i] < A[i]) {
				NOSAD();
			}
			if (B[i] > A[i]) {
				pq.emplace(B[i], i);
			}
		}
	}
	cout << ans << '\n';
	return 0;
}

