			bg.insert(i);
		}
	}

	while (!bg.empty()) {
		int ps = *bg.begin();
		bg.erase(ps);
		if (b[ps] == a[ps]) {
			ok[ps] = true;
			continue;
		}
		int i = ps;
		b[ps] -= b[(i - 1 + n) % n] + b[(i + 1) % n];
		if (b[ps] < a[ps]) {
			cout << -1 << endl;
			return;
		}
		++res;
		i = (ps + 1) % n;
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n] && !ok[i]) {
			bg.insert(i);
		}
		i = (ps - 1 + n) % n;
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n] && !ok[i]) {
			bg.insert(i);
		}
	}
	for (int i = 0; i < n; ++i) {
		if (a[i] != b[i]) {
			cout << -1 << endl;
			return;
		}
	}
	cout << res << endl;
}


