    if (b[i] > b[pr] && b[i] > b[nx])
        q.insert(i);
}

void change(int i, int x)
{
    if (x < a[i])
    {
        cout << "-1";
        exit(0);
    }
    b[i] = x;
    int pr = (i + n - 1) % n;
    int nx = (i + 1) % n;
    if (q.find(pr) != q.end())
        q.erase(pr);
    if (q.find(nx) != q.end())
        q.erase(nx);
    upd(pr);
    upd(nx);
    upd(i);
}

