int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for(int i = 0; i < n; i++) cin >> a[i];
  vector<int> v;
  for(int i = 0; i < n; i++) {
    cin >> b[i];
    if(a[i] > b[i]) NO();
  }
  auto check = [&](int i) {
    if(a[i] == b[i]) return;
    int d = max(b[(i-1+n)%n], b[(i+1)%n]);
    if(d < b[i]) v.emplace_back(i);
    if(d == b[i]) NO();
  };
  for(int i = 0; i < n; i++) {
    check(i);
  }
  dump(v);
  // mod は 1/2 以下に！
  ll ans = 0;
  while(v.size()) {
    int i = v.back();
    v.pop_back();
    if(a[i] == b[i]) continue;
    int k = (b[(i-1+n)%n] + b[(i+1)%n]);
    ans += b[i] / k;
    b[i] %= k;
    dump(i, a[i], b[i]);
    if(a[i] > b[i]) {
      if(a[i] % k != b[i] % k) NO();
      b[i] = a[i];
      ans -= (a[i] - b[i]) / k;
    }
    check((i-1+n)%n);
    check((i+1)%n);
  }
  dump(a);
  dump(b);
  if(a != b) NO();
  cout << ans << endl;
  return 0;
}

