void solve()
{
	long long n;
	cin >> n;

	vector<long long> cache(n);
	vector<long long> va(n);

	for (int i = 0; i<n; i++) {
		cin >> va[i];
		cache[i] = va[i];
	}

	vector<pair<long long,long long>> vb(n);

	for (int i = 0; i<n; i++) {
		cin >> vb[i].first;
		vb[i].second = i;
	}

	sort(vb.begin(), vb.end());

	long long res = 0;

	for (int i = 0; i<n; i++) {

		pair<long long, long long> vbi = vb[i];

		long long left = vbi.second;
		left--;

		if (left == -1) {
			left = n - 1;
		}

		long long right = vbi.second;

		right++;

		if (right == n) {
			right = 0;
		}

		long long rem = vbi.first - va[vbi.second];

		if (rem == 0) {
			continue;
		}
		if (rem<0) {
			res = -1;
			break;
		}
		else {

			long long lr = cache[left] + cache[right];

			if (rem%lr == 0) {
				res += rem / lr;
				cache[vbi.second] = vbi.first;

			}
			else {
				res = -1;
				break;
			}
		}

	}

	cout << res << endl;
}

