int main(int argc, char* argv[]) {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; i++)
    cin >> a[i];
  for (int i = 0; i < n; i++)
    cin >> b[i];
  set<pair<int, int>, greater<pair<int, int>>> s;
  for (int i = 0; i < n; i++)
    s.insert(make_pair(b[i], i));

  long long ans = 0;
  while (!s.empty()) {
    int i = s.begin()->second;
    s.erase(s.begin());
    int d = b[i] - a[i], t = b[(i + 1) % n] + b[(i - 1 + n) % n];
    if (d != 0 && d < t) {
      ans = -1;
      break;
    }
    ans += d / t;
    b[i] -= d / t * t;
    if (b[i] != a[i])
      s.insert(make_pair(b[i], i));
  }

  cout << ans << endl;

  return 0;
}

