bool anychange = 0;

int Bdec_all(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if ((Btmp[i] - A[i]) % Bnei == 0)
	{
		anstmp += (Btmp[i] - A[i]) / Bnei;
		if((Btmp[i] - A[i]) / Bnei > 0)
			anychange = 1;
		Btmp[i] = A[i];
	}
	else
	{
		anstmp += Btmp[i] / Bnei;
		if (Btmp[i] / Bnei > 0)
			anychange = 1;
		Btmp[i] %= Bnei;
	}
	if (Btmp[i] < A[i])
		return -1;
	return Btmp[i];
}

int Bdec(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if (Btmp[i] > A[i])
	{
		Btmp[i] -= Bnei;
		anstmp++;
	}
	return Btmp[i];
}

bool Btop(int i, vector<int> Btmp)
{
	if (Btmp[i] > (Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N]))
		return true;
	return false;
}

void DP()
{
  	vector<int> changelist;
  	int change_num = 0;
  	for(int p=0;p<N;p++)
      changelist.push_back(p);
  	change_num=N;
	while (1)
	{
		anychange = 0;
  		vector<int> changelist_next;
  		int change_num_next = 0;
		for (int q = 0; q < change_num; q++)
		{
          	for(int r=-1;r<=1;r++)
            {
              	int i = (changelist[q]+N+r)%N;
				if (Btop(i, B))
				{
                  	changelist_next.push_back(i);
                  	change_num_next++;
					B[i] = Bdec_all(i, B);
					if (B[i] == -1)
					{
						ansmin = -1;
						return;
					}
				}
            }
		}
		if (B == A)
		{
			ansmin = anstmp;
			return;
		}
		if (!anychange)
		{
			ansmin = -1;
			return;
		}
      changelist = changelist_next;
      change_num = change_num_next;
	}
	return;
}

