    b[ind] -= g;
    ++ret;
    if(a[ind]>b[ind]) {
      break;
    }
    pq.push(make_pair(b[ind],ind));
  }
  for(int i=0;i<n;++i) {
    if(a[i]!=b[i]) {
      ret = -1;
      break;
    }
  }
  printf("%d\n", ret);
}

