	auto prev = [&](int i) {return (i ? i : n) - 1; };

	auto calc_cnt = [](ll A, ll B, ll sum, ll ma) {
		ll cnt_a = (B - A) / sum;
		ll cnt_ma = (B - ma) / sum + 1;
		return min(cnt_a, cnt_ma);
	};

