const int maxn = 200010;

int N;
int A[maxn], B[maxn];

bool check(int p) {
	int l = p-1;
	if (l < 0) l += N;
	int r = p+1;
	if (r >= N) r -= N;
	return A[p] != B[p] && B[p] >= B[l] + B[r];
}

int main() {
	cin >> N;
	queue<int> que;

	rep(i, N) cin >> A[i];
	rep(i, N) cin >> B[i];

	ll ans = 0;
	rep(i, N) {
		if (check(i)) {
			que.push(i);
		}
	}

	while (!que.empty()) {
		int i = que.front(); que.pop();
		if (!check(i)) continue;

		int l = i-1;
		if (l < 0) l += N;
		int r = i+1;
		if (r >= N) r -= N;


