				num = (B[i] - A[i]) / dec;
				B[i] -= num * dec;
			}
		} else {
			num = (B[i] - dec) / dec;
			B[i] -= num * dec;
			if (B[i] > dec) {
				++num;
				B[i] -= dec;
			}
		}
		ans += num;
		if (check(l)) {
			que.push(l);
