void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    cin >> a >> b;
    queue<int> q;
    auto good = [&](int i) {
        i = (i + n) % n;
        return b[i] > a[i] && b[(i + n - 1) % n] + b[(i + 1) % n] <= b[i];
    };
    for (int i = 0; i < n; ++i) {
        if (b[i] < a[i]) {
            cout << "-1\n";
            return;
        }
        if (good(i)) {
            q.push(i);
        }
    }

    ll ans = 0;
    while (!q.empty()) {
        int i = q.front();
        q.pop();
        DUMP(i);

        int l = b[(i + n - 1) % n];
        int r = b[(i + 1) % n];

        int s = l + r;

        int targ = a[i];

        if (b[i] < targ) {
            cout << "-1\n";
            return;
        } else if (b[i] == targ || b[i] - s < targ) {
            continue;
        }

        /*
        Find the largest k >= 1 such that

        1. B - (k-1)*s >= s
        2. B - k*s >= targ

        k <= floor(B/s)
        k <= floor((B-targ)/s)

        */

        int k = min(b[i], b[i] - targ) / s;
        DUMP(k);
        ans += 1LL * k;

        b[i] -= k * s;
        if (good(i + 1)) q.push((i + 1) % n);
        if (good(i - 1)) q.push((i + n - 1) % n);
    }
    for (int i = 0; i < n; ++i)
        if (a[i] != b[i]) {
            cout << "-1\n";
            return;
        }
    cout << ans << "\n";
}

