ll dfs(int i)
{
  ll left = b[(i - 1 + n) % n];
  ll right = b[(i + 1 + n) % n];
  if (left + right == 0)
  {
    return 0;
  }
  ll ans = b[i] / (left + right);
  b[i] = b[i] % (left + right);
  if (b[i] == 0)
  {
    return 0;
  }
  if (a[i] == b[i])
    match[i] = true;

  if (b[(i - 2 + n) % n] + b[i] < b[(i - 1 + n) % n] && !match[(i - 1 + n) % n])
  {
    if (b[(i - 2 + n) % n] + b[i] != 0)
    {
      q.push(make_pair(b[(i - 1 + n) % n] % (b[(i - 2 + n) % n] + b[i]), (i - 1 + n) % n));
    }
  }
  if (b[i] + b[(i + 2 + n) % n] < b[(i + 1 + n) % n] && !match[(i + 1 + n) % n])
  {
    if (b[i] + b[(i + 2 + n) % n] != 0)
    {
      q.push(make_pair(b[(i + 1 + n) % n] % (b[i] + b[(i + 2 + n) % n]), (i + 1 + n) % n));
    }
  }
  return ans;
}

