// セグ木
template<typename T,typename F>
struct ST{

  int size;
  vector<T> seg;
  const F func;
  const T UNIT;

  ST(int N,F func , T UNIT): func(func) , UNIT(UNIT) {
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
  }

  ST(const vector<T> &v,F func , T UNIT) : func(func) , UNIT(UNIT){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size , UNIT);
    // set
    for(int i = 0; i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k, T x){
    seg[k + size] = x;
  }

  void build(){
    for(int k = size-1; k > 0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func( seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void add(int k , T x){
    k += size; seg[k] += x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  // 半開区間[a,b)へのクエリ
  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

void solve(){
  ini(N);
  vl a(N),b(N); in(a,b);
  auto f=[&](ll a,ll b){return max(a,b);};
  ST<ll,decltype(f)> seg(b,f,-1);
  ll ans = 0;
  auto nxt = [&](int idx){return (idx + 1) % N;};
  auto pre = [&](int idx){return (idx + N - 1) % N;};
  while(seg.query(0 , N) > 0){
    rep(i,N) trc(seg[i]);
    int idx;
    {
      int l = 0 , r = N;
      while(l + 1 < r){
        int med = (l + r) / 2;
        if(seg.query(l,med) < seg.query(med,r)) l = med;
        else r = med;
      }
      idx = l;
    }
    ll nei = b[pre(idx)] + b[nxt(idx)];
    ll val = b[idx] % nei;
    trc(idx , nei , val);
    if(val > a[idx] && val == b[idx]) die(-1); 
    if(val >= a[idx]){
      ans += b[idx] / nei;
      b[idx] = val;
      seg.update(idx , val == a[idx] ? -1 : val);
    }
    else{
      if(b[idx] % nei != a[idx] % nei) die(-1);
      ans += (b[idx] - a[idx]) / nei;
      seg.update(idx , -1);
      seg.update(pre(idx) , -1);
      seg.update(nxt(idx) , -1);
      b[idx] = a[idx];
    }
  }
  rep(i , N){
    if(a[i] != b[i]) die(-1);
  }
  out(ans);

}

