Int solve(vector<Int> A, vector<Int>B){
  const Int N = A.size();
  priority_queue<P> Q;
  for(Int i=0;i<N;i++) Q.emplace(B[i], i);

  Int res = 0;
  while(!Q.empty()){
    Int val, idx; tie(val, idx) = Q.top(); Q.pop();
    Int a = B[(idx-1+N)%N];
    Int b = B[idx];
    Int c = B[(idx+1)%N];
    Int target = A[idx];
    if(b == target) continue;
    if(b - a - c < target) return -1;
    Int nb = target + ((b - target) % (a + c));
    res += ((b - target) / (a + c));
    B[idx] = nb;
    if(nb != target) Q.emplace(nb, idx);

  }
  return res;

}

