#include <bits/stdc++.h>
#include <queue>
using namespace std;
int N; 
int f(int x){
	if(x == -1) return N-1; 
	if(x == N) return 0; 
	else return x; 
}
int main(){
	cin >> N; 
	long long int A[200010] = {}; 
	long long int B[200010] = {}; 
	long long int C[200010] = {}; 	
	for(int i = 0; i < N; i++){
		cin >> A[i];
	}
	for(int i = 0; i < N; i++){
		cin >> B[i]; C[i] = B[i]; 
	}
	priority_queue<pair<long long int, int>, vector<pair<long long int, int>>> que; 
	for(int i = 0; i < N; i++){
		que.push(make_pair(B[i], i)); 
	}
	bool ok = true; 
	long long int ans = 0; int update = 0; 
	while(que.size() > 0 && ok){
		pair<long long int, int> p = que.top(); 
		if(p.first == A[p.second]){ 
			que.pop(); update = 0; 
		}
		else if(p.first < C[f(p.second - 1)] + C[f(p.second + 1)]){
			ok = false; 
		}
		else{
			long long int now = p.first;
			long long int a = C[f(p.second - 1)] + C[f(p.second + 1)];
			long long int goal = A[p.second]; 
			long long int tmp = now % a;
			if(tmp == goal){
				C[p.second] = tmp; que.pop(); 
				ans += now / a; update = 0; 
			}
			else if(tmp > goal){
				C[p.second] = tmp; que.pop(); ans += now / a; 
				que.push(make_pair(tmp, p.second)); update = 0; 
			}
			else{
			    //ok = false; 
				C[p.second] = tmp + (goal + a - 1) / a * a; 
				ans += (now - C[p.second]) / a; 
				que.pop(); if(now != C[p.second]) update = 0; 
				que.push(make_pair(tmp + (goal + a - 1) / a * a, p.second)); 
			}
			update ++; 
			if(update >= N * 3) ok = false; 
		}
	}
	if(ok) cout << ans << endl; 
	else cout << -1 << endl; 
}

#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

int64 Solve() {
  int n;
  cin >> n;
  vector<int> as(n);
  vector<int> bs(n);
  for (int i = 0; i < n; i++) cin >> as[i];
  for (int i = 0; i < n; i++) cin >> bs[i];

  int64 cost = 0;
  int match_count = 0;
  for (int i = 0; i < n; i++) {
    if (as[i] == bs[i]) {
      match_count++;
    }
  }

  deque<int> queue;
  for (int i = 0; i < n; i++) {
    queue.push_back(i);
  }


  while (!queue.empty()) {
    int i = queue.front();
    queue.pop_front();
    if (bs[i] - (bs[(i + n - 1) % n] + bs[(i + 1) % n]) >= as[i]) {
      int q = (bs[i] - as[i]) / (bs[(i + n - 1) % n] + bs[(i + 1) % n]);
      bs[i] -= q * (bs[(i + n - 1) % n] + bs[(i + 1) % n]);
      cost += q;
      if (bs[i] == as[i]) {
        match_count++;
        if (match_count == n) {
          return cost;
        }
      }
      queue.push_back((i + n - 1) % n);
      queue.push_back(i);
      queue.push_back((i + 1) % n);
    }
  }
  return -1;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve() << endl;
}

