const ll MOD = 1e9 + 7;

class CNumbersOnACircle {
public:
    void solve(std::istream& in, std::ostream& out) {
        int N;
        in >> N;
        vector<int> A(N), B(N);
        REP(i,0,N) in >> A[i];
        REP(i,0,N) in >> B[i];

        priority_queue<pair<int,int>, vector<pair<int,int>>> que;
        REP(i,0,N) {
            que.push({B[i], i});
        }

        int answer = 0;
        while (!que.empty()) {
            auto p = que.top();
            que.pop();
            const int index = p.second;
            auto& current = B[index];
            const auto& previous = B[(index - 1 + N) % N];
            const auto& next = B[(index + 1) % N];

            int secondValue = A[index];
            if (!que.empty()) {
                secondValue = que.top().first;
            }

            const int cnt = max(1, (current - max(secondValue, A[index])) / (next + previous));
            current -= cnt * (next + previous);
            answer += cnt;
            if (A[index] > current) {
                out << -1 << "\n";
                return;
            } else if (A[index] < current) {
                que.push({current, index});
            }
        }
        out << answer << "\n";
    }
};


int main() {
	CNumbersOnACircle solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

