    for(int i = 0; i < n; i++) cin >> a[i];
    for(int i = 0; i < n; i++){
        cin >> b[i];
        ll sum;
        if(i == 0){
            sum = a[n-1] + a[i] + a[i+1];
        }else if(i == n-1){
            sum = a[i-1] + a[i] + a[0];
        }else{
            sum = a[i-1] + a[i] + a[i+1];
        }

        if(b[i] < sum){
            cout << -1 << endl;
            return 0;
        }
    }

    ll count = 0;
    while(true){
        bool flag = true;
        for(int i = 0; i < n; i++){
