            if(i == 0){
                sum = b[n-1] + b[i+1];
            }else if(i == n-1){
                sum = b[i-1] + b[0];
            }else{
                sum = b[i-1] + b[i+1];
            }

            if(b[i] > sum && b[i] != a[i]){
                flag = false;
                b[i] -= sum;
                count++;

