    cin >> A[i];
  }  
  for(int i = 0; i< N; i++){
    cin >> B[i];
  }
  bool done = false;
  ll count = 0;

  while(!done){
    // for(auto a : B) cout << a << " ";cout <<endl;
    done = true;  //change to false
    for(ll i = 0; i < N; i++){
      ll im = (i==0) ? N-1 : i-1;
      ll ip = (i==N-1) ? 0 : i+1;
      ll wi = B[im] + B[ip];
      if(B[i] - A[i] >= wi){
        count += (B[i] - A[i]) / wi;
        B[i] = (B[i] - A[i]) % wi + A[i];
        done = false;

        for(ll j = i-1; j >= 0; j--){
          ll jm = (j==0) ? N-1 : j-1;
          ll jp = (j==N-1) ? 0 : j+1;
          ll wj = B[jm] + B[jp];
          if(B[j] - A[j] >= wj){
             count += (B[j] - A[j]) / wj;
             B[j] = (B[j] - A[j]) % wj + A[j];
          }else{
            break;
          }
        }
      }
