signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);
	VEC(int, b, n);

	std::priority_queue<PAIR> pq;
	REP(i, n) {
		if (b[i] < a[i]) {
			OUT(-1)BR;
			return 0;
		}
		if (b[i] == a[i]) continue;
		int sum = b[(i + 1) % n] + b[(i - 1 + n) % n];
		int t = b[i] - sum - a[i];
		if (t >= 0) pq.push(PAIR(t, i));
	}

	int ans = 0;
	while (!pq.empty()) {
		PAIR p = pq.top(); pq.pop();
		int v = p.first, i = p.second;
		int sum = b[(i + 1) % n] + b[(i - 1 + n) % n];
		int t = b[i] - sum - a[i];
		if (v != t) continue;
		if (t < 0) continue;

		int k = (b[i] - a[i]) / sum;

		b[i] -= sum * k;
		ans += k;
		FOR(i_, i - 1, i + 2) {
			int I = (i_ + n) % n;
			int tsum = b[(I + 1) % n] + b[(I - 1 + n) % n];
			int tt = b[I] - tsum - a[I];
			if (tt >= 0) pq.push(PAIR(tt, I));
		}
	}
	if (a != b) {
		OUT(-1)BR;
		return 0;
	}
	OUT(ans)BR;

	return 0;
}

