int n;

int check(int p){
	if(p>=n)p-=n;
	if(p<0)p+=n;
	if(t[0][p]==t[1][p])return 0;
	LL a,b,c;
	int i,j,k;
	a=p-1,b=p+1;
	if(a<0)a+=n;
	if(b>=n)b-=n;
	if(t[1][a]>=t[1][p] || t[1][p]<=t[1][b])return 0;
	a=t[1][a]+t[1][b];
	c=(t[1][p]-t[0][p])/a;
	t[1][p]-=c*a;
	return check(p-1)+check(p+1)+c;
}

