//mint
struct mint {
    ll x; // typedef long long ll;
    mint(ll x=0):x((x%MOD+MOD)%MOD){}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += MOD-a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime MOD
    mint inv() const {
        return pow(MOD-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};
typedef vector<mint> Vmint;

struct combination {
    vector<mint> fact, ifact;
    combination(int n):fact(n+1),ifact(n+1) {
        assert(n < MOD);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
    }
    mint operator()(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n]*ifact[k]*ifact[n-k];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<std::setprecision(10);

    ll n;
    cin>>n;
    Vec a(n);
    Vec b(n);
    cin>>a>>b;

    ll cnt = 0;
    auto handle = [&](ll i)->bool{
        ll prev = b[ (n+i-1) % n ];
        ll next = b[ (n+i+1) % n ];

        if(b[i]<=prev)return false;
        if(b[i]<=next)return false;

        ll r = (b[i]-a[i]) % (prev+next);
        ll minus = b[i]-a[i]-r;
        if(minus == 0) return false;
        b[i] -= minus;
        cnt += minus / (prev+next);
        return true;
    };

    auto comp = [](P a,P b){
        return a.fi < b.fi;
    };
    priority_queue<P,VP, decltype(comp)> q(comp);

    rep(i,n){
        q.emplace(b[i],i);
    }

    while(!q.empty()){
        P now = q.top();
        dbg(now);
        q.pop();
        if(handle(now.se)){
            q.emplace(b[now.se], now.se);
        }
    }
    bool ok = true;
    rep(i,n){
        if(a[i]!=b[i])ok = false;
    }
    dbg(a)
    dbg(b)
    if(ok){
        out(cnt);
    }else{
        out(-1);
    }

    return  0;
}

