      return 0;
    }
    int times = max((b[pos]-a[pos])/(b[pre_pos]+b[nxt_pos]),1);
    ans+=times;
    b[pos] -= (b[pre_pos] + b[nxt_pos]) * times;
    if(b[pos]==a[pos]) continue;
    else if(b[pos] < a[pos]){
      cout << -1 << endl;
      return 0;
    }
    pq.push({b[pos],pos});
    // cout << b[pos] << endl;
  }

  cout << ans << endl;


  return 0;


}

