using namespace std;

int next(int i, int n) {
	if (i == n - 1) return 0;
	else return i + 1;
}

int prev(int i, int n) {
	if (i == 0) return n - 1;
	else return i - 1;
}

int main() {
	int n;
	cin >> n;
	vector<int> a(n), b(n), c(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	for (int i = 0; i < n; i++) {
		cin >> b[i];
	}

	int ans = 0, fin = 0, miss = 0;
	vector<bool> finished(n);
	for (int i = 0; i < n; i++) finished[i] = false;

	for (int i = 0;; i = next(i, n)) {
		if (fin == n || miss == n) break;
		if (!finished[i]) {
			int ne = next(i, n), pr = prev(i, n);
			if (b[i] - b[ne] - b[pr] > 0) {
				miss = 0;
				ans += b[i] / (b[ne] + b[pr]);
				b[i] = b[i] % (b[ne] + b[pr]);
				if (b[i] == a[i]) { finished[i] = true; fin++; }
				else if (b[i] < a[i]) miss = n;
			}
			else miss++;
		}
	}

	if (miss == n) cout << -1 << endl;
	else cout << ans << endl;

	return 0;
}

