    cauto check = [&](ll i){
        ll mi = (i - 1 + N) % N; // i - 1
        ll pi = (i + 1) % N;     // i + 1

        if(A[i] > B[i]){
            cout << -1 << endl;
            exit(EXIT_SUCCESS);
        }

        return B[i] - B[mi] - B[pi] > 0 and B[i] > A[i];
    };

