        if(check(i)){
            pq.emplace(B[i], i);
        }
    }

    ll ans = 0;
    while(not pq.empty()){
        cauto i = pq.top().second; pq.pop();
        ll mi = (i - 1 + N) % N; // i - 1
        ll pi = (i + 1) % N;     // i + 1

