ll solver2(vector<ll>A,vector<ll>B){
    int N = (int)A.size();
    ll res = 0;

    priority_queue<pll> pq;
    for(int i = 0; i < N;i++){
        if(A[i] == B[i]) continue;

        pq.push(pll(B[i],i));
    }
    while(pq.size()){
        ll ms,id; tie(ms,id) = pq.top(); pq.pop();

        ll S = B[(id-1+N)%N] + B[(id+1)%N];

        ll C = max(1LL,(ms-max(A[id],S))/S);
        res+=C;
        B[id] -= S*C;

        if(B[id] < A[id]) return -1;
        if(B[id] == A[id]) continue;
        pq.push(pll(B[id],id));
    }
    return res;
}

