bool localmax(int i, int c[]) {
    return c[i] >= (c[(i-1+n)%n] + c[(i+1)%n]);
}

pair<ll,vector<int>> check(int c[]) {
    ll cnt = 0;
    priority_queue<pair<int,int>> pq;
    for (int i = 0; i < n; i++) {
        if (localmax(i,c)) {
            pq.push({c[i],i});
        }
    }
    while (!pq.empty()) {
        auto p = pq.top(); pq.pop();
        int i = p.second;
        int s = c[(i-1+n)%n] + c[(i+1)%n];
        if (s == 0) continue;
        assert(s > 0);
        cnt += c[i]/s;
        c[i] %= s;
        if (localmax((i-1+n)%n,c)) pq.push({b[(i-1+n)%n],(i-1+n)%n});
        if (localmax((i+1+n)%n,c)) pq.push({b[(i+1+n)%n],(i+1+n)%n});
    }
    vector<int> res;
    for (int i = 0; i < n; i++) {
        res.push_back(c[i]);
    }
    return {cnt,res};
}

