            int mx = max<int>({b[(i + 1) % n], b[(i + n - 1) % n], a[i]});
            int step = (b[i] - mx) / sum;
            b[i] -= step * sum;
            ans += step;
        }
        if(judge(i))doit(i);
        if(judge((i + 1) % n))doit((i + 1) % n);
        if(judge((i + n - 1) % n))doit((i + n - 1) % n);
    }

