  cin.tie(nullptr);
  int N;
  cin >> N;
  vector<i64> A(N), B(N);
  for (auto& x : A) cin >> x;
  for (auto& x : B) cin >> x;

  auto solve = [&]() -> int {
    REP(i, N) {
      if (B[i] < A[i]) return -1;
    }
    priority_queue<pair<i64, int>> pq;
    int ok_cnt = 0;
    REP(i, N) {
      if (B[i] > A[i]) {
        pq.emplace(B[i], i);
      } else {
        ok_cnt++;
      }
    }
    int step = 0;
    while (pq.size()) {
      i64 btop = pq.top().first;
      int bix = pq.top().second;
      pq.pop();
      assert(B[bix] == btop);
      int l = (bix - 1 + N) % N;
      int r = (bix + 1) % N;
      if (B[bix] > A[bix] && B[bix] - (B[l] + B[r]) < A[bix]) return -1;
      int batch;
      if (pq.empty()) {
        if ((B[bix] - A[bix]) % (B[l] + B[r]) != 0) return -1;
        batch = (B[bix] - A[bix]) / (B[l] + B[r]);
      } else {
        batch = (B[bix] - max(A[bix], pq.top().first) + (B[l] + B[r]) - 1) /
                (B[l] + B[r]);
      }
      assert(batch > 0);
      step += batch;
      B[bix] -= batch * (B[l] + B[r]);
      assert(B[bix] >= A[bix]);
      if (B[bix] == A[bix]) {
        ok_cnt++;
      } else {
        pq.emplace(B[bix], bix);
      }
    }
    assert(ok_cnt == N);
    return step;
  };
  cout << solve() << endl;
}

