ll solve(int n, VL &a, VL &b) {
    ll ops = 0;

    while (true) {
        bool chg = false;

        FOR(i,0,n-1) {
            if (b[i] < a[i]) {
                return -1;
            } else if (b[i] > a[i]) {
                ll bPrev = b[(i - 1 + n) % n];
                ll bNext = b[(i + 1) % n];

                ll adjSum = bPrev + bNext;
                ll over = b[i] - a[i];

                if (over >= adjSum) {
                    ops += over / adjSum;
                    over %= adjSum;

                    b[i] = a[i] + over;
                    chg = true;
                }
            }
        }

        if (a == b) {
            return ops;
        }

        if (!chg) {
            return -1;
        }
    }
}

