int main() {
	int n = in;
	VL a = in[n], b = in[n];

	auto next = [&](int i) {return (i + 1) % n; };
	auto prev = [&](int i) {return (i ? i : n) - 1; };

	PQ<pair<ll, int>> pq;
	rep(i, n)pq.emplace(b[i], i);

	int ans = 0;
	while (!pq.empty()) {
		ll val; int i; tie(val, i) = pq.top(); pq.pop();
		if (val == a[i])continue;

		ll sum = b[next(i)] + b[prev(i)];
		if (val - sum < a[i]) {
			out.exit(-1);
		}

		ll cnt = (val - a[i]) / sum;
		ll next_val = val - sum * cnt;
		pq.emplace(next_val, i);
		b[i] = next_val;
		ans += cnt;
	}
	out(ans);
}

