typedef long long LL; using namespace std;

int N;

LL A[1 << 20], B[1 << 20];
priority_queue<pair<LL, int> > heap;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cin >> N;
	FOR (i, N)
		cin >> A[i];
	FOR (i, N)
		cin >> B[i];

	while (!heap.empty())
		heap.pop();

	FOR (i, N)
		heap.push(make_pair(B[i], i));

	LL ret = 0LL;
	while (!heap.empty()) {
		pair<LL, int> val = heap.top();
		heap.pop();
		int idx = val.second;
		if (A[idx] == B[idx])
			continue;

		int idxLeft = idx - 1;
		if (idxLeft < 0)
			idxLeft = N - 1;
		int idxRight = idx + 1;
		if (idxRight == N)
			idxRight = 0;

		LL sum = B[idxLeft] + B[idxRight];
		if (sum <= 0) {
			ret = -1;
			break;
		}
		LL times = (B[idx] - A[idx]) / sum;
		if (times == 0LL)
			times = 1LL;
		ret += times;

		B[idx] -= times * sum;
		if (B[idx] < A[idx]) {
			ret = -1;
			break;
		}

		heap.push(make_pair(B[idx], idx));
	}

	cout << ret << endl;
	return 0;
}

