using namespace std;

int A[200010],B[200010];
int N,Count=0;

bool Judge(){
    for(register int i=1;i<=N;++i)
        if(A[i]!=B[i]) return false;
    return true;
}

int main(){
    scanf("%d",&N);
    for(register int i=0;i<N;++i)
        scanf("%d",&A[i]);
    for(register int i=0;i<N;++i)
        scanf("%d",&B[i]);
    if(Judge()){cout<<0<<endl;return 0;}
    while(1){
        int MinPos=-1,MinNum=2147483647,Step=0;
        if(Judge()) break;
        for(register int i=0;i<=N-1;++i){
            if(B[i]<A[i]) {cout<<-1<<endl;return 0;}
            int temp=B[(i-1+N)%N]+B[(i+1)%N];
            int K=(B[i]-A[i])/temp;
            if(B[i]-K*temp<MinNum && K!=0){
                Step=K;
                MinPos=i;MinNum=B[i]-K*temp;   
            }
        }
        if(MinPos==-1){printf("-1\n");return 0;}
        Count+=Step;
        B[MinPos]=MinNum;
    }
    cout<<Count<<endl;
    //system("pause");
    return 0;
}

