int N;
ll A[int(2e5 + 5)], B[int(2e5 + 5)];
priority_queue <Pli> que;

int main(){
  scanf("%d", &N);
  for (int i = 0; i < N; i++) scanf("%lld", A + i);
  for (int i = 0; i < N; i++){
    scanf("%lld", B + i);
    que.push({B[i], i});
  }

  ll ans = 0;
  while (!que.empty()){
    Pli Q = que.top(); que.pop();
    int now = Q.se; ll sum = 0;

    if (B[now] == A[now]) continue;

    if (now == 0) sum = B[N - 1] + B[1];
    else if (now == N - 1) sum = B[N - 2] + B[0];
    else sum = B[now - 1] + B[now + 1];

    if (sum >= B[now]){
      printf("-1\n"); return 0;
    }

    ll turn;
    if (A[now] >= sum){
      turn = (B[now] - A[now]) / sum;
    }else{
      turn = (B[now] / sum);
      if (B[now] % sum == 0) turn--;
    }

    ans += turn;
    B[now] -= turn * sum;

    if (turn <= 0){
      printf("-1\n"); return 0;
    }

    if (A[now] == B[now]) continue;
    if (A[now] > B[now]){
      printf("-1\n"); return 0;
    }
    que.push({B[now], now});
  }
  printf("%lld\n", ans);

  return 0;
}

