struct str{
	int x,s;
};
bool operator <(str a,str b)
{
	return a.s<b.s;
}
priority_queue<str> q;
int main()
{
	scanf("%d",&n);
	for(i=0;i<n;i++)
		scanf("%d",&a[i]);
	for(i=0;i<n;i++)
	{
		scanf("%d",&b[i]);
		q.push((str){i,b[i]});
	}
	while(!q.empty())
	{
		str x=q.top();
		q.pop();
		if(a[x.x]==b[x.x])
			continue;
		int s=b[(x.x-1+n)%n]+b[(x.x+1)%n];
		if(b[x.x]<=s)
			break;
		if(a[x.x]>=s)
		{
			if((b[x.x]-a[x.x])%s==0)
			{
				ans+=(b[x.x]-a[x.x])/s;
				b[x.x]=a[x.x];
			}
			else
				break;
		}
		else
		{
			ans+=b[x.x]/s;
			b[x.x]%=s;
			q.push((str){x.x,b[x.x]});
		}
	}
	for(i=1;i<=n;i++)
		if(a[i]!=b[i])
		{
			printf("-1");
			return 0;
		}
	cout<<ans;
}

