priority_queue <node> Q; 

int main() {
  scanf("%d", &n); ll ans = 0; 
  for(int i = 1; i <= n; i++) {
    scanf("%d", &a[i]); 
  }
  for(int i = 1; i <= n; i++) {
    scanf("%d", &b[i]); 
    Q.push((node){b[i], i}); 
    if(b[i] < a[i]) {
      puts("-1"); 
      return 0; 
    }
  }
  while(!Q.empty()) {
    tmp = Q.top(); Q.pop(); 
    if(tmp.d == a[tmp.id]) continue ; 
    if(tmp.d < a[tmp.id]) {
      puts("-1"); 
      return 0; 
    }
    int id = tmp.id; 
    int id1 = id + 1; 
    int id2 = id - 1; 
    if(id1 > n) id1 -= n; 
    if(id2 < 1) id2 += n; 
    if(tmp.d <= b[id1] + b[id2]) {
      puts("-1");
