class Solve {
public:
    int N;
    vector<ll> A;
    vector<ll> B;

    void solve() {
        cin >> N;
        A.resize(N);
        B.resize(N);
        for (int i = 0; i < N; ++i) {
            cin >> A[i];
        }
        for (int i = 0; i < N; ++i) {
            cin >> B[i];
        }

        int cnt = 0;
        while (true) {
            bool del = false; // 消せるものがあるか
            bool ok = true; // クリア条件満たしているか
            for (int i = 0; i < N; ++i) {
                if (A[i] != B[i]) {
                    ok = false;
                    if (A[i] > B[i]) {
                        cout << -1 << endl;
                        return;
                    } else {
                        int a = i;
                        int l = (a - 1 + N) % N;
                        int r = (a + 1) % N;
                        if (B[i] - B[l] - B[r] >= A[i]) {
                            ll div = (B[i] - A[i]) / (B[l] + B[r]);
                            B[i] -= div * (B[l] + B[r]);
                            cnt += div;
                            if (div > 0) del = true;
                        }
                    }
                }
            }
            if (ok) {
                cout << cnt << endl;
                exit(-1);
                return;
            }
            if (!del) {
                cout << -1 << endl;
                return;
            }
        }


//        jikken();

    }

