        while (true) {
            for (int i = 0; i < N; ++i) {
                cout << B[i] << " ";
            }
            cout << endl;

            int a;
            cin >> a;
            if (a == -1) break;
            int l = (a - 1 + N) % N;
            int r = (a + 1) % N;
            B[a] -= (B[l] + B[r]);
        }
    }

};


