    scanf("%d",&a[i]);
  }
  long long ret = 0;
  priority_queue<pair<int,int> >pq;
  for(int i=0;i<n;++i) {
    scanf("%d",&b[i]);
    if(a[i]>b[i]) {
      printf("-1\n");
      return;
    }
    pq.push(make_pair(b[i],i));
  }
  while(!pq.empty()) {
    int ind = pq.top().second;
    int val = b[ind];
    pq.pop();
    if(val==a[ind]) {
      continue;
    }
    int maxi = max(b[(ind+n-1)%n], b[(ind+1)%n]);
    maxi = max(maxi,a[ind]);
    int g = b[(ind+n-1)%n] + b[(ind+1)%n];
    int diff = val - a[ind];
    if(b[ind]-g<a[ind]) {
      continue;
    }
    long long add = diff/g;
    long long tmp = b[ind] - add*g;
    if(tmp<a[ind]) {
      break;
    }
    b[ind] -= g*add;
    ret += add;
    pq.push(make_pair(b[ind],ind));
  }
  for(int i=0;i<n;++i) {
    if(a[i]!=b[i]) {
      ret = -1;
      break;
    }
