int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N=in<ll>();
	auto S=vecin<ll>(N);
	auto E=vecin<ll>(N);
	auto comp = [](pair<ll,ll>& l,pair<ll,ll>& r){return l.second<r.second;};
	priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,decltype(comp)> Q(comp);
	ll finish = 0;
	REP(i,N){
		pair<ll,ll> P(i,E[i]);
		Q.push(P);
		if(S[i]==E[i]) finish++;
	}

	int num = 0;
	while(!Q.empty()){
		auto V = Q.top();
		Q.pop();
		ll next = (V.first+1+N)%N;
		ll prev = (V.first-1+N)%N;
		ll PN = 1;
		if(!Q.empty()){
			auto VN = Q.top();
			PN = ceil((V.second-VN.second)/((double)E[next]+(double)E[prev]));
		}
		E[V.first] -= PN*(E[next]+E[prev]);
		num+=PN;
		if(E[V.first]<S[V.first]){
			cout << -1 << endl;
			return 0;
		}
		if(E[V.first]==S[V.first]){
			finish++;
		}
		else{
			Q.emplace(V.first,E[V.first]);
		}
		if(finish>=N) break;
	}

	out(num);
	return 0;
}

