bool good(vector<int> &v, int index){
	int a = (index-1+v.size())%v.size(), b = index, c = (index+1)%v.size();
	return (v[b] > v[a] + v[c]);
}
int ans=0;
void des(vector<int> &v, int index, int border){
	int a = (index-1+v.size())%v.size(), b = index, c = (index+1)%v.size();
	int sum = v[a] + v[c];
	int delta = v[index]-border;
	ans += delta/sum;
	v[b] -= sum * (delta/sum);
}
