priority_queue<P> Q;

int main(void)
{
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) cin >> b[i];

	for(int i = 0; i < n; i++){
		Q.push(make_pair(b[i], i));
	}

	llint ans = 0;
	while(Q.size()){
		llint id = Q.top().second;
		//cout << id << endl;
		//for(int i = 0; i < n; i++) cout << b[i] << " "; cout << endl;
		Q.pop();
		if(b[id] == a[id]) continue;
		if(b[id] < a[id]){
			cout << -1 << endl;
			return 0;
		}
		llint d = b[(id+1)%n] + b[(id-1+n)%n], m = max(b[(id+1)%n], b[(id-1+n)%n]);
		//cout << d << " " << m << endl;
		if(a[id] >= m && (b[id]-a[id]) % d == 0){
			ans += (b[id]-a[id]) / d;
			b[id] = a[id];
		}
		else{
			llint c = (b[id]-m+d-1) / d;
			ans += c;
			b[id] -= c*d;
			Q.push(make_pair(b[id], id));
		}
	}

	cout << ans << endl;

	return 0;
}

