using ll = long long int;

#define mp(a,b) make_pair(a,b)

const int MOD = 1000 * 1000 * 1000 + 7;

bool res() {
	int n;
	cin >> n;
	if (!cin) return false;
	vi a(n); for (int i = 0; i < n; ++i) cin >> a[i];
	vi b(n); for (int i = 0; i < n; ++i) cin >> b[i];

	priority_queue<ii, vii, less<ii>> pq;

	bool pos = true;
	ll nmov = 0;

	for (int i = 0; i < n; ++i) {
		if (b[i] < a[i]) {
			pos = false;
		}
		else if (b[i] == a[i]) {}
		else pq.push(mp(b[i], i));
	}

	while (!pq.empty() && pos) {
		ii nact = pq.top(); pq.pop();
		int lados = 0;
		if (nact.second == 0) lados += b[n - 1];
		else lados += b[nact.second - 1];
		if (nact.second == n - 1) lados += b[0];
		else lados += b[nact.second + 1];


		int divis;
		if (pq.empty()) {
			int dif = nact.first - a[nact.second];
			double divsnec = ((double)dif) / lados;
			divis = ceil(divsnec);
		}
		else {
			ii nsig = pq.top(); 
			int dif = nact.first - max(nsig.first, a[nact.second]);
			double divsnec = ((double)dif) / lados;
			divis = ceil(divsnec);
		}

		nact.first -= divis * lados;
		nmov += divis;
		b[nact.second] = nact.first;


		if (a[nact.second] == nact.first) {}
		else if (a[nact.second] > nact.first) {
			pos = false;
			break;
		}
		else { pq.push(nact); }
	}


	if (pos) cout << nmov << '\n';
	else cout << "-1\n";

	return true;
}

int main() {
	while (res()) {}
	return 0;
}

