  REP(i, N) pq.push((P){B[i], i});
  ll ans = 0;

  for (int same = 0; ;) {
    P p = pq.top(); pq.pop();
    int k = B[(p.pos - 1 + N) % N] + B[(p.pos + 1 + N) % N];
