using namespace std;

int solve(vector<int> A, vector<int> B){
    const int N = A.size();
    int res = 0;
    priority_queue<pair<int,int>> qu;
    for(int i=0;i<N;i++){
        if(A[i] > B[i]) return -1;
        if(A[i] == B[i]) continue;
        qu.emplace(B[i], i);
    }
    while(!qu.empty()){
        ++res;
        int idx = qu.top().second; qu.pop();
        B[idx] -= B[(idx+1)%N] + B[(idx+N-1)%N];
        if(B[idx] < A[idx]) return -1;
        if(B[idx] > A[idx]) qu.emplace(B[idx], idx);
    }
    return res;
}

int main(){
    int N;
    while(cin >> N){
        vector<int> A(N), B(N);
        for(auto& t : A) cin >> t;
        for(auto& t : B) cin >> t;
        cout << solve(A, B) << endl;
    }
}

