                    if(temp%j==0)
                    {
                        brr[i]=arr[i];
                        ans+=temp/j;
                    }
                    else err();
                }
                else
                {
                    ans+= brr[i]/j;
                    brr[i]=brr[i]%j;
                    if(brr[i]<arr[i]) err();
                }
            }
            brr[n+1]=brr[1];
        }

    }

    rep(i,1,n+1)
    {
        if(arr[i]!=brr[i])err();
    }
    cout<<ans;

    return 0;
}

