            if (b[i] < sum) no();
            cnt += b[i] / sum;
            b[i] %= sum;
            if (is_top((i - 1 + n) % n)) q.push((i - 1 + n) % n);
            if (is_top((i + 1) % n)) q.push((i + 1) % n);
        }
    }
