void _main()
{
    ll n; llin(n);
    S V<ll> alist; llina(alist, n);
    S V<ll> blist; llina(blist, n);

    priority_queue<t2> q;
    rep (i, n) {
        ll b = blist[i];
        q.push(t2(b, i));
    }

    ll ans = 0LL;

    while (q.size()) {
        auto item = q.top(); q.pop();
        ll idx = get<1>(item);
        ll pidx = (idx - 1 + n) % n;
        ll nidx = (idx + 1) % n;
        ll floor = max({alist[idx], blist[pidx], blist[nidx]});
        ll cnt = (blist[idx] - floor) / (blist[pidx] + blist[nidx]);

        blist[idx] -= (blist[pidx] + blist[nidx]) * cnt;
        ans += cnt;

        if (blist[idx] > floor) {
            blist[idx] -= blist[pidx] + blist[nidx];
            ans++;
        }

        if (blist[idx] < alist[idx]) {
            cout << -1 << endl;
            return;
        }
        if (blist[idx] > alist[idx]) {
            q.push(t2(blist[idx], idx));
        }
    }

    cout << ans << endl;
}

