    std::cin >> b_i;
  }

  std::set<std::pair<int, int>, std::greater<std::pair<int, int>>>
      uncomp_B_index;
  for (int i = 0; i < N; i++) {
    if (A.at(i) != B.at(i)) {
      uncomp_B_index.insert({B.at(i), i});
    }
