    uncomp_B_index.erase(it);

    const int d = B.at((N + i - 1) % N) + B.at((i + 1) % N); // 変化量

    const int howMany = std::min((b - nextMax) / d + 1, (b - a) / d);
    b -= d * howMany;
    count += howMany;

