void failed () {
	std::cout << -1 << '\n';
	exit(0);
}

int main() {
	int n;
	std::cin >> n;
	std::vector<int> a(n), b(n);
	for (int &e : a) std::cin >> e;
	for (int &e : b) std::cin >> e;

	long long ans = 0;
	std::priority_queue<std::pair<int, int>> que;
	for (int i = 0; i < n; i++) {
		if (a[i] != b[i]) que.emplace(b[i], i);
		if (a[i] > b[i]) failed();
	}

	while (not que.empty()) {
		auto [value, i] = que.top(); que.pop();
		const int l = (i == n - 1 ? 0 : i + 1);
		const int r = (i == 0 ? n - 1 : i - 1);
		const int s = b[l] + b[r];
		if (b[i] < s) failed();

		const int count = (b[i] - std::max(s, a[i]) + s - 1) / s;
		if ((b[i] -= (count * s)) < a[i]) failed();
		if (b[i] != a[i]) que.emplace(b[i], i);
		ans += count;
	}

	std::cout << ans << '\n';

	return 0;
}

