	cin >> N;
	vector< int > A(N);
	vector< int > B(N);
	rep(i, N) cin >> A[i];
	rep(i, N) cin >> B[i];
	priority_queue< pii > q;
	rep(i, N) q.push(make_pair(B[i], i));
	int ans = 0;
	while (!q.empty()) {
		pii p = q.top();
		q.pop();
		int i = p.second;
		int i1 = ((p.second - 1) % N + N) % N;
		int i2 = (p.second + 1) % N;
		if (B[i] < A[i]) {
			ans = -1;
			break;
		}
		int tmp = (B[i] - A[i]) / (B[i1] + B[i2]);
		//cout << i << " " << B[i1] << endl;
		if (tmp == 0) {
			ans = -1;
			break;
		}
		ans += tmp;
		B[i] -= tmp * (B[i1] + B[i2]);
		if (B[i] != A[i]) {
			q.push(make_pair(B[i], i));
		}
	}
	bool f = true;
	rep(i, N) if (A[i] != B[i]) f = false;
	cout << (f ? ans : -1) << endl;
