#define ll long long

ll a[MAXN];
ll  b[MAXN];


int N(int i, int k) {
    if (i == k) return 1;
    return i + 1;
}
int P(int i, int k) {
    if (i == 1) return k;
    return i - 1;
}
main(){
    int n = readInt();
    for (int i = 1; i <= n; i++) {
        a[i] = readInt();
    }
    queue<int> que;
    for (int i = 1; i <= n; i++) {
        b[i] = readInt();
        if (b[i] < a[i]) fail();
        que.push(i);
    }

    ll ans = 0;

    while (que.size()) {
        int i = que.front(); que.pop();
        ll near = b[N(i, n)] + b[P(i, n)];
        ll u = (b[i] - a[i]) / near;
        if (u <= 0) continue;
        ans += u;
        b[i] -= near * u;
        que.push(P(i, n));
        que.push(N(i, n));
    }

    for (int i = 1; i <= n; i++) {
        if (a[i] != b[i]) fail();
    }

    cout << ans << endl;

    return 0;
}

