		if (as[i] == bs[i]) ce++;
		if (bs[i] < as[i]) {
			cout << -1 << endl;
			return 0;
		}
	}

	queue<int> move_idx;

	if (bs[n - 1] + bs[1] < bs[0]) {
		move_idx.push(0);
	}
	FOR_LT(i, 1, n - 1) {
		if (bs[i - 1] + bs[i + 1] < bs[i]) {
			move_idx.push(i);
		}
	}
	if (bs[n - 2] + bs[0] < bs[n - 1]) {
		move_idx.push(n - 1);
	}

	int64_t ans = 0;

	while (ce != n) {
		if (move_idx.empty()) {
			cout << -1 << endl;
