struct seg {
	int cnt, lc[N << 1], rc[N << 1], c[N << 1], p[N << 1];

	void bt(int l, int r) {
		int now = ++cnt;
		lc[now] = rc[now] = -1;
		if(l == r) {
			if(a[l] == b[l]) c[now] = 0;
			else c[now] = b[l];
			p[now] = l;
		}
		if(l < r) {
			int mid = (l + r) / 2;
			lc[now] = cnt + 1; bt(l, mid);
			rc[now] = cnt + 1; bt(mid + 1, r);
			if(c[lc[now]] > c[rc[now]]) c[now] = c[lc[now]], p[now] = p[lc[now]];
			else c[now] = c[rc[now]], p[now] = p[rc[now]];
		}
	}
	void change(int now, int l, int r, int P, int C) {
		if(l == r) {
			b[P] = C;
			if(b[P] < a[P]) {s = -1;}
			if(C == a[P]) {s++, c[now] = 0;
			} else c[now] = C, p[now] = P;
			return ;
		} int mid = (l + r) / 2;
		if(P <= mid) change(lc[now], l, mid, P, C);
		else change(rc[now], mid + 1, r, P, C);
		if(c[lc[now]] > c[rc[now]]) c[now] = c[lc[now]], p[now] = p[lc[now]];
		else c[now] = c[rc[now]], p[now] = p[rc[now]];
	}
} t; int n;

