void dfs(int on) {
	int v[3];
	for(int i = -1; i <= 1; i++) {
		v[i+1] = b[(on+i+n)%n];
	}
	int use = v[1] / (v[0] + v[2]);
	use = std::min(use, (v[1] - a[on]) / (v[0] + v[2]));
	if(use == 0) {
		return;
	}
	ans += use;
	b[on] -= use * (v[0] + v[2]);
	dfs((on-1+n)%n);
	dfs((on+1+n)%n);
}

