int main() {
    cin >> n;
    for (int i = 0; i < n; i++) cin >> b[i];
    for (int i = 0; i < n; i++) cin >> a[i];
    priority_queue<pair<int,int>> pq;
    for (int i = 0; i < n; i++) {
        pq.push({a[i],i});
    }
    while (!pq.empty()) {
        int num = pq.top().first;
        int id = pq.top().second;
        pq.pop();
        int k;
        if (!pq.empty()) {
            int next = pq.top().first;
            k = (num - next) / (a[pre(id) + a[nxt(id)]]) + 1;
        } else {
            k = (num - b[id]) / (a[pre(id)] + a[nxt(id)]);
        }
        ans += k;
        a[id] -= k * (a[pre(id)] + a[nxt(id)]);
        if (a[id] == b[id]) continue;
        if (k == 0 && a[id] != b[id]) {
            cout << -1 << endl;
            return 0;
        }
        pq.push({a[id], id});
    }

    cout << ans << endl;
    return 0;
}

