using namespace std;

void solve() {
  long N;
  cin >> N;
  vector<long> A(N);
  rep (i, N) cin >> A[i];
  vector<long> B(N);
  rep (i, N) cin >> B[i];
  long result = 0;
  while (true) {
    long flag = true;
    rep (i, N) {
      if (A[i] == B[i]) continue;
      if (A[i] > B[i]) {
        cout << -1 << endl;
        return;
      }
      long prev = (i - 1 + N) % N;
      long next = (i + 1) % N;
      long max_naibor = max(B[prev], B[next]);
      if (B[i] < max_naibor) continue;
      if (B[i] == max_naibor) {
        cout << -1 << endl;
        return;
      }
      long target = max(max_naibor, A[i]);
      long sum_naibor = B[prev] + B[next];
      long count = target / sum_naibor;
      if (target % sum_naibor != 0) count++;
      B[i] -= count * sum_naibor;
      result += count;
      flag = false;
    }
    if (flag) break;
  }
  cout << result << endl;
}

int main(void) {
  cin.tie(0);
