    for(int i=0;i<n;i++){
        if(isOK(i)){
            que.push({b[i],i});
        }
    }
    ll ans = 0;
    while(!que.empty()){
        P p = que.top();
        que.pop();
        int id = p.second, l = (id-1+n)%n, r = (id+1)%n;
        ll sum = b[l]+b[r];
        if(b[id]-sum < a[id]) break;
        ans += (b[id]-a[id])/sum;
        b[id] -= (b[id]-a[id])/sum*sum;
        if(isOK(l)) que.push({b[l],l});
        if(isOK(r)) que.push({b[r],r});
    }
    bool ok = true;
    for(int i=0;i<n;i++) ok &= a[i]==b[i];
