int N;
int A[200000], B[200000];

struct cmp {
    bool operator() (int a, int b) const {
        return B[a] < B[b];
    }
};

priority_queue<int, vector<int>, cmp> pq;

bool chk(int i) {
    return A[i] < B[i] and B[(i+1)%N] < B[i] and B[(i-1+N)%N] < B[i];
}

int main(void) {
    iostream::sync_with_stdio(false);
    cin.tie(nullptr), cout.tie(nullptr);

    cin >> N;
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];

    rep(i, N) if (chk(i)) pq.push(i);

    ll res = 0;
    while(sz(pq) > 0) {
        int t = pq.top(); pq.pop();
        int ava = (B[t]-A[t])/(B[(t+1)%N]+B[(t-1+N)%N]);
        res += ava;
        B[t] -= ava*(B[(t+1)%N]+B[(t-1+N)%N]);
        if (chk((t+1)%N)) pq.push((t+1)%N);
        if (chk((t-1+N)%N)) pq.push((t-1+N)%N);
    }

    if (equal(A, A+N, B)) cout << res << endl;
    else cout << -1 << endl;
}

