const int maxn=200005;
int n;
int a[maxn],b[maxn];
priority_queue<pii>q;
ll ans;

int main(){
	scanf("%d",&n);
	rep(i,n)scanf("%d",&a[i]);
	rep(i,n){
		scanf("%d",&b[i]);
		if(b[i]<a[i]){
			puts("-1");
			return 0;
		}
		if(b[i]>a[i])q.push(mp(b[i],i));
	}
	while(!q.empty()){
		int x=q.top().snd;
		q.pop();
		int tmp=b[x]-a[x],sum=b[(x+1)%n]+b[(x+n-1)%n];
		assert(tmp>0);
		if(tmp<sum){
			puts("-1");
			return 0;
		}
		ans+=tmp/sum;
		b[x]=a[x]+tmp%sum;
		if(b[x]>a[x])q.push(mp(b[x],x));
	}
	printf("%lld\n",ans);
	return 0;
}

#include<iostream>
using namespace std;
int main()
{
    int n,k = 0;cin >> n;
    int a[n],b[n],fixer[n];
    for(int i = 0;i < n;i++)cin >> a[i];
    for(int i = 0;i < n;i++)cin >> b[i];
    for(int i = 0;i < n;i++)fixer[i] = -1;
    long int minimum,index;
    int cnt = 0,counter = 0,found = 0,founder = 0;
    while(cnt < n)
    {
        start:
        minimum = 9999998;
        for(int i = 0;i < n;i++)
        {
            if(minimum > b[i])
            {
                minimum = b[i];
                index = i;
            }
        }
        if(minimum == 9999998)
        {
            found = 1;
            break;
        }
        int restart = a[index];
        while(a[index] < b[index])
        {
            if(index + 1 == n)
                a[index] = a[index] + a[index - 1] + a[0];
            else if(index - 1 < 0)
                a[index] = a[index] + a[index + 1] + a[n-1];
            else
                a[index] = a[index] + a[index - 1] + a[index + 1];
            counter++;
        }
        if(a[index] == b[index])
        {
            if(founder == 1)
            {
                for(int i = 0;i < n;i++)
                    {
                        if(b[i] = 9999999)b[i] = fixer[i];
                    }
            }
            b[index] = 9999998;
        }
        else
        {
            a[index] = restart;
            fixer[index] = b[index];
            b[index] = 9999999;
            founder = 1;
            goto start;
            k++;
        }
        cnt++;
    }
    if(found == 1)cout << -1;
    else cout << counter;
    return 0;
}

