ll N;
vector<ll> A, B;
void solve(){
  ll ans = 0;
  bool update = 1;
  while(update){
    update = 0;
    rep(i, N){
      if(B[i] - A[i] >= B[(i-1 + N) % N] + B[(i+1 + N) % N]){
        update = 1;
        ans += (B[i] - A[i]) / (B[(i-1 + N) % N] + B[(i+1 + N) % N]);
        B[i] -= (B[i] - A[i]) / (B[(i-1 + N) % N] + B[(i+1 + N) % N]) * (B[(i-1 + N) % N] + B[(i+1 + N) % N]);
      }
    }
  }
  bool end = 1;
  rep(i, N) if(A[i] != B[i]) end = 0;
  if(end){
    cout << ans << endl;
    return;
  }
  cout << -1 << endl;
}

int main(){
  cin >> N;
  A.resize(N), B.resize(N);
  rep(i, N) cin >> A[i];
  rep(i, N) cin >> B[i];
  solve();
}

