int n;
ll a[200005], b[200005];
void solve() {
    cin >> n;
    rep(i, n) cin >> a[i];
    rep(i, n) cin >> b[i];

    bool ok = true;
    rep(i, n) if (a[i] > b[i]) { ok = false; break; }
    if (!ok) { cout << -1 << endn; return; }

    priority_queue<pair<ll, int>> que;
    ll ans = 0;
    rep(i, n) que.emplace(b[i], i);
    while (!que.empty()) {
        auto i = que.top().second; que.pop();
        auto s = b[(i + 1) % n] + b[(n + i - 1) % n];
        bool update = false;
        while (a[i] < b[i] && b[i] > s) { update = true; b[i] -= s; ++ans; }
        if (!update) break;
        if (a[i] < b[i]) que.emplace(b[i], i);
    }

    ok = true;
    rep(i, n) if (a[i] != b[i]) { ok = false; break; }
    if (ok) cout << ans << endn;
    else cout << -1 << endn;
}

