using namespace std;

void failure () {
  cout << -1 << endl;
  exit(0);
}

const int MAX_N = 2e5 + 5;

int A [MAX_N];
int B [MAX_N];

int n;
set<pair<int, int>> diffs;

int step_back (int i) {
  diffs.erase(make_pair(B[i], i));

  int li = (i + n - 1) % n;
  int ri = (i + 1) % n;

  // remove as little as possible to have
  // B[i] < max(B[li], B[ri])
  // and B[i] >= A[i]
  int rv = B[li] + B[ri];
  int case1 = (B[i] - max(B[li], B[ri])) / rv + 1;
  int case2 = (B[i] - A[i]) / rv;
  int remc = min(case1, case2);

  if (remc == 0) failure();
  B[i] -= remc * rv;

  if (B[i] != A[i]) {
    diffs.insert(make_pair(B[i], i));
  }
  return remc;
}

int main () {
  ios::sync_with_stdio(false);

  cin >> n;

  for (int i = 0; i < n; i++) {
    cin >> A[i];
  }

  for (int i = 0; i < n; i++) {
    cin >> B[i];
  }

  for (int i = 0; i < n; i++) {
    if (B[i] < A[i]) failure();
    diffs.insert(make_pair(B[i], i));
  }

  int ans = 0;
  while (!diffs.empty()) {
    int idx = diffs.rbegin()->second;
    ans += step_back(idx);
  }

  cout << ans << endl;
}

