            int sum = b[(top - 1 + n) % n] + b[(top + 1) % n], count = (b[top] - a[top]) / sum;
            result += count;
            b[top] -= sum * count;
            if (b[top] != a[top]) {
                queue.emplace(top);
            }
        } else {
            result = -1;
            break;
        }
    }
    cout << result;
