int N;
int A[201010];
int B[201010];
//---------------------------------------------------------------------------------------------------
bool check(int i) {
	i = (i + N) % N;
	return A[i] <= B[i] - B[(i - 1 + N) % N] - B[(i + 1) % N];
}
ll solve() {
	ll ans = 0;
	queue<int> q;
	rep(i, 0, N) if (check(i)) q.push(i);
	while (!q.empty()) {
		int i = q.front(); q.pop();
		i = (i + N) % N;
		int del = B[(i - 1 + N) % N] + B[(i + 1) % N];
		int delta = B[i] - A[i];
		if (delta == 0) continue;
		if (delta < 0) return -1;

		int c = delta / del;
		ans += c;
		B[i] -= c * del;
		if (check(i - 1)) q.push(i - 1);
		if (check(i + 1)) q.push(i + 1);
	}

	bool ok = true;
	rep(i, 0, N) if (A[i] != B[i]) ok = false;
	if (ok) return ans;
	return -1;
}
//---------------------------------------------------------------------------------------------------
void _main() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	rep(i, 0, N) cin >> B[i];
	cout << solve() << endl;
}

