      cnt++;
    } else {
      s.insert(make_pair(b[i], i));
    }
  }
  constexpr int kInf = 2'000'000'000;
  int64_t ans = 0;
  while (cnt < n) {
    int x = s.rbegin()->second;
    s.erase(make_pair(b[x], x));
    int y = (x + n - 1) % n, z = (x + 1) % n;
    // cout << "y = " << y << " z = " << z << endl;
