struct item{
	long value;
	int index;
	item(long v, int i){
		value = v;
		index = i;
	}
	bool operator<(const item& item) const{
		return value < item.value;
	}
};

int main(void){
	char *buffer = new char[2000000];
	fgets(buffer, 2000000, stdin);
	const int N = atoi(buffer);

	auto a_list = new long[N];
	auto b_list = new long[N];

	fgets(buffer, 2000000, stdin);
	for(int i = 0; i < N; i ++){
		char* token = i == 0 ? strtok(buffer, " ") : strtok(0, " ");
		a_list[i] = atoi(token);
	}

	fgets(buffer, 2000000, stdin);
	for(int i = 0; i < N; i ++){
		char* token = i == 0 ? strtok(buffer, " ") : strtok(0, " ");
		b_list[i] = atoi(token);
	}

	delete buffer;

	std::priority_queue<item> queue;

	int not_matched = 0;
	for(int i = 0; i < N; i ++){
		queue.push(item(b_list[i], i));
		if(b_list[i] != a_list[i]){
			not_matched ++;
		}
	}

	int count = 0;
	while(not_matched > 0){
		auto item = queue.top();

		queue.pop();

		auto item2 = queue.top();

		auto d = (b_list[(item.index - 1 + N) % N] + b_list[(item.index + 1) % N]);
		auto n = (item.value - item2.value) / d;
		if(n == 0 || (item.value - item2.value) % d != 0){
			n += 1;
		}

		item.value -= d * n;
		if(item.value < a_list[item.index]){
			count = -1;
			break;
		}
