struct Data {
	int value;
	int position;

	Data (int a, int b) {
		value = a;
		position = b;
	}

	inline bool operator < (const Data& foo) const {
		if (value != foo.value) return value > foo.value;
		return (position < foo.position);
	}
};

inline int mod(int MD, int vl) {
	if (vl < 0) vl += MD;
	if (vl >= MD) vl -= MD;
	return vl;
}

int a[MX], b[MX];

int main() {

	int n;
	ignore = scanf("%d", &n);

	for (int i = 0; i < n; i++) {
		ignore = scanf("%d", &b[i]);
	}
	for (int i = 0; i < n; i++) {
		ignore = scanf("%d", &a[i]);
	}

	set<Data> ids; // N log N  insert here -> with set N log^2 N
	for (int i = 0; i < n; i++) {
		ids.emplace(a[i], i);
	}

	bool fail = false;
	int ans = 0;
	while (ids.empty() == false) {
		Data tmp = *ids.begin();
		ids.erase(ids.begin());

		int pos = tmp.position;
		//cout << "GOT " << a[pos] << "@" << pos << endl;
		if (a[pos] < b[pos]) {
			fail = true;
			break;
		}
		if (a[pos] == b[pos]) {
			break;
		}

		int A = a[pos];
		int B = a[mod(n, pos-1)] + a[mod(n, pos+1)];
		int C = max(a[mod(n, pos-1)], a[mod(n, pos+1)]);

		if (A <= C) {
			fail = true;
			break;
		}

		// A - X * B < C
		// find first X
		// A - C < X * B
		//
		// A - C < X
		// -----
		//   B
		int x = (A - B + (B - 1)) / B;
		int x2 = (A - b[pos] + (B - 1)) / B;
		x = min(x, x2);
		if (x == 0) {
			fail = true;
			break;
		}
		//assert(A - x * B <= B);
		//assert(A - (x-1) * B > B);
		ans += x;
		a[pos] -= x * B;
		ids.emplace(a[pos], pos);
	}

	for (int i = 0; i < n; i++) {
		if (a[i] != b[i])
			fail = true;
	}

	if (fail) {
		printf("-1\n");
	}
	else {
		printf("%d\n", ans);
	}

	return 0;
}

