template<typename T>
struct SegmentTree{
private:
    int n;
    T E;
    vector<T> node;
    inline void updatef(T& x,T& y){
        x = y;
        //x += y;
        //x = max(x,y);
        //x = min(x,y);
    }
    inline T queryf(T& x,T& y){
        //return x*y;
        //return x+y;
        return max(x,y);
        //return min(x,y);
    }

public:
    SegmentTree(int sz,T E_):E(E_){
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
    }

    SegmentTree(vector<T>& A,T E_):E(E_){
        int sz=A.size();
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
        rep(i,sz)node[i+n-1]=A[i];
        for(int i=n-2;i>=0;--i){
            node[i]=queryf(node[2*i+1], node[2*i+2]);
        }
    }
    void update(int k,T x){
        k+=n-1;
        updatef(node[k],x);
        while(k>0){
            k=(k-1)/2;
            node[k]=queryf(node[2*k+1], node[2*k+2]);
        }
    }
       //[a,b)での和を返す
    T get(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return E;
        if(a<=l&&r<=b)return node[k];
        T xl=get(a,b,2*k+1,l,(l+r)/2);
        T xr=get(a,b,2*k+2,(l+r)/2,r);
        return queryf(xl, xr);
    }
    int find(int k = 0){
        if(k>=n-1)return k-(n-1);
        if(node[2*k+1]>=node[2*k+2])return find(2*k+1);
        return find(2*k+2);
    }
};
int main(){
    int n;
    cin>>n;
    ll a[n], b[n];
    rep(i,n)cin>>a[i];
    rep(i,n)cin>>b[i];
    SegmentTree<ll> sg(n,-longinf);
    rep(i,n){
        sg.update(i,b[i]);
    }
    int cnt = 0;
    while(1){
        if(sg.get(0,n)==-longinf)break;
        int idx = sg.find();
        if(a[idx]==b[idx]){
            sg.update(idx,-longinf);
        }
        else if(a[idx]<b[idx]){
            b[idx]-=b[(idx+1)%n];
            b[idx]-=b[(idx+n-1)%n];
            if(b[idx]<a[idx]){
                cout<<-1<<endl;
                return 0;
            }
            sg.update(idx,b[idx]);
            ++cnt;
        }
        else {
            cout<<-1<<endl;
            return 0;
        }
    }
    cout<<cnt<<endl;
    return 0;
}

