int Bdec_all(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if ((Btmp[i] - A[i]) % Bnei == 0)
	{
		anstmp += (Btmp[i] - A[i]) / Bnei;
		if((Btmp[i] - A[i]) / Bnei > 0)
			anychange = 1;
		Btmp[i] = A[i];
	}
	else
	{
		anstmp += Btmp[i] / Bnei;
		if (Btmp[i] / Bnei > 0)
			anychange = 1;
		Btmp[i] %= Bnei;
	}
	return Btmp[i];
}

int Bdec(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if (Btmp[i] > A[i])
	{
		Btmp[i] -= Bnei;
		anstmp++;
	}
	return Btmp[i];
}

bool Btop(int i, vector<int> Btmp)
{
	if (Btmp[i] > (Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N]))
		return true;
	return false;
}

void DP()
{
	anychange = 0;
	while (1)
	{
		for (int i = 0; i < N; i++)
		{
			if (Btop(i, B))
			{
				B[i] = Bdec_all(i, B);
			}
		}
		if (B == A)
		{
			ansmin = min(ansmin, anstmp);
			return;
		}
		for (int i = 0; i < N; i++)
		{
			if (B[i] < A[i])
			{
				ansmin = -1;
				return;
			}
		}
		if (!anychange)
		{
			ansmin = -1;
			return;
		}
	}
	return;
}

