using namespace std;

// 0-indexed
// now node k
// child node k*2+1 and k*2+2
// parent node (k-1)/2
struct data {
  pair<int, int> a;
};
const pair<int, int> minint = {-1, -1};
data resetdata = {minint};
struct RMQ {
  // except bottom size
  int sizen;
  vector<data> dat;
  RMQ(int newn = 1, data resets = resetdata) {
    reset(newn, resets);
  }
  void reset(int newn = 1, data resets = resetdata) {
    sizen = 1;
    while(sizen < newn) sizen *= 2;
    dat.resize(2 * sizen - 1);
    for(int i = 0; i < dat.size(); ++i) dat[i] = resets;
  }
  // "go up" process
  // data[k].a = newnum
  bool update(int k, pair<int, int> newnum) {
    k += sizen - 1;
    dat[k].a = newnum;
    while(k > 0) {
      k = (k - 1) / 2;
      dat[k].a = max(dat[k * 2 + 1].a, dat[k * 2 + 2].a);
    }
    return 1;
  }
  // "go down" process
  // return min number in [a,b)
  // pick(a,b,0,0,sizen)
  pair<int, int> pick(int a, int b, int k = 0, int l = 0,
                      int r = -1) {
    if(r == -1) r = sizen;
    // [l,r)[a,b) or [a,b)[l,r)
    if(r <= a || b <= l) return minint;
    // [a,[l,r),b)
    if(a <= l && r <= b) return dat[k].a;
    // else
    pair<int, int> nowl, nowr;
    int nextlr = k * 2 + 1, med = (l + r) / 2;
    nowl = pick(a, b, nextlr, l, med);
    nowr = pick(a, b, nextlr + 1, med, r);
    return max(nowl, nowr);
  }
};

long long n;
vector<long long> a, b;

long long solve();

int main() {
  cin >> n;
  a.resize(n);
  b.resize(n);
  for(int i = 0; i < n; ++i) cin >> a[i];
  for(int i = 0; i < n; ++i) cin >> b[i];
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long cnt = 0;
  RMQ rmq(n);
  for(int i = 0; i < n; ++i) {
    rmq.update(i, {b[i] - a[i], i});
  }
  while(1) {
    pair<int, int> now = rmq.pick(0, n);
    if(now.first == 0) break;
    ++cnt;
    b[now.second] -= b[(now.second + 1) % n];
    b[now.second] -= b[(now.second - 1 + n) % n];
    if(b[now.second] - a[now.second] < 0) return -1;
    rmq.update(now.second,
               {b[now.second] - a[now.second], now.second});
  }
  for(int i = 0; i < n; ++i)
    if(a[i] != b[i]) return -1;
  return cnt;
}

