        //dump(v);
        //dump(nextv);
        cnt += times;
        if (b[index] < a[index]) {
            cout << -1 << endl;
            return;
        }
        if (b[index] == a[index]) ++ok;
        q.emplace(b[index], index);
    }
    REP(i,0,n) if (a[i] != b[i]) {
        cout << -1 << endl;
        return;
    }
    cout << cnt << endl;
}

