    assert(val==pq.top().first);
    pq.pop();
    int maxi = max(b[(ind+n-1)%n], b[(ind+1)%n]);
    maxi = max(maxi,a[ind]);
    int g = b[(ind+n-1)%n] + b[(ind+1)%n];
    int diff = val - maxi;
    if(b[ind]-g<a[ind]) {
      continue;
    }
    long long add = max(1,diff/g);
    long long tmp = b[ind] - add*g;
    if(tmp<a[ind]) {
      break;
    }
    b[ind] -= g*add;
    ret += add;
    pq.push(make_pair(b[ind],ind));
  }
  for(int i=0;i<n;++i) {
    if(a[i]!=b[i]) {
      ret = -1;
      break;
    }
  }
  printf("%d\n", ret);
}

