int getPrev(int x){
    return (x-1+N)%N;
}
int getNext(int x){
    return (x+1)%N;
}
set<pr> tmp;
ll cnt=0;
int main(void){
    cin >> N;
    for(int i=0;i<N;i++){
        cin >> A[i];
    }

    for(int i=0;i<N;i++){
        cin >> B[i];
        if (B[i] < A[i]){
            cout << -1 << endl;
             return 0;
        }
        if (B[i]!=A[i]) tmp.insert({B[i], i});
    }
    int lastId = N+1;
    ll lastVal = 2e9+1;
    ll op = 0;
    while(tmp.size()>0){
        op++;
        if (op>1e7){
            cout << -1 << endl;
            return 0;
        }
        auto it = tmp.end();
        it--;
        int id = it->second;

        ll val = it->first;
        if (id == lastId && val == lastVal){
            cout << -1 << endl;
            return 0;
        }
        lastId = id;
        lastVal = val;
        auto previt = tmp.lower_bound({val,id});
        ll nxtval = A[id];
        if (previt!=tmp.begin()){
            previt--;
            nxtval =max(previt->first, nxtval);
        }
        tmp.erase(it);
        int prev = getPrev(id);
        int nxt = getNext(id);
        ll incre = (B[id]-nxtval)/(B[prev]+B[nxt]);
        B[id] = (B[id]-nxtval)%(B[prev]+B[nxt]) + nxtval;

        if (B[id] > nxtval){
            B[id] -= (B[prev] + B[nxt]);
            incre++;
        }
        if (incre==0){
            B[id] -= (B[prev] + B[nxt]);
            incre++;
        }
        cnt += incre;
        if (B[id] < A[id]){
            cout << -1 << endl;
            return 0;
        }
        if (B[id] > A[id]){
            tmp.insert({B[id], id});
        }
    }
    cout << cnt << endl;
    return 0;
}

