    int s = b[(p + 1) % n] + b[(p + n - 1) % n];
    if (b[p] < b[(p + 1) % n] + b[(p + n - 1) % n]) {
      puts("-1");
      return 0;
    }
    if (a[p] >= s) {
      if ((b[p] - a[p]) % s == 0) {
        b[p] = a[p];
        ans += (b[p] - a[p]) / s;
        continue;
      } else {
        puts("-1");
        return 0;
      }
    } else {
      ans += b[p] / s;
      b[p] %= s;
    }
    if (b[p] == 0) {
      puts("-1");
      return 0;
    }
    q.emplace(b[p], p);
  }
  printf("%lld\n", ans);
