using namespace std;
const int maxn=2e5+5;

priority_queue<pair<int,int> >pq;

int n;
int a[maxn],b[maxn];
int ans=0;

inline int getpos(const int &x){if(x==n+1)return 1;if(x==0)return n;return x;}
void No(){cout<<"-1\n";exit(0);}

int main()
{
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);

//	freopen("data.in","r",stdin);

	cin>>n;
	for(int i=1;i<=n;i++)cin>>a[i];
	for(int i=1;i<=n;i++)cin>>b[i];
	for(int i=1;i<=n;i++)
	{
		pq.push(make_pair(b[i],i));
	}

	while(!pq.empty())
	{
		int p=pq.top().second;pq.pop();
		int minu=b[getpos(p-1)]+b[getpos(p+1)];
		int k=(b[p]-a[p])/minu;
		if((b[p]-a[p])%minu==0)
		{
			ans+=k;
			b[p]=a[p];
			continue;
		}
		if(minu>=b[p])No();
		if(k==0)k++;
		ans+=k;
		b[p]%=minu;pq.push(make_pair(b[p],p));
		if(b[p]<a[p])No();
	}
	cout<<ans<<'\n';
//	cerr<<"loopcount:"<<lc<<'\n';
	return 0;
}

