int N;
vector<int>A, B;

int main() {
	cin >> N;
	auto L = [&](int i) {
		return (i + N - 1) % N;
	};
	auto R = [&](int i) {
		return (i + 1) % N;
	};
	for (int i = 0; i < N; ++i) {
		int tmp; cin >> tmp;
		B.push_back(tmp);
	}
	for (int i = 0; i < N; ++i) {
		int tmp; cin >> tmp;
		A.push_back(tmp);
	}
	set<pair<int, int>>que;
	map<int, int>val;
	auto seal = [&](int i) {
		if (que.count({ val[i],i })) {
			que.erase(que.find({ val[i],i }));
		}
		int An = A[i] % (A[L(i)] + A[R(i)]);
		if (An == A[i])return;
		que.insert({ An - B[i],i });
		val[i] = An - B[i];
	};
	for (int i = 0; i < N; ++i) {
		seal(i);
	}
	LL ans = 0;
	while (!que.empty()) {
		auto q = *que.begin();
		int i = q.second;
		ans += A[i] / (A[L(i)] + A[R(i)]);
		A[i] = q.first + B[i];
		/*for (int i = 0; i < N; ++i) {
			cout << A[i] << " ";
		}
		cout << endl;//*/
		seal(i);
		seal(L(i));
		seal(R(i));
	}
	for (int i = 0; i < N; ++i) {
		if (A[i] != B[i]) {
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

