const int N=2e5+5;

#define L(x) (x==1?n:x-1)
#define R(x) (x==n?1:x+1)

set< pair<int,int> > s;

int n,a[N],b[N];

void Wrong() {
	puts("-1");
	exit(0);
}

int main() {
	n=read();
	fo(i,1,n) a[i]=read();
	fo(i,1,n) b[i]=read();
	fo(i,1,n) s.insert(make_pair(-b[i],i));
	int ans=0;
	while (!s.empty()) {
		pair<int,int> tmp=*s.begin();s.erase(s.begin());
		int x=tmp.second,cnt=b[L(x)]+b[R(x)];
