			if (a[x]!=b[x]) Wrong();
			continue;
		}
		if (b[x]<a[x]) Wrong();
		if (a[x]%cnt==b[x]%cnt) ans+=(b[x]-a[x])/cnt,b[x]=a[x];
		else {
			ans+=b[x]/cnt;b[x]%=cnt;
			s.insert(make_pair(-b[x],x));
		}
	}
	printf("%d\n",ans);
