    // REP(i, N) A[i] = 1, B[i] = rand_int() % 1000000000 + 1;
    priority_queue<plint> pq;
    REP(i, N)
    {
        if (A[i] > B[i]) NO();
        if (B[i] > A[i]) pq.emplace(B[i], i);
    }

    int ret = 0;
    while (!pq.empty())
    {
        auto pa = pq.top();
        pq.pop();
        int i = pa.second;
        lint diff = pa.first - A[i];

        if (!pq.empty()) diff -= pq.top().first;

        lint dec = B[(i + 1) % N] + B[(i - 1 + N) % N];
        lint times = diff / dec;
        mmax(times, 1LL);

        B[i] = B[i] - dec * times;
        if (B[i] < A[i]) NO();
        if (B[i] > A[i]) pq.emplace(B[i], i);
        ret += times;
    }
    cout << (B == A ? ret : -1) << endl;
}

