        ll count = max(1LL, min(b[x] - a[x], b[x] - (b[ba] + b[ne])) / sum_next);
        b[x] -= sum_next * count;
        ret += count;
        if (b[x] < a[x])break;
        if (b[x] == a[x])continue;
        que.push({b[x], x});
    }

    bool flag = true;
    for (int i = 0; i < n; i++) {
        if (a[i] != b[i])flag = false;
    }

    cout << (flag ? ret : -1) << endl;
    return 0;
}

