void solve(void)
{
  ui N{}; std::cin >> N;
  vector<ll> A(N), B(N);
  for(auto& a : A) cin >> a;
  for(auto& b : B) cin >> b;

  typedef pair<ll, ui> Pair;
  std::priority_queue<Pair> queue;
  for(ui i = 0; i < N; ++i)
  {
    if(B[i] > A[i])
    {
      queue.push(Pair{B[i], i});
    }
    else if(B[i] < A[i])
    {
      cout << "-1" << '\n';
      return;
    }
  }

  ll ans{};
  while(!queue.empty())
  {
    auto curr = queue.top().second;
    queue.pop();

    auto sum = B[(curr + N - 1) % N] + B[(curr + 1) % N];

    if((A[curr] - B[curr]) % sum == 0)
    {
      ans += (B[curr] - A[curr]) / sum;
      B[curr] = A[curr];
      continue;
    }
    if(B[curr] <= sum)
    {
      ans = -1;
      break;
    }

    ans += B[curr] / sum;
    B[curr] %= sum;
    if(B[curr] < A[curr])
    {
      ans = -1;
      break;
    }
    queue.push(Pair{B[curr], curr});
  }

  cout << ans << '\n';
  return;
}

