int index_max(int a[],int num){
	int max=a[0];
	int index=0;
	for(int i=1;i<num;i++){
		if(max<a[i]){
			max=a[i];
			index=i;
		}
	}
	return index;
}

int reverse(int a[],int p,int num){
	if(p==0){
		return a[0]-a[num-1]-a[1];
	}else if(p==num-1){
		return a[num-1]-a[num-2]-a[0];
	}else{
		return a[p]-a[p-1]-a[p+1];
	}
}

