const ll B_I_MAX = 1e9;

ll N;
vector<ll> A;
vector<ll> B;

void solve() {
	scanf("%lld", &N);
	A.assign(N, 0);
	rep(i, N) scanf("%lld", &A[i]);
	B.assign(N, 0);
	rep(i, N) scanf("%lld", &B[i]);

	priority_queue<pair<ll,ll>> q;
	rep(i,N)q.push({B[i],i});

	ll ans = 0;
	vector<pair<ll,ll>> v;
	while(!q.empty()){
		pair<ll,ll> p=q.top();q.pop();
		ll r=p.second+1;
		if(r>=N)r-=N;
		ll l=p.second-1;
		if(l<0)l+=N;
		if(B[p.second]-A[p.second] >= B[l]+B[r]){
			B[p.second]-=B[l]+B[r];
			if(B[p.second]>A[p.second]){
				q.push({B[p.second],p.second});
			}
			rep(i,v.size()){q.push(v[i]);}
			v.clear();
			ans++;
		}else{
			v.push_back(p);
		}

	}


	if(v.size()==0)printf("%lld\n", ans);
	else printf("%d\n", -1);
}

