            ll dif = B[idx]-A[idx], div = B[l]+B[r];
            if(dif%div != 0){
                cout << -1 << endstr; return 0;
            }
            else{
                cnt += dif/div; cout << cnt << endstr; return 0;
            }
        }
        else{
            auto nmx = next(s.begin())->ff;
            if(A[idx] >= nmx){
                ll dif = B[idx]-A[idx], div = B[l]+B[r];
                if(dif%div != 0){
                    cout << -1 << endstr; return 0;
                }
                else{
                    cnt += dif/div; B[idx] = A[idx];
                    s.erase(s.begin());
                }
            }
            else{
                ll dif = B[idx]-(B[l]+B[r]), div = B[l]+B[r];
                ll add = (dif+div-1)/div;
                cnt += add;
                B[idx] -= add*div;
                if(B[idx] < A[idx]){
                    cout << -1 << endstr; return 0;
                }
                s.erase(s.begin());
                if(B[idx] != A[idx]){
                    s.insert({B[idx], idx});
                }
            }
        }
    }
    cout << -1 << endstr;
    return 0;
}

