typedef pair<ll,ll> P;

int main(){
  ll n; cin >> n;
  vector<ll> a(n), b(n);
  ll ans = 0;
  priority_queue<P, vector<P>, less<P>> pq;
  REP(i,n) cin >> a[i];
  REP(i,n){
    cin >> b[i];
    pq.push(make_pair(b[i],i));
  }

  while(!pq.empty()){
    P p = pq.top();
    pq.pop();
    ll i = p.second;
    ll bunbo = b[(n+i+1)%n]+b[(i-1+n)%n];
    ll diff;
    diff = (b[i]-max(a[i],bunbo)+bunbo-1)/bunbo;
    if(diff == 0) no();
    ans += diff;
    ll t = b[i]-diff*bunbo;
    b[i] = t;
    if(t>a[i]){
      pq.push({t,i});
    }
  }
  cout << ans << endl;
}

