int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	int N;
	cin >> N;
	vector<long long> A(N), B(N);
	for (int i = 0; i < N; ++i) cin >> A[i];
	for (int i = 0; i < N; ++i) cin >> B[i];
	bool ok = true;
	long long ans = 0;
	while (A != B) {
		vector<long long> preb = B;
		for (int i = 0; i < N; ++i) {
			if (B[(i + 1) % N] < B[i] && B[(i + N - 1) % N] < B[i]) {
				long long delta = (B[(i + 1) % N] + B[(i + N - 1) % N]);
				if (B[i] < delta) {
					ok = false;
					break;
				}
				ans += B[i] / delta;
				B[i] %= delta;
				if (B[i] < A[i]) {
					ok = false;
					break;
				}
			}
		}
		if (preb == B) ok = false;
		if (!ok) break;
	}
	cout << (ok ? ans : -1) << endl;
	return 0;
}

