int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for (auto &a : A) cin >> a;
    for (auto &b : B) cin >> b;
    int ans = 0;
    stack<int> S;
    auto check = [&](int i) {
        int& prev = B[(i-1+N)%N];
        int& curr = B[i];
        int& next = B[(i+1)%N];
        if (curr > A[i] && prev < curr && curr > next) {
            S.push(i);
        }
    };
    for (int i = 0; i < N; i++) {
        check(i);
    }
    while (!S.empty()) {
        int i = S.top();
        S.pop();
        int& prev = B[(i-1+N)%N];
        int& curr = B[i];
        int& next = B[(i+1)%N];
        int k = divup(curr - max({prev, next, A[i]}), prev + next);
        curr -= k * (prev + next);
        ans += k;
        if (curr < A[i]) {
            ans = -1;
            break;
        }
        check((i+1)%N);
        check(i);
        check((i-1+N)%N);
    }
    if (A == B) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
    return 0;
}

