ll solve(int N, vi& a, vi& b) {
    priority_queue<ii> pq;
    rep(i,N){
        if (b[i] < a[i]) return -1;
        int left = b[(i-1+N)%N], right = b[(i+1)%N];
        if (b[i] == left) {
            if (b[i] == a[i] && b[(i-1+N)%N] == a[(i-1+N)%N]) ;
            else return -1;
        }
        if (b[i] == right) {
            if (b[i] == a[i] && b[(i+1)%N] == a[(i+1)%N]) ;
            else return -1;
        }
    }
    rep(i,N){
        if (b[i] == a[i]) continue;
        pq.emplace(b[i], i);
    }

    ll ans = 0;
    while (!pq.empty()){
        int val=pq.top().first, i=pq.top().second; pq.pop();
        assert(b[i] == val);

        int left=b[(i-1+N)%N], right=b[(i+1)%N], w = left + right;
        if (left > val) return -1;
        if (left == val) {
            if (a[(i-1+N)%N] != left) return -1;
        }
        if (right > val) return -1;
        if (right == val) {
            if (a[(i+1)%N] != right) return -1;
        }

        int mi = min(left, right), mx = max(left, right);
        int target = mx-1; if (target == mi) --target;

        if (a[i] > target) {
            target = a[i];
        }
        int over = val - target;
        int step = (over + w-1) / w;
        int ws = w * step;

        if (val - ws < a[i]) return -1;
        b[i] = val - ws;
        ans += step;
        if (b[i] > a[i]) pq.emplace(b[i], i);
    }

    rep(i,N) if (b[i] != a[i]) return -1;

    return ans;
}

