void rec(ll depth, vector<int> &state, queue<int> &checkIndex) {
  dump(state, depth);
  if(state == A) {
    cout << depth << endl;
    exit(0);
  }
  if(state.size() == 0) {
    cout << -1 << endl;
    exit(0);
  }
  auto tmp = vector<int>(N);
  while(!checkIndex.empty()) {
    int i = checkIndex.front();
    checkIndex.pop();
    int prev = i - 1;
    int next = i + 1;
    if(i == 0) {
      prev = N - 1;
    }
    if(i == N - 1) {
      next = 0;
    }
    if(state[prev] + state[next] < state[i]) {
      int add = state[i] / (state[prev] + state[next]);
      state[i] = state[i] % (state[prev] + state[next]);
      checkIndex.push(i);
      checkIndex.push(prev);
      checkIndex.push(next);
      rec(depth + add, state, checkIndex);
    }
  }
  cout << -1 << endl;
  exit(0);
}

