	ll x=0,w=1; char c=getchar();
	while(c<'0'||c>'9') {if(c=='-') w=-1; c=getchar();}
	while(c<='9'&&c>='0') {x=(x<<1)+(x<<3)+c-'0'; c=getchar();}
	return w==1?x:-x;
}

ll n,a[maxn],b[maxn],ans;

inline int w(int x)
{
	if(x==0) return n; if(x==n+1) return 1; return x;
}

int main()
{
	n=read();
	for(int i=1;i<=n;i++) a[i]=read();
	for(int i=1;i<=n;i++) b[i]=read();
	//for(int i=1;i<=n;i++) if(a[i]>b[i]) return cout<<"-1",0;
	int f=0;
	while(1)
	{
		f=0;
		for(int i=1;i<=n;i++)
		{
			if(b[i]>b[w(i+1)]+b[w(i-1)]&&b[i]>a[i])
			{
				if((b[i]-a[i])%(b[w(i+1)]+b[w(i-1)])==0)
				{
					ll t=(b[i]-a[i])/(b[w(i+1)]+b[w(i-1)]);
					ans+=t; b[i]=a[i]; f=1;
				}
				else return cout<<"-1",0;
			}
		}
		if(f==0) break;
	}
	for(int i=1;i<=n;i++) if(a[i]!=b[i]) {puts("-1"); return 0;}
	cout<<ans<<endl;
	return 0;
}

