int64_t solve(const vector<int64_t> & a,
          vector<int64_t> & b) {
  const int64_t acc = accumulate(a.cbegin(), a.cend(), 0LL);
  int64_t val = accumulate(b.cbegin(), b.cend(), 0LL);
  if (val < acc) {
    return -1;
  }
  const auto comp = [&b](const size_t i, const size_t j) {
    return b[i] < b[j];
  };
  priority_queue<size_t, vector<size_t>, decltype(comp)> heap(comp);
  for (size_t i = 0; i < a.size(); ++i) {
    if (b[i] < a[i]) {
      return -1;
    }
    if (b[i] > a[i]) {
      heap.push(i);
    }
  }

  int64_t out = 0;
  while (acc < val && !heap.empty()) {
    const auto i = heap.top();
    const auto r = (i == 0 ? b.back() : b[i - 1])
      + (i + 1 == b.size() ? b[0] : b[i + 1]);

    heap.pop();
    const int64_t k = (b[i] - a[i]) / r;
    if (k == 0) {
      return -1;
    }

    if (heap.empty()) {
      out += k;
      b[i] -= k * r;
      val -= k * r;
    } else {
      const auto j = heap.top();
      const int64_t t = (b[i] - b[j]) / r + 1;
      out += min(k, t);
      b[i] -= min(k, t) * r;
      val -= min(k, t) * r;
    }

    if (b[i] > a[i]) {
      heap.push(i);
    }
  }

  return acc == val ? out : (int64_t)-1;
}

int main(const int /*argc*/, char ** /*argv*/) {
  ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);

  size_t n;
  cin >> n;
  vector<int64_t> a(n), b(n);
  cin >> a >> b;
  cout << solve(a, b);

  return EXIT_SUCCESS;
}

