int main() {
	cin >> N;
	vector< int > A(N);
	vector< int > B(N);
	rep(i, N) cin >> A[i];
	rep(i, N) cin >> B[i];
	priority_queue< pii > q;
	rep(i, N) q.push(make_pair(B[i] - A[i], i));
	int ans = 0;
	while (!q.empty()) {
		pii p = q.top();
		q.pop();
		int i = p.second;
		int i1 = ((p.second - 1) % N + N) % N;
		int i2 = (p.second + 1) % N;
		int tmp = p.first / (B[i1] + B[i2]);
		//cout << i << " " << B[i1] << endl;
		if (tmp == 0) {
			ans = -1;
			break;
		}
		ans += tmp;
		B[i] -= tmp * (B[i1] + B[i2]);
		if (B[i] != A[i]) {
			q.push(make_pair(B[i] - A[i], i));
		}
	}
	cout << ans << endl;
	return 0;
}

