struct num{
    ll idx;
    ll val;
    bool operator<(const num &o) const
    {
        return val < o.val;
    }
};


int main(void){
    ll n; cin >> n;
    vector <ll> as;
    REP(i, n){
        ll a; cin >> a; as.push_back(a);
    }
    priority_queue <num> bs_q;
    vector <ll> bs;
    REP(i, n){
        ll b; cin >> b;
        num nu = {i, b};
        bs_q.push({nu});
        bs.push_back(b);
    }
    ll ans = 0;
    ll cnt = 0;
    while(!bs_q.empty()){
        cnt ++;
        num top = bs_q.top();
        bs_q.pop();
        ll idx = top.idx;
        if (as[idx] == top.val) {
            continue;
        }
        ll diff = bs[(idx+n-1)%n] + bs[(idx+n+1)%n];
        ll diff2 = min(top.val - max(bs[(idx+n-1)%n], bs[(idx+n+1)%n]), top.val - as[idx]);
        ll sub_cnt = max(ll(1), (diff2/diff));
        top.val -=  sub_cnt * diff;
        if (as[idx] > top.val){
            cout << -1 << endl;
            return 0;
        }
        bs[idx] = top.val;
        ans += sub_cnt;
        if (as[idx] == top.val) {
            continue;
        }
        bs_q.push(top);
    }
    cout << ans << endl;
    return 0;
}

