class Solve {
public:
    int N;
    vector<ll> A;
    vector<ll> B;

    void solve() {
        cin >> N;
        A.resize(N);
        B.resize(N);
        for (int i = 0; i < N; ++i) {
            cin >> A[i];
        }
        for (int i = 0; i < N; ++i) {
            cin >> B[i];
        }

        ll cnt = 0;
        int lp = 0;
        bool rv = false;
        while (true) {
            lp++;
            bool del = false; // 消せるものがあるか
            bool ok = true; // クリア条件満たしているか
            for (int j = 0; j < N; ++j) {
                int i = j;
                if (rv) {
                    i = N - 1 - j;
                }
                if (A[i] != B[i]) {
                    ok = false;
                    if (A[i] > B[i]) {
                        cout << -1 << endl;
                        return;
                    } else {
                        int a = i;
                        int l = (a - 1 + N) % N;
                        int r = (a + 1) % N;
                        if (B[i] - B[l] - B[r] >= A[i]) {
                            ll div = (B[i] - A[i]) / (B[l] + B[r]);
                            B[i] -= div * (B[l] + B[r]);
                            cnt += div;
                            if (div > 0) del = true;
                        }
                    }
                }
            }
            rv = !rv;
            if (ok) {
                cout << cnt << endl;
                cerr << lp << endl;
                return;
            }
            if (!del) {
                cout << -1 << endl;
                return;
            }
        }


//        jikken();

    }

    void jikken() {
        while (true) {
            for (int i = 0; i < N; ++i) {
                cout << B[i] << " ";
            }
            cout << endl;

            int a;
            cin >> a;
            if (a == -1) break;
            int l = (a - 1 + N) % N;
            int r = (a + 1) % N;
            B[a] -= (B[l] + B[r]);
        }
    }

};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

