using namespace std;

struct node{
	int val,idx;
	node(int val,int idx):val(val),idx(idx){}
	friend bool operator < (node a,node b){
		return a.val < b.val;
	}
};

int n;
int a[200010],b[200010];

int pre(const int i) {return (i+n-1)%n;}
int pot(const int i) {return (i+n+1)%n;}
bool check(const int i){return (b[i] > a[i] && b[i] - a[i] >= b[pre(i)] + b[pot(i)]);}
priority_queue <node> q;

int main()
{
	long long ans = 0ll;
	cin >> n;
	for(int i = 0;i < n;i++) cin >> a[i];
	for(int i = 0;i < n;i++){
		cin >> b[i];
		if(a[i] > b[i]){
			cout << -1 << endl;
			return 0;
		}
	}

	for(int i = 0;i < n;i++) {if(check(i)) q.push(node(b[i],i));}

	while(!q.empty()){
		node temp = q.top();q.pop();
		int dis = temp.val - a[temp.idx];
		int dis2 = b[pre(temp.idx)] + b[pot(temp.idx)];
		ans += dis/dis2;
		b[temp.idx] = a[temp.idx] + dis%dis2;
		if(check(pre(temp.idx))) q.push(node(b[pre(temp.idx)],pre(temp.idx)));
		if(check(pot(temp.idx))) q.push(node(b[pot(temp.idx)],pot(temp.idx)));
	}

	for(int i = 0;i < n;i++){
		if(a[i] != b[i]){
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

