            B[id] -= (B[prev] + B[nxt]);
            incre++;
        }
        if (incre==0){
            B[id] -= (B[prev] + B[nxt]);
            incre++;
        }
        cnt += incre;
        if (B[id] < A[id]){
            cout << -1 << endl;
            return 0;
        }
        if (B[id] > A[id]){
            tmp.insert({B[id], id});
        }
    }
    cout << cnt << endl;
    return 0;
}

