int solve(int n, vector<int> a, vector<int> b) {
    set<pair<int, int>> st;
    for (int i = 0; i < n; i++) st.insert({b[i], i});

    int ans = 0;
    while (!st.empty()) {
        auto it = st.rbegin();
        int i = it->second;
        st.erase(*it);
        if (b[i] == a[i]) continue;
        else if (b[i] < a[i]) return -1;
        else if (b[i] > a[i]) {
            int t = b[(i - 1 + n) % n] + b[(i + 1) % n];
            if (b[i] <= t) return -1;
            b[i] %= t;
            if (a[i] > b[i] && a[i] % t == b[i] % t) {
                b[i] = a[i];
            }
            st.insert({b[i], i});
            ans++;
        } else assert(0);
    }
    return ans;
}

