    vector<int> A(N), B(N);
    for (auto &&a : A) { is >> a; } // end a
    for (auto &&b : B) { is >> b; } // end b

    segB = segtree(N);
    for (int i = 0; i < N; ++i) {
        segB.update(i, B[i]);
    } // end i


    ll K = count(A, B, 0, N);

    cout << K << endl;

}

