#include <cstdio>
#include <queue>
#include <vector>
const int MAXN = 2e5+5;
int A[MAXN];
int B[MAXN];
int N;

struct CMP {
  bool operator () (int lhs, int rhs) const {
    return B[lhs] < B[rhs];
  }
};

bool local_max(int i) {
    int u = (i + N - 1) % N;
    int v = (i + 1) % N;
    return (B[i] > B[u] + B[v]);
}

int solve() {
  std::priority_queue<int, std::vector<int>, CMP> pq;
  for (int i = 0; i < N; ++i) {
    if (local_max(i)) pq.push(i);
  }
  int ret = 0;
  while (!pq.empty()) {
    int cur = pq.top();
    pq.pop();
    if (B[cur] < A[cur]) break;
    if (!local_max(cur)) continue;

    int u = (cur + N - 1) % N;
    int v = (cur + 1) % N;
    int sum = B[u] + B[v];
    int step = (B[cur] - A[cur]) / sum;
    B[cur] -= step * sum;
    ret += step;

    if (local_max(u)) pq.push(u);
    if (local_max(v)) pq.push(v);
  }
  for (int i = 0; i < N; ++i) {
    if (B[i] != A[i]) return -1;
  }
  return ret;
}

int main() {
  scanf("%d", &N);
  for (int i = 0; i < N; ++i) scanf("%d", &A[i]);
  for (int i = 0; i < N; ++i) scanf("%d", &B[i]);
  printf("%d\n", solve());
  return 0;
}

