			int v = posEnd;
			do {
				auto prev = val(v).predecessor;
				assert(prev != -1);
				int weight = std::numeric_limits<int>::min();
				for (auto& edge : vertex[prev].edges) {
					if (edge.next == v) {
						weight = edge.w;
						break;
					}
				}
				assert(weight != std::numeric_limits<int>::min());
				if (val(v).dis > val(prev).dis + weight) {
					return false;
				}
				v = prev;
			} while (v != posStart);
		}
		return true;
	}
	pair<int, int> radiusImpl(int pos) {
