void proc() {
	LOAD(int, N);
	LOADVEC(int, A, N);
	LOADVEC(int, B, N);
	auto a = [&A, N](int id) -> int& {
		return A[mod(id, N)];
	};
	auto b = [&B, N](int id) -> int& {
		return B[mod(id, N)];
	};
	auto big = [&](int id) -> bool {
		return b(id) > b(id - 1) + b(id + 1);
	};
	//
	std::unordered_set<int> s;
	std::unordered_set<int> ng;
	for (int i = 0; i < N; ++i) {
		if (big(i)) {
			s.insert(i);
		}
		if (a(i) != b(i)) {
			ng.insert(i);
		}
	}
	int count = 0;
	while (!s.empty()) {
		int id = *s.begin();
		int sum = b(id - 1) + b(id + 1);
		int m = (b(id) - a(id)) / sum;
		count += m;
		b(id) -= sum * m;
		s.erase(id);
		if (a(id) == b(id)) {
			ng.erase(id);
		}
		if (big(id - 1)) {
			s.insert(mod(id - 1, N));
		}
		if (big(id + 1)) {
			s.insert(mod(id + 1, N));
		}
		if (ng.empty()) {
			cout << count << endl;
			return;
		}
	}
	cout << -1 << endl;
}

