int n;
int p(int i) {
	return (i+n)%n;
}

bool solve() {
	cin >> n;
	vi A(n), B(n);
	REP (i,n) cin >> A[i];
	REP (i,n) cin >> B[i];
	priority_queue<pair<int,int>> pq;
	REP (i,n) {
		int dif = B[i] - A[i];
		pq.push({dif,i});
	}
	int ans = 0;
	while (!pq.empty()) {
		pair<int,int> nxt = pq.top(); pq.pop();
		// cout << nxt.F << " " << nxt.S << endl;
		if (nxt.F <= 0) break;

		int minus = p(nxt.S-1), plus = p(nxt.S+1);
		int left = B[minus]-A[minus];
		int rigt = B[plus]-A[plus];
		int rem = max(left,rigt);
		int dim = nxt.F-rem; //cout << dim << " ";
		dim /= (B[minus]+B[plus]); chmax(dim,1ll);
		// cout << nxt.S << " " << dim << endl;

		// cout << B[nxt.S] << " ";
		B[nxt.S] -= dim*(B[p(nxt.S-1)] + B[p(nxt.S+1)]);
		// cout << nxt.S << " " << B[nxt.S] <<  endl;
		ans+=dim;
		if (B[nxt.S]-A[nxt.S] < 0) break;
		pq.push({B[nxt.S]-A[nxt.S],nxt.S});
	}
	bool flag = 1;
	REP (i,n) if (A[i] != B[i]) flag = 0;
	if (!flag) cout << -1 << endl;
	else cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

