    rep(i, n) cin >> b[i];

    queue<int> que;
    rep(i, n){
        if(b[i] > a[i] && b[i]>b[id(i-1)]+b[id(i+1)]){
            que.push(i);
        }
    }

    lint res = 0;
    while(!que.empty()){
        int i = que.front(); que.pop();
        while(b[i] > a[i] && b[i] > b[id(i+1)]+b[id(i-1)]){
            res++;
            b[i] -= b[id(i+1)]+b[id(i-1)];
