	ll j = (i + n - 1);
	ll val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		cnt += dov(b, j);
	}

	j = (i + 1);
	val = b[at(j - 1)] + b[at(j + 1)];
	if (val < b[at(j)]) {
		if (val == 0) { return 0; }
		cnt += b[at(j)] / val;
		b[at(j)] %= val;
		cnt += dov(b, j);
	}
	return cnt;
}

