      t_cnt++;
    }
    else{
      P add = {B[i],i};
      PQ.push(add);
    }
  }

  P d = {0,-1};
  PQ.push(d);

  while(PQ.size()){
    P p = PQ.top();
    PQ.pop();
    if(p.second == -1){
      break;
    }
    int64_t a, b, c;
    if(p.second == 0){
      a = B[N-1] + B[1];
      b = p.second;
      c = max({A[b], B[N-1], B[1]});
    }
    else if(p.second == N-1){
      a = B[N-2] + B[0];
      b = p.second;
      c = max({A[b], B[N-2], B[0]});
    }
    else{
      a =  B[p.second + 1] + B[p.second - 1];
      b = p.second;
      c = max({A[b], B[b+1], B[b-1]});
    }
    int64_t num =  (c+a-1)/a;
