             return 0;
        }
        if (B[i]!=A[i]) tmp.insert({B[i], i});
    }
    int lastId = N+1;
    ll lastVal = 2e9+1;
    while(tmp.size()>0){
        auto it = tmp.end();
        it--;
        int id = it->second;

        ll val = it->first;
