int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;

	priority_queue<pair<int, int> > que;
	vector<int> a(n);
	vector<int> b(n);
	for(int i=0;i<n;i++){
		cin >> a[i];
	}
	for(int i=0;i<n;i++){
		cin >> b[i];
		if(b[i] > a[i])
			que.push(make_pair(b[i], i));
	}

	unsigned long long cnt = 0;
	while(!que.empty()){
		auto p = que.top(); que.pop();

		int i = p.second;
		int l = b[(i-1+n) % n], r = b[(i+1+n) % n];
		unsigned long long target = max(a[i], max(l, r));
		unsigned long long mod = l+r;
		int num = (p.first - target + mod - 1)/mod;
		int x = p.first - num*mod;
		cnt+=num;
		b[i] = x;

		if(p.first == a[p.second]){
			continue;
		}else if(p.first < a[p.second]){
			break;
		}
		que.push(make_pair(x, i));
	}

	bool ans = true;
	for(int i=0;i<n;i++){
		if(a[i] != b[i]){
			ans = false;
			break;
		}
	}
	if(ans){
		cout << cnt << endl;
	}else{
		cout << -1 << endl;
	}
	return 0;
}

