    priority_queue<int> pque, pquea;

    for (int i = 0; i < N; i++){
        cin >> A[i];
        pquea.push(A[i]);
    }
    for (int i = 0; i < N; i++){
        cin >> B[i];
        dict[B[i]] = i;
        pque.push(B[i]);
    }
    while (1){
        int b = pque.top();
        pque.pop();

        int i = dict[b];
        int a = B[(N + i - 1)%N];
        int c = B[(i + 1)%N];

