int N;
int A[200010], B[200010];

void _main() {
    cin >> N;
    REP(i, N) cin >> A[i];
    REP(i, N) cin >> B[i];
    int cnt = 0;
    priority_queue<pii> q;
    REP(i, N) {
        q.emplace(B[i], i);
    }
    while (!q.empty()) {
        int v, p;
        tie(v, p) = q.top();
        q.pop();
        if (B[p] <= A[p]) continue;
        int sum = B[(p + N - 1) % N] + B[(p + 1) % N];
        if (sum > 0 && B[p] > sum) {
            int k = (B[p] - A[p]) / sum;
            cnt += k;
            B[p] -= k * sum;
            q.emplace(B[p], p);
        }
    }
    REP(i, N) {
        if (A[i] != B[i]) {
            cout << -1 << endl;
            return;
        }
    }
    cout << cnt << endl;
}

