const int M=2e5+10;
priority_queue<pair<int,int> > q;
int L[M], R[M],a[M],b[M];
int main(){
	int n;
	n=read();
	F(i,1,n) L[i]=i-1,R[i]=i+1,a[i]=read();
	L[1]=n; R[n]=1;
	int ok=0;
	F(i,1,n){
		b[i]=read();
		if (b[i]==a[i]) ok++;
		else q.push({b[i],i});
	}
	int step=0;
	while (ok<n){
		int x=q.top().second; q.pop();
//		cout<<x<<" ";
		int g=b[x]/(b[L[x]]+b[R[x]]);
		int r=b[x]%(b[L[x]]+b[R[x]]);
		if (a[x]>r && (a[x]-r)%((b[L[x]]+b[R[x]]))==0 && a[L[x]]==b[L[x]] && a[R[x]]==b[R[x]]){
			g-=(a[x]-r)/((b[L[x]]+b[R[x]]));
			r=a[x];
		}
		if (!g || r<a[x]) {
			puts("-1");
