int main() {
    int n;
    scanf("%d",&n);
    for(int i=0; i<n; i++)
        scanf("%d",&A[i]);
    bool f=1;
    for(int i=0; i<n; i++) {
        scanf("%d",&B[i]);
        if(A[i]>B[i])
            f=0;
    }
    if(f==0) {
        puts("-1");
        return 0;
    }
    int l,r,val,idx,ans=0,prevans=-1;
    while(prevans!=ans) {
        prevans=ans;
        for(int i=0; i<n; i++) {
            l=i-1;
            r=i+1;
            if(l<0)
                l=n-1;
            if(r>=n)
                r=0;
            if(A[i]==B[i])continue;
            int d=B[l]+B[r];
            int high=(B[i]-A[i])/d;
            if(high){
                ans+=high;
                B[i]-=high*d;
            }
        }
