int main(){
  int N;
  while(cin >> N){
    vector<int> A(N), B(N); cin >> A >> B;

    priority_queue<pair<int, int>> pq;

    REP(i,N) pq.emplace(B[i], i);

    int ans = 0;


    while(pq.size()){
      int x, i;
      tie(x, i) = pq.top(); pq.pop();

      if(B[i] != x) continue;
      if(B[i] == A[i]) continue;

      const int a = B[(i-1+N)%N];
      const int c = B[(i+1)%N];
      const int m = a + c;

      if(m < B[i]){

        int k = B[i] / m;

        if(B[i] % m < A[i]){
          k = (B[i] - A[i]) / m;
        }

        B[i] -= m * k;
        ans += k;
        pq.emplace(B[i], i);
      }

      dump(B);
    }

    if(A != B){
      cout << -1 << endl;
    }else{
      cout << ans << endl;
    }
  }

  return 0;
}

