    for(int i=0; i<N; i++)
    {
        cin >> b[i];
        c[i] = b[i] - a[i];
    }
    int cnt = 0;
    while (true) {
        if (a == b) break;
        std::vector<int>::iterator iter = std::max_element(c.begin(), c.end());
        size_t i = std::distance(c.begin(), iter);
        int ni = i + 1;
        int pi = i - 1;
        if (ni == N) ni = 0;
        if (pi == -1) pi = N - 1;
        if (b[i] >= b[ni] + b[pi]) {
            b[i] -= (b[ni] + b[pi]);
            c[i] = b[i] - a[i];
            cnt++;
        } else {
            cnt = -1;
            break;
        }
    }
    cout << cnt << endl;

    return 0;
}

