int main(){
    ll n, t, ans = 0;
    cin >> n;
    vll a(n), b(n);
    cin >> a >> b;
    vpll c(n);
    REP(i,n) c[i] = {b[i], i};

    int i, j, k;
    while(c.size()){
        t = distance(c.begin(), max_element(all(c)));
        i = c[t].second;

        if(b[i] == a[i]){
            c.erase(c.begin() + t);
            continue;
        }

        if(i == 0){
            j = 1; k = n-1;
        }
        else if(i == n-1){
            j = n-2; k = 0;
        }
        else{
