int N, A[MAX], B[MAX];

bool f(){
    rep(i, N){
        if(A[i] != B[i]) return false;
    }
    return true;
}

int main(){
    cin >> N;
    rep(i, N) cin >> A[i];
    rep(i, N) cin >> B[i];

    priority_queue<P> q;
    ll ans = 0;
    while(1){

        rep(i, N){
            int a = i - 1;
            int b = i;
            int c = i + 1;
            if(a < 0) a = N - 1;
            if(N <= c) c = 0;

            if(B[a] + B[c] < B[b] && B[b] > A[b]) q.push( P(B[i], i) );
        }

