        int b = i;
        int c = i + 1;
        if(a < 0) a = N - 1;
        if(N <= c) c = 0;

        ans += B[b] / (B[a] + B[c]);
        B[b] %= B[a] + B[c];
    }

    if(f()) cout << ans << endl;
    else cout << -1 << endl;

