int main() {
  cin.tie(0);
  int N;
  cin >> N;
  vector<int> A(N), B(N);
  FOR(i, N) cin >> A[i];
  FOR(i, N) cin >> B[i];
  set<int> can;
  FOR(i, N) {
    if (B[i] >= A[i] + B[(i + N - 1) % N] + B[(i + N + 1) % N]) can.insert(i);
  }
  ll ans = 0;
  while (!can.empty()) {
    int i = *can.begin();
    can.erase(can.begin());
    int bunbo = (B[i == 0 ? N - 1 : i - 1] + B[i == N - 1 ? 0 : i + 1]);
    int ct = (B[i] - A[i]) / bunbo;
    ans += ct;
    B[i] -= ct * bunbo;
    if (A[i == 0 ? N - 1 : i - 1] != B[i == 0 ? N - 1 : i - 1] &&
        B[i == 0 ? N - 1 : i - 1] >=
            A[i == 0 ? N - 1 : i - 1] + B[i < 2 ? i + N - 2 : i - 2] + B[i])
      can.insert(i == 0 ? N - 1 : i - 1);
    if (A[i == N - 1 ? 0 : i + 1] != B[i == N - 1 ? 0 : i + 1] &&
        B[i == N - 1 ? 0 : i + 1] >= A[i == N - 1 ? 0 : i + 1] + B[i] +
                                         B[i >= N - 2 ? i + 2 - N : i + 2])
      can.insert(i == N - 1 ? 0 : i + 1);
  }
  FOR(i, N) {
    if (A[i] != B[i]) {
      print(-1);
      return 0;
    }
  }
  print(ans);
  return 0;
}

