using namespace std;
typedef long long ll;

int n;

int convert(int x) {
    return (x + n) % n;
}

int main() {
    cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)cin >> a[i];
    vector<ll> b(n);
    for (int i = 0; i < n; i++)cin >> b[i];

    priority_queue<vector<ll>> que;
    for (int i = 0; i < n; i++) {
        if (b[i] > a[i]) que.push({b[i] - a[i], i});
    }

    int ret = 0;
    while (!que.empty()) {
        auto v = que.top();
        que.pop();

        int x = v[1];
        ll sum_next = b[convert(x - 1)] + b[convert(x + 1)];
        ll count = max(1LL, (b[x] - a[x]) / sum_next);
        b[x] -= sum_next * count;
        ret += count;
        if (b[x] < a[x])break;
        if (b[x] == a[x])continue;
        que.push({b[x] - a[x], x});
    }

    bool flag = true;
    for (int i = 0; i < n; i++) {
        if (a[i] != b[i])flag = false;
    }

    cout << (flag ? ret : -1) << endl;
    return 0;
}

