    REP(i, 0, n) {
        que.push(P(i, b[i]));
    }

    lli ans = 0;
    while (true) {
        P p = que.top();
        lli cur = p.first;
        lli prev = (p.first + n - 1) % n;
        lli next = (p.first + n + 1) % n;

        lli x = b[cur] - (b[prev] + b[next]);
        if (x < a[cur])
            break;

        b[cur] = x;
        que.pop();
        que.push(P(cur, b[cur]));

        ans++;
