    }
    ll ans = 0;
    while(pq.size()) {
       pii top = pq.top(); pq.pop();
       int x = b[prv(top.se)], y = b[top.se], z = b[nxt(top.se)];
       Q[top.se] = 0;
       if(y > x + z) {
         b[top.se] = y % (x + z);
         ans += y / (x + z);
       }
       if(Check(top.se)) {pq.push(mp(b[top.se], top.se)); Q[top.se] = 1;}
