         pq.push(mp(b[nxt(top.se)], nxt(top.se)));
         Q[nxt(top.se)] = 1;
       }
    }
    for(int i = 1; i <= n; ++i) {
        if(a[i] != b[i]) return cout << -1, 0;
    }
