    ll N;cin>>N;
    vector<int> A(N);
    REP(i, N) cin >> A[i];
    vector<int> B(N+2);
    REP(i, N) cin >> B[i+1];
    ll ans=0;
    while(1){
        B[0]=B[N];
        B[N+1]=B[1];
        bool ok=true;
        bool impossible=true;
        rep(i,1,N+1){
            if(B[i]!=A[i-1]){ 
                ok=false;
                if(B[i]>B[i-1]+B[i+1]){
                    impossible=false;
                    ll n=B[i]/(B[i-1]+B[i+1]);
                    B[i]-=n*(B[i-1]+B[i+1]);
                    ans+=n;
                }
            }
            //cout<<B[i]<<" \n"[i==N];
        }
        if(ok) break;
        if(impossible){
            cout<<-1<<endl;
            return 0;
        }

    }
    cout<<ans<<endl;
}

