typedef pair<ll, ll> b_i;
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll n;
  cin >> n;
  ll a[n], b[n];
  priority_queue<b_i> que;
  for(ll i = 0; i < n; i++) {
    cin >> a[i];
  }
  for(ll i = 0; i < n; i++) {
    cin >> b[i];
    que.push(b_i(b[i], i));
  }
  ll count = 0;
  while(!que.empty()) {
    b_i bi = que.top();
    que.pop();
    ll left, right;
    ll bval = bi.first;
    ll i = bi.second;
    if(b[i] == a[i]) continue;
    if(i == 0) left = n - 1;
    else left = i - 1;
    if(i == n - 1) right = 0;
    else right = i + 1;
    ll diff = b[i] - a[i];
    ll count_diff = diff / (b[left] + b[right]);
    if(diff < 0 || count_diff == 0) {
      count = -1;
      break;
    }
    b[i] -= count_diff * (b[left] + b[right]);
    count += count_diff;
    que.push(b_i(b[i], i));
  }
  cout << count << "\n";
  return 0;
}

