    vll A(N), B(N);
    for(auto &e : A)
        cin >> e;
    for(auto &e : B)
        cin >> e;
    ll ok = false;
    ll update = false;
    ll ans = 0;
    while(!ok) {
        update = false;
        for(i = 0; i < N; i++) {
            ll le = i - 1;
            if(le < 0)
                le = N - 1;
            ll ri = i + 1;
            if(ri >= N)
                ri = 0;
            if(B[i] > A[i] && B[i] > B[le] && B[i] > B[ri]) {
                if(B[i] - (B[le] + B[ri]) < A[i]) {
