                update = true;
                ans += B[i] / (B[le] + B[ri]);
                B[i] %= B[le] + B[ri];
            }
        }
        if(update)
            continue;
        else {
            for(i = 0; i < N; i++) {
                if(A[i] != B[i]) {
                    cout << -1 << endl;
                    return 0;
                }
            }
            ok = true;
        }
    }
    cout << ans << endl;

