void solve(){
    cin >> n;
    a.resize(n,0);b.resize(n,0);
    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    while (true){
        int change=0;
        rep(i,n){
            ll x=b[(n+i-1)%n],y=b[(n+i+1)%n];
            if (b[i]<x+y) continue;
            if (a[i]==b[i]) continue;
            change+=1;
            ll t=b[i]%(x+y);
            if (t<a[i]){
                ll p=b[i]-a[i];
                if (p%(x+y)!=0) {
                    B=-1;
                }
                B+=p/(x+y);
                b[i]=a[i];
            }
            else{
                B+=b[i]/(x+y);
                b[i]=t;
            }

        }
        if (change==0 || B==-1) break;
    }

    bool pos=true;
    rep(i,n) {
        if (a[i]!=b[i]) {
            pos = false;
        }
    }
    if (pos) cout << B << endl;
    else cout << -1 << endl;


}

