ll ans{0};

void Yes()
{
  cout << ans << endl;
  exit(0);
}
void No()
{
  cout << "-1" << endl;
  exit(0);
}

ll N;
vector<ll> A, B;
ll A_sum{0}, B_sum{0};
queue<int> Q;

void update(int v)
{
  int before = (v + N - 1) % N;
  int after = (v + 1) % N;
  ll a_c{B[before] + B[after]};
  ll cnt{B[v] / a_c};
  ll mod{B[v] % a_c};
  if (cnt == 0)
  {
    return;
  }
  if (mod >= A[v])
  {
    B[v] = mod;
    ans += cnt;
    B_sum -= a_c * cnt;
    Q.push(before);
    Q.push(after);
  }
  else
  {
    if ((A[v] - mod) % a_c == 0)
    {
      B[v] = A[v];
      cnt -= (A[v] - mod) / a_c;
      ans += cnt;
      B_sum -= a_c * cnt;
    }
    else
    {
      No();
    }
  }
}

void same()
{
  assert(A_sum == B_sum);
  for (auto i = 0; i < N; i++)
  {
    if (A[i] != B[i])
    {
      No();
    }
  }
  Yes();
}

void solve()
{
  while (A_sum < B_sum && !Q.empty())
  {
    update(Q.front());
#if DEBUG == 1
    cerr << "update(" << Q.front() << "), cnt = " << ans << ", ";
    for (auto i = 0; i < N; i++)
    {
      cerr << B[i] << " ";
    }
    cerr << endl;
#endif
    Q.pop();
  }
  if (A_sum == B_sum)
  {
    same();
  }
  else
  {
    No();
  }
}

int main()
{
  cin >> N;
  A = vector<ll>(N);
  B = vector<ll>(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  for (auto i = 0; i < N; i++)
  {
    cin >> B[i];
  }
  A_sum = accumulate(A.begin(), A.end(), 0LL);
  B_sum = accumulate(B.begin(), B.end(), 0LL);
  for (auto i = 0; i < N; i++)
  {
    Q.push(i);
  }
  solve();
}

