struct segment_tree {
  #define ls (p << 1)
  #define rs (p << 1 | 1)
  #define mid (l + r >> 1)
  segment_tree() { memset(this, 0, sizeof (segment_tree)); }
  segment_tree(const segment_tree &x) { *this = x; }
  pii tr[800005];
  inline void pushup(int p) {
    tr[p] = max(tr[ls], tr[rs]);
  }
  void build(int p, int l, int r, int *a) {
    if (l == r) {
      tr[p].first = b[l];
      tr[p].second = l;
      return ;
    }
    build(ls, l, mid, a);
    build(rs, mid + 1, r, a);
    pushup(p);
  }
  void modify(int p, int l, int r, int pos, int val) {
    if (l == r) {
      tr[p].first = val;
      if (tr[p].first < a[l]) flag = 1;
      cnt += (tr[p].first == a[l]);
      return ;
    }
    if (pos <= mid)
      modify(ls, l, mid, pos, val);
    else
      modify(rs, mid + 1, r, pos, val);
    pushup(p);
  }
  int query(int p, int l, int r, int pos) {
    if (l == r) return tr[p].first;
    if (pos <= mid) return query(ls, l, mid, pos);
    else return query(rs, mid + 1, r, pos);
  }
  inline void print(int p, int l, int r) {
    if (l == r) {
      eprintf("%d ", tr[p].fi);
      return ;
    }
    print(ls, l, mid);
    print(rs, mid + 1, r);
  }
  #undef ls
  #undef rs
  #undef mid
