struct data 
{
	int id;
	bool operator < (const data &other) const
	{
		return b[id] < b[other.id];
	}
};

int main()
{
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; ++i)
		scanf("%d", &a[i]);
	for (int i = 1; i <= n; ++i)
		scanf("%d", &b[i]);
	std::priority_queue<data> q;
	for (int i = 1; i <= n; ++i)
		q.push({i});
	long long res = 0;
	while (true)
	{
		int x = q.top().id;
		q.pop();
		if (b[x] <= a[x])
			break;
		int prv = x > 1 ? x - 1 : n;
		int nxt = x < n ? x + 1 : 1;
		int sum = b[prv] + b[nxt];
		int cnt = (b[x] - a[x]) / sum;
		if (cnt == 0)
			break;
		res += cnt;
		b[x] %= sum;
		q.push({x});
	}
