	int N;
	cin >> N;

	vector<lint> A(N), B(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < N; i++) cin >> B[i];

	priority_queue<pair<lint, int>> pq;
	for (int i = 0; i < N; i++) pq.emplace(B[i], i);
