#define GET_IDX(idx, n) ((idx+n) % n)


using namespace std;

int main(){
  int n;
  scanf("%d", &n);
  vector<long> a(n);
  vector<long> b(n);
  vector<bool> flags(n);
  int num_flgs = n;
  bool is_crct=true;
  int count = 0;

  for(int i=0;i<n;i++){
    scanf("%ld", &a[i]);
    flags[i] = true;
  }
  for(int i=0;i<n;i++){
    scanf("%ld", &b[i]);
  }

  while(num_flgs>0){
    long tmp=-100;
    size_t max_idx = -1;
    int m;
    long sum;
    for(int i=0;i<n;i++){
      if(!(tmp>b[i]*flags[i])){
        tmp = b[i];
        max_idx = i;
      }
    }
    if(b[max_idx]==a[max_idx]){
      num_flgs--;
      flags[max_idx] = false;
      continue;
    }
    sum = (b[GET_IDX(max_idx+1,n)] + b[GET_IDX(max_idx-1,n)]);
    m = max((b[max_idx] - 1) / (sum),1L);
    tmp = b[max_idx] - sum*m;
    if(tmp<=0){
      is_crct = false;
      break;
    }
    b[max_idx] = tmp;
    count+=m;
  }

  if(is_crct){
    cout << count << endl;
  }else{
    cout << "-1" << endl;
  }


  return 0;
}

