using namespace std;
using ll = long long;

const int N = 2 * (int)1e5;
ll as[N];
ll bs[N];
ll cou = 0;

void check(int i, int n) {
	int pi = (i + (n-1)) % n;
	int ni = (i + 1) % n;
	ll d = bs[i] - as[i];
	if (d > 0) {
		ll add = bs[pi] + bs[ni];
		ll r = d / add;
		cou += r;
		bs[i] -= r * add;

		if (r > 0) {
			check(pi, n);
			check(ni, n);
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	for (int i = 0; i < n; ++i) cin >> as[i];
	for (int i = 0; i < n; ++i) cin >> bs[i];
	for (int i = 0; i < n; ++i) check(i, n);

	bool fail = false;
	for (int i = 0; i < n; ++i) fail |= (as[i] != bs[i]);

	if (fail) cout << "-1\n";
	else cout << cou << '\n';
}

