int main() {
  scanf("%d", &n);
  for (int i = 0; i < n; ++i)
    scanf("%d", &a[i]);
  for (int i = 0; i < n; ++i)
    scanf("%d", &b[i]);
  ll ans = 0;
  priority_queue<pair<int, int>> q;
  for (int i = 0; i < n; ++i)
    q.emplace(b[i], i);
  while (!q.empty()) {
    int p, v;
    tie(v, p) = q.top(); q.pop();
    if (b[p] == a[p]) continue;
    if (b[p] < a[p]) {
      puts("-1");
