    }
    int s = b[(p + 1) % n] + b[(p + n - 1) % n];
    if (b[p] < s) {
      puts("-1");
      return 0;
    }
    if (a[p] >= s) {
      if ((b[p] - a[p]) % s == 0) {
        ans += (b[p] - a[p]) / s;
        b[p] = a[p];
        continue;
      } else {
        puts("-1");
        return 0;
      }
    } else {
      ans += b[p] / s;
      b[p] %= s;
    }
    if (b[p] < a[p]) {
      puts("-1");
      return 0;
    }
    q.emplace(b[p], p);
  }
  printf("%lld\n", ans);
  return 0;
