		}
		/*
		for (LL i = 0; i < N; ++i) {
			cout << A[i] << " ";
		}
		cout << endl;//*/
		seal(i);
		seal(L(i));
		seal(R(i));
	}
	for (LL i = 0; i < N; ++i) {
		if (A[i] != B[i]) {
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

