bool isSameAry(VI &a, VI &b) {
    REP(i,0,a.size()) if (a[i] != b[i]) return false;
    return true;
}
bool isSmallAry(VI &a, VI &b) {
    REP(i,0,a.size()) if (a[i] > b[i]) return true;
    return false;    
}

void solve() {
    int n;
    cin >> n;
    VI a(n), b(n);
    REP(i,0,n) cin >> a[i];
    REP(i,0,n) cin >> b[i];
    LL cnt = 0;
    priority_queue<PII> q;
    REP(i,0,n) q.emplace(b[i],i);
    int ok = 0;
    while (ok < n) {
        auto p = q.top();
        q.pop();
        int index = p.second, v = p.first;
        int diff = b[(index-1+n)%n] + b[(index+1)%n];
        int maxc = max({b[(index-1+n)%n], b[(index+1)%n], a[index]});
        LL times = (v - maxc + diff - 1) / diff;
        b[index] -= (b[(index-1+n)%n] + b[(index+1)%n]) * times;
        //dump(times);
        //dump(diff);
        //dump(v);
        //dump(nextv);
        cnt += times;
        if (b[index] < a[index]) {
            cout << -1 << endl;
            return;
        }
        if (b[index] == a[index]) ++ok;
        q.emplace(b[index], index);
    }
    cout << cnt << endl;
}

int main() {
    solve();

    return 0;
}

