void solve(){
    cin >> n;
    a.resize(n,0);b.resize(n,0);
    rep(i,n) cin >> a[i];
    rep(i,n) cin >> b[i];
    while (true){
        int change=0;
        rep(i,n){
            ll x=b[(n+i-1)%n],y=b[(n+i+1)%n];
            ll r=b[i]%(x+y);
            if (b[i]>x+y && b[i]>a[i]){
