                    B+=b[i]/(x+y);
                    b[i]=r;
                }
            }
        }
        if (change==0 || B==-1) break;
    }

    bool pos=true;
    rep(i,n) {
        if (a[i]!=b[i]) {
            pos = false;
        }
    }
    if (pos) cout << B << endl;
    else cout << -1 << endl;


}

