const int N = 3e5 + 100, LOG = 20, oo = 1e9;

int n, a[N], b[N];
bool used[N];

bool kek(int nm) {
    int ls = nm - 1, nx = nm + 1;
    if (ls == -1)
        ls = n - 1;
    if (nx == n)
        nx = 0;
    if (b[nm] > a[nm] && b[nm] > b[ls] + b[nx])
        return true;
    return false;
}

void smain() {


    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    set <pii> st;
    for (int i = 0; i < n; i++) {
        if (kek(i)) {
            used[i] = true;
            st.insert({b[i], i});
        }
    }
    int ans = 0;
    while (st.size()) {
        auto it = st.end(); it--;
        pii p = *it;
        int nm = p.second;
        if (b[nm] < a[nm]) {
            cout << -1;
            return;
        }
        int ls = nm - 1, nx = nm + 1;
        if (ls == -1)
            ls = n - 1;
        if (nx == n)
            nx = 0;

        st.erase(it);
        ans += (b[nm] - a[nm]) / (b[ls] + b[nx]);
        if ((b[nm] - a[nm]) / (b[ls] + b[nx]) == 0) {
            cout << -1;
            return;
        }
        b[nm] = a[nm] + (b[nm] - a[nm]) % (b[ls] + b[nx]);
        if (b[nm] != a[nm]) {
            st.insert({b[nm], nm});
        }
        if (!used[ls] && kek(ls)) {
            used[ls] = true;
            st.insert({b[ls], ls});
        }
        if (!used[nx] && kek(nx)) {
            used[nx] = true;
            st.insert({b[nx], nx});
        }

    }


    for (int i = 0; i < n; i++) {
        if (b[i] != a[i]) {
            cout << -1;
            return;
        }
    }

    cout << ans;


}

