int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    int A[n], B[n];
    for(int i = 0; i < n; ++i) cin >> A[i];
    for(int i = 0; i < n; ++i) cin >> B[i];

    for(int i = 0; i < n; ++i) if(A[i] > B[i]) {cout << "-1"; return 0;}

    priority_queue<pii> Q;
    for(int i = 0; i < n; ++i)
        if(A[i] != B[i]) Q.push({B[i], i});

    int ans = 0;
    while(!Q.empty())
    {
        pii tmp = Q.top(); Q.pop();

        int x = (tmp.ss + n - 1) % n;
        int y = tmp.ss;
        int z = (tmp.ss + 1) % n;

        int cnt = (B[y] - A[y]) / (B[x] + B[z]);
        int tar = B[y] - cnt * (B[x] + B[z]);
        ans += cnt;
        if(tar == B[y]) {ans = -1; break;}
        B[y] = tar;
        if(tar != A[y]) Q.push({B[y], y});
    }

    cout << ans;
    return 0;
}

