typedef long long int lli;
typedef pair<lli, lli> P;

// 大きい順にpop
class CompareDist
{
public:
    bool operator()(P n1, P n2) {
        return n1.second<=n2.second;
    }
};

int main() {
    lli n;
    cin1(n);
    lli a[n];
    lli b[n];
    ncin1(n, a);
    ncin1(n, b);


    priority_queue< P, vector<P>, CompareDist > que;

    REP(i, 0, n) {
        que.push(P(i, b[i]));
    }

    lli ans = 0;
    while (true) {
        P p = que.top();
        lli cur = p.first;
        lli prev = (cur + n - 1) % n;
        lli next = (cur + n + 1) % n;

        lli x = b[cur] - (b[prev] + b[next]);
        if (x < a[cur])
            break;

        b[cur] = x;
        que.pop();
        que.push(P(cur, b[cur]));

        ans++;
    }

    REP(i, 0, n) {
        if (a[i] != b[i]) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;
}

