    for(int i = 0; i < N; i++) {
        cin >> B[i];
        if(A[i] != B[i]) s.push({B[i], i});
    }
    int ans = 0;
    while(!s.empty()) {
        int pos = s.top().second;
        s.pop();

        int nxt = max(B[(pos - 1 + N) % N] , max(B[(pos + 1) % N], A[pos]));
        int neg = B[(pos - 1 + N) % N] + B[(pos + 1) % N];
        int diff = max(1, (B[pos] - nxt) / neg);
        ans += diff;
        B[pos] -= diff * neg;
        if(B[pos] < A[pos]) {
            cout << -1;
            return 0;
        } else if(B[pos] != A[pos]) {
            s.push({B[pos], pos});
        }
    }

    for(int i = 0; i < N; i++)
        if(A[i] != B[i]) {
            cout << -1;
            return 0;
        }

    cout << ans;
}

