      x=update(2*in+1,s,mid,i);
    else
      y=update(2*in+2,mid+1,l,i);
    seg[in]= a[x]>a[y]?x:y;
    //cout<<s<<l<<seg[in]<<endl;
    return seg[in];
}
ll segment(ll in , ll s , ll l)
{
    if(s==l)
    {
        seg[in]=s;
        return s;
    }
    ll mid=(s+l)/2;
    ll x=segment(2*in+1,s,mid);
    ll y=segment(2*in+2,mid+1,l);
    seg[in]= a[x]>a[y]?x:y;
   // cout<<s<<l<<seg[in]<<endl;
    return seg[in];
}
