class segtree{
    int N;
    using val_type = pair<int, int>;
    vector<val_type > dat;

    val_type query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return {-1, -1};

        if(a <= l && r <= b) return dat[k];

        auto mid = (l+r) / 2;
        auto vl = query(a, b, k*2 + 1, l, mid);
        auto vr = query(a, b, k*2 + 2, mid, r);

        return std::max(vl, vr);
    }

public:
    explicit segtree(int n) :dat() {
        N = 1;
        while(N < n) N *= 2;

        dat.resize(2*N, {-1, -1});
    }

    // A[k] -> a
    void update(int k, int a){
        int i = k;
        k += N-1;
        dat[k] = {a, i};
        while(k > 0){
            k = (k-1) / 2;
            dat[k] = std::max(dat[k*2 + 1] , dat[k*2 + 2]);
        }
    }

    val_type max(){
        return query(0, N, 0, 0, N);
    }

};

void sub_main(istream &is) {
    int N;
    is >> N;
    if(!is) return;
    vector<int> A(N), B(N);
    for (auto &&a : A) { is >> a; } // end a
    for (auto &&b : B) { is >> b; } // end b

    segtree segB(N);
    for (int i = 0; i < N; ++i) {
        segB.update(i, B[i]);
    } // end i

    ll K = 0;
    while(true){
        auto big = segB.max();
        int it = big.second;
        if(B[it] <= A[it]) break;
        int next, prev;
        next = it+1; next %= N;
        prev = it-1; prev += prev < 0 ? N : 0;

        B[it] -= B[prev] + B[next];
        if(B[it] < A[it]) break;
        segB.update(it, B[it]);
        K++;
    }

    for (int i = 0; i < N; ++i) {
        if(A[i] != B[i]){
            cout << -1 << endl;
            return;
        }
    } // end i
    cout << K << endl;

}

