        ll t = b[(i+n-1)%n] + b[(i+1)%n];
        ll num = min((b[i]-1)/t, (b[i]-a[i]+t-1)/t);
        dump(b[i], a[i], t, num);
        b[i] -= t * num;
        ans += num;
        dump(b);

        if(num == 0) {
            cout << "-1\n";
            return 0;
        }
        if(b[i] != a[i]) que.push({b[i], i});
    }

    cout << ans << endl;

    return 0;
}

