int minCount(vector<int> a_vec, vector<int> b_vec) {
    int count=0,n=a_vec.size();
    for(int j=0; j<n; j++){
        int i = min_element(b_vec.begin(), b_vec.end()) - b_vec.begin();
        while(a_vec[i] < b_vec[i]){
            int a = (i == 0) ? a_vec[n-1] : a_vec[i-1];
            int b = a_vec[i];
            int c = (i == n-1) ? a_vec[0] : a_vec[i+1];
            a_vec[i] = a+b+c;
            count++;
        }
        if(a_vec[i] == b_vec[i]){
            b_vec[i] = INT_MAX;
        }else return -1;
    }
    return count;
}

