int b[MAXN];

main(){
    int n = readInt();
    for (int i = 1; i <= n; i++) {
        a[i] = readInt();
    }
    multiset<pair<int,int>> s;
    for (int i = 1; i <= n; i++) {
        b[i] = readInt();
        if (a[i] > b[i]) {
            cout << -1;
            return 0;
        }
        if (b[i] > a[i])
        s.insert({-b[i], i});
    }
    int ans = 0;
    while(!s.empty()) {
        auto ptr = s.begin();
        pair <int, int> val = *ptr;
        int i = val.second;
        s.erase(ptr);
        int kek = (val.second == 1 ? b[n] : b[val.second - 1]) + (val.second == n ? b[1] : b[val.second + 1]);
        if (b[i] == a[i]) continue;
        int cnt = (b[i]-a[i]) / kek;
        if (cnt <= 0) {
            continue;
        }
        ans += cnt;
        b[i] %= kek;
        if (b[i] > a[i]) {
            s.insert({-b[i], i});
        }
    }
    for (int i = 1; i <= n; i++) {
        if (a[i] != b[i]) {
            cout << -1;
            return 0;
        }
    }
    cout << ans;
    return 0;
}

