int f(vector<int>&v) {
	queue<int>que;
	rep(i, n) {
		if (v[x(i - 1)] + v[x(i + 1)] < v[i]) {
			que.push(i);
		}
	}
	int res = 0;
	while (!que.empty()) {
		int i = que.front(); que.pop();
		if (v[i] <= v[x(i - 1)] + v[x(i + 1)])continue;
		res += v[i] / (v[x(i - 1)] + v[x(i + 1)]);
		v[i] %= v[x(i - 1)] + v[x(i + 1)];
		if (v[x(i - 1)] > v[i] + v[x(i - 2)])que.push(x(i - 1));
		if (v[x(i + 1)] > v[i] + v[x(i + 2)])que.push(x(i + 1));
	}
	return res;
}
