void enqueue(int i) {
	i = (i + n) % n;
	int j = (i - 1 + n) % n;
	int k = (i + 1) % n;
	int sum = b[j] + b[k];
	if (b[i] - sum >= a[i]) {
		q.push(make_pair(sum, i));
	}
}

long long greedy() {
	long long count = 0;
	for (int i = 0; i < n; i++) {
		enqueue(i);
	}
	while (!q.empty()) {
		pair<int, int> p = q.top();
		int i = p.second;
		q.pop();
		b[i] -= p.first;
		if (b[i] == a[i]) {
			match++;
		}
		enqueue(i);
		enqueue(i - 1);
		enqueue(i + 1);
		count++;
	}
	return count;
}

