			t = (b[top.yy] - a[top.yy] + dec - 1) / dec;

		b[top.yy] -= t * dec;

		if (b[top.yy] < a[top.yy])
		{
			printf("-1\n");
			return 0;
		}

		q.emplace(b[top.yy], top.yy);
