  for (auto& a_i : A) {
    std::cin >> a_i;
  }
  for (auto& b_i : B) {
    std::cin >> b_i;
  }

  std::vector<bool> comp_index(N, false);
  for (int i = 0; i < N; i++) {
    if (A.at(i) == B.at(i)) {
      comp_index[i] = true;
    }
  }

  while (1) {
    bool       end          = true;
    const auto before_count = count;

    int maxB = 0, maxB_i, secondmaxB;
    for (int i = 0; i < N; i++) {
      if (!comp_index.at(i) && B.at(i) > maxB) {
        secondmaxB = maxB;
        maxB       = B.at(i);
        maxB_i     = i;
      }
    }
    // 終了条件
    if (maxB == 0) {
      std::cout << count;
      return 0;
    }

    int d; // 変化量
    if (maxB_i == 0) {
      d = B.at(N - 1) + B.at(1);
    } else if (maxB_i == N - 1) {
      d = B.at(N - 2) + B.at(0);
    } else {
      d = B.at(maxB_i - 1) + B.at(maxB_i + 1);
    }
    int &     a = A.at(maxB_i), &b = B.at(maxB_i);
    const int howMany = std::min((b - secondmaxB) / d + 1, (b - a) / d);
    b -= d * howMany;
    count += howMany;

    if (howMany <= 0) {
      std::cout << "-1";
      return 0;
    }
    if (a == b) {
      comp_index[maxB_i] = true;
    }
  }
  return 0;
}

