using namespace std;

bool match[200000] = {};
ll a[200000] = {};
ll b[200000] = {};
int n;

ll dfs(int i)
{
  ll left = b[(i - 1 + n) % n];
  ll right = b[(i + 1 + n) % n];
  if (left + right == 0)
  {
    return 0;
  }
  ll ans = b[i] / (left + right);
  b[i] = b[i] % (left + right);
  if (b[i] == 0)
  {
    return 0;
  }
  if (a[i] == b[i])
    match[i] = true;

  if (b[(i - 2 + n) % n] + b[i] < b[(i - 1 + n) % n] && !match[(i - 1 + n) % n])
    ans += dfs((i - 1 + n) % n);
  if (b[i] + b[(i + 2 + n) % n] < b[(i + 1 + n) % n] && !match[(i + 1 + n) % n])
    ans += dfs((i + 1 + n) % n);
  return ans;
}

int main()
{
  cin >> n;
  REP(i, n)
  {
    cin >> a[i];
  }
  REP(i, n)
  {
    cin >> b[i];
  }

  ll ans = 0;
  REP(i, n)
  {
    ll left = b[(i - 1 + n) % n];
    ll right = b[(i + 1 + n) % n];
    if (left + right < b[i] && !match[i])
    {
      ans += dfs(i);
    }
  }

  REP(i, n)
  {
    if (!match[i])
    {
      cout << -1 << endl;
      return 0;
    }
  }
  cout << ans << endl;
}

