int prv(int at) { return at==0?n-1:at-1; }
int nxt(int at) { return at==n-1?0:at+1; }
bool can(int at) { return c[at]-c[prv(at)]-c[nxt(at)]>=a[at]; }
void upd(int at) { if(!inq[at]&&can(at)) inq[at]=true,q.push(at); }

ll solve() {
	q=queue<int>(); REP(i,n) inq[i]=false;
	REP(i,n) c[i]=b[i],upd(i);
