bool f(ll i) {
  bool res;
  if(i == 0) {
    ll m = b[n - 1] + b[1];
    res = b[0] > m && b[0] > a[0];
  } else if(i == n - 1) {
    ll m = b[n - 2] + b[0];
    res = b[n - 1] > m && b[n - 1] > a[n - 1];
  } else {
    ll m = b[i - 1] + b[i + 1];
    res = b[i] > m && b[i] > a[i];
  }
  return res;
}

int main() {
