  rep2(i, 1, n - 1) {
    ll m = b[i - 1] + b[i + 1];
    if(b[i] > m && b[i] > a[i]) st.insert(i);
  }
  ll m0 = b[n - 1] + b[1];
  if(b[0] > m0 && b[0] > a[0]) st.insert({0, 0});
  ll mn = b[n - 2] + b[0];
  if(b[n - 1] > mn && b[n - 1] > a[n - 1]) st.insert({0, n - 1});
