      b[n - 1] %= m;
      if(f(n - 2)) st.insert(n - 2);
      if(f(0)) st.insert(0);
    } else {
      ll m = b[i - 1] + b[i + 1];
      ans += b[i] / m;
      b[i] %= m;
      if(f(i - 1)) st.insert(i - 1);
      if(f(i + 1)) st.insert(i + 1);
    }
  }
  bool ok = true;
  rep(i, n) if(a[i] != b[i]) ok = false;
  if(ok)
    cout << ans << endl;
  else
    cout << -1 << endl;
}

