const ll INF = (ll) 1e15;

struct SegmentTree {
    SegmentTree(ll n) : n(n), t(n * 2, {0, 0}) {}
    SegmentTree(vl x) : n(x.size()), t(n * 2, {0, 0}) {
        for (int i = 0; i < n; ++i) {
            t[i + n] = {x[i], i};
        }
        build();
    }

    pll combine(pll a, pll b) {
        return max(a, b);
    }

    void build() {  // build the tree
        for (ll i = n - 1; i > 0; --i) t[i] = combine(t[i << 1], t[(i << 1) | 1]);
    }

    void modify(ll p, ll value) {  // set value at position p
        for (t[p += n].fi = value; p > 1; p >>= 1) t[p >> 1] = combine(t[p], t[p ^ 1]);
    }

    pll query(ll l, ll r) {  // [l, r)
        pll res = {-INF, 0};
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = combine(res, t[l++]);
            if (r & 1) res = combine(res, t[--r]);
        }
        return res;
    }

    ll n;
    vector<pll> t;
};

void no() {
    cout << "-1" << endl;
    exit(0);
}

int main() {
    cout << setprecision(30);
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);

    ll n;
    cin >> n;
    vl a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }

    for (int i = 0; i < n; ++i) {
        if (a[i] > b[i]) no();
    }

    ll ans = 0;
    SegmentTree st(b);
    while (true) {
        auto res = st.query(0, n);
        ll bb = res.first;
        ll i = res.second;

        if (bb == -INF) break;
        if (bb == a[i]) {
            st.modify(i, -INF);
            continue;
        }
        ll aa = b[(i - 1 + n) % n];
        ll cc = b[(i + 1) % n];
        assert(aa <= bb && cc <= bb);
        ll dd = aa + cc;

        assert(bb > a[i]);
        ans += (bb - a[i]) / dd;
        bb = a[i] + (bb - a[i]) % dd;
        if (b[i] == bb) no();
        b[i] = bb;

        st.modify(i, bb);
    }

    cout << ans << endl;

    return 0;
}

