void chk(int i){
	int l = (i - 1 + n) % n, r = (i + 1) % n;
	if(a[i]>b[i]&&a[i]-(a[l]+a[r])>=b[i])Q.push(i);
}

void calc(int i) {
	int l = (i - 1 + n) % n, r = (i + 1) % n;
	if(a[i]<b[i])return;
	int t = (a[i] - b[i]) / (a[l] + a[r]);
	a[i] -= t * (a[l] + a[r]),ans+=t;
	chk(l),chk(r);
}

