const int ComputePrev(const int N, vector<int> &values,
    multimap<int, int> &value2IndexMap)
{
    auto itr = --value2IndexMap.end();
    const int index = itr->second;
    const int prev = index - 1 < 0 ? N - 1 : index - 1;
    const int next = index + 1 >= N ? 0 : index + 1;
    values[index] -= values[prev] + values[next];
    value2IndexMap.erase(itr);
    value2IndexMap.insert({ values[index], index });
    return index;
}

void Check(const int changedIndex,
    const vector<int> &As, const vector<int> &Bs, int &flag)
{
    const int goal = As[changedIndex], current = Bs[changedIndex];
    // 目標値の方が下ならば続行
    if (goal < current)
    {
        flag = 1;
    }
    // 目標値に一致したならばフラグ＝０
    else if (goal == current)
    {
        flag = 0;
    }
    // 目標値を下回ってしまった場合は失敗
    else
    {
        flag = -1;
    }
}

const int CountRemained(const int N, const vector<int> &As, const vector<int> &Bs)
{
    int remained = N;
    for (int i = 0; i < N; ++i)
    {
        if (As[i] == Bs[i])
        {
            --remained;
        }
    }
    return remained;
}

void CheckCondition(const int N, const vector<int> &As, const vector<int> &Bs,
    bool &isWrong, bool &isSame)
{
    isWrong = false;
    isSame = true;
    for (int i = 0; i < N; ++i)
    {
        if (As[i] > Bs[i])
        {
            isWrong = true;
            return;
        }
        else if (As[i] < Bs[i])
        {
            isSame = false;
        }
    }
}

int main()
{
    int N;
    cin >> N;
    vector<int> As(N), Bs(N);
    for (int i = 0; i < N; ++i) cin >> As[i];
    for (int i = 0; i < N; ++i) cin >> Bs[i];

    bool isWrong, isSame;
    CheckCondition(N, As, Bs, isWrong, isSame);
    if (isWrong)
    {
        cout << -1 << endl;
        return 0;
    }
    else if (isSame)
    {
        cout << 0 << endl;
        return 0;
    }

    multimap<int, int> value2IndexMap;
    for (int i = 0; i < N; ++i)
    {
        if (As[i] != Bs[i])
        {
            value2IndexMap.insert({ Bs[i], i });
        }
    }

    int flag;
    int remained = CountRemained(N, As, Bs);
    for (int count = 1;; ++count)
    {
        const int changedIndex = ComputePrev(N, Bs, value2IndexMap);
        Check(changedIndex, As, Bs, flag);
        if (flag == 0)
        {
            --remained;
            if (remained == 0)
            {
                cout << count << endl;
                break;
            }
        }
        else if (flag < 0)
        {
            cout << -1 << endl;
            break;
        }
    }
}

