	vector<ll> A(N),B(N);
	for(int i = 0; i < N; ++i) cin >> A[i];
	for(int i = 0; i < N; ++i) cin >> B[i];
	priority_queue<pair<ll,int>> pq;
	for(int i = 0; i < N; ++i){
		int l = (i-1+N)%N;
		int r = (i+1)%N;
		if(B[l]<B[i]&&B[i]>B[r]) pq.push({B[i],i});
	}
	ll ans = 0;
	while(pq.size()){
		auto p = pq.top();
		int c = p.second;
		pq.pop();
		if(B[c]<=A[c]) continue;
		int l = (c-1+N)%N;
		int r = (c+1)%N;
		ll d = (B[l]+B[r]);
