		while(ok-ng>1){
			md = (ok+ng)/2;
			ll diff = md*d;
			(B[c]-diff<=B[l]&&B[c]-diff<=B[r]?ok:ng)=md;
		}
		B[c] -= ok*d;
		ans += ok;

		if(B[c]<B[r]&&B[r]>B[(r+1)%N]&&B[r]!=A[r]) pq.push({B[r],r});
		if(B[(l-1+N)%N]<B[l]&&B[l]>B[c]&&B[l]!=A[l]) pq.push({B[l],l});
