int Bdec(int i, vector<int> Barg)
{
	vector<int> Btmp = Barg;
	int Bnei = Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N];
	if (Btmp[i] > A[i])
	{
		Btmp[i] -= Bnei;
		anstmp++;
	}
	return Btmp[i];
}

bool Btop(int i, vector<int> Btmp)
{
	if (Btmp[i] > (Btmp[(i + N - 1) % N] + Btmp[(i + 1) % N]))
		return true;
	return false;
}

