}

void Get_ans(){
  for (int i=1;i<=n;++i)
	if (b[i]>a[i]) vis[i]=1,q.push(state(i,b[i]));
    else if (b[i]<a[i]) {ans=-1;return;}
  for (;!q.empty();){
	int p=q.top().x;q.pop();
	vis[p]=0;
	int l=p==1?n:p-1,r=p==n?1:p+1;
	int s=b[l]+b[r],t=(b[p]-a[p])/s;
	ans+=t;b[p]-=t*s;
	if (Check(l)) vis[l]=1,q.push(state(l,b[l]));
	if (Check(r)) vis[r]=1,q.push(state(r,b[r]));
  }
  for (int i=1;i<=n;++i)
	if (b[i]>a[i]) ans=-1;
}

void work(){
  Get_ans();
}

void outo(){
  printf("%d\n",ans);
}

int main(){
