using namespace std;

int n;
vector<int> a;
vector<int> b;
int match;

long long solve() {
	if (match == n) {
		return 0;
	}
	long long best = -1;
	for (int i = 0; i < n; i++) {
		int j = (i - 1 + n) % n;
		int k = (i + 1) % n;
		int sum = b[j] + b[k];
		if (b[i] - sum < a[i]) {
			continue;
		}
		bool flag = b[i] - sum == a[i];

		if (flag) match++;
		b[i] -= sum;
		long long child = solve();
		b[i] += sum;
		if (flag) match--;

		if (child < 0) {
			continue;
		}
		if (best < 0 || child + 1 < best) {
			best = child + 1;
		}
	}
	return best;
}

int main() {
	scanf("%d", &n);
	int x;
	for (int i = 0; i < n; i++) {
		scanf("%d", &x);
		a.push_back(x);
	}
	match = 0;
	for (int i = 0; i < n; i++) {
		scanf("%d", &x);
		b.push_back(x);
		if (b[i] == a[i]) {
			match += 1;
		}
	}
	printf("%lld\n", solve());
	return 0;
}

