int f(vector<int>&v) {
	queue<int>que;
	rep(i, n) {
		if (v[x(i - 1)] + v[x(i + 1)] < v[i]) {
			que.push(i);
		}
	}
	int res = 0;
	while (!que.empty()) {
		int i = que.front(); que.pop();
		if (v[i] % (v[x(i - 1)] + v[x(i + 1)]) == 0) {
			int memo= v[i] / (v[x(i - 1)] + v[x(i + 1)]) - 1;
			res += memo;
			v[i] -= (v[x(i - 1)] + v[x(i + 1)]) * memo;
		}
		else {
			res += v[i] / (v[x(i - 1)] + v[x(i + 1)]);
			v[i] %= v[x(i - 1)] + v[x(i + 1)];
		}
		if (v[x(i - 1)] > v[i] + v[x(i - 2)])que.push(x(i - 1));
		if (v[x(i + 1)] > v[i] + v[x(i + 2)])que.push(x(i + 1));
	}
	return res;
}
