	rep(i, n) cin >> b[i];
	priority_queue<pll> q;
	rep(i, n)
	{
		q.push(make_pair(b[i], i));
	}
	ll res = 0;
	while (!q.empty()) {
		auto p = q.top();
		q.pop();
		int i = p.second;
		int ne = (i + 1) % n;
		int be = (i + n - 1) % n;

