        sort(all(ord),[&](int x,int y){ return b[x] > b[y]; });
        bool ok = false;
        for(int i : ord) {
            int sum = b[((i-1)%n+n)%n]+b[(i+1)%n];
            if(b[i]-sum < a[i]) continue;
            int r = (b[i]-a[i])/sum;
            b[i] -= sum*r;
            ok = true;
            cnt += r;
            break;
        }
        if(!ok) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << cnt << endl;
}

