int n;
set<pair<int, int>> diffs;

void step_back (int i) {
  diffs.erase(make_pair(B[i] - A[i], i));

  B[i] -= B[(i + n - 1) % n];
  B[i] -= B[(i + 1) % n];
  if (B[i] < A[i]) failure();

  diffs.insert(make_pair(B[i] - A[i], i));
}

int main () {
  ios::sync_with_stdio(false);

  cin >> n;

  for (int i = 0; i < n; i++) {
    cin >> A[i];
  }

  for (int i = 0; i < n; i++) {
    cin >> B[i];
  }

  for (int i = 0; i < n; i++) {
    if (B[i] < A[i]) failure();
    diffs.insert(make_pair(B[i] - A[i], i));
  }

  int ans = 0;
  while (diffs.rbegin()->first > 0) {
    int idx = diffs.rbegin()->second;
    step_back(idx);
    ans++;
  }

  cout << ans << endl;
}

