#define ll long long

int next(int i, int k) {
    if (i == k) return 1;
    return i + 1;
}
int prev(int i, int k) {
    if (i == 1) return k;
    return i - 1;
}
main(){
    int n = readInt();
    for (int i = 1; i <= n; i++) {
        a[i] = readInt();
    }
    queue<int> que;
    for (int i = 1; i <= n; i++) {
        b[i] = readInt();
        if (b[i] < a[i]) fail();
        que.push(i);
    }

    ll ans = 0;

    while (que.size()) {
        int i = que.front(); que.pop();
        ll near = b[next(i, n)] + b[prev(i, n)];
        ll u = (b[i] - a[i]) / near;
        if (u <= 0) continue;
        ans += u;
        b[i] %= near;
        que.push(prev(i, n));
        que.push(next(i, n));
    }

    for (int i = 1; i <= n; i++) {
        if (a[i] != b[i]) fail();
    }

    cout << ans << endl;

    return 0;
}

