		if (a[x] == b[x]) continue
		int x = top.second;
		int p = b[lxt(x)] + b[nxt(x)];
		if (b[x] - p < a[x]) {
			puts("-1");
			return ;
		} else {
			int d = (b[x] - a[x]) / p;
			ans += d;
			b[x] -= d * p;
			que.push(make_pair(b[x], x));
		}
	}
	printf("%d\n", ans);
}

