inline int p(int u){ return (u+n-1)%n; }
inline int s(int u){ return (u+1  )%n; }
inline bool check(int u) { return b[u]>b[p(u)] && b[u]>b[s(u)]; }
void solve() {
    queue <int> que;
    rep (i,n) if (check(i)) que.push(i);
    int ans=0;
    while (!que.empty()) {
        int u=que.front(); que.pop();
        if (b[u]==a[u]) { continue; } ALERT(b[u]<a[u],"-1");
        int sub=b[p(u)]+b[s(u)];
        int del=b[u]-a[u];
        ALERT(del<sub,"-1");
        ans+=del/sub; b[u]-= del/sub*sub;
        if (check(p(u))) { que.push(p(u)); } 
        if (check(u)) { que.push(u); } 
        if (check(s(u))) { que.push(s(u)); } }
    rep (i,n) ALERT(b[i]!=a[i],"-1");
    printf(IN,ans);
}

