  }

  for(int i=0; i<N; i++) {
    scanf("%lld", B+i);
  }

  queue<int> que;
  bool ok[SIZE] = {};

  for(int i=0; i<N; i++) {
    int a = B[(i+N-1)%N];
    int b = B[(i+1)%N];

    if(B[i] >= A[i] + a + b) {
      que.push(i);
      ok[i] = true;
    }
  }

  ll counter = 0;
  while(que.size()) {
    int i = que.front(); que.pop();
    ll &a = B[(i+N-2)%N];
    ll &b = B[(i+N-1)%N];
    ll &c = B[i];
    ll &d = B[(i+1)%N];
    ll &e = B[(i+2)%N];

    assert(B[i] > A[i]);
    int t = (B[i] - A[i]) / (d + b);
    counter += t;
    B[i] -= t * (d + b);
    ok[i] = false;

    if (c >= A[i] + b + d && !ok[i]) {
      que.push(i);
      ok[i] = true;
