    }

    if (b >= A[(i+N-1)%N] + a + c && !ok[(i+N-1)%N]) {
      que.push((i+N-1)%N);
      ok[(i+N-1)%N] = true;
    }

    if (d >= A[(i+1)%N] + c + e && !ok[(i+1)%N]) {
      que.push((i+1)%N);
      ok[(i+1)%N] = true;
    }
  }


