long long solve() {
    long long rlt = 0;
    while (1) {
        bool fg = 1;
        for (int i = 1; i <= n; i ++) {
            if (a[i] > b[i]) return -1;
            if (a[i] == b[i]) continue;
            int k = b[i>1?i-1:n] + b[i<n?i+1:1];
