void solve(long long N, std::vector<long long> A, std::vector<long long> B){
  multimap<ll,ll> m;
  REP(B.size()){
    if(B[i]!=A[i]){
    m.insert(make_pair(B[i],i));
    }
  }
  REP(N){
    if(A[i]>B[i]){
      cout<<-1<<endl;
      return;
    }
  }
  ll ans=0;
  while(!m.empty()){
    ll tmp=m.rbegin()->second;
    m.erase(prev(m.end()));
    if(A[tmp]==B[tmp])continue;
    if(A[tmp]<B[tmp]){
      ll mx=B[(tmp+1)%N]+B[(tmp+N-1)%N];
      if(mx>B[tmp]){
        if(A[tmp]!=B[tmp]){
          cout<<-1<<endl;
          return;
        }
        continue;
      }
      if(A[tmp]>B[tmp]%mx){
        if((B[tmp]-A[tmp])!=0){
          cout<<-1<<endl;
          return;
        }
        ans+=(B[tmp]-A[tmp])/mx;
        B[tmp]=A[tmp];
        continue;
      }
      ans+=B[tmp]/mx;
      B[tmp]%=mx;
      if(A[tmp]>B[tmp]){
        cout<<-1<<endl;
        return ;
      }
      if(A[tmp]!=B[tmp]){
        m.insert(make_pair(B[tmp],tmp));
      }
    }else{
      cout<<-1<<endl;
      return;
    }
  }
  cout<<ans<<endl;
}

