const int N = 200100;
int n, a[N], b[N], ans;
priority_queue <pair<int, int>  > pq;

int main() {
	ios_base::sync_with_stdio(false);

	cin >> n;
	for(int i = 0; i < n; i++)
		cin >> a[i];

	for(int i = 0; i < n; i++) {
		cin >> b[i];
		if(b[i] != a[i])
			pq.push({b[i], i});
	}

	while(!pq.empty()) {
		auto p = pq.top();
		pq.pop();
		int nxt = a[p.nd];
		// dbg(p);
		int dif = p.st - nxt;
		dif /= (b[(n + p.nd - 1) % n] + b[(p.nd + 1) % n]);
		dif = max(dif, 1);
		ans += dif;
		p.st -= dif * (b[(n + p.nd - 1) % n] + b[(p.nd + 1) % n]);
		if(p.st != a[p.nd])
			pq.push(p);

		if(p.st < a[p.nd]) return cout << "-1\n", 0;
		b[p.nd] = p.st;
	}
	cout << ans << '\n';
}

