    int n; in(n);
    vi a(n); rep(i, n) in(a[i]);
    vi b(n + 2); rep(i, n) in(b[i + 1]);

    int ans = 0;

    while (1) {
        int c = 0;
        b[0] = b[n]; b[n + 1] = b[1];
        repr(i, 1, n + 1) {
            int x = (b[i - 1] + b[i + 1]);
            c += b[i]/x;
            b[i] %= x;
        }
        ans += c;
        if (!c) break;
    }

    bool e = 1;
