const int N = 200200; 

int n, a[N], b[N]; 

struct node {
  int d, id; 
  bool operator < (const node &x) const {
    return d < x.d; 
  }
} tmp; 

priority_queue <node> Q; 

int main() {
  scanf("%d", &n); int ans = 0; 
  for(int i = 1; i <= n; i++) {
    scanf("%d", &a[i]); 
  }
  for(int i = 1; i <= n; i++) {
    scanf("%d", &b[i]); 
    Q.push((node){b[i], i}); 
  }
  while(!Q.empty()) {
    tmp = Q.top(); Q.pop(); 
    if(tmp.d == a[tmp.id]) continue ; 
    if(tmp.d < a[tmp.id]) {
      puts("-1"); 
      return 0; 
    }
    ans++; 
    int id = tmp.id; 
    int id1 = id + 1; 
    int id2 = id - 1; 
    if(id1 > n) id1 -= n; 
    if(id2 < 1) id2 += n; 
    if(tmp.d < b[id1] + b[id2]) {
      puts("-1");
      return 0; 
    }
    b[id] -= b[id1] + b[id2]; 
    Q.push((node){b[id], id}); 
  }
  for(int i = 1; i <= n; i++) {
    if(a[i] != b[i]) {
      puts("-1"); return 0; 
    }
  }
  printf("%d\n", ans);
  return 0; 
}

