    rep(i,n){
        q.emplace(b[i],i);
    }

    while(!q.empty() && suma != sumb){
        P now = q.top();
        dbg(now);
        q.pop();
        if(handle(now.se)){
            q.emplace(b[now.se], now.se);
        }
    }
    bool ok = true;
    rep(i,n){
        if(a[i]!=b[i])ok = false;
    }
    dbg(a)
    dbg(b)
    if(ok){
        out(cnt);
    }else{
        out(-1);
    }

    return  0;
}

