	vi a(n); for (int i = 0; i < n; ++i) cin >> a[i];
	vi b(n); for (int i = 0; i < n; ++i) cin >> b[i];

	priority_queue<ii, vii, less<ii>> pq;

	for (int i = 0; i < n; ++i) pq.push(mp(b[i],i));

	ll nmov = 0;
	bool pos = true;
	while (!pq.empty()) {
		ii nact = pq.top(); pq.pop();
