      return;
    }
    pq.push(make_pair(b[i],i));
  }
  while(!pq.empty()) {
    int ind = pq.top().second;
    int val = b[ind];
    assert(val==pq.top().first);
    pq.pop();
    int maxi = max(b[(ind+n-1)%n], b[(ind+1)%n]);
    maxi = max(maxi,a[ind]);
    int g = b[(ind+n-1)%n] + b[(ind+1)%n];
    int diff = val - maxi;
    int add = diff/g;
    if(add==0) {
      maxi = max(a[ind], min(b[(ind+n-1)%n], b[(ind+1)%n]));
      diff = val - maxi;
      add = diff/g;
    }
    if(add==0) {
      maxi = a[ind];
      diff = val - maxi;
      add = diff/g;
    }
    if(add==0) {
      break;
    }
    ret += add;
    b[ind] -= add*g;
    if(a[ind]>b[ind]) {
      break;
    }
    pq.push(make_pair(b[ind],ind));
  }
  for(int i=0;i<n;++i) {
    if(a[i]!=b[i]) {
