int main(int argc, char const *argv[]) {
  ll N;
  std::cin >> N;
  std::vector<ll> A(N), B(N);
  multimap<ll, ll> mp;
  for(int i=0;i<N;i++) std::cin >> A[i];
  for(int i=0;i<N;i++) {
    std::cin >> B[i];
    mp.emplace(B[i], i);
  }
  ll count=0;
  bool flag = true;
  while(mp.size()!=0){
    auto itr = mp.end();
    itr--;
    ll num = (*itr).first;
    ll i = (*itr).second;
    ll x = B[(i==N-1?0:i+1)]+B[(i==0?N-1:i-1)];
    count+=((num-x)/x + 1);
    num -= x * ((num-x)/x + 1);
    //count+=((num-x)/x + (num-x%x==0?0:1));
    //num -= x * ((num-x)/x + (num-x%x==0?0:1));
    if(num < A[i]) {
      flag = false;
      break;
    }
    B[i] = num;
    mp.erase(itr);
    if(num!=A[i]) mp.emplace(num, i);
  }
  if(flag) std::cout << count << '\n';
  else std::cout << -1 << '\n';
  return 0;
}

