using namespace std;

int main() {

	SINT64 N;	cin >> N;

	vector<SINT64> fdata(N);
	vector<SINT64> ndata(N);
	vector<SINT64> mdata(N);
	vector<SINT64> ans(N,0);

	rep(i,0,N) {
		cin >> fdata[i];
	}
	rep(i,0,N) {
		cin >> ndata[i];
		if (fdata[i] == ndata[i]) {
			ans[i] = 1;
		}
	}

	rep(i,1,N-1) {
		mdata[i] = ndata[i-1]+ndata[i+1];
	}
	mdata[0] = ndata[1]+ndata[N-1];
	mdata[N-1] = ndata[0]+ndata[N-2];

	queue<SINT64> bufq;

	rep(i,0,N) {
		if (mdata[i] == 0) {
		} else {
			if (ndata[i]-mdata[i] >= fdata[i]) {
				bufq.push(i);
			}
		}
	}

	SINT64 cnt = 0;

	while(bufq.size() != 0) {
		SINT64 buf;
		SINT64 cc;
		SINT64 i = 0;

		i = bufq.front();
		bufq.pop();

		buf = ndata[i] - fdata[i];

		cc = buf / mdata[i];
		cnt += cc;
		cc = cc * mdata[i];
		ndata[i] = (buf % mdata[i]) + fdata[i];
		if (ndata[i] == fdata[i]) {
			ans[i] = 1;
		}

		if (i != 0) {
			mdata[i-1] -= cc;
			if (ndata[i-1]-mdata[i-1] >= fdata[i-1]) {
				bufq.push(i-1);
			}
		} else {
			mdata[N-1] -= cc;
			if (ndata[N-1]-mdata[N-1] >= fdata[N-1]) {
				bufq.push(N-1);
			}
		}
		if (i != N-1) {
			mdata[i+1] -= cc;
			if (ndata[i+1]-mdata[i+1] >= fdata[i+1]) {
				bufq.push(i+1);
			}
		} else {
			mdata[0] -= cc;
			if (ndata[0]-mdata[0] >= fdata[0]) {
				bufq.push(0);
			}
		}
	}

	rep(i,0,N) {
		if (ans[i] == 0) {
			put(-1);
			return 0;
		}
	}


	put(cnt);
	return 0;
}


