int A[N], B[N], n;
int q[30 * N], cur, sz;

inline int prv(int x){
	return (x - 1 + n) % n;
}

inline int nxt(int x){
	return (x + 1) % n;
}

int main(){
	scanf("%d", &n);
	for(int i = 0;i < n;i++)
		scanf("%d", A + i);
	for(int i = 0;i < n;i++)
		scanf("%d", B + i);
	for(int i = 0;i < n;i++){
		if(B[i] > B[prv(i)] + B[nxt(i)] && B[i] > A[i])
			q[sz++] = i;
	}
	int sol = 0;
	for(;cur < sz;){
		int i = q[cur++];
		B[i] %= B[prv(i)] + B[nxt(i)];
		if(B[prv(i)] > A[prv(i)] && B[prv(i)] > B[prv(prv(i))] + B[i])
			q[sz++] = prv(i);
		if(B[nxt(i)] > A[nxt(i)] && B[nxt(i)] > B[nxt(nxt(i))] + B[i])
			q[sz++] = prv(i);
		if(B[i] > A[i] && B[i] > B[prv(i)] + B[nxt(i)])
			q[sz++] = nxt(i);
		sol++;
	}
	bool ans = 1;
	for(int i = 0;i < n;i++)
		ans &= (A[i] == B[i]);
	printf("%d\n", ans ? sol : -1);
	return 0;
}

