#define ff(i, x, y) for(int i = x;i <= y;i++)
#define fs(i, x, y) for(int i = x;i >= y;i--)
#define maxn 200005
using namespace std;
typedef long long ll;
typedef struct node {
    int id, val;
    node(int a1, int a2) {
        id = a1;
        val = a2;
    }
};
bool operator <(const node &a1, const node &a2) {
    if(a1.val <= a2.val) return true;
    return false;
}
int a[maxn], b[maxn], n;
priority_queue<node>p;
int main() {
    scanf("%d", &n);
    ff(i, 1, n)
    scanf("%d", &a[i - 1]);
    ff(i, 1, n)
    scanf("%d", &b[i - 1]);
    ff(i, 1, n) {
        if(a[i - 1] < b[i - 1])
            p.push(node(i - 1, b[i - 1]));
    }
    int flag = 1, ans = 0;
    while(!p.empty()){
        node temp = p.top();
        p.pop();
        int pos = temp.id, v = temp.val;
        //printf("%d\n", v);
        int mod = b[(pos - 1 + n) % n] + b[(pos + 1) % n];
        if(v <= mod) {
            flag = 0;
            break;
        }
        v = (b[pos] - a[pos]) % mod;
        ans += (b[pos] - a[pos]) / mod;
        b[pos] = a[pos] + v;
        if(v == 0);
        else
            p.push(node(pos, b[pos]));
    }
    while(!p.empty()) {
        p.pop();
    }
    if(flag)
        printf("%d", ans);
    else
        printf("-1");
    return 0;
}

