using namespace std;

int main() {
	int n;
	cin >> n;
	vector<int> a(n),b(n);
	for rep(i, n)
		cin >> b[i];
	for rep(i, n)
		cin >> a[i];
	vector<bool> ju(n, true);
	priority_queue<pair<int, int>> da;
	int ans = 0;
	for rep(i, n) {
		da.push(make_pair(a[i], i));
		ju[i] = bool(a[i] == b[i]);
	}
	while (!da.empty()) {
		int x = da.top().second;
		da.pop();
		if (!ju[x]) {
			int y= a[(x + 1) % n] + a[(x - 1 + n) % n];
			if (y < b[x]) {
				if ((a[x] - b[x]) % y) {
					ans = -1;
					break;
				}
				else {
					ju[x] = true;
					ans += (a[x] - b[x]) / y;
					a[x] = b[x];
				}
			}
			else {
				ans += a[x] / y;
				a[x] %= y;
			}
			if (a[x] == b[x]) {
				ju[x] = true;
			}
			else if (a[x] < b[x]) {
				ans = -1;
				break;
			}
			else {
				da.push(make_pair(a[x], x));
			}
		}
	}
	cout << ans << endl;
}

