bool kek(int nm) {
    int ls = nm - 1, nx = nm + 1;
    if (ls == -1)
        ls = n - 1;
    if (nx == n)
        nx = 0;
    if (b[nm] > a[nm] && b[nm] > b[ls] + b[nx])
        return true;
    return false;
}

