    for (int i = 0; i < n; i++) {
        if (kek(i)) {
            used[i] = true;
            st.insert({b[i], i});
        }
    }
    int ans = 0;
    while (st.size()) {
        auto it = st.end(); it--;
        pii p = *it;
        int nm = p.second;
        if (b[nm] < a[nm]) {
            cout << -1;
            return;
