        }
        used[nm] = false;
        b[nm] = a[nm] + (b[nm] - a[nm]) % (b[ls] + b[nx]);
        if (b[nm] != a[nm] && kek(nm)) {
            used[nm] = true;
            st.insert({b[nm], nm});
        }
        if (!used[ls] && kek(ls)) {
            used[ls] = true;
            st.insert({b[ls], ls});
        }
        if (!used[nx] && kek(nx)) {
            used[nx] = true;
            st.insert({b[nx], nx});
        }

    }


    for (int i = 0; i < n; i++) {
        if (b[i] != a[i]) {
            cout << -1;
            return;
        }
    }

