int solve(vector<int> A, vector<int> B){
    int res = 0;
    const int N = A.size();
    while(true){
        int idx = -1;
        for(int i=0;i<N;i++){
            if(A[i] > B[i]) return -1;
            if(A[i] == B[i]) continue;
            if(idx == -1 || B[idx] < B[i]) idx = i;
        }
        if(idx == -1) break;
        B[idx] -= B[(idx+1)%N] + B[(idx+N-1)%N];
        ++res;
    }
    return res;
}

