  vector<bool> C(N, false);
  priority_queue<pll> BP;
  REP(i, N) cin >> A[i];
  REP(i, N) {
    cin >> B[i];
    BP.push(make_pair(B[i], i));
  }
  ll ans = 0;
  ll cc = 0;

  while (true) {
    pll t = BP.top();
    BP.pop();
    ll oldb = t.first - B[(t.second + 1) % N] - B[(t.second + N - 1) % N];
    if (oldb <= 0) {
      ans = -1;
      break;
    }
    if (oldb == A[t.second]) {
      C[t.second] = true;
      cc++;
      if (cc == N) {
        ans++;
        break;
      }
    } else if (C[t.second] == true && oldb != A[t.second]) {
      cc--;
      C[t.second] = false;
    }
    B[t.second] = oldb;
    BP.push(make_pair(oldb, t.second));
    ans++;
  }
  cout << ans << endl;
  return 0;
}

