    return (x+1)%N;
}
set<pr> tmp;
ll cnt=0;
int main(void){
    cin >> N;
    for(int i=0;i<N;i++){
        cin >> A[i];
    }

    for(int i=0;i<N;i++){
        cin >> B[i];
        if (B[i] < A[i]){
            cout << -1 << endl;
             return 0;
        }
        if (B[i]!=A[i]) tmp.insert({B[i], i});
    }
    while(tmp.size()>0){
        auto it = tmp.end();
        it--;
        int id = it->second;
        ll val = it->first;
        tmp.erase(it);
