ll solve() {
    ll N;
    cin >> N;
    V<ll> A(N), B(N);
    for(auto &&e : A) cin >> e;
    for(auto &&e : B) cin >> e;
    priority_queue<PLL> pq;
    for(ll i = 0; i < N; i++) if(A[i] < B[i]) pq.emplace(B[i], i);
    ll ret = 0;
    while(pq.size()) {
        ll val, idx;
        tie(val, idx) = pq.top();
        pq.pop();
        ll l = B[(idx + N - 1) % N], r = B[(idx + 1) % N];
        if(val < l + r) break;
        if(l + r == 0) break;
        ll div = min(val / (l + r), (val - A[idx]) / (l + r));
        if(div == 0) break;
        ret += div;
        val -= div * (l + r);
        B[idx] = val;
        if(A[idx] < val) pq.emplace(val, idx);
    }
    return A == B ? ret : -1;
}

