using vvl = vector<vector<ll>>;

struct N {
  int i;
  ll v;
};

bool operator<(const N &l, const N &r) {
  return l.v < r.v;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  vector<ll> a(n), b(n);
  for (int i = 0; i < n; i++) cin >> a[i];
  for (int i = 0; i < n; i++) cin >> b[i];
  priority_queue<N> q;
  for (int i = 0; i < n; i++) {
    if (b[i] > a[i])
      q.push(N{i, b[i]});
    else if (b[i] < a[i]) {
      cout << "-1" << endl;
      return 0;
    }
  }
  ll ans = 0;
  while (q.size()) {
    auto now = q.top();
    q.pop();
    ll side = b[(now.i + n - 1) % n] + b[(now.i + 1) % n];
    if (side == 0 || now.v - side < a[now.i]) {
      cout << -1 << endl;
      return 0;
    }
    ll skip = (now.v - side) / side;
    if (skip == 0) skip++;
    skip = min(skip, (now.v - a[now.i] + side - 1) / side);
    b[now.i] -= skip * side;
    if (b[now.i] > a[now.i]) {
      q.push(N{now.i, b[now.i]});
    }
    ans += skip;
  }
  cout << ans << endl;

  return 0;
}

#include <bits/stdc++.h>
#define MAX 200010
using namespace std;

int N;
int arr[MAX];
int brr[MAX];
queue<int> q;

int test(int idx)
{
	if (idx == 0) return brr[0] > brr[1] + brr[N - 1];
	if (idx == N - 1) return brr[N - 1] > brr[0] + brr[N - 2];
	return brr[idx] > brr[idx - 1] + brr[idx + 1];
}

int main(void)
{
	cin >> N;
	for (int i = 0; i < N; i++) cin >> arr[i];
	for (int i = 0; i < N; i++) cin >> brr[i];
	for (int i = 0; i < N; i++)
	{
		if (test(i)) q.push(i);
	}
	long long ans = 0;
	while (!q.empty())
	{
		int cur = q.front();
		q.pop();
		int prv;
		int nxt;
		if (cur) prv = cur - 1;
		else prv = N - 1;
		if (cur < N - 1) nxt = cur + 1;
		else nxt = 0;
		if (brr[prv] + brr[nxt] == 0)
		{
			cout << -1 << endl;
			return 0;
		}
		int increment = (brr[cur] - arr[cur]) / (brr[prv] + brr[nxt]);
		ans += increment;
		brr[cur] -= increment * (brr[prv] + brr[nxt]);
		if (test(prv)) q.push(prv);
		if (test(nxt)) q.push(nxt);
	}
	for (int i = 0; i < N; i++)
	{
		if (arr[i] != brr[i])
		{
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

