using namespace std;
struct node{
    int pos, val;
    node(int a,int b):pos(a),val(b){}
    bool operator <(const node &B)const{
        return val<B.val;        
    }
};
priority_queue<node> q;
const int maxn=200005;
int a[maxn],b[maxn],n;
int prev(int x){
    return (x-1+n)%n;
}
int succ(int x){
    return (x+1)%n;
}
int main(){
    scanf("%d",&n);
    for(int i=0;i<n;++i){
        scanf("%d",a+i);
    }
    for(int i=0;i<n;++i){
        scanf("%d",b+i);
    }
    for(int i=0;i<n;++i){
        q.push(node(i,b[i]));
    }
    long long cnt=0;
    while(!q.empty()){
        node tmp=q.top();q.pop();
        if(a[tmp.pos]==b[tmp.pos])continue;
        else{
            int sum=b[prev(tmp.pos)]+b[succ(tmp.pos)];
            if((b[tmp.pos]-a[tmp.pos])/sum <= 0){
                printf("-1\n");
                return 0;
            }
            cnt+=(b[tmp.pos]-a[tmp.pos])/sum;
            b[tmp.pos]-=(b[tmp.pos]-a[tmp.pos])/sum*sum;//注意不能一步一步做, 否则会超时
            q.push(node(tmp.pos,b[tmp.pos]));
        }
    }
    printf("%lld\n",cnt);
    return 0;
}

