    vector<ll> as(n), bs(n);
    rep(i, n)cin >> as[i];
    rep(i, n) cin >> bs[i];

    priority_queue<P> q;
    rep(i, n) q.push(P(bs[i], i));

    auto a_get = [&](int i) {
        if (i == -1) return as.back();
        if (i == n) return as.front();
        return as[i];
    };

    auto b_get = [&](int i) {
        if (i == -1) return bs.back();
        if (i == n) return bs.front();
        return bs[i];
    };

    ll ans = 0;

    while (!q.empty()) {
        P p = q.top();
        q.pop();

        ll l = b_get(p.second - 1);
        ll c = b_get(p.second);
        ll ac = a_get(p.second);
        assert(p.first == c);
        ll r = b_get(p.second + 1);

        if (!(l + r <= c)) continue;
        if (!(ac < c)) continue;

        ll target = [&] {
            ll lr = l + r;
            ll count = (c + lr - 1) / lr;
            ll sub = lr * count;
            return min(sub / lr, ac);
        }();
        ll diff = c - target;
        assert(diff > 0);

        ll count = diff / (l + r);
        if (count == 0) continue;
        ans += count;

        ll sub = count * (l + r);
        bs[p.second] -= sub;

        q.push(P(bs[p.second], p.second));
    }

