ll solve( int n, const int* a, int* b, set<pair<int,int> >& setb )
{
    if(setb.empty()) {
        return 0;
    }
    auto it = setb.rbegin();
    int val=it->first;
    int id=it->second;
    if(a[id]==b[id]) { 
        setb.erase(make_pair(b[id],id));
        return solve(n, a, b, setb);
    }

    int prev=b[(id-1+n)%n];
    assert(prev>0);
    int next=b[(id+1+n)%n];
    assert(next>0);
    int step=prev+next;
    if(val<=step) {
        return -1;
    }
    int valnew=val%step;
    int add=val/step;

    if(a[id]>valnew) {
        if(a[id]%step!=valnew) {
            return -1;
        }
        valnew = a[id];
        add = (val - valnew) / step;
        setb.erase(make_pair(b[id],id));
        b[id]=valnew;
    }
    else {
        if(valnew==0) {
            return -1;
        }
        setb.erase(make_pair(b[id],id));
        b[id]=valnew;
        setb.insert(make_pair(b[id],id));
    }

    ll ans0 = solve( n, a, b, setb);
    if(ans0<0) {
        return -1;
    }
    ll ans = ans0 + add;

    return ans;
}

int main(int argc, char* argv[])
{
    int n;
