        scanf("%d", &a[i]);
    }
    set<pair<int,int> > setb;
    for(i=0; i<n; i++) {
        scanf("%d", &b[i]);
        setb.insert(make_pair(b[i], i));
    }

    ll ans = solve( n, &a[0], &b[0], setb );
    printf("%lld\n", ans);

    return 0;
}

