const int N = 2000 * 100 + 57;
bool ok[N];
set<int> bg;

inline void solve() {
	int n;
	cin >> n;
	vector<int> a(n);
	cin >> a;
	vector<int> b(n);
	cin >> b;
	int res = 0;
	for (int i = 0; i < n; ++i) {
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n]) {
			bg.insert(i);
		}
	}

	while (!bg.empty()) {
		int ps = *bg.begin();
		bg.erase(ps);
		if (b[ps] == a[ps]) {
			ok[ps] = true;
			continue;
		}
		int i = ps;
		res += b[ps] / (b[(i - 1 + n) % n] + b[(i + 1) % n]);
		b[ps] %= b[(i - 1 + n) % n] + b[(i + 1) % n];
		if (b[ps] < a[ps]) {
			cout << -1 << endl;
			return;
		}
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n] && !ok[i]) {
			bg.insert(i);
		}
		i = (ps + 1) % n;
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n] && !ok[i]) {
			bg.insert(i);
		}
		i = (ps - 1 + n) % n;
		if (b[i] >= b[(i - 1 + n) % n] && b[i] >= b[(i + 1) % n] && !ok[i]) {
			bg.insert(i);
		}
	}
	for (int i = 0; i < n; ++i) {
		if (a[i] != b[i]) {
			cout << -1 << endl;
			return;
		}
	}
	cout << res << endl;
}


