int main() {
	int N; cin >> N;
	vector<ll> A(N),B(N);
	for(int i = 0; i < N; ++i) cin >> A[i];
	for(int i = 0; i < N; ++i) cin >> B[i];
	//一点加算 + 区間総和
	using p = pair<ll,int>;
	function<p(p,p)> funcNode =  [&](p a,p b){return max(a,b);};
	function<p(p,p)> funcMerge = [&](p a,p b){
		p c;
		c.first = a.first+b.first;
		c.second = b.second;
		return c;};
	SegmentTree<p> seg(N,{0,-1},funcNode,funcMerge);
	for(int i = 0; i < N; ++i) seg.update(i,{B[i],i});
	int cnt = 0;
	while(1){
		p m = seg.get(0,N);
		ll maxi = m.first;
		if(maxi <= 0) break;
		int i = m.second;
		if(A[i]==maxi) {
			seg.update(i,{-maxi,i});
			A[i] = 0;
		}
		else if(A[i]<maxi){
			cnt++;
			int l = (N+i-1)%N;
			int r = (i+1)%N;
			p ml = seg.get(l,l+1);
			p mr = seg.get(r,r+1);
			ll d = ml.first + mr.first;
			if(maxi-d<A[i]){
				cnt = -1;
				break;
			}
			seg.update(i,{-d,i});
		}
		else{
			cnt = -1;
			break;
		}
	}
	for(int i = 0; i < N; ++i) if(A[i]) cnt = -1;
	cout << cnt << endl;
}

