int main() {
	cin >> N;
	auto L = [&](int i) {
		return (i + N - 1) % N;
	};
	auto R = [&](int i) {
		return (i + 1) % N;
	};
	for (int i = 0; i < N; ++i) {
		LL tmp; cin >> tmp;
		B.push_back(tmp);
	}
	for (int i = 0; i < N; ++i) {
		LL tmp; cin >> tmp;
		A.push_back(tmp);
	}
	multiset<pair<LL, LL>>que;
	map<LL, LL>val;
	auto seal = [&](LL i) {
		if (que.count({ val[i],i })) {
			que.erase(que.find({ val[i],i }));
		}
		LL An = (A[i] - B[i]) % (A[L(i)] + A[R(i)]) + B[i];
		if (An == A[i])return;
		que.insert({ A[i] - B[i],i });
		val[i] = A[i] - B[i];
	};
	for (LL i = 0; i < N; ++i) {
		seal(i);
	}
	LL ans = 0;
	while (!que.empty()) {
		auto q = *que.begin();
		LL i = q.second;
		ans += A[i] / (A[L(i)] + A[R(i)]);
		A[i] = (A[i] - B[i]) % (A[L(i)] + A[R(i)]) + B[i];
		if (A[i] < B[i]) {
			cout << -1 << endl;
			return 0;
		}
		/*
		for (LL i = 0; i < N; ++i) {
			cout << A[i] << " ";
		}
		cout << endl;//*/
		seal(i);
		seal(L(i));
		seal(R(i));
	}
	for (LL i = 0; i < N; ++i) {
		if (A[i] != B[i]) {
			cout << -1 << endl;
			return 0;
		}
	}
	cout << ans << endl;
	return 0;
}

