int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int N;
	cin >> N;
	vector<int>A(N);
	vector<int>B(N);

	priority_queue<pair<ll,int>>pq;
	for (int i = 0; i < N; i++)cin >> A[i];
	for (int i = 0; i < N; i++) {
		cin >> B[i];
		pq.push({ B[i],i });
	}


	ll ans = 0;
	while (pq.size()) {
		auto p = pq.top();
		pq.pop();
		ll num = p.first;
		ll idx = p.second;
		if (A[idx] > B[idx])err();
		else if (A[idx] == B[idx])continue;
		ll left = B[(idx != 0)?idx-1:N-1];
		ll right = B[(idx != N-1)?idx+1:0];
		ll sum = left + right;
		if ((num - A[idx]) % sum == 0) {
			ans += (num - A[idx]) / sum;
			B[idx] = A[idx];
			continue;
		}
		if (A[idx] > max(left, right))err();
		ll k = (num - max(left, right) + sum - 1LL) / sum;
		B[idx] -= k * sum;
		ans += k;
		if (B[idx] < A[idx])err();
		pq.push({B[idx],idx});
	}
	puts(ans);


	return 0;
}

