    priority_queue<P> pq;
    rep(i, n){
        pq.emplace(b[i], i);
    }

    int ans = 0;
    bool updated = true;
    while(updated && not pq.empty()){
        updated = false;
        int x = pq.top().first;
        int id = pq.top().second;
        pq.pop();

        if(x <= a[id]){
            continue;
        }

        int sum = b[(id+n-1)%n] + b[(id+1)%n];
        int cnt = min(x / sum, (x - a[id]) / sum);
        ans += cnt;
        b[id] -= sum * cnt;

        if(b[id] > a[id]){
            pq.emplace(b[id], id);
        }
        if(b[id] != x){
            updated = true;
        }
    }

    rep(i, n){
        if(a[i] != b[i]){
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;

    return 0;
}

