class segtree{
    ll N;
    using val_type = pair<int, int>;
    vector<val_type > dat;

    val_type query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return {-1, -1};

        if(a <= l && r <= b) return dat[k];

        auto mid = (l+r) / 2;
        auto vl = query(a, b, k*2 + 1, l, mid);
        auto vr = query(a, b, k*2 + 2, mid, r);

        return std::max(vl, vr);
    }

public:
    explicit segtree(int n) :dat() {
        N = 1;
        while(N < n) N *= 2;

        dat.resize(2*N, {-1, -1});
    }

    // A[k] -> a
    void update(int k, int a){
        int i = k;
        k += N-1;
        dat[k] = {a, i};
        while(k > 0){
            k = (k-1) / 2;
            dat[k] = std::max(dat[k*2 + 1] , dat[k*2 + 2]);
        }
    }

    val_type max(int l, int r){
        return query(l, r, 0, 0, N);
    }

};
segtree segB(0);

ll count(vector<int>& A, vector<int>& B, int l, int r){
    if(l >= r) return 0;
    auto t = segB.max(l, r);
    if(t.first == -1) return 0;
    auto it = t.second;
    ll K = 0;
    if(A[it] > B[it]) return -1;
    if(A[it] == B[it]){
        int lit = it-1, rit = it+1;
        while(lit >= 0 and A[lit] == B[lit]) {
            lit--;
            segB.update(lit, -1);
        }
        while(rit < A.size() and A[rit] == B[rit]) {
            rit++;
            segB.update(rit, -1);
        }
        segB.update(it, -1);
        return count(A, B, l, r);
    }
    else{
        ll p = B[(it-1 + A.size()) % A.size()], n = B[(it+1) % A.size()];
        ll dif = (B[it] - A[it]) / (p + n);
        if(dif == 0) return -1;
        B[it] -= dif * (p+n);
        segB.update(it, B[it]);
        auto v = count(A, B, l, r);
        return v == -1 ? -1 : dif + v;

    }
}


void sub_main(istream &is) {
    int N;
    is >> N;
