using namespace std;

const int SZ=1<<18;
tuple<int,int,int> tree[2*SZ];
int A[200000], B[200000];

bool comp(tuple<int,int,int> a, tuple<int,int,int> b)
{
	return get<0>(a)+get<1>(a)>get<0>(b)+get<1>(b);
}

bool check(tuple<int,int,int> a)
{
	return get<0>(a) && get<1>(a);
}

void add_tree(int n, int v1, int v2)
{
	get<0>(tree[n+=SZ])+=v1;
	get<1>(tree[n])+=v2;
	while(n>>=1) {
		if(check(tree[2*n]) && check(tree[2*n+1])) tree[n]=comp(tree[2*n],tree[2*n+1]) ? tree[2*n]:tree[2*n+1];
		else if(check(tree[2*n])) tree[n]=tree[2*n];
		else tree[n]=tree[2*n+1];
	}
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL); cout.tie(NULL);
	TEST(freopen("input.txt", "r", stdin));
	TEST(freopen("output.txt", "w", stdout));
	TEST(freopen("debug.txt", "w", stderr));
	int N, cnt=0;
	long long ans=0;
	cin>>N;
	fill(tree,tree+2*SZ,make_tuple(0,0,-1));
	for(int i=0;i<N;i++) cin>>A[i];
	for(int i=0;i<N;i++) cin>>B[i];
	for(int i=0;i<N;i++) {
		get<2>(tree[SZ+i])=i;
		if(A[i]!=B[i]) {
			if(A[i]>B[i]) {
				cout<<"-1\n";
				return 0;
			}
			cnt++;
			if(B[(i+N-1)%N]<B[i]) get<0>(tree[SZ+i])=B[(i+N-1)%N];
			if(B[(i+1)%N]<B[i]) get<1>(tree[SZ+i])=B[(i+1)%N];
		}
	}
	for(int i=SZ-1;i;i--) {
		if(check(tree[2*i]) && check(tree[2*i+1])) tree[i]=comp(tree[2*i],tree[2*i+1]) ? tree[2*i]:tree[2*i+1];
		else if(check(tree[2*i])) tree[i]=tree[2*i];
		else tree[i]=tree[2*i+1];
	}
	while(cnt) {
		int v1, v2, idx, m;
		tie(v1,v2,idx)=tree[1];
		if(idx==-1) {
			cout<<"-1\n";
			return 0;
		}
		if((B[idx]-A[idx])%(v1+v2)==0) m=(B[idx]-A[idx])/(v1+v2);
		else m=(B[idx]+min(v1,v2)-1)/(v1+v2);
		if((B[idx]-=m*(v1+v2))<A[idx]) {
			cout<<"-1\n";
			return 0;
		}
		ans+=m;
		if(B[(idx+N-1)%N]>B[idx]) {
			add_tree(idx,-v1,0);
			if(A[(idx+N-1)%N]!=B[(idx+N-1)%N]) add_tree((idx+N-1)%N,0,B[idx]);
		}
		if(B[(idx+1)%N]>B[idx]) {
			add_tree(idx,0,-v2);
			if(A[(idx+1)%N]!=B[(idx+1)%N]) add_tree((idx+1)%N,B[idx],0);
		}
		if(A[idx]==B[idx]) {
			cnt--;
			add_tree(idx,-get<0>(tree[SZ+idx]),-get<1>(tree[SZ+idx]));
		}
	}
	cout<<ans<<'\n';
	return 0;
}

