auto fl = [](auto a, auto b) { assert(b != 0); return a / b - (a % b != 0 && ((a >= 0) != (b >= 0)) ? 1 : 0); };
auto ce = [](auto a, auto b) { assert(b != 0); return a / b + (a % b != 0 && ((a >= 0) == (b >= 0)) ? 1 : 0); };
auto mo = [](auto a, auto b) { assert(b != 0); a %= b; if(a < 0) { a += abs(b); } return a; };

int main() {
	IN(int, n);
	vector<LL> a(n), b(n);
	cin >> a >> b;

	LL ans = 0;
	queue<int> q;

	auto f = [&](int i) {
		int l = mo(i - 1, n);
		int r = mo(i + 1, n);
		if(a[i] <= b[i] - b[l] - b[r]) { q.push(i); }
	};

	auto g = [&](int i) {
		int l = mo(i - 1, n);
		int r = mo(i + 1, n);
		LL s = b[l] + b[r];
		if_not(a[i] <= b[i] - s) { return; }

		LL c = min(fl(b[i] - a[i], s), ce(b[i] - max(b[l], b[r]), s));
		assert(c > 0);
		b[i] -= c * s;
		ans += c;
		f(l);
		f(r);
	};

	inc(i, n) { f(i); }
	until(q.empty()) {
		auto i = q.front(); q.pop();
		g(i);
	}

	OUT(a == b ? ans : -1);
}

