template <class T>
inline void read(T &x) {
    x = 0;
    char c = getchar();
    bool f = 0;
    for (; !isdigit(c); c = getchar()) f ^= c == '-';
    for (; isdigit(c); c = getchar()) x = x * 10 + (c ^ 48);
    x = f ? -x : x;
}

template <class T>
inline void write(T x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    T y = 1;
	int len = 1;
    for (; y <= x / 10; y *= 10) ++len;
    for (; len; --len, x %= y, y /= 10) putchar(x / y + 48);
}

const int MAXN = 2e5;
int n, ans, a[MAXN + 5], b[MAXN + 5];
struct Node {
	int val, id;

	inline friend bool operator<(Node x, Node y) {
		return x.val < y.val;
	}
};
priority_queue<Node> q;

int main() {
	read(n);
	for (int i = 1; i <= n; ++i) read(a[i]);
	for (int i = 1; i <= n; ++i) {
		read(b[i]);
		if (b[i] != a[i]) q.push((Node) { b[i], i });
	}
	for (; !q.empty(); ) {
		int i = q.top().id, l = i == 1 ? n : i - 1, r = i == n ? 1 : i + 1;
		q.pop();
		b[i] -= b[l] + b[r];
		++ans;
		if (b[i] < a[i]) {
			puts("-1");
			return 0;
		}
		if (b[i] > a[i]) q.push((Node) { b[i], i });
	}
	write(ans);
	putchar('\n');
	return 0;
}

