int n;
int a[MAXN], b[MAXN];

#define Prev(pos) ((pos)==1?n:(pos)-1)
#define Next(pos) ((pos)==n?1:(pos)+1)

int main(){
	FILEIO();

	Read(n);
	Read(a,1,n);
	Read(b,1,n);

	For(i,n) if( a[i] > b[i] ) END(-1);

	int ans = 0;
	static priority_queue<pii> pq;
	For(i,n) if( a[i] < b[i] ) pq.push({b[i],i});
	while(!pq.empty()){
		int pos = pq.top().S;
		pq.pop();
		if( b[pos] - b[Prev(pos)] - b[Next(pos)] < a[pos] ) END(-1);
		int lim = min( pq.empty() ? a[pos] : max(a[pos],pq.top().F-1) , b[pos] - b[Prev(pos)] - b[Next(pos)] );
		int times = (b[pos]-lim) / (b[Prev(pos)]+b[Next(pos)]);
		b[pos] -= times*(b[Prev(pos)]+b[Next(pos)]);
		ans += times;
		// b[pos] = b[pos] - b[Prev(pos)] - b[Next(pos)];
		if( b[pos] != a[pos] ) pq.push({b[pos],pos});
	}

	cout << ans << endl;

