int solve() {
    int n; in(n);
    vi a(n); rep(i, n) in(a[i]);
    vi b(n + 2); rep(i, n) in(b[i + 1]);

    int ans = 0;

    while (1) {
        bool e = 1;
        rep(i, n) e &= (a[i] <= b[i + 1]);
        if (not e) break;

        int c = 0;
        b[0] = b[n];
        repr(i, 1, n + 1) {
            int x = (b[i - 1] + b[i + 1]);
            int y = (b[i] - a[i - 1])/x;
            c += y;
            b[i] -= x*y;
            b[n + 1] = b[1];
        }
        ans += c;
        if (c == 0) break;
    }

    bool e = 1;
    rep(i, n) e &= (a[i] == b[i + 1]);

    out(e ? ans: -1);
    return 0;
}

