const int MAXN = 2e5+5;

int n, a[MAXN], b[MAXN];

bool check(int i){
	int x = b[i];
	int y = b[(i-1+n)%n];
	int z = b[(i+1)%n];
	return x>y && x>z && b[i] > a[i];
}

int main(){
	scan(n);
	for(int i=0; i<n; i++) scan(a[i]);
	for(int i=0; i<n; i++) scan(b[i]);

	queue<int> q;
	for(int i=0; i<n; i++){
		if(check(i)){
			q.push(i);
		}
	}
	ll ans = 0;
	while(!q.empty()){
		int i = q.front(); q.pop();

		int x = b[i];
		int y = b[(i-1+n)%n];
		int z = b[(i+1)%n];

		int k = (x - max(y+1, max(z+1, a[i])))/(y+z);
		assert(k>=0);
		b[i] -= k*(y+z);
		ans += k;
		assert(b[i] >= a[i]);
		assert(b[i] > y);
		assert(b[i] > z);
		if(b[i] > a[i]){
			ans++;
			b[i] -= y+z;
		}
		if(b[i] < a[i]) break;

		if(check(i)) q.push(i);
		if(check((i-1+n)%n)) q.push((i-1+n)%n);
		if(check((i+1)%n)) q.push((i+1)%n);
	}
	bool good = true;
	for(int i=0; i<n; i++) good &= a[i]==b[i];
	if(!good) ans = -1;
	printf("%lld\n", ans);
}

