        if (endo == 1)break;
        if (b.at(i % n) >= b.at((i - 1) % n) && b.at(i % n) >= b.at((i + 1) % n) && !(b.at(i % n) == a.at(i % n) && b.at((i + 1) % n) == a.at((i + 1) % n) && b.at((i - 1) % n) == a.at((i - 1) % n))) {
            if (b.at(i % n) / (b.at((i - 1) % n) + b.at((i + 1) % n)) == 0) {
                ans = -1;
                break;
