            if ((a.at(i % n) - b.at(i % n)) % (b.at((i - 1) % n) + b.at((i + 1) % n)) == 0 && (b.at(i % n) - a.at(i % n)) / (b.at(i % n) / (b.at((i - 1) % n) + b.at((i + 1) % n))) != 0) {
