{
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N;
	cin >> N;

	vector<ll> As(N);
	vector<ll> Bs(N);

	for (ll i = 0; i < N; ++i)
	{
		cin >> As[i];
	}

	for (ll i = 0; i < N; ++i)
	{
		cin >> Bs[i];
	}

	set<ll> check;
	for (ll i = 0; i < N; ++i)
	{
		if (Bs[i] > Bs[(i + 1) % N] + Bs[(i != 0) ? (i - 1) : (N - 1)])
		{
			check.insert(i);
		}
	}

	ll res = 0;
	ll pos;
	ll equalCount = 0;
	while (true)
	{
		if (check.empty())
		{
			res = -1;
			break;
		}

		ll pos = *(check.begin());

		ll decr = Bs[(pos + 1) % N] + Bs[(pos != 0) ? (pos - 1) : (N - 1)];
		ll quot = (Bs[pos] - As[pos]) / decr ;
		res += quot;
		Bs[pos] -= decr * quot;

		check.erase(pos);
		ll mpos = (pos != 0) ? (pos - 1) : (N - 1);
		if (Bs[mpos] > Bs[(mpos + 1) % N] + Bs[(mpos != 0) ? (mpos - 1) : (N - 1)])
		{
			check.insert(mpos);
		}
		ll ppos = (pos + 1) % N;
		if (Bs[ppos] > Bs[(ppos + 1) % N] + Bs[(ppos != 0) ? (ppos - 1) : (N - 1)])
		{
			check.insert(ppos);
		}

		if (Bs[pos] == As[pos])
		{
			++equalCount;
		}
		if (equalCount == N)
		{
			break;
		}
	}

	cout << res << endl;

	return 0;
}

