        cnt += (x - a.at(i)) / ((b.at(prev(i)) + b.at(next(i))));
        x -=  ((x - a.at(i)) / ((b.at(prev(i)) + b.at(next(i))))) * (b.at(prev(i)) + b.at(next(i)));

        if (a.at(i) < x) que.push(make_pair(x, i));
    }

