	queue<ll> to_operate;
	ll a_plus_c;
	for (ll i = 0; i < N; ++i) {
		a_plus_c = Bs[(i - 1 + N) % N] + Bs[(i + 1 + N) % N];
		if (Bs[i] > a_plus_c && Bs[i] > As[i]) {
			to_operate.push(i);
		}
	}

	ll res = 0;
	while (!to_operate.empty()) {
		auto idx = to_operate.front();
		to_operate.pop();

		a_plus_c = Bs[(idx - 1 + N) % N] + Bs[(idx + 1 + N) % N];
		if (Bs[idx] - a_plus_c < As[idx]) {
			continue;
		}

		res += Bs[idx] / a_plus_c;
		Bs[idx] %= a_plus_c;
		if (Bs[idx] < As[idx]) {
			ll incr = (As[idx] - Bs[idx] + a_plus_c - 1) / a_plus_c;
			res -= incr;
			Bs[idx] += a_plus_c * incr;
		}

		ll i = (idx - 1 + N) % N;
		a_plus_c = Bs[(i - 1 + N) % N] + Bs[(i + 1 + N) % N];
		if (Bs[i] > a_plus_c && Bs[i] > As[i]) {
			to_operate.push(i);
		}

		i = (idx + 1 + N) % N;
		a_plus_c = Bs[(i - 1 + N) % N] + Bs[(i + 1 + N) % N];
		if (Bs[i] > a_plus_c && Bs[i] > As[i]) {
			to_operate.push(i);
		}
	}

	for (ll i = 0; i < N; ++i) {
		if (As[i] != Bs[i]) {
			res = -1;
			break;
		}
	}

	cout << res << endl;

