            ll d = b[x]+b[y];
            if((b[p]-a[p])%d) return 0 * printf("-1\n");
            ans += (b[p]-a[p])/d;
            b[p] = a[p], ok[p] = 1;
        }
        else{
            ll mx = 0;
            if(!ok[x]) mx = max(mx,b[x]);
            if(!ok[y]) mx = max(mx,b[y]);
            if(b[p]<mx) continue;
            ll d = b[x]+b[y];
            ans += (b[p]-mx+d-1)/d;
            b[p] -= ((b[p]-mx)+d-1)/d*d;
            while(b[p]>=mx) b[p]-=d, ans++;
            if(b[p]<a[p]) return 0 * printf("-1\n");
            if(b[p]==a[p]) ok[p] = 1;
            q.push(x), q.push(y);
        }
    }
    printf("%lld\n",ans);
}

