        if (r < a[id] || r == b[id]) {
            cout << -1 << endl;
            return 0;
        }
        if (r != a[id]) {
            que.push({ r, id });
        }
        b[id] = r;
        ans += q;
    }
    cout << ans << endl;

    return 0;
}

