int solve(int N, const vector<int>& A, const vector<int>& B0) {
    auto B = B0;
    set<pair<tuple<int, int, int>, int>> bag;
    REP(i, N) {
        if (B[i] < A[i]) return -1;
        if (B[i] == A[i]) continue;
        int i0 = i == 0 ? N-1 : i-1;
        int i1 = i == N-1 ? 0 : i+1;
        bag.insert({{-B[i], B[i0], B[i1]}, i});
    }
    int ans = 0;
    //debug(A);
    //debug(B, bag);
    while (!bag.empty()) {
        //debug(B, bag);
        int i = bag.begin()->second;
        bag.erase(bag.begin());
        int i0 = i == 0 ? N-1 : i-1;
        int i1 = i == N-1 ? 0 : i+1;
        //debug(i0, i, i1, "B:", B[i0], B[i], B[i1]);
        int delt = B[i0] + B[i1];
        int q = min((B[i] - A[i]) / delt, (B[i] - max(B[i0], B[i1]) + delt-1) / delt);
        //debug(delt, q, delt*q);
        ans += q;
        B[i] -= q*delt;
        if (q == 0 || B[i] < A[i]) return -1;
        if (B[i] == A[i]) continue;
        bag.insert({{-B[i], B[i0], B[i1]}, i});
    }
    return ans;
}

