void solve()
{
	ll N;  cin >> N;
	vll A = cinv(N);
	vll B = cinv(N);

	multimap<ll, ll> mp;

	REP(i, N){
		if (B[i] != A[i]) mp.emplace(B[i], i);
	}
	ll actionSum = 0;
	while (!mp.empty()){
		auto it = mp.end();
		it--;
		ll i = it->second;
		mp.erase(it);
		ll b0 = B[(i-1+N)%N];
		ll b1 = B[(i+1)%N];
		ll c = max(b0, b1);
		if (A[i] >= c){
			ll sa = B[i] - A[i];
			if (sa % (b0+b1) == 0){
				actionSum += sa / (b0+b1);
				//mp.erase(it);
				B[i] = A[i];
			}
			else bye(-1);
		}
		else{
			ll actionNum = 1 + (B[i] - c) / (b0+b1);
			actionSum += actionNum;
			B[i] -= actionNum*(b0+b1);

			if (B[i] > A[i]){
				mp.emplace(B[i], i);
			}
			else if (B[i] < A[i]) bye(-1);
		}
	}
	cout << actionSum << '\n';
}

