int n;

bool is_good(int i) {
    int l = (i - 1 + n) % n;
    int r = (i + 1) % n;
    return b[l] + b[r] <= b[i] - a[i];
}

set<int> good;
int ans = 0;

void down(int i) {
    int l = (i - 1 + n) % n;
    int r = (i + 1) % n;
    int s = b[l] +  b[r];
    int delta = b[i] - a[i];
    ans += delta / s;
    b[i] -= delta / s * s;
    good.erase(i);
    good.erase(l);
    good.erase(r);
    if (is_good(l)) good.insert(l);
    if (is_good(r)) good.insert(r);
//    assert(!is_good(i));
}

void smain() {

    cin >> n;
    a.resize(n);
    b.resize(n);
    fori (i, n) cin >> a[i];
    fori (i, n) cin >> b[i];
    fori (i, n) if (is_good(i)) good.insert(i);
    while (!good.empty()) {
        auto it = good.begin();
        down(*it);
    }
    if (a == b) {
        cout << ans;
    } else {
        cout << "-1";
    }
}

