	for (int i = 0; i < n; ++i)
	{
		cin>>a[i];
	}
	for (int i = 0; i < n; ++i)
	{
		cin>>b[i];
		if (a[i]!=b[i])
		{
			memo.insert(make_pair(b[i],i));
		}
	}
	int cnt=0;
	long long ans=0LL;
	while (cnt!=n)
	{
		for (auto i = memo.end(); ; --i)
		{
			if (i==memo.end())
			{
				--i;
			}
			auto p=*i;
			int l=(p.second-1+n)%n,r=(p.second+1)%n;
			if (b[p.second]>b[l]+b[r])
			{
				memo.erase(i);
				if (a[p.second]<=b[p.second]%(b[l]+b[r]))
				{
					ans+=b[p.second]/(b[l]+b[r]);
					b[p.second]%=(b[l]+b[r]);
				}
				else
				{
					b[p.second]-=a[p.second];
					ans+=b[p.second]/(b[l]+b[r]);
					b[p.second]%=(b[l]+b[r]);
					b[p.second]+=a[p.second];
				}
				if (a[p.second]==b[p.second])
