		int pos = S.rbegin()->second;
		long long m = (long long)B[(pos + N - 1) % N] + B[(pos + 1) % N];
		if (m < B[pos] && B[pos] - m >= A[pos]) {
			S.erase(--S.end());
			if (B[pos] == A[pos]) {
				printf("-1\n");
				return 0;
			}
			int nextval = S.rbegin()->first;
		//	nextval = max(nextval, A[pos]);
			int diff = min((val - nextval) / m + 1, (val - A[pos])/m);
			int times = diff;
			if (times == 0) {
				printf("-1\n");
				return 0;
			}
			B[pos] -= m * times;
			ans += times;
			if (B[pos] == A[pos]) {
				eq++;
				if (eq == N) {
					printf("%d\n", ans);
					return 0;
				}
			}


			S.insert(make_pair(B[pos], pos));
		} else {
			printf("-1\n");
			return 0;
		}
	}
}

