const int MAX_NUM = 2 * 1e5 + 10;
vector<int> a(MAX_NUM, 0);
vector<int> b(MAX_NUM, 0);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    priority_queue<pair<int, int>, vector<pair<int,int>>, less<pair<int,int>>> pq;
    int n; cin >> n;
    for(int i=0; i<n; i++){
        cin >> a[i]; 
    }
    for(int i=0; i<n; i++){
        cin >> b[i]; 
        if(b[i] != a[i]){
            pq.push(pair<int, int>{b[i], i});
        }
    }

    int ans = 0;
    while(!pq.empty()){
        pair<int, int> maxp = pq.top(); pq.pop();
        ll m = maxp.first; int id = maxp.second;
        ll l = b[(id + n - 1) % n];
        ll r = b[(id + 1) % n];
        ll div = m / (l + r);
        if((m - a[id]) % (l + r) == 0){
            div = min(div, (m - a[id]) / (l+r));
        }
        m -= div * (l + r);
        ans += div;
        b[id] = m;
        // for(int i=0; i<n; i++){
        //     cout << b[i] << " ";
        // }
        // cout << endl;
        if(div <= 0){cout << -1 << endl; return 0;}
        if(m == a[id]){continue;}
        else if(m < a[id]){cout << -1 << endl; return 0;}
        else{
            pq.push(pair<int, int>{m, id});
        }
    }

    cout << ans << endl;
    return 0;
}

