	while(!q.empty())
	{
		int val = q.top().first;
		int id = q.top().second;

		q.pop();

		int dif = val - a[id];

		int p = b[lft(id)] + b[rht(id)];

		int k = dif / p;
		k = max(k, 1LL);

		ans += k;

		val -= k * p;

		if(val < a[id])
		{
