int A[MAX_N], B[MAX_N];

int solve()
{
  int n = 0;
  bool update;
  do
  {
    update = false;
    for (int i = 0; i < N; ++i)
    {
      int i1 = (i + 1) % N, i2 = (i + 2) % N;
      if (B[i1] - B[i] - B[i2] >= A[i1])
      {
        B[i1] -= B[i] + B[i2];
        ++n;
        update = true;
        break;
      }
    }
  } while (update);
  for (int i = 0; i < N; ++i)
  {
    if (A[i] != B[i])
    {
      return -1;
    }
  }
  return n;
}

