#define mid ((l+r)/2)
using namespace std;
int n,ans,a[222222],b[222222],t[888888];
void build(int l,int r,int p){
	if(l==r){scanf("%d",&b[l]),t[p]=b[l];return;}
	build(l,mid,p*2),build(mid+1,r,p*2+1),t[p]=max(t[p*2],t[p*2+1]);
}
void update(int l,int r,int p,int c,int v){
	if(l==r){t[p]=v;return;}
	mid>=c?update(l,mid,p*2,c,v):update(mid+1,r,p*2+1,c,v);
	t[p]=max(t[p*2],t[p*2+1]);
}
int query(int l,int r,int p){
	if(l==r)return l;
	return t[p]==t[p*2]?query(l,mid,p*2):query(mid+1,r,p*2+1);
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++)scanf("%d",&a[i]);
	build(1,n,1),b[0]=b[n],b[n+1]=b[1];
	for(int tmp=n;tmp;){
		int p=query(1,n,1),d=b[p]-a[p],k=b[p+1]+b[p-1];
		if(!d){tmp--;continue;}
		if(d<k){printf("-1");return 0;}
		ans+=d/k,b[p]=a[p]+d%k,b[0]=b[n],b[n+1]=b[1],update(1,n,1,p,a[p]==b[p]?0:b[p]);
		if(b[p]==a[p])tmp--;
	}
	printf("%d",ans);
}

#include <bits/stdc++.h>

using namespace std;

const int Nmax = 2e5 + 5;

queue<int> q;
int a[Nmax], b[Nmax];
int n; 
long long nr_op = 0;
bool inQ[Nmax];


static int nxt(int x)
{
    return (x < n ? x + 1 : 1);
}

static int prv(int x)
{
    return (x > 1 ? x - 1 : n);
}

void check(int i)
{
    if(!inQ[i] && b[i] - (b[prv(i)] + b[nxt(i)]) >= a[i])
        q.push(i), inQ[i] = 1;
}

void solve()
{
    int i;
    for(i=1; i<=n; ++i)
        check(i);

    while(q.size())
    {
        int x = q.front();
        q.pop();
        inQ[x] = 0;

        int curr = (b[x] - a[x]) / (b[prv(x)] + b[nxt(x)]);
        assert(curr);
        nr_op += curr;
        b[x] -= curr * (b[prv(x)] + b[nxt(x)]);

        check(x);
        check(nxt(x));
        check(prv(x));
    }

    for(i=1; i<=n; ++i) 
        if(a[i] != b[i]) 
        {
            cout << -1 << '\n';
            return;
        }

    cout << nr_op << '\n';
}

int main()
{
 //   freopen("input", "r", stdin);
    cin.sync_with_stdio(false); cin.tie(0);

    cin >> n;
    int i;
    for(i=1; i<=n; ++i) cin >> a[i];
    for(i=1; i<=n; ++i) cin >> b[i];

    solve();

    return 0;
}

