int main() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    REP(i, n){
        cin >> a[i];
    }
    REP(i, n){
        cin >> b[i];
    }

    ll sumx = accumulate(a.begin(), a.end(), 0LL);
    ll sumx_now = accumulate(b.begin(), b.end(), 0LL);

    priority_queue<pii> pq;
    vector<int> now = b;
    int ans = 0;

    REP(i, n){
        pq.push(make_pair(b[i], i));
    }

    while(!pq.empty() && sumx_now > sumx){
        auto top = pq.top();
        pq.pop();
        int second = pq.top().first;
        int idx_second = pq.top().second;

        int num_top = top.first;
        int idx_top = top.second;

        int num1 = now[(idx_top + 1) % n];
        int num2 = now[(idx_top + n - 1) % n];
        int num12 = num1 + num2;
        int diff = num_top - second;


        // でかいやつが隣同士で2つのときはスキップ、二度とやらない
        if((num1==num_top || num2==num_top)){
            continue;
        }

        int timestosub = diff / num12 + 1;
        if(diff % num12 == 0)
            timestosub--;

        // 通り過ぎ防止
        if(num_top - (timestosub * num12) < a[idx_top]){
            timestosub = (num_top - a[idx_top]) / num12;
        }

        // もう引けない→二度とやらない
        if(timestosub == 0)
            continue;

        int num_new = num_top - (num12 * timestosub);

        ans += timestosub;
        pq.push(make_pair(num_new, idx_top));
        now[idx_top] = num_new;
        sumx_now = sumx_now - num_top + num_new;

    }

    cout << ((sumx_now == sumx && a == now) ? ans : -1) << endl;

    return 0;
}

