		for (int j = 0; j < p && ok; j++)
		{
			if (!(s[i + j] == t[j]
				|| s[i + j] == '?' || t[j] == '?')) {
				ok = false;
			}
		}

		if (!ok) continue;
		string v = "";
		for (int j = 0; j < i; j++)
		{
			v += s[j];
		}
		for (int j = 0; j < t.size(); j++)
		{
