		y2 /= 3;
	}
	return false;
}
ll get_extra(ll x1, ll y1, ll x2, ll y2) {
	ll ans = 0;
	int i;
	ll three = 1;
	rep(i, 36) {
		if (x1 / three == x2 / three && between(x1 / three, y1 / three, y2 / three)) {
			ll tmp = min(min(x1 % three, x2 % three) + 1, three - max(x1 % three, x2 % three));
			ans = max(ans, tmp);
		}
		three *= 3;
	}
	return ans;
}
ll get_dist(ll x1, ll y1, ll x2, ll y2)
{
	return abs(x1 - x2) + abs(y1 - y2) + 2 * max(get_extra(x1, y1, x2, y2), get_extra(y1, x1, y2, x2));
}
void solv() {

	cin >> n;
	ll a[200010],b[200010];

	rep(i, n)cin >> a[i];
	rep(i, n)cin >> b[i];


	// bからaにする方が楽である
	priority_queue<pll> q;
	rep(i, n) {
		q.push(make_pair(b[i], i));
	}

	ll res = 0;
	while (!q.empty()) {

		auto p = q.top();
		q.pop();

		//両サイドの値かaの一番大きい数を取る
		int cu = p.second;
		int ne = (p.second + 1) % n;
		int be = ((p.second + n) - 1) % n;
		ll v = max({ a[cu], b[ne],b[be]});
		// 最後に操作された数
		ll ad = b[ne] + b[be];
		// vとp.firstの差を取る
		ll rm = p.first - v;
		// 操作回数
		ll cn = rm / ad;
		// 割り切れない場合はcnを一つ増やす
		if (rm % ad > 0)cn++;
		res += cn;
		ll np = p.first - cn * ad;
		if (np < a[cu]) {
			cout << -1 << endl;
			return;
		}
		b[cu] = np;
		if (np > a[cu]) {
			q.push(make_pair(np, cu));
		}
	}

	cout << res << endl;
}
