const int ComputePrev(const int N, vector<int> &values,
    multimap<int, int> &value2IndexMap, int &subtractNum)
{
    auto itr = --value2IndexMap.end();
    const int index = itr->second;
    const int prev = index - 1 < 0 ? N - 1 : index - 1;
    const int next = index + 1 >= N ? 0 : index + 1;
    const int subtract = values[prev] + values[next];
    subtractNum = max(1, values[index] / subtract);
    values[index] -= subtract * subtractNum;
    value2IndexMap.erase(itr);
    return index;
}

void Check(const int changedIndex,
    const vector<int> &As, const vector<int> &Bs,
    multimap<int, int> &value2IndexMap, int &flag)
{
    const int goal = As[changedIndex], current = Bs[changedIndex];
    // 目標値の方が下ならば続行
    if (goal < current)
    {
        value2IndexMap.insert({ current, changedIndex });
        flag = 1;
    }
    // 目標値に一致したならばフラグ＝０
    else if (goal == current)
    {
        flag = 0;
    }
    // 目標値を下回ってしまった場合は失敗
    else
    {
        flag = -1;
    }
}

int main()
{
    int N;
    cin >> N;
    vector<int> As(N), Bs(N);
    for (int i = 0; i < N; ++i) cin >> As[i];
    for (int i = 0; i < N; ++i) cin >> Bs[i];

    multimap<int, int> value2IndexMap;
    for (int i = 0; i < N; ++i)
    {
        const int Ai = As[i], Bi = Bs[i];
        if (Ai < Bi)
        {
            value2IndexMap.insert({ Bs[i], i });
        }
        else if (Ai > Bi)
        {
            cout << -1 << endl;
            return 0;
        }
    }

    int flag;
    int remained = static_cast<int>(value2IndexMap.size());
    for (int count = 0;;)
    {
        if (remained == 0)
        {
            cout << count << endl;
            break;
        }

        int subtractNum;
        const int changedIndex = ComputePrev(N, Bs, value2IndexMap, subtractNum);
        count += subtractNum;
        Check(changedIndex, As, Bs, value2IndexMap, flag);
        if (flag == 0)
        {
            --remained;
        }
        else if (flag < 0)
        {
            cout << -1 << endl;
            break;
        }
    }
}

