      B[ib] -= ac*tmp;
      cnt += tmp;
      if (B[ib] > A[ib]) pq.push(make_pair(B[ib], ib));
    }
  }
  if (A != B) cout << -1 << endl;
  else cout << cnt << endl;

  return 0;
}

