int64_t divceil(int64_t a, int64_t b) {
    return a / b + (a > 0 && a % b ? 1 : 0);
}

// O(N log N)
int main() {
    int N;
    cin >> N;
    // 頂点を探すpqueue
    priority_queue<pair<i64, int>> q;
    vector<i64> A(N), B(N);
    for(auto &x : A) cin >> x;
    for(int i = 0; i < N; i++) {
        cin >> B[i];
        if(A[i] != B[i]) {
            q.push({B[i], i});
        }
    }
    i64 ans = 0;
    // 互除法の改造
    while(!q.empty()) {
        auto x = q.top(); q.pop();
        i64 a, b, c, d; int i;
        if (!q.empty()) {
            tie(d, i) = q.top();
        } else {
            d = 0;
        }
        tie(b, i) = x;
        if(b < A[i]) {
            cout << -1 << endl;
            return 0;
        }
        c = B[(i + 1) % N];
        a = B[(i - 1 + N) % N];
        i64 S = a + c;
        int j = divceil(b - d, S);
        i64 v = B[i] - j * S;
        if(j <= 0) {
            cout << -1 << endl;
            return 0;
        }
        if(A[i] < v) {
            q.push({v, i});
            ans += j;
        } else if((A[i] - v) % S == 0) {
            ans += j - (A[i] - v) / S;
        } else {
            cout << -1 << endl;
            return 0;
        }
        B[i] = v;
    }
    cout << ans << endl;
    return 0;
}

