using namespace std;

typedef pair<int, int> P;

class CNumbersOnACircle {
public:
    static constexpr int kStressIterations = 0;

    static void generateTest(std::ostream& test) {
    }

    int calc(vector<int>& A) {
        priority_queue<pair<int, int>> pq;
        int sz = A.size();
        REP(i, sz) {
            pq.push({A[i], i});
        }
        int res = 0;
        while (!pq.empty()) {
            int val, idx;
            tie(val, idx) = pq.top();
            pq.pop();

            int l = idx > 0 ? idx - 1 : sz - 1;
            int r = idx < sz - 1 ? idx + 1 : 0;

            int bc = A[l] + A[r];
            if (A[idx] <= bc) continue;

            res += (A[idx] - 1) / bc;
            A[idx] %= bc;
            if (A[idx] == 0) A[idx] = bc;

            pq.push({A[idx], idx});
        }
        return res;
    }

    void solve(std::istream& cin, std::ostream& cout) {
        int N;
        cin >> N;
        vector<int> A(N), B(N);
        REP(i, N) cin >> A[i];
        REP(i, N) cin >> B[i];

        int a = calc(A);
        int b = calc(B);
        if (A == B && b >= a) {
            cout << b - a << endl;
        } else {
            cout << -1 << endl;
        }
    }
};


signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);

    CNumbersOnACircle solver;
    solver.solve(in, out);
    return 0;
}

