	}

	int ans = 0;
	while (1) {
		int val = S.rbegin()->first;
		int pos = S.rbegin()->second;
		long long m = (long long)B[(pos + N - 1) % N] + B[(pos + 1) % N];
		if (m < B[pos]) {
			S.erase(--S.end());
			if (B[pos] == A[pos]) {
