const int N = 3e5 + 5;
int A[N], B[N];
int main() {
    int n;
    while(~scanf("%d", &n)) {
        for(int i = 0; i < n; ++i) {
            scanf("%d", &A[i]);
        }
        for(int i = 0; i < n; ++i) {
            scanf("%d", &B[i]);
        }

        priority_queue <pair<int, int>  > Q;
        for(int i = 0; i < n; ++i) {
            if(A[i] != B[i])
                Q.push({B[i], i});
        }

        bool flag = true; int ans = 0;
        while(!Q.empty()) {
            auto tp = Q.top(); Q.pop();
            // debug(tp);
            // break;
            int neiSum =  B[ (tp.second - 1 + n) % n ] + B[ (tp.second + 1 + n) % n ] ;
            int nowB = tp.first - ceil( (tp.first - A[tp.second]) * 1.0 / neiSum) * neiSum;
            ans += ceil( (tp.first - A[tp.second]) * 1.0 / neiSum);
            if(tp.first < A[tp.second]) {
                flag = false;
                break;
            }
            // debug(tmp, tp);
            // break;
            B[tp.second] = nowB;
            if(B[tp.second] != A[tp.second]) Q.push({B[tp.second], tp.second});
        }

        if(flag == false) printf("-1\n");
        else printf("%d\n", ans);
    }
    return 0;
}

