int main()
{
    int N;
    cin >> N;
    vector<lint> A(N);
    cin >> A;
    vector<lint> B(N);
    cin >> B;
    priority_queue<plint> pq;
    REP(i, N)
    {
        if (A[i] > B[i]) NO();
        if (B[i] > A[i]) pq.emplace(B[i], i);
    }

    int ret = 0;
    while (!pq.empty())
    {
        auto pa = pq.top();
        pq.pop();

        int i = pa.second;
        lint b1 = B[(i + 1) % N], b2 = B[(i - 1 + N) % N];

        lint diff = B[i] - A[i];
        mmin(diff, B[i] - max(b1, b2));
        mmax(diff, 0LL);

        lint dec = b1 + b2;
        lint times = diff / dec - 1;
        mmax(times, 1LL);

        B[i] = B[i] - dec * times;
        if (B[i] < A[i]) NO();
        if (B[i] > A[i]) pq.emplace(B[i], i);
        ret += times;
        // dbg(B);
    }

    cout << (B == A ? ret : -1) << endl;
}

