int main() {
    int n;
    in(n);

    auto a = vin<i64>(n);
    auto b = vin<i64>(n);

    int ans = 0;

    priority_queue<pair<i64, int>> que;

    int d = 0;

    for (int i = 0; i < n; i++) {
        if (b[i] > (b[(i - 1 + n) % n] + b[(i + 1) % n]) && b[i] > a[i]) {
            que.emplace(b[i], i);
        }
    }

    while(!que.empty()) {
        i64 maxi;
        int i;

        tie(maxi, i) = que.top();
        que.pop();

        if (b[i] != maxi) {
            continue;
        }

        i64 sec = que.top().first;

        int il = (i - 1 + n) % n;
        int ir = (i + 1) % n;

        if (b[i] - (b[il] + b[ir]) < a[i]) {
            continue;
        }

        auto x = (b[il] + b[ir]);

        int k1 = b[i] / x;
        int k2 = (b[i] - a[i]) / x;

        if ((b[i] - a[i]) % x == 0 && k2 <= k1) {
            k1 = k2;
        } 

        b[i] -= x * k1;
        ans += k1;

        if (b[ir] > (b[i] + b[(ir + 1) % n]) && b[ir] > a[ir]) {
            que.emplace(b[ir], ir);
        }

        if (b[il] > (b[i] + b[(il - 1 + n) % n]) && b[il] > a[il]) {
            que.emplace(b[il], il);
        }
    }
    if (a == b) {
        out(ans);
    } else {
        out(-1);
    }
}

