#include <bits/stdc++.h>
using namespace std;

int N;
const int MAX_N = 200000;
int A[MAX_N], B[MAX_N];
set<int> U;

bool check(int i)
{
  int i_prev = (i + N - 1) % N, i_next = (i + 1) % N;
  return B[i] - B[i_prev] - B[i_next] >= A[i];
}
void check_insert(int i)
{
  if (check(i))
  {
    U.insert(i);
  }
}

int solve()
{
  U.clear();
  int res = 0;
  for (int i = 0; i < N; ++i)
  {
    if (check(i))
    {
      U.insert(i);
    }
  }
  while (!U.empty())
  {
    int i = *(U.begin());
    U.erase(i);
    int i_prev = (i + N - 1) % N, i_next = (i + 1) % N;
    B[i] -= B[i_prev] + B[i_next];
    check_insert(i_prev);
    check_insert(i);
    check_insert(i_next);
    ++res;
  }
  for (int i = 0; i < N; ++i)
  {
    if (A[i] != B[i])
    {
      return -1;
    }
  }
  return res;
}

int main()
{
  cin >> N;
  for (int i = 0; i < N; ++i)
  {
    cin >> A[i];
  }
  for (int i = 0; i < N; ++i)
  {
    cin >> B[i];
  }
  cout << solve() << endl;
  return 0;
}

