	for (int i = 0; i < n; i++)
	{
		cin >> newArr[i];
	}
	for (int i = 0; i < n; i++)
	{
		pq.push(i);
	}
	int elementsLeft = n;
	ll result = 0;
	while (elementsLeft > 0)
	{
		int u = pq.top();
		pq.pop();
