int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int N; cin >> N;
  vector<ll> A(N); rep(i, N) cin >> A[i];
  vector<ll> B(N); rep(i, N) cin >> B[i];
  priority_queue<pair<ll, int>> q;
  rep(i, N) {
    if (A[i] < B[i]) q.emplace(B[i], i);
    if (A[i] > B[i]) {
      cout << -1 << endl;
      return 0;
    }
  }
  int ans = 0;
  while (!q.empty()) {
    int i = q.top().second; q.pop();
    ll x = B[(i - 1 + N) % N];
    ll z = B[(i + 1) % N];
    // B[i] - k*(x+z) >= u && B[i] - k*(x+z) >= A[i]
    // (B[i] - u) / (x + z)
    ll k1 = (B[i] - A[i]) / (x + z);
    ll k2 = (B[i] - max(x, z) - 1) / (x + z) + 1;
    ll k = min(k1, k2);
    if (k <= 0) k = 1;
    B[i] -= k * (x + z);
    ans += k;
    if (B[i] < A[i]) {
      cout << -1 << endl;
      return 0;
    }
    if (B[i] > A[i]) {
      q.emplace(B[i], i);
    }
  }
  cout << ans << endl;
}

