void down(int x){
	int i=x;
	if (x*2<=l&&b[f[x]]<b[f[x*2]])i=x*2;
	if (x*2<l&&b[f[i]]<b[f[x*2+1]])i=x*2+1;
	if (i!=x){
		swap(f[x],f[i]);
		down(i);
	}
}
