    }
    REP(i,n){
        cin>>b[i];
    }

    PQ_DESC_VL pq;
    REP(i,n){
        pq.push({b[i],i});
    }

    LL result = 0;

    while(!pq.empty()){
        LL now = pq.top()[0];
        LL idx = pq.top()[1];
        pq.pop();

        if(now == a[idx]){
            continue;
        }

        LL target = a[idx];
        if(!pq.empty()){
            target = max(target, pq.top()[0]);
        }

        if(now == a[idx]){
            continue;
        }
        if(now < a[idx]){
            cout<<-1<<endl;
            return;
        }

        LL prev_idx = (idx-1+n)%n;
