#define N 2666666
struct str{
	int val;
	int id;
	 bool operator < (const str &b)const
	 {
	 	return val<b.val;
	 } 
};
int a[N],b[N],arr[N];
priority_queue<str> q;
signed main(){
	int n;
	scanf("%lld",&n);
	for(int i=1;i<=n;i++){
		scanf("%lld",&a[i]);
		arr[i]=a[i];
	} 
	int f=1;
	for(int i=1;i<=n;i++){
		scanf("%lld",&b[i]);
		if(b[i]<a[i]) f=0;
		q.push((str){b[i],i});
	} 
	if(!f){
		cout<<"-1";
		return 0; 
	}
	f=1;
	int ans=0;
	while(!q.empty()){
		struct str t=q.top();
		q.pop();
		int id=t.id;
		if(id==1){
			int temp=b[t.id+1]+b[n];
			if(t.val==a[id]){
				continue;
			}
			if(t.val-temp<a[id]){
				f=0;
			}
			if(a[id+1]==b[id+1]&&a[n]==b[n]){
				if((t.val-a[id])%(a[n]+a[id+1])){
					f=0;
				}else{
					ans+=(t.val-a[id])/(a[n]+a[id+1]);
				}
			}else{
				ans++;
				b[id]-=temp;
				if(b[id]!=a[id])
					q.push((str){b[id],t.id});		
			}

		}else if(id==n){
			int temp=b[t.id-1]+b[1];
			if(t.val==a[id]){
				continue;
			}
			if(t.val-temp<a[id]){
				f=0;
			}
			if(a[1]==b[1]&&a[id-1]==b[id-1]){
				if((t.val-a[id])%(a[1]+a[id-1])){
					f=0;
				}else{
					ans+=(t.val-a[id])/(a[1]+a[id-1]);
				}
			}else{
				ans++;
				b[id]-=temp;
				if(b[id]!=a[id])
					q.push((str){b[id],t.id});			
			}

		}else{
			if(t.val==a[id]){
				continue;
			}
			int temp=b[t.id-1]+b[1+t.id];
			if(t.val-temp<a[id]){
				f=0;
			}
			if(a[1+id]==b[id+1]&&a[id-1]==b[id-1]){
				if((t.val-a[id])%(a[1+id]+a[id-1])){
					f=0;
				}else{
					ans+=(t.val-a[id])/(a[1+id]+a[id-1]);
				}
			}else{
				ans++;
				b[id]-=temp;
				if(b[id]!=a[id])
					q.push((str){b[id],t.id});
			}
		}
		if(!f){
			break;
		}
	}
	if(!f) cout<<"-1";else cout<<ans;
	return 0;
}

