using namespace std;

int n,a[200001], b[200001];
priority_queue< pair<int, int> > q;

int main(){
  scanf("%d",&n);

  for(int i = 0;i < n;++i)
    scanf("%d", &a[i]);

  for(int i = 0;i < n;++i)
    scanf("%d", &b[i]);

  for(int i = 0;i < n;++i){
    q.push(make_pair(b[i], i));
  }

  int ans = 0;

  while(!q.empty() && ans != -1){
    pair<int, int> cur = q.top();
    q.pop();

    if(cur.first != a[cur.second]){
      int pos1 = cur.second - 1;
      int pos2 = cur.second + 1;
      if(pos1 < 0) pos1 += n;
      if(pos2 >= n) pos2 -= n;

      b[cur.second] -= b[pos1] + b[pos2];

      if(b[cur.second] < a[cur.second]) ans = -1;
      else{
        q.push(make_pair(b[cur.second], cur.second));
        ++ans;
      }
    }
  }

  printf("%d\n", ans);

  return 0;
}

