    ll n,A[200001],B[200001];
    cin>>n;
    rep(i,n) cin>>A[i];
    rep(i,n) cin>>B[i];
    ll C[200001]={0};
    rep(i,n) C[i]=B[(i-1+n)%n]+B[(i+1)%n];
    queue<int> que;
    rep(i,n) if(C[i]<=B[i]) que.push(i);
    ll ans=0;
    while(!que.empty()){
        int a=que.front();
        que.pop();
        if(C[a]>B[a]||A[a]==B[a]) continue;
