        if(C[(a-1+n)%n]<=B[(a-1+n)%n]) que.push((a-1+n)%n);
        if(C[(a+1)%n]<=B[(a+1)%n]) que.push((a+1)%n);
    }
    int x=1;
    rep(i,n) if(A[i]!=B[i]) x=0;
