int A[200005],B[200005];
struct node
{
	int r,v;
	node(int r,int v):r(r),v(v){}
	bool operator < (const node& rhs) const
	{
		return v < rhs.v;
	}
};
priority_queue<node> q;
int main()
{
	int N;
	scanf("%d",&N);
	ll cnt = 0;int cnt2 = 0;
	for(int i = 1;i <= N;i ++)
		scanf("%d",&A[i]);
	for(int i = 1;i <= N;i ++)
		scanf("%d",&B[i]),cnt2 += (A[i] == B[i]),q.push(node(i,B[i]));
	while(true)
	{
		if(cnt2 == N)
		{
			printf("%lld\n",cnt);
			return 0;
		}
		if(q.empty())
		{
			printf("-1\n");
			return 0;
		}
		node t = q.top();q.pop();
		int i0 = t.r == 1?N:t.r-1;
		int i1 = t.r;
		int i2 = t.r == N?1:t.r+1;
		if(B[i1] < A[i1])
		{
			printf("-1\n");
			return 0;
		}
		if(B[i1] == A[i1])
		{
			cnt2 ++;
			continue;
		}
		if(B[i1]-A[i1] < B[i0]+B[i2])
		{
			printf("-1\n");
			return 0;
		}
		int rm = (B[i1]-A[i1])/(B[i0]+B[i2]);
		cnt += rm;B[i1] -= rm*(B[i0]+B[i2]);
		q.push(node(i1,B[i1]));
	}
	return 0;
}

