    cin.tie(0);

    ll n;
    in >> n;
    ll a[n];
    ll b[n];
    REP(i, n){
        in >> a[i];
    }
    REP(i, n){
        in >> b[i];
    }
    priority_queue<pair<ll, ll> > q;
    ll cnt = 0;
    REP(i, n){
        q.push(lp(b[i], i));
    }

    ll idx, p_idx, n_idx;
    ll minus, times;

    while(!q.empty()){
        idx = q.top().second;
        q.pop();

        if(b[idx] == a[idx]) continue;
        p_idx = idx - 1;
        n_idx = idx + 1;
        if(p_idx == -1) p_idx = n - 1;
        if(n_idx == n) n_idx = 0;

        times = 1;
        minus = b[p_idx] + b[n_idx];
        if(b[idx] - minus <= 0){
            out << "-1" << endl;
            return 0;
        }
        ll t1 = ll(ceil((b[idx] - max(b[p_idx], b[n_idx])) / double(minus)));
        times = max(times, t1);
        if(!q.empty()){
            ll t2 = ll(ceil((b[idx] - q.top().first) / double(minus)));
            times = max(times, min(t1, t2));
        }

        b[idx] -= minus * times;
        if(b[idx] < a[idx]){
            b[idx] += minus;
            times -= 1;
        }
        // out << idx << " " << b[idx] << endl;
        cnt += times;

        if(b[idx] == a[idx]){
            continue;
        }else{
            q.push(lp(b[idx], idx));
        }
    }
    out << cnt << endl;
