ll N;
ll A[200010], B[200010];
std::priority_queue<P> pque;
ll ans;

int main()
{
  std::cin >> N;

  rep( i, N )
    std::cin >> A[i];

  rep( i, N )
  {
    std::cin >> B[i];

    if( A[i] < B[i] )
      pque.emplace( B[i], i );
  }

  while( !pque.empty() )
  {
    P p = pque.top(); pque.pop();
    ll idx = p.second;

    ll mod = B[(idx-1+N)%N]+B[(idx+1)%N];

    if( B[idx]-A[idx] >= mod )
    {
      ans += (B[idx]-A[idx])/mod;
      B[idx] = A[idx] + (B[idx]-A[idx]) % mod;

      if( B[idx] > A[idx] )
        pque.emplace( B[idx], idx );
    }
  }

  rep( i, N ) if( A[i] != B[i] )
  {
    std::cout << -1 << std::endl;

    return 0;
  }

  std::cout << ans << std::endl;

  return 0;
}

