int main(){
  auto end=[](){cout<<-1<<endl; exit(0);};
  ll N;
  cin>>N;
  vector<ll> A(N),B(N);
  cin>>A>>B;
  auto sum=[&](ll idx)->ll{return B[(idx+N-1)%N]+B[(idx+1)%N];};
  auto good=[&](ll idx)->bool{return B[idx]>A[idx] && B[idx]>sum(idx);};
  queue<ll> Q;
  for(int i=0;i<N;i++){
    if(B[i]<A[i]){end();}
    if(B[i]>A[i] && B[i]>sum(i)){Q.push(i);}
  }
  ll ans=0;
  while(!Q.empty()){
    ll idx=Q.front(); Q.pop();
    ll s=sum(idx);
    ll k=(B[idx]-A[idx])/s;
    ans+=k;
    B[idx]-=s*k;
    if(good((idx+1)%N)){Q.push((idx+1)%N);}
    if(good((idx+N-1)%N)){Q.push((idx+N-1)%N);}
  }
  if(A==B){cout<<ans<<endl;}
  else{cout<<-1<<endl;}


  return 0;
}

