int main()
{
    int n;
    cin >> n;
    ll a[200002], b[200002];
    priority_queue<P> que;
    for(int i = 0; i < n; i++) cin >> a[i];
    for(int i = 0; i < n; i++){
        cin >> b[i];
        que.push(P(b[i], i));
    }
    ll ans = 0;
    int count = 0;
    while(!que.empty()){
        P now = que.top();
        que.pop();
        int num = now.second;
        if(b[num] < a[num]){
            cout << -1 << endl;
            return 0;
        }
        if(b[num] == a[num]) continue;
        ll lr = b[(num + n - 1) % n] + b[(num + 1) % n];
        ans += ((b[num] - a[num]) / lr);
        b[num] -= ((b[num] - a[num]) / lr) * lr;
        now.first = b[num];
        que.push(P(b[num], num));
        count++;
        if(count > 5000000){
            cout << -1 << endl;
            return 0;
        }
    }
    bool able = true;
    for(int i = 0; i < n; i++){
        if(a[i] != b[i]) able = false;
    }
    if(able) cout << ans << endl;
    else cout << -1 << endl;
}

