  for (int i = 0; i < n; ++i) {
    if (b[i] > a[i]) {
      b_set.emplace(b[i], i);
    }
  }

  ll num_ops = 0;
  while (!b_set.empty()) {
    int val, loc;
    tie(val, loc) = *b_set.rbegin();
    debug(val, loc, a, b);
    b_set.erase(prev(b_set.end()));
    assert(val > a[loc]);

    const ll x = b[(loc+n-1)%n];
