    }

    const int bound = max<ll>({a[loc], x - diff, y - diff});
    const int max_steps = (b[loc] - bound) / diff;
    num_ops += max_steps;
    b[loc] -= max_steps * diff;
    if (b[loc] > a[loc]) {
