int64_t judge(int n, int *a, int *b) {
	for (int i = 0; i < n; i++) if (a[i] > b[i]) return -1;
	std::set<int> all;
	for (int i = 0; i < n; i++) {
		int prev = (i - 1 + n) % n;
		int next = (i + 1) % n;
		int sum = b[prev] + b[next];
		if (b[i] > sum) all.insert(i);
	}
	int64_t res = 0;
	while (all.size()) {
		int i = *all.begin();
		all.erase(i);
		int prev = (i - 1 + n) % n;
		int next = (i + 1) % n;
		int sum = b[prev] + b[next];
		if (b[i] >= sum) {
			int yo = b[i] - a[i];
			res += yo / sum;
			b[i] -= yo / sum * sum;
			int pprev = (prev - 1 + n) % n;
			int nnext = (next + 1) % n;
			if (b[prev] > b[pprev] + b[i]) all.insert(prev);
			if (b[next] > b[nnext] + b[i]) all.insert(next);
		}
	}
	for (int i = 0; i < n; i++) if (a[i] != b[i]) return -1;
	return res;
}


