// 優先度付きキュー Priority Queue
// 最大を保持
// 二分ヒープで実装
typedef struct 
{
    int64_t pri;
    int64_t val;
}que;
que pq[2*MAXN+1];
int pq_size=0;

void PQadd(int64_t pri, int64_t val)
{
    pq_size++;
    pq[pq_size].pri = pri;
    pq[pq_size].val = val;
    int i = pq_size;
    while( (i>1) && (pq[i].pri > pq[i/2].pri))
    {
        que temp;
        temp = pq[i];
        pq[i] = pq[i/2];
        pq[i/2] = temp;
        i /= 2;
    }
}

que PQget(void)
{
    que ret;
    ret = pq[1];
    pq[1] = pq[pq_size];
    pq_size--;

    int i = 1;
    while(i*2 <= pq_size) // 葉ならやめる
    {
        int j;
        if(i*2 == pq_size) //左の子しかいない
        {
            j = i*2;
        }else
        {
            j = pq[i*2].pri > pq[i*2+1].pri ? i*2 : i*2+1;
        }

        if(pq[i].pri < pq[j].pri)
        {
            que temp;
            temp = pq[i];
            pq[i] = pq[j];
            pq[j] = temp;
            i = j;
        }else
        {
            break;
        }

    }

    return ret;
}

