  int itr=1,itr2,flag;
  H->length--;
  flag=flag_heap_univ(H,itr,temp);
  while(flag){
    itr2=2*itr+flag-1;
    H->cells[itr]=H->cells[itr2];
    itr=itr2;
    flag=flag_heap_univ(H,itr,temp);
  }
  H->cells[itr]=temp;
  return x;
}

int flag_heap_univ(heap* H, int itr,cell temp){
