    flag=(compare_cell(temp,H->cells[itr*2])?0:1);
  else if(compare_cell(H->cells[itr*2],H->cells[itr*2+1]))
    flag=(compare_cell(temp,H->cells[itr*2])?0:1);
  else flag=(compare_cell(temp,H->cells[itr*2+1])?0:2);

  //  printf("%d ",flag);
  return flag;
}



