        if (b[i] > a[i]) {
            val d = b[(n + i - 1) % n] + b[(i + 1) % n]
            val c = (b[i] - a[i]) / d
            if (c == 0) {
                ans = -1
                break
            }
            ans += c
            b[i] -= c*d
            q.add(Pair(i, b[i]))
        }
    }
    kout.println(ans)
}

