public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];

        for (int i = 0; i < N; i++) A[i] = sc.nextInt();
        for (int i = 0; i < N; i++) B[i] = sc.nextInt();

        LinkedList<Integer> indices = new LinkedList<>();

        for (int i = 0; i < N; i++) {
            int prev = i > 0 ? i - 1 : N - 1;
            int next = i < N - 1 ? i + 1 : 0;
            if (B[i] > A[i] && B[i] > B[prev] + B[next]) indices.add(i);
        }

        int sol = 0;

        while (!indices.isEmpty()) {
            int i = indices.pollLast();
            int prev = i > 0 ? i - 1 : N - 1;
            int next = i < N - 1 ? i + 1 : 0;
            int prevprev = prev > 0 ? prev - 1 : N - 1;
            int nextnext = next < N - 1 ? next + 1 : 0;

            if ((B[i] - A[i]) % (B[prev] + B[next]) == 0) {
                sol += (B[i] - A[i]) / (B[prev] + B[next]);
                B[i] = A[i];
            } else {
                int times = Math.min(B[i] / (B[prev] + B[next]), (B[i] - Math.max(B[prev], B[next])) / (B[prev] + B[next]) + 1);
                sol += times;
                B[i] -= times * (B[prev] + B[next]);
            }

            if (B[prev] > A[prev] && B[prev] > B[i] + B[prevprev]) indices.addLast(prev);
            if (B[next] > A[next] && B[next] > B[i] + B[nextnext]) indices.addLast(next);
        }

        for (int i = 0; i < N; i++) {
            if (A[i] != B[i]) {
                sol = -1;
                break;
            }
        }

        System.out.println(sol);
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        B = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        PriorityQueue<int[]> q = new PriorityQueue<>(Comparator.comparingInt(ib -> -ib[1]));
        for (int i = 0; i < N; i++) {
            q.add( new int[]{i, B[i]} );
        }

        int cnt = 0;
        while(!q.isEmpty()) {

            int[] ib = q.poll();
            int idx = ib[0];
            int b = ib[1];

            if( b == A[idx] ) continue;

            // B[idx] = B[idx-1] + B[idx] + B[idx+1]
            int b0 = B[(idx-1+N)%N];
            int b2 = B[(idx+1+N)%N];
            int b1 = b - b0 - b2;
            if( b1 < A[idx] ) return -1;

            B[idx] = b1;
            q.add( new int[]{idx, b1} );

            cnt++;
        }
        return cnt;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

