class Pair{
	Long x;
	Integer idx; //値と、bにおける添字

	public Pair(long x, int idx) {
		super();
		this.x = x;
		this.idx = idx;
	}

}

public class Main {
	static void solve() {
		int n = ni();
		long a[] = nla(n), b[] = nla(n);

		PriorityQueue<Pair> pq = new PriorityQueue<>((p1, p2)->p2.x.compareTo(p1.x));
		for(int i=0;i<n;i++) {
			pq.add(new Pair(b[i], i));
		}

		int cnt = 0;
		while(!pq.isEmpty()) {
			Pair t = pq.poll();
			long memo = t.x;
			int bIdx = t.idx - 1; if(bIdx < 0)bIdx += n;
			int aIdx = t.idx + 1; if(aIdx >= n) aIdx -= n;
			long sum = b[bIdx] + b[aIdx];
			long rem = t.x % sum;
			long pro = t.x / sum;
			cnt += pro;
			t.x = rem;
			b[t.idx] = t.x;
			if(b[t.idx] < a[t.idx]) {
				out.println(-1);
				return;
			}
			if(b[t.idx] == a[t.idx]) {
				continue;
			}
			if(memo == t.x) {
				out.println(-1);
				return;
			}
			pq.add(t);
		}
		out.println(cnt);
	}

