public class Main {
  private static void solve() {
    int n = ni();
    long[] a = nal(n);
    long[] b = nal(n);

    int ret = 0;
    TreeSet<Integer> q = new TreeSet<>((o1, o2) -> {
      long l1 = b[(o1 - 1 + n) % n];
      long r1 = b[(o1 + 1) % n];
      long l2 = b[(o2 - 1 + n) % n];
      long r2 = b[(o2 + 1) % n];

      return Long.signum((b[o2] - (l2 + r2)) - (b[o1] - (l1 + r1)));
    });

    int same = 0;
    for (int i = 0; i < n; i++) {
      if (a[i] == b[i]) {
        same++;
      } else {
        q.add(i);
      }
    }

    while (same < n) {
      int i = q.pollFirst();
      int l = (i - 1 + n) % n;
      int r = (i + 1) % n;

      if (b[i] - b[l] - b[r] < a[i]) {
        System.out.println(-1);
        return;
      }
      q.remove(l);
      q.remove(r);
      q.remove(i);
      b[i] -= b[l] + b[r];
      q.add(l);
      q.add(r);
      ret++;
      if (b[i] == a[i]) {
        same++;
      } else {
        q.add(i);
      }
    }
    System.out.println(ret);
  }

