public class Main {
    public static class Task {

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int[] A = new int[n];
            int[] B = new int[n];
            for (int i = 0; i < n; i++) {
                A[i] = sc.nextInt();
            }
            for (int i = 0; i < n; i++) {
                B[i] = sc.nextInt();
            }
            if (Arrays.equals(A, B)) {
                pw.println(0);
                return;
            }
            boolean[] eq = new boolean[n];
            int eqCount = 0;
            for (int i = 0; i < n; i++) {
                eq[i] = A[i] == B[i];
                eqCount += eq[i] ? 1 : 0;
                if (A[i] > B[i]) {
                    pw.println(-1);
                    return;
                }
            }
            PriorityQueue<int[]> bPQ = new PriorityQueue<>(new Comparator<int[]>() {
                @Override
                public int compare(int[] o1, int[] o2) {
                    return -o1[0] + o2[0];
                }
            });
            for (int i = 0; i < n; i++) {
                bPQ.add(new int[]{B[i], i});
            }
            long steps = 0;
            while (eqCount < n) {
                int[] entry = bPQ.poll();
                int index = entry[1];
                int prevVal = B[(index + n - 1) % n];
                int nextVal = B[(index + 1) % n];
                int decreOnce = prevVal + nextVal;
                int atMostDecre = (entry[0] - A[index]) / decreOnce;
                if (atMostDecre <= 0) {
                    pw.println(-1);
                    return;
                }
                steps += atMostDecre;
                int curVal = entry[0] - atMostDecre * decreOnce;
                B[index] = curVal;
                if (curVal == A[index]) {
                    eqCount++;
                }
                bPQ.add(new int[]{curVal, index});
            }
            pw.println(steps);
        }
    }

