import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        B = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        // a + b + c = b'
        // なので必ず前後より大きいのでそういうやつから処理していけばよい、はず

        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int idx = 0; idx < N; idx++) {
            if( isTarget(idx) ) {
                q.add(idx);
            }
        }

        int cnt = 0;
        while(!q.isEmpty()) {
            int idx = q.poll();
            int b = B[idx];

            // B[idx] = B[idx] + n(B[idx-1] + B[idx+1])
            int idx0 = (idx-1+N)%N;
            int idx2 = (idx+1)%N;
            int b0 = B[idx0];
            int b2 = B[idx2];
            // aより小さくならないところまで引く
            int d = (b-A[idx]) / (b0+b2);
            int b1 = b - d * (b0 + b2);

            B[idx] = b1;
            cnt += d;

            // 前後も対象になった可能性があるので調べる
            if( isTarget(idx) ) {
                q.add(idx);
            }
            if( isTarget(idx0) ) {
                q.add(idx0);
            }
            if( isTarget(idx2) ) {
                q.add(idx2);
            }
        }

        // 最後にcheck
        for (int i = 0; i < N; i++) {
