      int l1 = b[(o1 - 1 + n) % n];
      int r1 = b[(o1 + 1) % n];
      int l2 = b[(o2 - 1 + n) % n];
      int r2 = b[(o2 + 1) % n];

      return (b[o2] - (l2 + r2)) - (b[o1] - (l1 + r1));
    });

