    int max = 0;
    for(int i = 1; i < n; i++){
      if(array[i] > array[max]){
        max = i;
      }
    }
    return max;
  }

  public static void main(String[] args){
    Scanner scanner = new Scanner(System.in);
    int n = scanner.nextInt();
    int[] a = new int[n];
    int[] aa = new int[n];
    int[] b = new int[n];
    int[] bb = new int[n];
    int[] c = new int[n];
    int[] c_index = new int[n];
    int index = 0;
    int achieved = 0;
    int step = 0;
    for(int i = 0; i < n; i++){
      int tmp = scanner.nextInt();
      a[i] = tmp;
      aa[i] = tmp;
    }
    for(int i = 0; i < n; i++){
      int tmp = scanner.nextInt();
      b[i] = tmp;
      bb[i] = tmp;
      c[i] = tmp;
      c_index[i] = i;
    }

    for(int i = n-1; i > 0; i--){
      for(int j = 0; j < i; j++){
        if(c[j] < c[j+1]){
          c[j] ^= c[j+1];
          c[j+1] ^= c[j];
          c[j] ^= c[j+1];

          c_index[j] ^= c_index[j+1];
          c_index[j+1] ^= c_index[j];
          c_index[j] ^= c_index[j+1];
        }
      }
    }

    while(true){
      int max = c_index[index];
      if(a[max] == bb[max]){
        bb[max] = -1;
        index++;
        achieved++;
      }else{
        bb[max] -= b[(max-1)>=0?max-1:n-1];
        bb[max] -= b[(max+1)<n?max+1:0];
        b[max] = bb[max];
        c[index] = b[max];
        if(bb[max] < a[max]){
          step = -1;
          break;
        }else if(bb[max] == a[max]){
          bb[max] = -1;
          index++;
          achieved++;
        }
      }

      for(int j = index; j < n-1; j++){
        if(c[j] < c[j+1]){
          c[j] ^= c[j+1];
          c[j+1] ^= c[j];
          c[j] ^= c[j+1];

          c_index[j] ^= c_index[j+1];
          c_index[j+1] ^= c_index[j];
          c_index[j] ^= c_index[j+1];
        }else{
          break;
        }
      }

      step++;
      if(achieved == n){
        break;
      }
    }

    System.out.println(step);
  }
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];

        for (int i = 0; i < N; i++) A[i] = sc.nextInt();
        for (int i = 0; i < N; i++) B[i] = sc.nextInt();

        LinkedList<Integer> indices = new LinkedList<>();

        for (int i = 0; i < N; i++) {
            int prev = i > 0 ? i - 1 : N - 1;
            int next = i < N - 1 ? i + 1 : 0;
            if (B[i] > A[i] && B[i] > B[prev] + B[next]) indices.add(i);
        }

        int sol = 0;

        while (!indices.isEmpty()) {
            int i = indices.pollLast();
            int prev = i > 0 ? i - 1 : N - 1;
            int next = i < N - 1 ? i + 1 : 0;
            int prevprev = prev > 0 ? prev - 1 : N - 1;
            int nextnext = next < N - 1 ? next + 1 : 0;

            if ((B[i] - A[i]) % (B[prev] + B[next]) == 0) {
                sol += (B[i] - A[i]) / (B[prev] + B[next]);
                B[i] = A[i];
            } else {
                int times = Math.min(B[i] / (B[prev] + B[next]), (B[i] - Math.max(B[prev], B[next]) + 1));
                sol += times;
                B[i] -= times * (B[prev] + B[next]);
            }

            if (B[prev] > A[prev] && B[prev] > B[i] + B[prevprev]) indices.addLast(prev);
            if (B[next] > A[next] && B[next] > B[i] + B[nextnext]) indices.addLast(next);
        }

        for (int i = 0; i < N; i++) {
            if (A[i] != B[i]) {
                sol = -1;
                break;
            }
        }

        System.out.println(sol);
    }
}

import java.util.TreeSet;

public class Main {
  private static void solve() {
    int n = ni();
    long[] a = nal(n);
    long[] b = nal(n);

    TreeSet<Integer> q = new TreeSet<>((o1, o2) -> {
      long l1 = b[(o1 - 1 + n) % n];
      long r1 = b[(o1 + 1) % n];
      long l2 = b[(o2 - 1 + n) % n];
      long r2 = b[(o2 + 1) % n];

      return Long.signum((b[o2] - (l2 + r2)) - (b[o1] - (l1 + r1)));
    });

    int same = 0;
    for (int i = 0; i < n; i++) {
      if (a[i] == b[i]) {
        same++;
      } else {
        q.add(i);
      }
    }

    long ret = 0;
    while (same < n) {
      int i = q.pollFirst();
      int l = (i - 1 + n) % n;
      int r = (i + 1) % n;

      if (b[i] - b[l] - b[r] < a[i]) {
        System.out.println(-1);
        return;
      }
      q.remove(l);
      q.remove(r);
      q.remove(i);
      long sum = b[l] + b[r];
      long x = (b[i] - a[i]) / sum;
      ret += x;
      b[i] -= x * sum;
      q.add(l);
      q.add(r);
      if (b[i] == a[i]) {
        same++;
      } else {
        q.add(i);
      }
    }
    System.out.println(ret);
  }

