    static class CNumbersOnACircle {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = in.readIntArray(n);
            int[] b = in.readIntArray(n);

            PriorityQueue<IntIntPair> q = new PriorityQueue<>(Comparator.reverseOrder());
            for (int i = 0; i < n; i++) {
                if (b[i] > a[i]) q.add(new IntIntPair(b[i], i));
            }

            long ans = 0;
            while (!q.isEmpty()) {
                IntIntPair p = q.poll();
                int val = p.first;
                int idx = p.second;
                int sum = b[(idx - 1 + n) % n] + b[(idx + 1) % n];
                int times = (val - Math.max(sum, a[idx]) + sum - 1) / sum;
                if (times == 0) {
                    out.printLine(-1);
                    return;
                }
                val -= times * sum;
                ans += times;
                b[idx] = val;
                if (val > a[idx]) q.add(new IntIntPair(val, idx));
            }

            for (int i = 0; i < n; i++) {
                if (a[i] != b[i]) {
                    out.printLine(-1);
                    return;
                }
            }

            out.printLine(ans);
        }

    }

