import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;
import java.util.Collections;
import java.util.Arrays;
import java.lang.Math;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Main {
    static class Count {
        public int index   = 0;
        public int current = 0;

        public Count(int index, int current) {
            this.index   = index;
            this.current = current;
        }

        public int compareTo(Count c) {
            return this.current - c.current;
        }
    }

	public static void main(String[] args) {
		FS reader = new FS();
		// write reader
		int N = reader.nextInt();
		int[] A = new int[N];
		int[] B = new int[N];
		for(int i=0; i<N; i++) {
		    A[i] = reader.nextInt();
		}
		for(int i=0; i<N; i++) {
		    B[i] = reader.nextInt();
		}
		solver(N, A, B);
	}

	public static void solver(int N, int[] A, int[] B) {
		// write logic
		Comparator<Count> cmp = new Comparator<Count>() {
		    @Override
		    public int compare(Count c1, Count c2) {
		        return -c1.compareTo(c2);
		    }
		};

		PriorityQueue<Count> pq = new PriorityQueue<Count>(cmp);
		for(int i=0; i<N; i++) {
		    Count tmp = new Count(i, B[i]);
		    pq.add(tmp);
		}

		int ans = 0;
		while(pq.size() > 0) {
		    Count nxt = pq.poll();
		    if (nxt.current == A[nxt.index]) continue;
		    while(true) {
		        int dif = B[(N+nxt.index-1)%N]+B[(N+nxt.index+1)%N];
    		    nxt.current -= dif;
    		    B[nxt.index] = nxt.current;
    		    ans++;
    		    if (nxt.current <= A[nxt.index] || nxt.current <= dif) break;
		    }
		    if (nxt.current < A[nxt.index]) {
		        ans = -1;
		        break;
		    }
		    if (nxt.current == A[nxt.index]) continue;
		    pq.add(nxt);
		}
		System.out.println(ans);
	}

	// Read Class
	static class FS {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
		private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
		private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

		public boolean hasNext() { skipUnprintable(); return hasNextByte();}
		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while(isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}
		public int nextInt() {
			return (int)nextLong();
		}
		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while(true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if(b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        B = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        // a + b + c = b'
        // なので必ず前後より大きいのでそういうやつから処理していけばよい、はず

        PriorityQueue<Integer> q = new PriorityQueue<>(Comparator.comparingInt(idx -> -B[idx]));
        for (int idx = 0; idx < N; idx++) {
            if( isTarget(idx) ) {
                q.add(idx);
            }
        }

        int cnt = 0;
        while(!q.isEmpty()) {
            int idx = q.poll();
            int b = B[idx];

            // B[idx] = B[idx-1] + B[idx] + B[idx+1]
            int idx0 = (idx-1+N)%N;
            int idx2 = (idx+1)%N;
            int b0 = B[idx0];
            int b2 = B[idx2];
            int b1 = b - b0 - b2;
            B[idx] = b1;
            cnt++;

            // 前後も対象になった可能性があるので調べる
            if( isTarget(idx) ) {
                q.add(idx);
            }
            if( isTarget(idx0) ) {
                q.add(idx0);
            }
            if( isTarget(idx2) ) {
                q.add(idx2);
            }
        }

        // 最後にcheck
        for (int i = 0; i < N; i++) {
            if( A[i] != B[i] ) return -1;
        }

        return cnt;
    }

    static boolean isTarget(int idx) {
        int b = B[idx];
        int b0 = B[(idx-1+N)%N];
        int b2 = B[(idx+1)%N];

        if( b <= b0 || b <= b2 ) return false;

        int b1 = b - b0 - b2;

        if( b1 < A[idx] ) return false;
        return true;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

