public class Main {
    public static class Task {

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int[] A = new int[n];
            int[] B = new int[n];
            for (int i = 0; i < n; i++) {
                A[i] = sc.nextInt();
            }
            for (int i = 0; i < n; i++) {
                B[i] = sc.nextInt();
            }
            if (Arrays.equals(A, B)) {
                pw.println(0);
                return;
            }
            boolean[] eq = new boolean[n];
            int eqCount = 0;
            for (int i = 0; i < n; i++) {
                eq[i] = A[i] == B[i];
                eqCount += eq[i] ? 1 : 0;
            }
            PriorityQueue<int[]> bPQ = new PriorityQueue<>(new Comparator<int[]>() {
                @Override
                public int compare(int[] o1, int[] o2) {
                    return -o1[0] + o2[0];
                }
            });
            for (int i = 0; i < n; i++) {
                bPQ.add(new int[]{B[i], i});
            }
            int steps = 0;
            while (eqCount < n) {
                int[] entry = bPQ.poll();
                int prevVal = B[(entry[1] + n - 1) % n];
                int nextVal = B[(entry[1] + 1) % n];
                int curVal = entry[0] - prevVal - nextVal;
                B[entry[1]] = curVal;
                if (curVal == A[entry[1]]) {
                    eqCount++;
                } else if (curVal < A[entry[1]]) {
                    pw.println(-1);
                    return;
                }
                bPQ.add(new int[]{curVal, entry[1]});
                steps++;
            }
            pw.println(steps);
        }
    }

    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
//        Scanner sc = new Scanner(new FileInputStream("input"));
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
//        PrintWriter pw = new PrintWriter(new FileOutputStream("output"));

        Runtime runtime = Runtime.getRuntime();
        long usedMemoryBefore = runtime.totalMemory() - runtime.freeMemory();
        TIME_START = System.currentTimeMillis();
        Task t = new Task();
        t.solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long usedMemoryAfter = runtime.totalMemory() - runtime.freeMemory();
        pw.close();
        System.err.println("Memory increased: " + (usedMemoryAfter - usedMemoryBefore) / 1000000);
        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

