import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class Main {
  private static void solve() {
    int n = ni();
    long[] a = nal(n);
    long[] b = nal(n);

    Deque<Integer> q = new ArrayDeque<>();

    for (int i = 0; i < n; i++) {
      q.add(i);
    }

    long ret = 0;
    while (q.size() > 0) {
      int i = q.pollFirst();
      int l = (i - 1 + n) % n;
      int r = (i + 1) % n;

      if (b[i] < a[i]) {
        System.out.println(-1);
        return;
      }

      long sum = b[l] + b[r];
      long x = (b[i] - a[i]) / sum;
      ret += x;
      b[i] -= x * sum;

      if (x > 0) {
        q.add(l);
        q.add(r);
      }
    }
    System.out.println(Arrays.equals(a, b) ? ret : -1);
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
