public class Main {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        for(int i = 0; i < n;i++) {
            int num = sc.nextInt();
            a[i] = num;
        }
        PriorityQueue<Pair> pq = new PriorityQueue<>((x, y) -> y.num - x.num);
        for(int i = 0; i < n; i++) {
            int num = sc.nextInt();
            b[i] = num;
            pq.add(new Pair(i, num));
        }
        long count = 0;
        while(!pq.isEmpty()) {
            Pair p = pq.poll();
            int index = p.index;
            if (p.num == a[index]) continue;
            int prevIndex = (index + n - 1) % n;
            int nextIndex = (index + 1) % n;
            int prev = b[prevIndex];
            int next = b[nextIndex];
            int newNum = p.num -= (prev + next);
            if (newNum < a[index]) {
                System.out.println("-1");
                return;
            }
            b[index] = newNum;
            count++;
            if (newNum == a[index]) continue;
            pq.add(new Pair(index, newNum));
        }
        System.out.println(count);
    }

    static class Pair {
        int index;
        int num;
        Pair(int i, int n) {
            index = i;
            num = n;
        }
    }
