class Num {
    int idx;
    long num;

    Num(int idx, long num) {
        this.idx = idx;
        this.num = num;
    }
}

public class Main {

    public static void main(String[] args){
        PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        int N = sc.nextInt();
        long A[] = sc.nextLongArray(N);
        long B[] = sc.nextLongArray(N);

        PriorityQueue pq = new PriorityQueue (N, new MyComparator ());
        for (int i=0;i<B.length;i++) {
            pq.add(new Num(i, B[i]));
        }

        int ans = 0;

        for (int i=0;i<N;i++) {
            if (A[i] > B[i]) {
                ans = -1;
            }
        }

        if (ans == 0) {
            while (pq.isEmpty() == false) {
                Num tar = (Num) pq.poll();
                int i = tar.idx;
                int b1 = (i - 1 + N) % N;
                int b2 = (i + 1 + N) % N;
                long target = Math.max(A[i], Math.max(B[b1], B[b2]));
                long cnt = Math.max(1, (B[i] - target) / (B[b1] + B[b2]));

//                System.out.printf("%d %d %d\n", target, cnt, B[i]);
                B[i] -= (B[b1] + B[b2]) * cnt;

                ans += cnt;

                if (B[i] < A[i]) {
                    ans = -1;
                    break;
                } else if (B[i] > A[i]) {
                    pq.add(new Num(i, B[i]));
                }
            }
        }

        for (int i=0;i<N;i++) {
            if (A[i] != B[i]) {
                ans = -1;
            }
