    int ret = 0;
    while (!Arrays.equals(a, b)) {
      boolean ok = false;
      for (int i = 0; i < n; i++) {
        int l = b[(i - 1 + n) % n];
        int r = b[(1 + i) % n];
        if (b[i] - l - r >= a[i]) {
