import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int n = in.nextInt();
        int[] a = in.nextIntArray(n);
        int[] b = in.nextIntArray(n);
        PriorityQueue<Integer> queue = new PriorityQueue<>(Comparator.comparingInt(i -> b[i]));
        for (int i = 0; i < n; i++) {
            int left = (i + n - 1) % n;
            int right = (i + 1) % n;
            if (b[i] - b[left] - b[right] >= a[i]) {
                queue.add(i);
            }
        }
        int ans = 0;
        while (!queue.isEmpty()) {
            int i = queue.poll();
            int left = (i + n - 1) % n;
            int right = (i + 1) % n;
            if (b[i] - b[left] - b[right] < a[i]) {
                continue;
            }
            int c = (b[i] - a[i]) / (b[left] + b[right]);
            ans += c;
            b[i] -= c * (b[left] + b[right]);
            int ll = (left + n - 1) % n;
            int lr = i;
            int rl = i;
            int rr = (right + 1) % n;
            if (b[left] - b[ll] - b[lr] >= a[left]) {
                queue.add(left);
            }
            if (b[right] - b[rl] - b[rr] >= a[right]) {
                queue.add(right);
            }
        }
        if (Arrays.equals(a, b)) {
            out.println(ans);
        } else {
            out.println(-1);
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

