		long[] b = new long[n + 2];
		for(int i = 1; i < n + 1; i++) {
			b[i] = sc.nextLong();
		}
		for(int i = 1; i < n + 1; i++) {
			a[i] = sc.nextLong();
		}
		a[0] = a[n];
		a[n + 1] = a[1];
		b[0] = b[n];
		b[n + 1] = b[1];
		long cnt = 0;
		boolean flag = true;
		while(flag) {
			flag = false;
			for(int i = 1; i < n + 1; i++) {
				boolean back = false;
				while(a[i] > a[i - 1] && a[i] > a[i + 1] && a[i] > b[i]) {
					flag = true;
					back = true;
					a[i] = a[i] - a[i - 1] - a[i + 1];
					cnt++;
