                int sum = b[(i - 1 + n) % n] + b[(i + 1) % n];
                int sub = (b[i] - a[i]) / sum;
                if (sub <= 0) {
                    out.printLine(-1);
                    return;
                }
                b[i] -= sub * sum;
                if (b[i] > a[i]) {
