class MyComparator implements Comparator {
    @Override
    public int compare (Object arg0, Object arg1) {
        long x = ((Num) arg0).num;
        long y = ((Num) arg1).num;

        if (x < y) {
            return 1;
        } else if (x > y) {
            return -1;
        } else{
            return 0;
        }
    }
}

class Num {
    int idx;
    long num;

    Num(int idx, long num) {
        this.idx = idx;
        this.num = num;
    }
}

public class Main {

    public static void main(String[] args){
        PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        int N = sc.nextInt();
        long A[] = sc.nextLongArray(N);
        long B[] = sc.nextLongArray(N);

        PriorityQueue pq = new PriorityQueue (N, new MyComparator ());
        for (int i=0;i<N;i++) {
            pq.add(new Num(i, B[i]));
        }

        int ans = 0;
        boolean is_ok = true;

        for (int i=0;i<N;i++) {
            if (A[i] > B[i]) {
                ans = -1;
            }

            if (A[i] != B[i]) {
                is_ok = false;
            }
        }

        if (ans == 0 && is_ok == false) {
            while (pq.isEmpty() == false) {
                Num tar = (Num) pq.poll();
                int i = tar.idx;
                int b1 = (i - 1 + N) % N;
                int b2 = (i + 1 + N) % N;
                long target = Math.max(A[i], Math.max(B[b1], B[b2]));
                long cnt = Math.max(1, (B[i] - target) / (B[b1] + B[b2]));

//                System.out.printf("%d %d %d\n", target, cnt, B[i]);
                if (A[i] == B[i]) continue;

                B[i] -= (B[b1] + B[b2]) * cnt;
                ans += cnt;

//                System.out.printf("+ ");
//                for (int j=0;j<N;j++) {
//                    System.out.printf("%d ", B[j]);
//                }
//                System.out.println();
                if (B[i] < A[i]) {
                    ans = -1;
                    break;
                } else if (B[i] > A[i]) {
                    pq.add(new Num(i, B[i]));
                }
            }
        }

        for (int i=0;i<N;i++) {
            if (A[i] != B[i]) {
                ans = -1;
            }
        }

        out.println(ans);
        out.flush();
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
