			inv[i] = MOD - inv[(int)(MOD%i)] * (MOD/i) % MOD;
			finv[i] = finv[i-1] * inv[i] % MOD;
		}
		isPreprocessing = true;
	}

	//二項係数i_C_jをMODで割った余りを返す
	static long COM(int i, int j){
		if(i<j)return 0;
		if(i<0 || j<0)return 0;
		if(!isPreprocessing)COMinit();
		return fac[i] * (finv[j] * finv[i-j] % MOD) % MOD;
	}

}

import java.util.PriorityQueue;

public class Main {
  private static void solve() {
    int n = ni();
    int[] a = na(n);
    int[] b = na(n);

    int ret = 0;
    PriorityQueue<Integer> q = new PriorityQueue<>((o1, o2) -> {
      int l1 = b[(o1 - 1 + n) % n];
      int r1 = b[(o1 + 1) % n];
      int l2 = b[(o2 - 1 + n) % n];
      int r2 = b[(o2 + 1) % n];

      return (b[o2] - (l2 + r2)) - (b[o1] - (l1 + r1));
    });

    for (int i = 0; i < n; i++) {
      q.add(i);
    }

    int same = 0;
    for (int i = 0; i < n; i++) {
      if (a[i] == b[i]) {
        same++;
      }
    }

    while (same < n) {
      int i = q.poll();
      int l = (i - 1 + n) % n;
      int r = (i + 1) % n;

      if (b[i] - b[l] - b[r] < a[i]) {
        System.out.println(-1);
        return;
      }
      q.remove(l);
      q.remove(r);
      q.remove(i);
      b[i] -= b[l] + b[r];
      q.add(l);
      q.add(r);
      q.add(i);
      ret++;
      if (b[i] == a[i]) {
        same++;
      }
    }
    System.out.println(ret);
  }

