  static class TaskC {

    int[] a;
    int[] b;
    int[] q;
    boolean[] inq;
    int ql;
    int qr;
    int n;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      n = in.nextInt();
      a = new int[n];
      for (int i = 0; i < n; ++i) {
        a[i] = in.nextInt();
      }
      b = new int[n];
      inq = new boolean[n];
      q = new int[40 * n];
      ql = 0;
      qr = 0;
      for (int i = 0; i < n; ++i) {
        b[i] = in.nextInt();
        if (okish(i)) {
          q[ql++] = i;
          inq[i] = true;
        }
      }
      long res = 0;
      while (ql > qr) {
        int x = q[qr++];
        inq[x] = false;
        if (!okish(x)) {
          continue;
        }
        int val = b[x] - a[x];
        int l = (x + n - 1) % n;
        int r = (x + 1) % n;
        int delta = b[l] + b[r];
        int steps = val / delta;
        b[x] -= steps * delta;
        res += steps;
        if (okish(x) && !inq[x]) {
          inq[x] = true;
          q[ql++] = x;
        }
        if (okish(l) && !inq[l]) {
          inq[l] = true;
          q[ql++] = l;
        }
        if (okish(r) && !inq[r]) {
          inq[r] = true;
          q[ql++] = r;
        }
      }
      for (int i = 0; i < n; ++i) {
        if (a[i] != b[i]) {
          out.printLine(-1);
          return;
        }
      }
      out.printLine(res);
    }

    private boolean okish(int x) {
      if (a[x] >= b[x]) {
        return false;
      }
      int l = (x + n - 1) % n;
      if (b[x] <= b[l]) {
        return false;
      }
      int r = (x + 1) % n;
      if (b[x] <= b[r]) {
        return false;
      }
      if (b[x] - (b[l] + b[r]) < a[x]) {
        return false;
      }
      return true;
    }

  }

