public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] a = sc.nextIntArray(n);
		int[] b = sc.nextIntArray(n);

		PriorityQueue<Pair> pq = new PriorityQueue<>(Collections.reverseOrder());
		for (int i = 0; i < n; i++) {
			pq.add(new Pair(b[i] - a[i], i));
		}

		long ans = 0;
		while (!pq.isEmpty()) {
			Pair e = pq.remove();

			if (e.a < 0) {
				pr.println(-1);
				return;
			} else if (e.a == 0) {
				continue;
			}

			e.a -= b[(e.b - 1 + n) % n] + b[(e.b + 1) % n];
			b[e.b] -= b[(e.b - 1 + n) % n] + b[(e.b + 1) % n];
			if (e.a < 0) {
				pr.println(-1);
				return;
			}

			pq.add(e);
			ans++;
		}

		pr.println(ans);
	}

	static class Pair implements Comparable<Pair> {
		int a;
		int b;

		Pair(int a, int b) {
			this.a = a;
			this.b = b;
		}

		@Override
		public int compareTo(Pair o) {
			int result = Integer.compare(a, o.a);
			if (result == 0) {
				result = Integer.compare(b, o.b);
			}
			return result;
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = a;
			result = prime * result + b;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (!(obj instanceof Pair))
				return false;

			Pair o = (Pair) obj;
			return a == o.a && b == o.b;
		}

		@Override
		public String toString() {
			//			Pair [xxx, xxxx]
			StringBuilder stmp = new StringBuilder(32);
			stmp.append("Pair [");
			stmp.append(a);
			stmp.append(',');
			stmp.append(' ');
			stmp.append(b);
			stmp.append(']');

			return stmp.toString();
		}
	}

