class AtCoder
{
    const int MOD = 1000000007;
    int TryCalc(int i, int[] start, int[] end, int[] sums)
    {
        var temp = sums[i];
        int n = start.Length;
        if (start[i] + temp <= end[i])
        {
            int bef = (i - 1 + n) % n;
            int aft = (i + 1) % n;
            end[i] -= temp;
            sums[bef] -= temp;
            sums[aft] -= temp;
            //Console.WriteLine(i);
            return
                TryCalc(i, start, end, sums) +
                TryCalc(aft, start, end, sums) +
                TryCalc((i + 1) % n, start, end, sums) +
                TryCalc(bef, start, end, sums) +
                TryCalc((i - 2 + n) % n, start, end, sums) + 1;
        }
        return 0;
    }
    public void Slove()
    {
        var n = int.Parse(Console.ReadLine());
        var start = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var end = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var sums =
            Enumerable.Range(0, n)
            .Select(i => end[(i + 1) % n] + end[(i - 1 + n) % n])
            .ToArray();
        int count = 0;
        foreach (int i in Enumerable.Range(0, n))
        {
            count += TryCalc(i, start, end, sums);
        }
        if (Enumerable.Range(0, n).Any(j => start[j] != end[j]))
        {
            Console.WriteLine(-1);
        }
        else
            Console.WriteLine(count);
    }
    static void Main()
    {
        var ac = new AtCoder();
        ac.Slove();
    }
}

