class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		string[] str = Console.ReadLine().Split();
		string[] str2 = Console.ReadLine().Split();
		int[]A = new int[N];
		int[]B = new int[N];
      	var p = new HashSet<int>();
		for(var i=0;i<N;i++){
			A[i] = int.Parse(str[i]);
			B[i] = int.Parse(str2[i]);
          	p.Add(i);
		}
		int ct = 0;
      	int[]F = new int[N];
		int[]G = new int[N];
		while(p.Count>0){
			var p2 = new HashSet<int>(p);
			p.Clear();
			foreach(var a1 in p2){
				bool flag = false;
				int a0 = (a1+N-1)%N;
				int a2 = (a1+1)%N;
				while(B[a0]+B[a2]<=B[a1] && B[a1]-B[a0]-B[a2]>=A[a1]){
					B[a1] -= B[(a1+N-1)%N]+B[(a1+1)%N];
					ct++;
					flag = true;
				}
				if(flag){
					if(F[a0]==1 && G[a0]==0){
						F[a0]=0;
						p.Add(a0);
					}
					if(F[a2]==1 && G[a2]==0){
						p.Add(a2);
						F[a2]=0;
					}
					if(B[a1] == A[a1]){
						G[a1] = 1;
					} else {
						p.Add(a1);
					}
				} else {
					F[a1] = 1;
				}
			}
		}
		for(var i=0;i<N;i++){
			if(A[i]!=B[i]){
				ct = -1;
            }
		}
		Console.WriteLine(ct);
	}
}

