public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var A = GetLongs(N);
		var B = GetLongs(N);

		var pq = new PriorityQueue<(long, long)>(N, (x, y) => y.Item2.CompareTo(x.Item2));
		for(long i = 0; i < N; i++)
		{
			if(A[i] > B[i])
			{
				WriteLine(-1);
				return;
			}
			pq.Push((i, B[i]));
		}

		long cnt = 0;
		while(pq.Count > 0)
		{
			bool update = false;
			var (i, v) = pq.Pop();
			while(B[i] > A[i] && B[i] > B[(i + N - 1) % N] + B[(i + 1) % N])
			{
				B[i] -= B[(i + N - 1) % N] + B[(i + 1) % N];
				update = true;
				cnt++;
			}
			if(!update)
				break;

			if(B[i] != A[i])
				pq.Push((i, B[i]));
		}

		if(A.Zip(B, (x, y) => x == y).Count(x => x) == N)
			WriteLine(cnt);
		else
			WriteLine(-1);
	}
}

public class PriorityQueue<T>
{
	public long Count { get; private set; } = 0;
	public long MaxSize { get; private set; } = 0;
	private T[] m_heap;
	private Comparison<T> Comp = null;

	public PriorityQueue(long maxSize, Comparison<T> comp)
	{
		if(maxSize <= 0)
			throw new Exception();
		MaxSize = maxSize;
		m_heap = new T[maxSize];

		Comp = comp;
	}

	public void Push(T x)
	{
		if(Count == MaxSize)
		{
			T[] new_heap = new T[MaxSize << 1];
			Array.Copy(m_heap, new_heap, MaxSize);
			m_heap = new_heap;
			MaxSize <<= 1;
		}

		long i = Count++;
		while(i > 0)
		{
			long p = (i - 1)/2;
			if(Comp(m_heap[p], x) <= 0)
				break;
			m_heap[i] = m_heap[p];
			i = p;			
		}
		m_heap[i] = x;		
	}

	public T Pop()
	{
		if(Count == 0)
			throw new Exception("Queue is empty.");

		T result = m_heap[0];
		T x = m_heap[--Count];
		long i = 0;
		while(i * 2 + 1 < Count)
		{
			long c1 = i * 2 + 1, c2 = i * 2 + 2;
			if(c2 < Count && Comp(m_heap[c2], m_heap[c1]) < 0)
				c1 = c2;
			if(Comp(m_heap[c1], x) >= 0)
				break;
			m_heap[i] = m_heap[c1];
			i = c1;
		}
		m_heap[i] = x;

		return result;		
	}

	public T Peek() => m_heap[0];
}

