class Solver
{
    Scanner sc = new Scanner();
    //

    public void Solve()
    {
        var N = sc.Int;
        var ar = sc.ArrInt;
        var bs = sc.ArrInt;
        var pq = new PriorityQueue<P>((a, b) => b.v - a.v);
        for (var i = 0; i < N; i++)
            if (ar[i] != bs[i]) pq.Enqueue(new P(bs[i], i));
        var res = 0L;
        while (pq.Any())
        {
            int v, idx;
            pq.Dequeue().Tie(out v, out idx);if (v - ar[idx] < 0) Fail(-1);
            var adj = bs[(idx - 1 + N) % N] + bs[(idx + 1) % N];
            if (adj >= v) Fail(-1);
            var m = v % adj;
            if (m <= ar[idx])
            {
                if ((v - ar[idx]) % adj == 0) { bs[idx] = ar[idx];res += (v - ar[idx]) / adj; continue; }
                Fail(-1);
            }
            else
            {
                bs[idx] = m;
                res += v / adj;
                pq.Enqueue(new P(m, idx));
            }
        }
        WriteLine(res);
    }
    struct P
    {
        public int v, idx;public P(int V,int i) { v = V;idx = i; }
        public void Tie(out int a,out int b) { a = v;b = idx; }
    }
}

public class PriorityQueue<T>
{
    private List<T> item = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return item.Count; } }
    public T Peek { get { return item[0]; } }
    public PriorityQueue() { cmp = Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    public PriorityQueue(IComparer<T> comparer) { cmp = comparer.Compare; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Enqueue(T val)
    {
        int i = item.Count;
        item.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(item[p], val) <= 0)
                break;
            item[i] = item[p];
            i = p;
        }
        item[i] = val;
        return val;
    }
    public T Dequeue()
    {
        var ret = item[0];
        var p = 0;
        var x = item[item.Count - 1];
        while (Left(p) < item.Count - 1)
        {
            var l = Left(p);
            if (l < item.Count - 2 && cmp(item[l + 1], item[l]) < 0) l++;
            if (cmp(item[l], x) >= 0)
                break;
            item[p] = item[l];
            p = l;
        }
        item[p] = x;
        item.RemoveAt(item.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => item.Count > 0;
}
