	public class Program
	{
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			long[] a = new long[n];
			long[] b = new long[n];
			for (int i = 0; i < n; i++) {
				a[i] = cin.Long();
			}

			for (int i = 0; i < n; i++) {
				b[i] = cin.Long();
			}

			var pq = new PriorityQueue<PriorityQueue<long>.Pair<int>>();
			for (int i = 0; i < n; i++) {
				pq.Push(new PriorityQueue<long>.Pair<int>(b[i], i));
			}

			long ans = 0;
			while (pq.Count > 0) {
				var target = pq.Pop();
				long prev = target.Value != 0 ? b[target.Value - 1] : b[n - 1];
				long next = target.Value != n - 1 ? b[target.Value + 1] : b[0];
				if (target.Priority >= prev && target.Priority >= next) {
					if (b[target.Value] > a[target.Value] && (prev + next) != 0) {
						long count = (b[target.Value] - a[target.Value]) / (prev + next);
						b[target.Value] -= (prev + next) * count;
						ans += count;

						if (b[target.Value] > a[target.Value] && count != 0) {
							pq.Push(new PriorityQueue<long>.Pair<int>(b[target.Value], target.Value));
						}
					}
				}
			}

			for (int i = 0; i < n; i++) {
				if (a[i] != b[i]) {
					Console.WriteLine(-1);
					return;
				}
			}

			Console.WriteLine(ans);
		}
	}

	public class PriorityQueue<T>
		where T : IComparable<T>
	{
		private readonly List<T> buf_ = new List<T>();
		public bool Reverses { get; set; } = false;

		public T Top => buf_[0];
		public int Count => buf_.Count;

		public void Push(T elem)
		{
			int n = buf_.Count;
			buf_.Add(elem);
			while (n > 0) {
				int i = (n - 1) >> 1;
				if (Compare(n, i) > 0) {
					Swap(i, n);
				}

				n = i;
			}
		}
		public T Pop()
		{
			T ret = buf_[0];
			int n = buf_.Count - 1;
			buf_[0] = buf_[n];
			buf_.RemoveAt(n);
			for (int i = 0, j; (j = (i << 1) + 1) < n; i = j) {
				if (j != n - 1 && Compare(j, j + 1) < 0) {
					++j;
				}

				if (Compare(i, j) < 0) {
					Swap(i, j);
				}
			}
			return ret;
		}

		private int Compare(int self, int target)
			=> buf_[self].CompareTo(buf_[target]) * (Reverses ? -1 : 1);
		private void Swap(int x, int y)
		{
			var t = buf_[x];
			buf_[x] = buf_[y];
			buf_[y] = t;
		}

		public class Pair<U> : IComparable<Pair<U>>
		{
			public T Priority { get; set; }
			public U Value { get; set; }
			public Pair(T priority, U value)
			{
				Priority = priority;
				Value = value;
			}
			public int CompareTo(Pair<U> target)
				=> Priority.CompareTo(target.Priority);
			public override string ToString()
				=> $"{Priority} {Value}";
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int()
		{
			return int.Parse(Next());
		}
		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

