            var B = Console.ReadLine().Split(' ').Select(item => int.Parse(item)).ToArray();
            var res = Calc(B, A, N,0);
            Console.WriteLine(res);

        }

        static int Calc(int[] state, int[] target, int N, int count)
        {
            if (Check(state, target)) return count;
            for (var i = 0; i < N; i++)
            {
                var ns = state[i]- state[(i + 1) % N] - state[(i + N - 1) % N];
                if (ns < target[i]) continue;
                var old = state[i];
                state[i] = ns;
                var res = Calc(state, target, N,count+1);
                if (res != -1) return res;
                state[i] = old;
            }
            return -1;
        }

        static bool Check(int[] l, int[] r)
        {
            var N = l.Length;
            for (var i = 0; i < N; i++)
            {
                if (l[i] != r[i]) return false;
            }
            return true;
        }
    }
