class AtCoder
{
    const int MOD = 1000000007;
    public void Slove()
    {
        var n = int.Parse(Console.ReadLine());
        var start = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var end = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var sums =
            Enumerable.Range(0, n)
            .Select(i => end[(i + 1) % n] + end[(i - 1 + n) % n])
            .ToArray();
        int count = 0;
        while(true)
        {
            //Console.WriteLine(string.Join(" ", end));
            //Console.WriteLine(string.Join(" ", sums));
            bool ok = false;
            foreach(int i in Enumerable.Range(0, n))
            {
                var temp = sums[i];
                if (start[i] + temp <= end[i])
                {
                    end[i] -= temp;
                    sums [(i - 1 + n) % n] -= temp;
                    sums[(i + 1) % n] -= temp;
                    ok = true;
                    count++;
                    //Console.WriteLine(i);
                    break;
                }
            }
            if(!ok)
            {
                if(Enumerable.Range(0, n).Any(j => start[j] != end[j]))
                {
                    Console.WriteLine(-1);
                    return;
                }
                break;
            }
        }
        Console.WriteLine(count);
    }
    static void Main()
    {
        var ac = new AtCoder();
        ac.Slove();
    }
