namespace AtCoderWorkspace
{
    class Program
    {
        static void Main(string[] args)
        {
            var cin = new Scanner();
            var N = cin.nextInt();

            var A = new Dictionary<int,long>();
            var B = new Dictionary<int, long>();

            for (int i = 0; i < N; i++)
            {
                A.Add(i, cin.nextLong());
            }

            for (int i = 0; i < N; i++)
            {
                B.Add(i, cin.nextLong());
            }


            // Aの最大値
            var am = A.OrderBy(val => val.Value).Last().Value;
            var count = 0;
            while (true)
            {
                // 終わるまでgreedy
                var mp = B.OrderBy(val => val.Value).Last();
                var m = mp.Value;
                var index = mp.Key;
                var before = GetBefore(B,index);
                var next = GetNext(B, index);

                // 終了判定
                if (am == m)
                {
                    Console.WriteLine(count);
                    return;
                }

                // 無理判定
                if (m - (before + next) <= 0)
                {
                    Console.WriteLine(-1);
                    return;
                }

                // Bの更新
                B[index] = m - (before + next);
                count++;
            }
        }

        static long GetBefore(Dictionary<int,long> dict, int index)
        {
            var size = dict.Count-1;
            if(index == 0)
            {
                return dict[size];
            }
            return dict[index-1];
        }

        static long GetNext(Dictionary<int, long> dict, int index)
        {
            var size = dict.Count-1;
            if (size < index+1)
            {
                return dict[0];
            }
            return dict[index+1];
        }
    }

