                dp[0, 2] = dp[0, 3] = -1000000000;
                for(int i = 0; i < N; ++i)
                {
                    dp[i + 1, 0] = dp[i, 1] + 1; if (i > 0 && S[i] != S[i - 1]) { dp[i + 1, 0] = Math.Max(dp[i + 1, 0], dp[i, 0] + 1); }
                    dp[i + 1, 1] = dp[i, 2] + 1; if (i > 3 && (S[i] != S[i - 2] || S[i - 1] != S[i - 3])) { dp[i + 1, 1] = Math.Max(dp[i + 1, 1], dp[i, 3] + 1); }
                    dp[i + 1, 2] = dp[i, 0];
                    dp[i + 1, 3] = dp[i, 1];
                }
