                    {
                        count += (b - A[i]) / (a + c);
                        B[i] = A[i];
                    }
                    else
                    {
                        var v = (b - A[i] - 1) / (a + c);
                        count += v;
                        B[i] -= v * (a + c);
                        if (v == 0 || A[i] > B[i]) { Console.WriteLine(-1); return; }
                        queue.Push(new Tuple<int, int>(B[i], i));
                    }
                }
                Console.WriteLine(count);
