class Program
{
static long[] check = new long[2];

	static void Main()
	{
    bool isAnswer = true;
    long answer = 0;
    long lookedMemo = -1;
		int n = int.Parse(Console.ReadLine());
		long[] numsaa = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
    long[] numsbb = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);

    long[][] numsa = new long[n][];//数と初期位置番号
    long[][] numsb = new long[n][];
    for(int i = 0; i < n; i++)
    {
      numsa[i] = new long[2];
      numsb[i] = new long[2]; 
      numsa[i][0] = numsaa[i];
      numsa[i][1] = i;
      numsb[i][0] = numsbb[i];
      numsb[i][1] = i;
    }
    Array.Sort(numsb, (a, b) => b[0].CompareTo(a[0]));

    List<long[]> list = new List<long[]>();
    for(int i = 0; i < n; i++)
      list.Add(new long[2]{numsb[i][0], numsb[i][1]});

    while(list.Count > 0)
    {
      list = PopHeap(list);
      long minusNum = 0;//引く値
      if(check[1]-1 >= 0) minusNum += numsbb[check[1]-1];
      else minusNum += numsbb[n-1];
      if(check[1]+1 < n) minusNum += numsbb[check[1]+1];
      else minusNum += numsbb[0];

      //Console.WriteLine(check[0]+" "+check[1]);

      if(check[0] < numsaa[check[1]] || lookedMemo == check[1])
      {
        isAnswer = false;
        break;
      }

      long maxMinus = (check[0] - numsaa[check[1]])/minusNum;//最大何回引けるか
      answer += maxMinus;
      check[0] -= minusNum*maxMinus;
      numsbb[check[1]] -= minusNum*maxMinus;
      lookedMemo = check[1];
      //Console.WriteLine(check[0]+"a"+check[1]);

      if(check[0] != numsaa[check[1]]) list = PushHeap(list, new long[2]{check[0],check[1]});
      //Console.WriteLine(list.Count);
    }

		if(isAnswer) Console.WriteLine(answer);
    else Console.WriteLine(-1);
	}

  static List<long[]> PushHeap(List<long[]> nums, long[] addNum)//現在のヒープnumsにaddNumを追加
{
  int n = nums.Count;
  nums.Add(addNum);

  while (n > 0)
  {
    int i = (n-1)/2;
    if (nums[n][0] > nums[i][0])//親のほうが大きいなら入れ替え。
    {
      long tmp0 = nums[n][0];
      long tmp1 = nums[n][1];
      nums[n][0] = nums[i][0];
      nums[n][1] = nums[i][1];
      nums[i][0] = tmp0;
      nums[i][1] = tmp1;
    }
    n = i;
  }
  return nums;
}

static List<long[]> PopHeap(List<long[]> nums)//ヒープnumsからポップ
{
  int n = nums.Count - 1;
  check[0] = nums[0][0];//捨てる値の保存
  check[1] = nums[0][1];
  nums[0][0] = nums[n][0];//最小値である根を削除してリストの最後を持ってくる
  nums[0][1] = nums[n][1];
  nums.RemoveAt(n);

  for (int i = 0, j; (j = 2*i+1) < n; )
  {
    if ((j != n-1) && (nums[j][0] < nums[j+1][0]))// ２つの子のうち、値の小さい方を選ぶ
      j++;
    if (nums[i][0] < nums[j][0])//子が親より小さいなら入れ替え
    {
    long tmp0 = nums[j][0];
    long tmp1 = nums[j][1];
    nums[j][0] = nums[i][0];
    nums[j][1] = nums[i][1];
    nums[i][0] = tmp0;
    nums[i][1] = tmp1;
    }
    i = j;
  }
  return nums;
}

}

