namespace Kujikatsu016.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/agc037/tasks/agc037_c
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            _ = inputStream.ReadInt();
            var a = inputStream.ReadIntArray();
            var b = ImmutableList.Create(inputStream.ReadIntArray());
            var canChangeIndexBuilder = ImmutableHashSet.CreateBuilder<int>();

            var matchedCount = 0;
            for (int i = 0; i < b.Count; i++)
            {
                if (b[i] - (b[(i - 1 + b.Count) % b.Count] + b[(i + 1) % b.Count]) >= a[i])
                {
                    canChangeIndexBuilder.Add(i);
                }
                if (a[i] == b[i])
                {
                    matchedCount++;
                }
            }

            var canChangeIndex = canChangeIndexBuilder.ToImmutable();
            var count = GetCount(a, b, canChangeIndex, matchedCount, 0);
            yield return count == int.MaxValue ? -1 : count;
        }

        int GetCount(int[] a, ImmutableList<int> b, ImmutableHashSet<int> canChange, int matchedNumbers, int count)
        {
            if (matchedNumbers == a.Length)
            {
                return count;
            }
            else
            {
                var minCount = int.MaxValue;
                foreach (var index in canChange)
                {
                    var next = b[index] - (b[(index - 1 + b.Count) % b.Count] + b[(index + 1) % b.Count]);
                    if (next >= a[index])
                    {
                        var bNext = b.SetItem(index, next);
                        var builder = canChange.ToBuilder();
                        for (int d = -1; d <= 1; d++)
                        {
                            if (bNext[(index + d + b.Count) % b.Count] - (bNext[(index + d - 1 + b.Count) % b.Count] + bNext[(index + d + 1 + b.Count) % b.Count]) >= a[(index + d + b.Count) % a.Length])
                            {
                                builder.Add((index + d + b.Count) % b.Count);
                            }
                            else
                            {
                                builder.Remove((index + d + b.Count) % b.Count);
                            }
                        }
                        minCount = Math.Min(minCount, GetCount(a, bNext, builder.ToImmutable(), matchedNumbers + (next == a[index] ? 1 : 0), count + 1));
                    }
                }
                return minCount;
            }
        }
    }
}

