func maxHeapify(i int) {
	l := 2 * i
	r := 2*i + 1
	var largest int
	if l <= H && A[l].value > A[i].value {
		largest = l
	} else {
		largest = i
	}
	if r <= H && A[r].value > A[largest].value {
		largest = r
	}
	if largest != i {
		A[i], A[largest] = A[largest], A[i]
		maxHeapify(largest)
	}
}

func extract() pair {
	var maxv pair
	if H < 1 {
		return pair{
			index: -1,
			value: -9999999999999,
		}
	}
	maxv = A[1]
	A[1] = A[H]
	H--
	maxHeapify(1)
	return maxv
}

func increaseKey(i int, key pair) {
	if key.value < A[i].value {
		return
	}
	A[i] = key
	for i > 1 && A[i/2].value < A[i].value {
		A[i], A[i/2] = A[i/2], A[i]
		i /= 2
	}
}

func insert(key pair) {
	H++
	A[H] = pair{
		index: -1,
		value: -9999999999999,
	}
	increaseKey(H, key)
}

