// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()

	as := io.NextInts(N)
	bs := io.NextInts(N)

	// 後の形から b[i] -= (b[i-1]+b[i+1]) として a になるかを見る
	// 両隣の和がより小さい数でないとこの操作は行えない & 全要素について a になるまで操作をする必要は必ずあることから、
	// a 以上でこの操作が行える限り行う必要がある
	// なお、両端の和がより小さくない ⇒ 操作後の b は 0 以下になる　なので、
	// 操作後の b が a 未満でない ⇒ 操作が行える となり、 操作後の値のチェックのみで十分
	prev := make([]int, N)
	next := make([]int, N)

	for i := range prev {
		prev[i] = i - 1
		next[i] = i + 1
	}
	prev[0] = N - 1
	next[N-1] = 0

	queue := make([]int, N)
	for i := 0; i < N; i++ {
		queue[i] = i
	}

	res := 0
	nonUpdateCt := 0

	for len(queue) > 0 {
		if nonUpdateCt >= len(queue)*2 {
			io.Println(-1)
			return
		}

		i := queue[0]
		queue = queue[1:]

		prev := bs[prev[i]]
		next := bs[next[i]]

		// 操作後の値が a 未満にならない限り (prev+next) を引き続ける
		ct := (bs[i] - as[i]) / (prev + next)

		bs[i] -= (prev + next) * ct
		res += ct

		if bs[i] > as[i] {
			queue = append(queue, i)
		}

		if ct == 0 {
			nonUpdateCt++
		} else {
			nonUpdateCt = 0
		}
	}

	io.Println(res)
}

func main() {
	io := NewIo()
	defer io.Flush()
	solve(io, nil)
}

