var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextInt() int {
  var n int
  n, _ = strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

type Item struct {
  Comparison  int
  Index int
}
type PriorityQueue []*Item
func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
  return pq[i].Comparison < pq[j].Comparison
}
func (pq PriorityQueue) Swap(i, j int) {
  pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n - 1]
  *pq = old[0:n - 1]
  return item
}
func (pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq, item)
}

func Max(a, b, c int) int {
  ans := a
  if ans < b { ans = b }
  if ans < c { ans = c }
  return ans
}

func main() {
  N := NextInt()
  A := NextIntVec()
  B := NextIntVec()
  var Q PriorityQueue
  for i, b := range B {
    heap.Push(&Q, &Item{-b, i})
  }
  cnt := 0
  for len(Q) > 0 {
    i := heap.Pop(&Q).(*Item).Index
    d := B[(i - 1 + N) % N] + B[(i + 1 + N) % N]
    k := (B[i] - Max(A[i], B[(i - 1 + N) % N], B[(i + 1 + N) % N]) + d - 1) / d
    B[i] -= d * k
    if B[i] < A[i] {
      cnt = -1
      break
    }
    cnt += k
    if A[i] < B[i] {
      heap.Push(&Q, &Item{-B[i], i})
    }
  }
  Write(cnt)
  Output()
}

