)

var rdr = bufio.NewReaderSize(os.Stdin, 1000000)

type Item struct {
	i int
	priority int
	index int
}

type PriorityQueue []*Item

func (pq PriorityQueue) Len() int { return len(pq) }

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].priority > pq[j].priority
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}

func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.index = n
	*pq = append(*pq, item)
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	item.index = -1 // for safety
	*pq = old[0 : n-1]
	return item
}

func readLine() string {
	buf := make([]byte, 0, 1000000)
	for {
		l, p, e := rdr.ReadLine()
		if e != nil {
			panic(e)
		}
		buf = append(buf, l...)
		if !p {
			break
		}
	}
	return string(buf)
}

func main() {
	var N int
	fmt.Scanf("%d", &N)
	aStr := readLine()
	aSlice := strings.Split(aStr, " ")
	A := make([]int, N)

	for i, s := range aSlice {
		A[i], _ = strconv.Atoi(s)
	}

	q := &PriorityQueue{}
	heap.Init(q)

	bStr := readLine()
	bSlice := strings.Split(bStr, " ")
	B := make([]int, N)
	for i, s := range bSlice {
		B[i], _ = strconv.Atoi(s)
		heap.Push(q, &Item{
			i:        i,
			priority: B[i],
		})
	}

	total := 0
	for {
		if q.Len() == 0 {
			break
		}

		p := heap.Pop(q).(*Item)
		// もし A[i] == B[i] なら スキップ
		if A[p.i] == B[p.i] {
			continue
		}

		if A[p.i] >= B[p.i] {
			fmt.Printf("%d", -1)
			return
		}

		before := p.priority - B[roundIndex(N, p.i-1)] - B[roundIndex(N, p.i+1)]
		B[p.i] = before

		heap.Push(q, &Item{
			i: p.i,
			priority: before,
		})

		total++
	}

	fmt.Printf("%d", total)
}

func roundIndex(l, i int) int {
	if i >= l {
		return i - l
	}

	if i < 0 {
		return i + l
	}

	return i
}

