func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1000005), 1000005)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func getNextUint64(scanner *bufio.Scanner) uint64 {
	i, _ := strconv.ParseUint(getNextString(scanner), 10, 64)
	return i
}

func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}

func main() {
	fp := os.Stdin
	wfp := os.Stdout
	cnt := 0

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
		cnt = 3
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}

	writer.Flush()
}

func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int, n)
	bb := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	yy := &ysp49{}
	heap.Init(yy)
	for i := 0; i < n; i++ {
		bb[i] = getNextInt(scanner)
		heap.Push(yy, newy(bb[i], i))
	}

	c := int64(0)
	for yy.Len() > 0 {
		p := heap.Pop(yy).(ysp48)
		if bb[p.i] <= bb[(p.i-1+n)%n] {
			continue
		}
		if bb[p.i] <= bb[(p.i+1+n)%n] {
			continue
		}
		if bb[p.i] <= bb[(p.i-1+n)%n]+bb[(p.i+1+n)%n] {
			continue
		}
		if bb[(p.i-1+n)%n]+bb[(p.i+1+n)%n] == 0 {
			continue
		}
		c += int64(bb[p.i] / (bb[(p.i-1+n)%n] + bb[(p.i+1+n)%n]))
		bb[p.i] %= (bb[(p.i-1+n)%n] + bb[(p.i+1+n)%n])
		heap.Push(yy, newy(bb[p.i], p.i))
	}

	if isok(aa, bb, n) {
		fmt.Fprintln(writer, c)
		return
	}
	fmt.Fprintln(writer, -1)
}

func isok(aa, bb []int, n int) bool {
	for i := 0; i < n; i++ {
		if aa[i] != bb[i] {
			return false
		}
	}

	return true
}
func newy(v, i int) ysp48 {
	return ysp48{
		v: v,
		i: i,
	}
}

type ysp48 struct {
	v, i int
}

type ysp49 []ysp48

func (h ysp49) Len() int           { return len(h) }
func (h ysp49) Less(i, j int) bool { return h[i].v > h[j].v }
func (h ysp49) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *ysp49) Push(x interface{}) {
	*h = append(*h, x.(ysp48))
}
func (h *ysp49) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

