	"bufio"
	"fmt"
	"os"
	"strconv"
)

var H int
var A []*pair

type pair struct {
	index int
	value int
}

func maxHeapify(i int) {
	l := 2 * i
	r := 2*i + 1
	var largest int
	if l <= H && A[l].value > A[i].value {
		largest = l
	} else {
		largest = i
	}
	if r <= H && A[r].value > A[largest].value {
		largest = r
	}
	if largest != i {
		A[i], A[largest] = A[largest], A[i]
		maxHeapify(largest)
	}
}

func extract() *pair {
	var maxv *pair
	if H < 1 {
		return &pair{
			index: -1,
			value: -9999999999999,
		}
	}
	maxv = A[1]
	A[1] = A[H]
	H--
	maxHeapify(1)
	return maxv
}

func increaseKey(i int, key *pair) {
	if key.value < A[i].value {
		return
	}
	A[i] = key
	for i > 1 && A[i/2].value < A[i].value {
		A[i], A[i/2] = A[i/2], A[i]
		i /= 2
	}
}

func insert(key *pair) {
	H++
	A[H] = &pair{
		index: -1,
		value: -9999999999999,
	}
	increaseKey(H, key)
}

// 1万回以上scanするならこっち(10万回で600msとかだった)
var sc = bufio.NewScanner(os.Stdin)

func rs() string {
	sc.Scan()
	return sc.Text()
}

func ri() int {
	s := rs()
	a, _ := strconv.Atoi(s)
	return a
}

func main() {
	sc.Split(bufio.ScanWords)
	n := ri()
	A = make([]*pair, n+100)
	ar := make([]int, n)
	for i := range ar {
		ar[i] = ri()
	}
	br := make([]int, n)
	for i := 0; i < n; i++ {
		br[i] = ri()
		insert(&pair{
			index: i,
			value: br[i],
		})
	}
	sum := 0
	for H > 0 {
		p := extract()
		if ar[p.index] == p.value {
			continue
		}
		left := p.index - 1
		right := p.index + 1
		if left < 0 {
			left = n - 1
		}
		if right == n {
			right = 0
		}
		value := p.value - br[left] - br[right]
		if value < ar[p.index] {
			fmt.Println(-1)
			return
		}
		sum++
		p.value = value
		insert(p)
		br[p.index] = value
	}
	fmt.Println(sum)
}

