package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

func nextInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

type Item struct {
	i int
	priority int
	index int
}

type PriorityQueue []*Item

func (pq PriorityQueue) Len() int { return len(pq) }

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].priority > pq[j].priority
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}

func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.index = n
	*pq = append(*pq, item)
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	item.index = -1 // for safety
	*pq = old[0 : n-1]
	return item
}

func main() {
	sc.Split(bufio.ScanWords)
	N := nextInt()
	A := make([]int, N)
	B := make([]int, N)
	q := make(PriorityQueue, N)

	for i:=0; i<N ; i++ {
		A[i] = nextInt()
	}

	for i:=0; i<N ; i++ {
		B[i] = nextInt()
		if A[i] == B[i] {
			continue
		}
		q[i] = &Item{
			i: i,
			priority: B[i],
		}
	}

	heap.Init(&q)

	total := 0
	for {
		if q.Len() == 0 {
			break
		}

		p := heap.Pop(&q).(*Item)
		if A[p.i] >= B[p.i] {
			fmt.Printf("%d", -1)
			return
		}

		before := 0
		count := 0
		gap := B[p.i] - A[p.i]
		base := B[roundIndex(N, p.i-1)] + B[roundIndex(N, p.i+1)]
		if gap % base == 0 {
			count = gap / base
			before = B[p.i] - gap
		} else {
			before = p.priority - base
			count = 1
		}


		B[p.i] = before

		if A[p.i] > B[p.i] {
			fmt.Printf("%d", -1)
			return
		}


		total += count

		// もし A[i] == B[i] なら push しない
		if A[p.i] == B[p.i] {
			continue
		}

		heap.Push(&q, &Item{
			i: p.i,
			priority: before,
		})

	}

	fmt.Printf("%d", total)
}

func roundIndex(l, i int) int {
	if i >= l {
		return i - l
	}

	if i < 0 {
		return i + l
	}

	return i
}

