var sc = bufio.NewScanner(os.Stdin)

func rs() string {
	sc.Scan()
	return sc.Text()
}

func ri() int {
	s := rs()
	a, _ := strconv.Atoi(s)
	return a
}

func main() {
	sc.Split(bufio.ScanWords)
	n := ri()
	A = make([]*pair, n+10)
	ar := make([]int, n)
	for i := range ar {
		ar[i] = ri()
	}
	br := make([]int, n)
	for i := 0; i < n; i++ {
		br[i] = ri()
		insert(&pair{
			index: i,
			value: br[i],
		})
	}
	sum := 0
	for H > 0 {
		p := extract()
		if ar[p.index] == p.value {
			continue
		}
		left := p.index - 1
		right := p.index + 1
		if left < 0 {
			left = n - 1
		}
		if right == n {
			right = 0
		}
		se := extract()
		second := se.value
		insert(se)
		mv := second
		if mm := (p.value - mv) / (br[left] + br[right]); mm >= 100 {
			value := p.value - (br[left]-br[right])*(mm-10)

			if value < ar[p.index] {
				fmt.Println(-1)
				return
			}
			sum += mm - 10
			p.value = value
			insert(p)
			br[p.index] = value
		} else {
			value := p.value - br[left] - br[right]

			if value < ar[p.index] {
				fmt.Println(-1)
				return
			}
			sum++
			p.value = value
			insert(p)
			br[p.index] = value
		}
	}
	fmt.Println(sum)
}

my $N =  <STDIN>;
chomp ($N);
my @A;
foreach (split(/ /o, <STDIN>)) {
  chomp($_);
  push(@A, $_) if ($_ ne '');
}
my @B;
foreach (split(/ /o, <STDIN>)) {
  chomp($_);
  push(@B, $_) if ($_ ne '');
}
my $n = 0;
if ( &check_arr(@B) ){
  print 0;
  exit 0;
}

my $t = 1;
while ($t) {
  ($t, @B) = &check(@B);
  $n = $n + $t;
}
if ( &check_arr(@B) ){
  print $n;
} else {
  print -1;
}

sub check {
  my (@P) = @_;
  my $t = 0;
  for (my $i = 0; $i < $N; $i++) {
    my $j = $i + 1;
    $j = 0 if ($j > $N - 1);
    my $k = $i - 1;
    $k = $N - 1 if ($k < 0);
    if ( $P[$i] > $A[$i] ) {
      my $tmp = $P[$j] + $P[$k];
      if ( $P[$i] > $tmp ) {
        $P[$i] = $P[$i] - $tmp;
        $t++;
      }
    }
  }
  return ($t, @P);
}
sub check_arr() {
  my (@Q) = @_;
  my $same = 1;
  for (my $i = 0; $i < $N; $i++) {
    if ( $A[$i] != $Q[$i] ) {
      $same = 0;
    }
  }
  return $same;
}

