	foreach(i; 0 .. n - 1){
		xs[i].next = xs[i + 1];
		xs[i + 1].prev = xs[i];
	}
	xs[n - 1].next = xs[0];
	xs[0].prev = xs[n - 1];

	auto xh = new RedBlackTree!(X, "a.b>b.b", false);

	foreach(x; xs){
		if(x.prev.a + x.next.a > x.b - x.a){
