		}
		if(x.b > x.a){
			xh.insert(x);
		}
	}
	log("xh:", xh[], "xs:", xs);

	long ans = 0;
	while(xh.length > 0){
		X x = xh.front;
		xh.removeFront;
		long bsum = x.prev.b + x.next.b;
		long asum = x.prev.a + x.next.a;
		long bmax = max(x.prev.b, x.next.b);
		if(bsum > x.b - x.a){
			"-1".writeln;
			return;
		}
		if(x.a >= bmax){
			if((x.b - x.a) % bsum == 0){
				ans += (x.b - x.a) / bsum;
				x.b = x.a;
			}
			else{
				"-1".writeln;
				return;
			}
		}
		else{
			long k = (x.b - bmax + bsum - 1) / bsum;
			long b2 = x.b - k * bsum;
			if(b2 < x.a){
				"-1".writeln;
				return;
			}
			else{
				ans += k;
				x.b = b2;
				if(x.a < x.b) xh.insert(x);
			}
		}
		log("xh:", xh[], "xs:", xs, "ans:", ans);

	}

