void main() {
  long N;
  scanln(N);
  long[] as = readln.split.to!(long[]);
  long[] bs = readln.split.to!(long[]);

  foreach (i; 0 .. N) {
    if (bs[i] < as[i]) {
      writeln(-1);
      return;
    }
  }

  bool f(long i) {
    i += N;
    i %= N;
    return bs[i] > bs[(i - 1 + N) % N] + bs[(i + 1) % N];
  }

  auto list = DList!long();
  foreach (i; 0 .. N) {
    if (f(i)) {
      list.insertBack(i);
    }
  }

  long ans = 0;
  while (!list.empty) {
    long i = list.front;
    i += N;
    i %= N;
    list.removeFront;
    if (bs[i] == as[i])
      continue;
    assert(bs[i] > as[i]);
    long s = bs[i];
    long t = bs[(i - 1 + N) % N] + bs[(i + 1) % N];
    if (s <= t)
      continue;
    long c = (s - as[i]).floor(t);
    bs[i] -= c * t;
    ans += c;
    if (f(i - 1))
      list.insertBack(i - 1);
    if (f(i + 1))
      list.insertBack(i + 1);
  }

  foreach (i; 0 .. N) {
    if (as[i] != bs[i]) {
      writeln(-1);
      return;
    }
  }
  ans.writeln;
}

