        auto sideValue = bList[mod(elem.idx-1, N)]+bList[mod(elem.idx+1, N)];
        auto target = aList[elem.idx]; 
        auto value = bList[elem.idx]; 
        if(value <= sideValue) end(-1);
        res += value / sideValue;
        bList[elem.idx] = value = value % sideValue;
        if(target==value)continue;
        if(value>target){
            tree.insert(Elem(value, elem.idx));
            continue;
        }
        if((target-value)%sideValue!=0) end(-1);
        res -= (target-value)/sideValue;
    }
    writeln(res);
}

void end(T)(T v)
if(isIntegral!T||isSomeString!T||isSomeChar!T)
{
    import core.stdc.stdlib;
    writeln(v);
    stdout.flush();
    exit(0);
}

struct PascalTriangle(Int=long)
if(is(Int==typeof(Int.init+Int.init)))
{
    private Int[] arr;

    Int cmb(long n, long r){
        assert(n>=r);
        return arr[idx(r, n)];
    }

    this(long height)
    {
        arr.length = sequenceSum(height+2);
        arr[0] = 1;
        foreach(y;0..height)
        {
            foreach(x;0..y+1){
                arr[idx(x+0,y+1)]+=arr[idx(x,y)];
                arr[idx(x+1,y+1)]+=arr[idx(x,y)];
            }
        }
    }

    private long idx(long x, long y) pure
    {
        return sequenceSum(y)+x;
    }
}
private long sequenceSum(long n) pure
{
    return n*(n+1)/2;
}

//HL分解
struct HeavyLightDecomposition
{
    immutable long root = 1;

    long[][] edge;
    long[] vid;
    long[] invid;
    long[] parent;
    long[] depth;
    long[] subCount;
    long[] head;

    this(long n, long root = 1)
    {
        this.root = root;
        n++;
        edge.length = n;
        vid.length = n;
        invid.length = n;
        parent.length = n; parent[] = -1;
        depth.length = n;
        head.length = n; head[root] = root;
        subCount.length = n; subCount[] = 1;
    }

    void addEdge(long u, long v)
    {
        edge[u] ~= v;
        edge[v] ~= u;
    }

    void build()
    {
        void dfs(long v){
            foreach(ref u; edge[v])
            {
                if(u==parent[v]) continue;
                parent[u] = v;
                depth[u] = depth[v] + 1;
                dfs(u);
                subCount[v] += subCount[u];
                if(edge[v][0]==parent[v]||subCount[u]>subCount[edge[v][0]])
                    swap(u, edge[v][0]);
            }
        }
        void dfsHead(long v, ref long pos){
            invid[pos] = v;
            vid[v] = pos;
            pos++;
            foreach(ref u; edge[v])
            {
                if(u==parent[v]) continue;

                head[u] = u == edge[v][0] ? head[v] : u;
                dfsHead(u, pos);
            }
        }
        dfs(root);
        long pos;
        dfsHead(root, pos);
    }

    long lca(long u, long v)
    {
        while(true){
            if(vid[u]>vid[v]) swap(u,v);
            if(head[u]==head[v]) return u;
            v = parent[head[v]];
        }
    }

    long distance(long u, long v) { return depth[u] + depth[v] - 2 * depth[lca(u,v)]; }

    //idxのn個上の親を返す
    //バグあるかも
    long nParent(long n, long idx){
        auto u = 0L;
        auto v = idx;
        while(true)
        {
            if(vid[u]>vid[v]) swap(u,v);

            immutable _u = max(vid[head[v]], vid[u]);
            immutable _v = vid[v] + 1;
            if(_v<=_u+n){
                n -= _v-_u;
            }else{
                return invid[_v-n-1];
            }

            if(head[u]==head[v]) return -1;
            v = parent[head[v]];
        }
    }

    void each(alias pred)(long u, long v)
    if(is(typeof(binaryFun!pred(0L,0L))))
    {
        while(true)
        {
            if(vid[u]>vid[v]) swap(u,v);
            binaryFun!pred(max(vid[head[v]], vid[u]), vid[v] + 1);
            if(head[u]==head[v]) return;
            v = parent[head[v]];
        }
    }
}

struct RMQ(T)
{
    alias STree = SegTree!(long, -1L);

    T[] arr;
    STree tree;

    bool delegate(T,T) F;
    this(InputRange)(InputRange range, bool delegate(T,T) f)
    if(isInputRange!InputRange)
    {
        this.arr = range.array;
        F = f;

        tree = STree(iota(0, arr.length), (a,b){
            if(a==-1)return b;
            if(b==-1)return a;
            return F(arr[a], arr[b])?a:b;
        });
    }
    this(long n, bool delegate(T,T) f)
    {
        arr.length = n;
        F = f;

        tree = STree(iota(0, n), (a,b){
            if(a==-1)return b;
            if(b==-1)return a;
            return F(arr[a], arr[b])?a:b;
        });
    }

    void build()
    {
        tree.build();
    }
    void set(long i, T value)
    {
        arr[i] = value;
        tree.set(i, i);
    }
    void update(long i, T value)
    {
        arr[i] = value;
        tree.update(i, i);
    }
    T get(long s, long t)
    {
        return arr[tree.get(s,t)];
    }
    long getIndex(long s, long t)
    {
        return tree.get(s,t);
    }
}
