int solve (int n, int [] a, int [] b)
{
	alias Pair = Tuple !(int, q{val}, int, q{pos});
	auto t = redBlackTree !(Pair);
	foreach (i; 0..n)
	{
		if (b[i] != a[i])
		{
			t.insert (Pair (b[i], i));
		}
	}
	int res = 0;
	while (!t.empty)
	{
		auto i = t.back.pos;
		t.removeBack ();
		auto next = b[i] - b[(i + n - 1) % n] - b[(i + 1) % n];
		if (next < a[i])
		{
			return -1;
		}
		res += 1;
		b[i] = next;
		if (next > a[i])
		{
			t.insert (Pair (b[i], i));
		}
	}
	return res;
}

