def solve(N: int, A: "List[int]", B: "List[int]"):

    lh = [[-b, i] for i, b in enumerate(B)]
    heapify(lh)

    count = 0
    while len(lh) > 0:
        b, i = heappop(lh)
        a, b = A[i], B[i]
        c = B[i-1]+B[(i+1) % N]
        if b > a and b >= c:
            d, m = divmod(b-a, c)
            if d == 0:
                break
            count += d
            B[i] = a+m
            if m != 0:
                heappush(lh, [-B[i], i])

    if A != B:
        count = -1

    print(count)
    return


