import sys
from heapq import heapify, heappop, heappush

def solve():
	input = sys.stdin.readline
	N = int(input())
	A = [int(a) for a in input().split()]
	B = [int(b) for b in input().split()]
	Bdict = dict()
	q = []
	heapify(q)
	for i in range(N):
		heappush(q, (-B[i], i))
		Bdict[i] = -B[i]

	count = 0
	while q:
		bi, i = heappop(q)
		if -bi > A[i] and bi < Bdict[(i-1)%N] + Bdict[(i+1)%N]:
			if A[i] >= -(Bdict[(i-1)%N]+Bdict[(i+1)%N]):
				k = (-Bdict[i]-A[i]) // (-1 * (Bdict[(i-1)%N]+Bdict[(i+1)%N]))
				count += k
				Bdict[i] -= (Bdict[(i-1)%N]+Bdict[(i+1)%N])*k
				if Bdict[i] != -A[i]: heappush(q, (Bdict[i],i))
			else:
				k = (-Bdict[i] + Bdict[(i-1)%N]+Bdict[(i+1)%N])//(-Bdict[(i-1)%N]-Bdict[(i+1)%N])
				count += k
				Bdict[i] -= (Bdict[(i-1)%N]+Bdict[(i+1)%N])*k
				if Bdict[i] - (Bdict[(i-1)%N]+Bdict[(i+1)%N]) < 0 and Bdict[i] - (Bdict[(i-1)%N]+Bdict[(i+1)%N]) <= -A[i]:
					count += 1
					Bdict[i] -= Bdict[(i-1)%N]+Bdict[(i+1)%N]
				heappush(q, (Bdict[i], i))

	for i in range(N):
		if -Bdict[i] != A[i]:
			print(-1)
			break
	else: print(count)

	return 0

if __name__ == '__main__':
	solve()

