input = sys.stdin.readline

def f(i, b, N):
    b[i] -= b[(i-1)%N] + b[(i+1)%N]

def check(i, a, b, N):
    if a[i] <= b[i] - (b[(i-1)%N] + b[(i+1)%N]):
        return True

def main():
    N = int(input())
    # N, K = map(int, input().split())
    a = np.array(list(map(int, input().split())))
    b = np.array(list(map(int, input().split())))
    # s = input().strip()
    remain = np.sum(b > a)
    # print(remain)
    indi = []
    for i in range(N):
        if b[(i-1)%N] + b[(i+1)%N] < b[i]:
            indi.append(i)
    count = 0
    while remain > 0:
        # print(indi)
        # print(b)
        cont = False
        for i in indi:
            if check(i, a, b, N):
                # print("True:", i)
                f(i, b, N)
                count += 1
                indi.remove(i)
                for j in [(i-1)%N, i, (i+1)%N]:
                    if check(j, a, b, N):
                        indi.append(j)
                if b[i] == a[i]:
                    remain -= 1
                cont = True
                break
        if not cont:
