#include <queue>

struct item{
	long value;
	int index;
	item(long v, int i){
		value = v;
		index = i;
	}
	bool operator<(const item& item) const{
		return value < item.value;
	}
};

int main(void){
	char *buffer = new char[200000];
	fgets(buffer, 200000, stdin);
	const int N = atoi(buffer);

	auto a_list = new long[N];
	auto b_list = new long[N];

	fgets(buffer, 200000, stdin);
	for(int i = 0; i < N; i ++){
		char* token = i == 0 ? strtok(buffer, " ") : strtok(0, " ");
		a_list[i] = atoi(token);
	}

	fgets(buffer, 200000, stdin);
	for(int i = 0; i < N; i ++){
		char* token = i == 0 ? strtok(buffer, " ") : strtok(0, " ");
		b_list[i] = atoi(token);
	}

	delete buffer;

	std::priority_queue<item> queue;

	int not_matched = 0;
	for(int i = 0; i < N; i ++){
		queue.push(item(b_list[i], i));
		if(b_list[i] != a_list[i]){
			not_matched ++;
		}
	}

	int count = 0;
	while(not_matched > 0){
		item item = queue.top();

		queue.pop();
		item.value -= (b_list[(item.index - 1 + N) % N] + b_list[(item.index + 1) % N]);
		if(item.value < a_list[item.index]){
			count = -1;
			break;
		}
		if(item.value == a_list[item.index]){
			not_matched --;
		}
		count ++;
		queue.push(item);
		b_list[item.index] = item.value;
	}

	printf("%d\n", count);

	return 1;
}

