import sys
import heapq


def solve(N: int, A: "List[int]", B: "List[int]"):

    lh = []
    for i, b in enumerate(B):
        heapq.heappush(lh, [-b, i])

    count = 0
    while len(lh) > 0:
        b, i = heapq.heappop(lh)
        a, b = A[i], B[i]
        c = B[i-1]+B[(i+1) % N]
        if b > a and b >= c:
            d, m = divmod(b-a, c)
            if m == 0:
                count += d
                B[i] = a
            if m != 0:
                d, m = divmod(b, c)
                count += d
                B[i] = m
                heapq.heappush(lh, [-B[i], i])
    # print(*A)
    # print(*B)
    for a, b in zip(A, B):
        if a != b:
            print(-1)
            return

    print(count)
    return


