class MyHeap(object):
    def __init__(self, x):
        self.heap = [self._encode(e) for e in x]
        heapq.heapify(self.heap)

    def push(self, value):
        heapq.heappush(self.heap, self._encode(value))

    def pop(self):
        return self._decode(heapq.heappop(self.heap))

    def _encode(self, x):
        a, b, i = x
        return [-b, a, i]

    def _decode(self, x):
        b, a, i = x
        return [a, -b, i]

    def __len__(self):
        return len(self.heap)


def solve(N: int, A: "List[int]", B: "List[int]"):

    lh = MyHeap([])
    for i in range(N):
        lh.push((A[i], B[i], i))

    count = 0
    while len(lh) > 0:
        a, b, i = lh.pop()
        if B[i]-B[(i+1) % N]-B[(i-1) % N] > 0:
            count += B[i]//(B[(i+1) % N]+B[(i-1) % N])
            B[i] %= (B[(i+1) % N]+B[(i-1) % N])
            if A[i] < B[i]:
                lh.push([A[i], B[i], i])
        else:
            continue
    for i in range(N):
        if A[i] != B[i]:
            print(-1)
            return

    print(count)
    return


