				elif cur.v > v:
					if cur.l:
						depth += 1
						stack_n[depth] = cur
						stack_p[depth] = True
						cur = cur.l
					else:
						cur.l = AVLTree.Node(v, x)
						if cur.r == None:
							cur.balance = 1
							increase = 1
							if len(self.stack_n) <= depth + 1:
								self.stack_n.append(None)
								self.stack_p.append(None)
						else:
							cur.balance = 0
							increase = 0
						break
				else:
					if cur.r:
						depth += 1
						stack_n[depth] = cur
						stack_p[depth] = False
						cur = cur.r
					else:
						cur.r = AVLTree.Node(v, x)
						if cur.l == None:
							cur.balance = -1
							increase = 1
							if len(self.stack_n) <= depth + 1:
								self.stack_n.append(None)
								self.stack_p.append(None)
						else:
							cur.balance = 0
							increase = 0
						break

			if increase != 0:
				while depth >= 0:
					cur = stack_n[depth]
					if stack_p[depth]:
						cur.balance += increase
					else:
						cur.balance -= increase
					if cur.balance == 0:
						return

					if cur.balance == 2:
						rotated = self.rotate_lr(cur)
					elif cur.balance == -2:
						rotated = self.rotate_rl(cur)
					else:
						rotated = None

					depth -= 1
					if rotated:
						if depth < 0:
							self.root = rotated
						elif stack_p[depth]:
							stack_n[depth].l = rotated
						else:
							stack_n[depth].r = rotated
						return

	def rotate_lr(self, a):
		b = a.l
		if b.balance < 0:
			e = b.r
			b.r = e.l
			a.l = e.r

			e.l = b
			e.r = a
			if e.balance == 0:
				a.balance = 0
				b.balance = 0
			elif e.balance == 1:
				a.balance = -1
				b.balance = 0
			else:
				a.balance = 0
				b.balance = 1
			e.balance = 0
			return e
		else:
			a.l = b.r
			b.r = a
			b.balance -= 1
			a.balance = 0

			if b.balance == 0:
				a.balance = 0
			else:
				a.balance = 1

			return b

	def rotate_rl(self, a):
		b = a.r
		if b.balance > 0:
			e = b.l
			b.l = e.r
			a.r = e.l

			e.r = b
			e.l = a
			if e.balance == 0:
				a.balance = 0
				b.balance = 0
			elif e.balance == -1:
				a.balance = 1
				b.balance = 0
			else:
				a.balance = 0
				b.balance = -1
			e.balance = 0
			return e
		else:
			a.r = b.l
			b.l = a
			b.balance += 1

			if b.balance == 0:
				a.balance = 0
			else:
				a.balance = -1
			return b

	def rotate(self, a):
		if a.balance == 2:
			b = a.l
			if b.balance < 0:
				e = b.r
				b.r = e.l
				a.l = e.r

				e.l = b
				e.r = a
				if e.balance == 0:
					a.balance = 0
					b.balance = 0
				elif e.balance == 1:
					a.balance = -1
					b.balance = 0
				else:
					a.balance = 0
					b.balance = 1
				e.balance = 0
				return e
			else:
				a.l = b.r
				b.r = a
				b.balance -= 1
				a.balance = 0

				if b.balance == 0:
					a.balance = 0
				else:
					a.balance = 1

				return b
		elif a.balance == -2:
			b = a.r
			if b.balance > 0:
				e = b.l
				b.l = e.r
				a.r = e.l

				e.r = b
				e.l = a
				if e.balance == 0:
					a.balance = 0
					b.balance = 0
				elif e.balance == -1:
					a.balance = 1
					b.balance = 0
				else:
					a.balance = 0
					b.balance = -1
				e.balance = 0
				return e
			else:
				a.r = b.l
				b.l = a
				b.balance += 1

				if b.balance == 0:
					a.balance = 0
				else:
					a.balance = -1
				return b
		else:
			return a.balance


	def remove(self, v):
		if self.root:
			cur = self.root
			stack_n = self.stack_n
			stack_p = self.stack_p
			depth = -1
			while cur:
				if cur.v == v:
					if cur.l and cur.r:
						replace = cur
						if cur.balance > 0:
							depth += 1
							stack_n[depth] = cur
							stack_p[depth] = True
							cur = cur.l
							while cur.r:
								depth += 1
								stack_n[depth] = cur
								stack_p[depth] = False
								cur = cur.r
							replace.v = cur.v
							replace.x = cur.x
							new_top = cur.l
						else:
							depth += 1
							stack_n[depth] = cur
							stack_p[depth] = False
							cur = cur.r
							while cur.l:
								depth += 1
								stack_n[depth] = cur
								stack_p[depth] = True
								cur = cur.l
							replace.v = cur.v
							replace.x = cur.x
							new_top = cur.r
					elif cur.l:
						new_top = cur.l
					else:
						new_top = cur.r
					break
				elif cur.v > v:
					if cur.l:
						depth += 1
						stack_n[depth] = cur
						stack_p[depth] = True
						cur = cur.l
					else:
						return
				elif cur.v < v:
					if cur.r:
						depth += 1
						stack_n[depth] = cur
						stack_p[depth] = False
						cur = cur.r
					else:
						return
			if depth >= 0:
				cur = stack_n[depth]
				lr_flag = stack_p[depth]
				if lr_flag:
					cur.l = new_top
				else:
					cur.r = new_top
				while True:
					if lr_flag:
						cur.balance -= 1
					else:
						cur.balance += 1

					if cur.balance == 1 or cur.balance == -1:
						return

					if cur.balance == 2:
						rotated = self.rotate_lr(cur)
					elif cur.balance == -2:
						rotated = self.rotate_rl(cur)
					else:
						rotated = None

					depth -= 1
					if depth < 0:
						if rotated:
							self.root = rotated
						return
					cur = stack_n[depth]
					lr_flag = stack_p[depth]
					if rotated:
						if lr_flag:
							cur.l = rotated
						else:
							cur.r = rotated
						if rotated.balance == -1 or rotated.balance == 1:
							return
			else:
				self.root = new_top

	def to_list(self):
		items = []
		if self.root:
			stack = []
			cur = self.root
			while True:
				if cur == None:
					if not stack:
						break
					cur = stack.pop()
					items.append((cur.v, cur.x))
					cur = cur.r
				else:
					if cur.l:
						stack.append(cur)
						cur = cur.l
					else:
						items.append((cur.v, cur.x))
						cur = cur.r
		return items

	def max(self):
		if self.root:
			return self.root.max()
		else:
			return None

	def min(self):
		if self.root:
			return self.root.min()
		else:
			return None

	def calc_depth(self):
		if self.root:
			return self.root.depth
		else:
			return 0

	def check(self):
		if self.root:
			self.check_rec(self.root)
			pass

	def check_rec(self, cur):
		if cur.l:
			self.check_rec(cur.l)
		dl = cur.l.calc_depth() if cur.l else 0
		dr = cur.r.calc_depth() if cur.r else 0
		if abs(dl - dr) >= 2 or dl - dr != cur.balance:
			print("ERROR", dr, dl, cur.balance)
			self.root.print()
			exit()
		if cur.r:
			self.check_rec(cur.r)


	def print(self):
