			self.root.print()

	def __iter__(self):
		self.stack_in = []
		self.stack_ip = []
		self.cur_i = self.root
		return self

	def __next__(self):
		pass



	class Node:
		def __init__(self, v, x):
			self.v = v
			self.x = x
			self.l = None
			self.r = None
			self.balance = 0

		def calc_balance(self):
			dl = self.l.calc_depth() if self.l else 0
			dr = self.r.calc_depth() if self.r else 0
			return dl - dr

		def calc_depth(self):
			dl = self.l.calc_depth() if self.l else 0
			dr = self.r.calc_depth() if self.r else 0
			return max(dl, dr) + 1

		def print_nodedata(self):
	#		print("-{}:{}({}, {})".format(self.v, self.x, self.balance, self.calc_balance()))
