import numpy as np


def make_O(N, i):
    O = np.eye(N)
    O[i][(i + N - 1) % N] = -1
    O[i][(i + 1) % N] = -1
    return O


def calc(N, A, B):
    a = np.array(A)
    b = np.array(B)
    result = 0
    while (True):
        flag = True
        for j in range(N):
            if (b[j] < a[j]):
                return - 1
            elif (b[j] > a[j]):
                flag = False
        if (flag):
            return result
        result += 1
        k = [0]
        k_v = 0
        for j in range(N):
            if (k_v < b[j]):
                k = [j]
                k_v = b[j]
            elif (k_v == b[j]):
                k += [j]
        new_b = [np.dot(make_O(N, _k), b) for _k in k]
        if (len(new_b) > 1):
            new_result = [calc(N, A, _b) for _b in new_b]
            return result + max(new_result)
        else:
            b = new_b[0]


