import sys
from heapq import heapify, heappush, heappop


def solve(N: int, A: "List[int]", B: "List[int]"):

    lh = []
    for i, b in enumerate(B):
        heappush(lh, (-b, i))

    count = 0
    while lh:
        b, i = heappop(lh)
        a, b, c = A[i], B[i], B[i-1]+B[(i+1) % N]
        if b > a and b > c:
            d, m = divmod(b-a, c)
            if d <= 0:
                break
            count += d
            B[i] = a+m
            if m > 0:
                heappush(lh, (-B[i], i))

    if A != B:
        count = -1

    print(count)
    return


