import sys
from heapq import heapify, heappop, heappush


def solve(N: int, A: "List[int]", B: "List[int]"):

    lh = []
    for i, b in enumerate(B):
        heappush(lh, [-b, i])

    count = 0
    while len(lh) > 0:
        b, i = heappop(lh)
        a, b = A[i], B[i]
        c = B[i-1]+B[(i+1) % N]
        d, m = divmod(b-a, c)
        if d == 0:
            break
        count += d
        B[i] = a+m
        if m != 0:
            heappush(lh, [-B[i], i])

    if A != B:
        count = -1

    print(count)
    return


