        let prev = if i == 0 { b[n - 1] } else { b[i - 1] };
        let next = if i == n - 1 { b[0] } else { b[i + 1] };
        ans += (b[i] - a[i]) / (prev + next);
        b[i] = (b[i] - a[i]) % (prev + next) + a[i];
        add(&a, &b, &mut q, (i + 1) % n);
        add(&a, &b, &mut q, (n + i - 1) % n);
    }

    if a == b {
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

fn add(a: &Vec<u64>, b: &Vec<u64>, q: &mut BinaryHeap<(u64, usize)>, i: usize) {
    let n = a.len();
    let prev = if i == 0 { b[n - 1] } else { b[i - 1] };
    let next = if i == n - 1 { b[0] } else { b[i + 1] };

    if b[i] - a[i] >= prev + next {
        q.push(((b[i] - a[i]) / (prev + next), i));
    }
}

