fn solve() {
    let n = get!(usize);
    let a = get!([usize]);
    let mut b = get!([usize]);

    for i in 0..n {
        if a[i] > b[i] {
            println!("-1");
            return;
        }
    }

    let mut count = 0;
    let mut flag = true;
    while flag {
        flag = false;
        for i in 0..n {
            let left = if i==0 {
                b[n-1]
            } else {
                b[i-1]
            };
            let right = if i==n-1 {
                b[0]
            } else {
                b[i+1]
            };
            let center = b[i];
            let tmp = (center-a[i])/(right+left);
            if center > right && center > left && tmp > 0 {
                flag = true;
                count += tmp;
                b[i] -= tmp*(right+left);
            }
        }
    }
    for i in 0..n {
        if a[i] != b[i] {
            println!("-1");
            return;
        }
    }
    println!("{}", count);
}

