use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [i64; n],
        ys: [i64; n],
    }
    let mut ys = ys;
    let mut res = 0;
    loop {
        let mut ok = true;
        for i in 0..n {
            if xs[i] > ys[i] {
                writeln!(buf, "-1");
                return buf;
            }
            if xs[i] != ys[i] {
                ok = false;
            }
        }
        if ok {
            break;
        }
        for i in 0..n {
            let a = ys[(i + n - 1) % n];
            let b = ys[i];
            let c = ys[(i + 1) % n];
            if a < b && b > c {
                if b < a + c {
                    writeln!(buf, "-1");
                    return buf;
                }
                res += b / (a + c);
                ys[i] = b % (a + c);
            }
        }
    }
    writeln!(buf, "{}", res);
    buf
}

