        for i in 1..n+2 {
            let l:i64 = d[i] - d[i-1] - d[i+1];
            if l>0 {
                count+=1;
                if i==n {
                    doub[0] = l;
                }
                if i==1 {
                    doub[n+1] = l;
                }
                doub[i] = l;
            }
        }
        if g==count {
            break;
        }
        // println!("{:?}", doub);
        // equal check
        let mut ans_f = true;
        for i in 0..n {
            if a[i] != doub[i] {
                ans_f = false;
            }
