#[derive(Debug, PartialEq, Eq)]
struct State(usize, usize);

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        self.1.cmp(&other.1)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    input!{
        n: usize,
        a: [usize; n],
        mut b: [usize; n]
    }
    let mut pq = BinaryHeap::new();
    for i in 0..n {
        if b[i] >= b[(i + n - 1) % n] + b[(i + 1) % n] + a[i] {
            pq.push(State(i, b[i]));
        }
    }
    let mut ans = 0;
    while let Some(st) = pq.pop() {
        let i = st.0;
        let k = (b[i] - a[i]) / (b[(i + n - 1) % n] + b[(i + 1) % n]);
        ans += k;
        b[i] -= k * (b[(i + n - 1) % n] + b[(i + 1) % n]);
        if b[(i + n - 1) % n] >= b[(i + n - 2) % n] + b[i] + a[(i + n - 1) % n] {
            pq.push(State((i + n - 1) % n, b[(i + n - 1) % n]));
        }
        if b[(i + 1) % n] >= b[i] + b[(i + 2) % n] + a[(i + 1) % n] {
            pq.push(State((i + 1) % n, b[(i + 1) % n]));
        }
    }
    if a.iter().zip(b.iter()).all(|(&x, &y)| x == y) {
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

