use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      aa: [usize; n],
      mut bb: [usize; n],
    }

    let mut ans = 0u64;
    let mut ok = 0;
    let mut q = std::collections::VecDeque::new();

    for i in 0..n {
        if aa[i] == bb[i] {
            continue;
        }

        let xi = if i == 0 { n-1 } else { i-1 };
        let yi = i;
        let zi = if i == n-1 { 0 } else { i+1 };

        let x = bb[xi];
        let y = bb[yi];
        let z = bb[zi];

        if x < y && y > z {
            q.push_back(i);
        }
    }

    while q.len() > 0 {
        let i = q.pop_front().unwrap();
        if aa[i] == bb[i] {
            continue;
        }

        // debug!(i, bb);

        let xi = if i == 0 { n-1 } else { i-1 };
        let yi = i;
        let zi = if i == n-1 { 0 } else { i+1 };

        let x = bb[xi];
        let y = bb[yi];
        let z = bb[zi];

        if !(x < y && y > z) {
            continue;
        }

        if aa[i] > y {
            return puts!("{}\n", -1);
        }
        let dy = x + z;
        if (y-aa[i]) % dy == 0 {
            ans += ((y - aa[i]) / dy) as u64;
            bb[i] = aa[i];
            ok += 1;
            q.push_back(xi);
            q.push_back(zi);
        } else {
            let sub = y / dy * dy;
            bb[i] -= sub;
            ans += (y/dy) as u64;
            if sub != 0 {
                q.push_back(xi);
                q.push_back(zi);
            }
        }
    }

    // debug!(ok, bb);
    if ok == n {
        return puts!("{}\n", ans);
    } else {
        return puts!("{}\n", -1);
    }
}

use std::collections::BinaryHeap;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let mut b: Vec<i64> = sc.vec(n);
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        let center = b[i];
        let prev = b[(i + n - 1) % n];
        let next = b[(i + 1) % n];
        if center - a[i] >= prev + next {
            let count = (center - a[i]) / (prev + next);
            heap.push((count, i));
        }
    }

    let mut ans = 0;
    while let Some((_, i)) = heap.pop() {
        let prev = b[(i + n - 1) % n];
        let next = b[(i + 1) % n];
        let count = (b[i] - a[i]) / (prev + next);
        ans += count;
        b[i] -= (prev + next) * count;

        let i = (i + 1) % n;
        let center = b[i];
        let prev = b[(i + n - 1) % n];
        let next = b[(i + 1) % n];
        if center - a[i] >= prev + next {
            let count = (center - a[i]) / (prev + next);
            heap.push((count, i));
        }

        let i = (i + n - 2) % n;
        let center = b[i];
        let prev = b[(i + n - 1) % n];
        let next = b[(i + 1) % n];
        if center - a[i] >= prev + next {
            let count = (center - a[i]) / (prev + next);
            heap.push((count, i));
        }
    }

    if a != b {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

