fn argmax(v: &Vec<i64>) -> usize {
    let mut val = 0i64;
    let mut max_idx: usize = 0;
    for (i, x) in v.iter().enumerate() {
        if x > &val {
            val = *x;
            max_idx = i;
        } else if x == &val {
            continue;
        }
    }
    max_idx
}

