    for i in (0..N) {
        q.push((B[i], i))
    }
    let mut ans = 0;
    while !q.is_empty() {
        let (b, i) = q.pop().unwrap();
        let s = B[(N + i - 1) % N] + B[(i + 1) % N];
        if b == A[i] {
            continue;
        }
        if b < s {
            ans = -1;
            break;
        }
        let d = (b - A[i]) / s;
        ans += d;
        B[i] -= d * s;
        if B[i] < A[i] || d == 0 {
            ans = -1;
            break;
        } else if B[i] > A[i] {
            q.push((B[i], i))
        }
    }
