fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($($T:ty),+; $n:expr) => {
      (0..$n).map(|_| scan!($($T),+))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  let n = scan!(usize);
  let a = scan!(i64; n);
  let mut b = scan!(i64; n);

  let mut cnt = 0;
  let mut d_heap = BinaryHeap::from_iter((0..n).map(|i| (b[i] - a[i], i)));

  loop {
    dbg!(b);

    let (d1, d1_idx) = d_heap.pop().unwrap();
    let (d2, _) = d_heap.peek().cloned().unwrap();

    if d1 == 0 {
      println!("{}", cnt);
      return;
    }

    let b_d1_l = b[(d1_idx + n - 1) % n];
    let b_d1_r = b[(d1_idx + 1) % n];

    if b_d1_l < 0 || b_d1_r < 0 {
      println!("-1");
      return;
    }

    let tmp = b_d1_l + b_d1_r;
    let tmp_d = b[d1_idx] - (d2 + a[d1_idx]);
    let tmp_cnt = cmp::max(1, tmp_d / tmp);

    dbg!(cnt, d1_idx, d1, tmp, tmp_d, tmp_cnt);

    cnt += tmp_cnt;
    b[d1_idx] -= tmp * tmp_cnt;
    d_heap.push((b[d1_idx] - a[d1_idx], d1_idx));
  }
}

use std::io::{self, BufRead};
use std::collections::BinaryHeap;

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let xs: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
  let mut ys: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
  let mut zs: BinaryHeap<usize> = BinaryHeap::new();
  for i in 0..n {
    let j = (i + 1) % n;
    let k = (i + 2) % n;
    if ys[i] + ys[k] < ys[j] && xs[j] <= ys[j] - ys[i] - ys[k] {
      zs.push(i);
    }
  }
  let mut count: usize = 0;
  while !zs.is_empty() {
    let i = zs.pop().unwrap();
    let j = (i + 1) % n;
    let k = (i + 2) % n;
    ys[j] -= ys[i] + ys[k];
    let l = (i + n - 1) % n;
    let m = (i + 3) % n;
    if ys[i] + ys[k] < ys[j] && xs[j] <= ys[j] - ys[i] - ys[k] {
      zs.push(i);
    }
    if ys[l] + ys[j] < ys[i] && xs[i] <= ys[i] - ys[l] - ys[j] {
      zs.push(l);
    }
    if ys[j] + ys[m] < ys[k] && xs[k] <= ys[k] - ys[j] - ys[m] {
      zs.push(j);
    }
    count += 1;
  }
  if xs == ys {
    println!("{}", count);
  } else {
    println!("-1");
  }
}

