fn run() {
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n],
    }
    let mut b = b;
    let mut h = std::collections::BinaryHeap::new();
    for i in 0..n {
        h.push((b[i] - a[i], i));
    }
    let mut cnt = 0;
    loop {
        let (v, i) = h.pop().unwrap();
        if v <= 0 {
            break;
        }
        cnt += 1;
        let v = b[(i + 1) % n] + b[(i + n - 1) % n];
        b[i] -= v;
        if b[i] <= 0 {
            break;
        }
        h.push((b[i] - a[i], i));
    }
    for i in 0..n {
        if a[i] != b[i] {
            println!("-1");
            return;
        }
    }
    println!("{}", cnt);
}

fn main() {
    run();
}

