    for i in 0..n {
        if a[i] > b[i] {
            f = false;
        }
    }
    // a <= b
    let mut doub:Vec<i64> = b.clone();
    doub.append(&mut b);
    // println!("{:?}", doub);
    let mut count = 0;
    let mut ans_f_true = false;
