fn main() {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let mut b = read_vec::<i64>();

    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((b[i], i));
    }

    let mut ans = 0;
    while let Some((bnum, i)) = heap.pop() {
        if bnum == a[i] {
            continue;
        }
        if bnum < a[i] {
            println!("-1");
            return;
        }
        let mut left = i + n - 1;
        if left >= n {
            left -= n;
        }
        let mut right = i + 1;
        if right == n {
            right = 0;
        }

        if (b[i] - a[i]) % (b[left] + b[right]) == 0 {
            let coef = (b[i] - a[i]) / (b[left] + b[right]);
            ans += coef;
            b[i] -= coef * (b[left] + b[right]);
            continue;
        }

        let coef = max((b[i] - (b[left] + b[right])) / (b[left] + b[right]), 1);
        b[i] -= coef * (b[left] + b[right]);
        heap.push((b[i], i));
        ans += coef;
    }
    println!("{}", ans);
}

