use std::collections::BinaryHeap;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n = sc.read();
    let a: Vec<u64> = sc.vec(n);
    let mut b: Vec<u64> = sc.vec(n);
    if (0..n).any(|i| a[i] >= b[i]) {
        println!("-1");
        return;
    }

    let mut ans = 0;
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        push(&mut heap, &a, &b, i);
    }

    while let Some((_, i)) = heap.pop() {
        let prev = b[(n + i - 1) % n];
        let next = b[(i + 1) % n];
        let d = b[i] - a[i];
        ans += d / (prev + next);
        let diff = d / (prev + next) * (prev + next);
        b[i] -= diff;
        push(&mut heap, &a, &b, (i + 1) % n);
        push(&mut heap, &a, &b, (n + i - 1) % n);
    }

    if a != b {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

fn push(heap: &mut BinaryHeap<(u64, usize)>, a: &Vec<u64>, b: &Vec<u64>, i: usize) {
    let n = b.len();
    let prev = b[(n + i - 1) % n];
    let next = b[(i + 1) % n];
    let d = b[i] - a[i];
    let diff = d / (prev + next) * (prev + next);
    if diff > 0 {
        heap.push((diff, i));
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<usize> = parse!(it, n);
    let mut b: Vec<usize> = parse!(it, n);
    let mut count = 0;
    loop {
        let mut flag = false;
        for i in 0..n {
            let s = match i {
                0 => b[n - 1] + b[1],
                i if i == n - 1 => b[0] + b[n - 2],
                i => b[i - 1] + b[i + 1],
            };
            if b[i] <= s || a[i] == b[i] {
                continue;
            }

            flag = true;
            let next = if a[i] >= s { a[i] } else { b[i] % s };
            if (b[i] - next) % s != 0 {
                break;
            }
            count += (b[i] - next) / s;
            b[i] = next;
        }
        if !flag {
            break;
        }
    }
    if (0..n).all(|i| a[i] == b[i]) {
        println!("{}", count);
    } else {
        println!("{}", -1);
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

