use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      aa: [usize; n],
      mut bb: [usize; n],
    }

    let mut ans = 0u64;
    let mut ok = 0;
    let mut q = std::collections::VecDeque::new();

    for i in 0..n {
        if aa[i] == bb[i] {
            continue;
        }

        let xi = if i == 0 { n-1 } else { i-1 };
        let yi = i;
        let zi = if i == n-1 { 0 } else { i+1 };

        let x = bb[xi];
        let y = bb[yi];
        let z = bb[zi];

        if x < y && y > z {
            q.push_back(i);
        }
    }

    while q.len() > 0 {
        let i = q.pop_front().unwrap();
        if aa[i] == bb[i] {
            continue;
        }

        // debug!(i, bb);

        let xi = if i == 0 { n-1 } else { i-1 };
        let yi = i;
        let zi = if i == n-1 { 0 } else { i+1 };

        let x = bb[xi];
        let y = bb[yi];
        let z = bb[zi];

        if !(x < y && y > z) {
            continue;
        }

        if aa[i] > y {
            return puts!("{}\n", -1);
        }
        let dy = x + z;
        let nv = max(x, z);
        if aa[i] > nv {
            // aにするしかない
            if (y - aa[i]) % dy != 0 {
                return puts!("{}\n", -1);
            }
            ans += ((y - aa[i]) / dy) as u64;
            bb[i] = aa[i];
            ok += 1;
            // 右/左は固定
        } else {
            // nv 以下にする
            let sub = y / dy * dy;
            if sub == 0 {
                if aa[i] != bb[i] {
                    return puts!("{}\n", -1);
                }
                continue;
            }
            bb[i] -= sub;
            ans += (y/dy) as u64;
            if bb[i] < aa[i] {
                return puts!("{}\n", -1);
            }

            if bb[i] == aa[i] {
                ok += 1;
            }
            q.push_back(xi);
            q.push_back(yi);
        }
    }

    // debug!(ok, bb);
    if ok == n {
        return puts!("{}\n", ans);
    } else {
        return puts!("{}\n", -1);
    }
}

