    while let Some(mut p) = queue.peek_mut() {
        let (bi, i) = *p;
        if bi == 0 {
            break;
        }
        count += 1;
        let i0 = if i == 0 {
            n - 1
        } else {
            i - 1
        };
        let i2 = if i == n - 1 {
            0
        } else {
            i + 1
        };
        if b[i0] + b[i2] > bi {
            println!("-1");
            return;
        }
        let new_bi = bi - b[i0] - b[i2];
        b[i] = new_bi;
        if b[i] < a[i] {
            println!("-1");
            return;
        }
        if a[i] == b[i] {
            *p = (0, i);
        } else {
            *p = (new_bi, i);
        }
    }
    println!("{}", count);
}

