macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<usize> = parse!(it, n);
    let mut b: Vec<usize> = parse!(it, n);
    let mut count = 0;
    loop {
        let mut flag = false;
        for i in 0..n {
            let s = match i {
                0 => b[n - 1] + b[1],
                i if i == n - 1 => b[0] + b[n - 2],
                i => b[i - 1] + b[i + 1],
            };
            if b[i] <= s || a[i] == b[i] {
                continue;
            }

            let next = if a[i] >= s { a[i] } else { b[i] % s };
            if (b[i] - next) % s != 0 {
                break;
            }
            flag = true;
            count += (b[i] - next) / s;
            b[i] = next;
        }
        if !flag {
            break;
        }
    }
    if (0..n).all(|i| a[i] == b[i]) {
        println!("{}", count);
    } else {
        println!("{}", -1);
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

