fn main() {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let mut b = read_vec::<i64>();

    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((b[i], i));
    }

    let mut ans = 0;
    while let Some((bnum, i)) = heap.pop() {
        if bnum == a[i] {
            continue;
        }
        if bnum < a[i] {
            println!("-1");
            return;
        }
        let left = (i + n - 1) % n;
        let right = (i + 1) % n;
        let coef = max((b[i] - max(b[left], b[right])) / (b[left] + b[right]), 1);
        b[i] -= coef * (b[left] + b[right]);
        heap.push((b[i], i));
        ans += coef;
    }
    println!("{}", ans);
}

