        vec![dvec!($t; $($rest),*); $len]
    };
}

#[allow(unused_macros)]
macro_rules! debug {
    ($($a:expr),*) => {
        println!(concat!($(stringify!($a), " = {:?}, "),*), $($a),*);
    }
}

fn solve(mut a: Vec<i64>, mut b: Vec<i64>) -> i64 {
    let n = a.len();
    for i in 0..n {
        if b[i] < a[i] {
            return -1;
        }
    }
    let mut pq = BinaryHeap::new();
    for i in 0..n {
        if a[i] < b[i] {
            pq.push((b[i], i));
        }
    }

    let mut step = 0;
    while let Some((mut v, i)) = pq.pop() {
        let lr = b[(i+1)%n] + b[(i+n-1)%n];
        if lr > v {
            return -1;
        }
        v -= lr;
        b[i] = v;
        if a[i] > b[i] {
            return -1;
        } else if a[i] < b[i] {
            pq.push((b[i], i));
        }
        step += 1;
    }

    for i in 0..n {
        if a[i] != b[i] {
            return -1;
        }
    }
    step
}

fn main() {
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n]
    };

    println!("{}", solve(a, b));
}

