      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  let n = scan!(usize);
  let a = scan!(i64; n);
  let mut b = scan!(i64; n);

  let mut cnt = 0;
  let mut d_heap = BinaryHeap::from_iter((0..n).map(|i| (b[i] - a[i], i)));

  loop {
    dbg!(b);

    let (d1, d1_idx) = d_heap.pop().unwrap();

    if d1 == 0 {
      println!("{}", cnt);
      return;
    }

    let b_d1_l = b[(d1_idx + n - 1) % n];
    let b_d1_r = b[(d1_idx + 1) % n];

    if b_d1_l < 0 || b_d1_r < 0 {
      println!("-1");
      return;
    }

    let tmp = b_d1_l + b_d1_r;
    let tmp_d = b[d1_idx] - (b_d1_l + b_d1_r);
    let tmp_cnt = tmp_d / tmp + if tmp_d % tmp != 0 { 1 } else { 0 };

    dbg!(cnt, d1_idx, d1, tmp, tmp_d, tmp_cnt);

    cnt += tmp_cnt;
    b[d1_idx] -= tmp * tmp_cnt;
    d_heap.push((b[d1_idx] - a[d1_idx], d1_idx));
  }
}

