fn run() {
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n],
    }
    let mut b = b;
    let mut h = std::collections::BinaryHeap::new();
    for i in 0..n {
        h.push((b[i], i));
    }
    let mut cnt = 0;
    while let Some((_, i)) = h.pop() {
        if b[i] <= a[i] {
            continue;
        }
        let l = (i + n - 1) % n;
        let r = (i + 1) % n;
        let v = b[r] + b[l];
        let max = std::cmp::max;
        let k = (b[i] - max(a[i], max(b[l], b[r])) + v - 1) / v;
        cnt += k;
        b[i] -= k * v;
        if b[i] < a[i] {
            break;
        }
        h.push((b[i], i));
    }
    for i in 0..n {
        if a[i] != b[i] {
            println!("-1");
            return;
        }
    }
    println!("{}", cnt);
}

