fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n],
    }
    let mut b = b;
    let mut que = BinaryHeap::new();
    for i in 0..n {
        que.push((b[i], i));
    }
    let mut ans = 0;
    while let Some((x, idx)) = que.pop() {
        let y = b[(idx + 1) % n];
        let z = b[(idx + n - 1) % n];
        if y + z < x {
            let q = (x - 1) / (y + z);
            ans += q;
            b[idx] = x - q * (y + z);
            if b[idx] > a[idx] {
                que.push((b[idx], idx));
            }
        }
    }
    if a == b {
        puts!("{}\n", ans);
    } else {
        puts!("-1\n");
    }
}

