use std::collections::BinaryHeap;
fn main() {
    input! { n, a: [usize; n], mut b: [usize; n] };
    let mut ans = 0;
    if (0..n).any(|i| a[i] > b[i]) {
        ans = -1;
    } else {
        let mut heap = (0..n)
            .filter_map(|i| if a[i] < b[i] { Some((b[i], i)) } else { None })
            .collect::<BinaryHeap<_>>();
        while let Some((_, i)) = heap.pop() {
            let x = b[(i + n - 1) % n] + b[(i + 1) % n];
            if x + a[i] > b[i] {
                ans = -1;
                break;
            }
            let m = (b[i] - a[i]) / x;
            b[i] -= m * x;
            ans += m as isize;
            if b[i] > a[i] {
                heap.push((b[i], i));
            }
        }
    }
    println!("{}", ans);
}

