        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        aa: [u32; n],
        bb: [u32; n],
    }
    let mut heap = BinaryHeap::new();
    for (i, b) in bb.iter().enumerate() {
        heap.push((*b, i));
    }
    let mut bb = bb.clone();
    let mut count = 0;
    while let Some((b, i)) = heap.pop() {
        if b == aa[i] {
            continue;
        }
        let b1 = bb[(i + n - 1) % n];
        let b2 = bb[(i + 1) % n];
        if b < aa[i] + b1 + b2 {
            println!("-1");
            return;
        }
        let b = b - b1 - b2;
        bb[i] = b;
        count += 1;
        if b > aa[i] {
            heap.push((b, i));
        }
    }
    println!("{}", count);
}

