    }
    let mut heap = BinaryHeap::new();
    for (i, b) in bb.iter().enumerate() {
        heap.push((*b, i));
    }
    let mut bb = bb.clone();
    let mut count = 0;
    while let Some((mut b, i)) = heap.pop() {
        if b == aa[i] {
            continue;
        }
        let diff = bb[(i + n - 1) % n] + bb[(i + 1) % n];
        if b < aa[i] + diff {
