    }
    let mut f = true;
    for i in 0..n {
        if a[i] > b[i] {
            f = false;
        }
    }
    // a <= b
    let mut doub:Vec<i64> = b.clone();
    doub.append(&mut b);
    // println!("{:?}", doub);
    let mut count = 0;
    let mut ans_f_true = false;
    loop {
        // minus check
        for i in 0..n {
            if a[i] > doub[i] {
                f = false;
            }
        }
        if f==false {
            break;
        }
        let g = count;
        // downgrade
        let d = doub.clone();
        for i in 1..n+2 {
            let l:i64 = d[i] % (d[i-1] + d[i+1]);
            let r:i64 = d[i] / (d[i-1] + d[i+1]);
            if r>0 {
                count+=r;
                if i==n {
                    doub[0] = l;
                }
                if i==1 {
                    doub[n+1] = l;
                }
                doub[i] = l;
            }
        }
        if g==count {
            break;
        }
        // println!("{:?}", doub);
        // equal check
        let mut ans_f = true;
        for i in 0..n {
            if a[i] != doub[i] {
                ans_f = false;
            }
        }
        if ans_f {
            ans_f_true = true;
            break;
        }
    }
    if ans_f_true {
        println!("{}", count);
    }else{
        println!("-1");
    }
}

