use std::collections::HashSet;
use std::process;

fn neighbor_sum(i: usize, bs: &[u32]) -> u32 {
    bs[(i+bs.len()-1) % bs.len()] + bs[(i+1) % bs.len()]
}

fn check(i: usize, aa: &[u32], bs: &[u32]) -> bool {
    aa[i] < bs[i] && bs[i] > neighbor_sum(i, bs)
}

fn main() {
    readls!(n = usize, aa = Vec<u32>, mut bs = Vec<u32>);
    let mut is: HashSet<usize> = (0..n)
        .filter(|&i| check(i, &aa, &bs))
        .collect();

    let mut ans = 0;
    while let Some(&i) = is.iter().next() {
        let s = neighbor_sum(i, &bs);
        if bs[i] % s > aa[i] {
            ans += bs[i] / s;
            bs[i] %= s;
        } else if (bs[i] - aa[i]) % s == 0 {
            ans += (bs[i] - aa[i]) / s;
            bs[i] = aa[i];
        } else {
            println!("-1");
            process::exit(0);
        }

        is.remove(&i);
        if check((i+n-1) % n, &aa, &bs) {
            is.insert((i+n-1) % n);
        }
        if check((i+1) % n, &aa, &bs) {
            is.insert((i+1) % n);
        }
    }

    if aa == bs {
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

