fn main() {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let mut b = read_vec::<i64>();

    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((b[i], i));
    }

    let mut ans = 0;
    while let Some((bnum, i)) = heap.pop() {
        if bnum == a[i] {
            continue;
        }
        if bnum < a[i] {
            println!("-1");
            return;
        }
        let left = (i + n - 1) % n;
        let right = (i + 1) % n;

        if (b[i] - a[i]) % (b[left] + b[right]) == 0 {
            let coef = (b[i] - a[i]) / (b[left] + b[right]);
            ans += coef;
            b[i] -= coef * (b[left] + b[right]);
            continue;
        }

        let coef = max((b[i] - (b[left] + b[right])) / (b[left] + b[right]), 1);
        b[i] -= coef * (b[left] + b[right]);
        heap.push((b[i], i));
        ans += coef;
    }
    println!("{}", ans);
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}
